import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.cooperation_scores = {}
        self.interaction_count = {}
        self.generation = 0
        self.round_in_generation = 0
        self.my_history = []
        self.opponent_history = {}
        self.trust = {}
        self.last_opponent = None
        self.my_recent_actions = []
        self.opponent_recent_actions = {}
        self.defection_count = {}
        self.cooperation_count = {}
        self.sit_out_count = 0
        self.total_rounds = 0
        self.total_generations = 30
        self.rounds_per_generation = 30

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        self.last_opponent = opponent

        # Initialize state for opponent
        if opponent not in self.reputation:
            self.reputation[opponent] = 0.0
            self.interaction_count[opponent] = 0
            self.opponent_history[opponent] = []
            self.trust[opponent] = 0.5
            self.defection_count[opponent] = 0
            self.cooperation_count[opponent] = 0
            self.opponent_recent_actions[opponent] = []

        # Track my recent actions
        recent_my = self.my_recent_actions[-3:] if self.my_recent_actions else []

        # If I've defected a lot recently, maybe cooperate now
        if recent_my.count(False) >= 3:
            return True

        # If opponent has defected in last 2 interactions, be cautious
        opponent_recent = self.opponent_recent_actions.get(opponent, [])[-2:]
        if opponent_recent.count(False) >= 1:
            return False

        # Use reputation: if opponent's overall cooperation rate is high, cooperate
        total_opp_actions = self.cooperation_count.get(opponent, 0) + self.defection_count.get(opponent, 0)
        if total_opp_actions >= 5:
            coop_rate = self.cooperation_count.get(opponent, 0) / total_opp_actions
            if coop_rate > 0.6:
                return True
            elif coop_rate < 0.4:
                return False

        # If we've interacted many times, use trust
        if self.interaction_count.get(opponent, 0) >= 10:
            trust = self.trust.get(opponent, 0.5)
            if trust > 0.7:
                return True
            elif trust < 0.3:
                return False

        # Default: cooperate with some randomness based on reputation
        rep = self.reputation.get(opponent, 0.0)
        if rep > 0.5:
            return True
        elif rep < -0.5:
            return False
        else:
            return random.random() < 0.6

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Track generation and round
        self.round_in_generation += 1
        if self.round_in_generation > self.rounds_per_generation:
            self.round_in_generation = 1
            self.generation += 1
            # At generation change, maybe reset some state
            if self.generation % 5 == 0:
                # Soft reset to adapt to new opponents
                for opp in list(self.trust.keys()):
                    self.trust[opp] = self.trust[opp] * 0.5 + 0.25

        # Update my own history
        if donor_id == self.agent_id:
            self.my_history.append(donor_action == 'cooperate')
            self.my_recent_actions.append(donor_action == 'cooperate')
            if len(self.my_recent_actions) > 10:
                self.my_recent_actions.pop(0)
        if recipient_id == self.agent_id:
            self.my_history.append(recipient_action == 'cooperate')
            self.my_recent_actions.append(recipient_action == 'cooperate')
            if len(self.my_recent_actions) > 10:
                self.my_recent_actions.pop(0)

        # Update opponent info
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            # Third-party observation: update reputation of both
            self._update_reputation(donor_id, donor_action)
            self._update_reputation(recipient_id, recipient_action)
        else:
            # Self-observation: update my own and opponent's info
            if donor_id == self.agent_id:
                # I was donor
                opp = recipient_id
                action = recipient_action
                self._update_opponent_info(opp, action)
                # My action also affects my reputation
                my_action = donor_action
            elif recipient_id == self.agent_id:
                # I was recipient
                opp = donor_id
                action = donor_action
                self._update_opponent_info(opp, action)
                my_action = recipient_action
            else:
                # Shouldn't happen
                return

            # If I was in the pair, also update my own reputation
            if donor_id == self.agent_id:
                self._update_reputation(self.agent_id, donor_action)
            if recipient_id == self.agent_id:
                self._update_reputation(self.agent_id, recipient_action)

    def _update_reputation(self, agent_id: int, action: str) -> None:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.0
        if action == 'cooperate':
            self.reputation[agent_id] = min(1.0, self.reputation[agent_id] + 0.05)
        else:
            self.reputation[agent_id] = max(-1.0, self.reputation[agent_id] - 0.1)

    def _update_opponent_info(self, opponent: int, action: str) -> None:
        if opponent not in self.interaction_count:
            self.interaction_count[opponent] = 0
            self.opponent_history[opponent] = []
            self.trust[opponent] = 0.5
            self.defection_count[opponent] = 0
            self.cooperation_count[opponent] = 0
            self.opponent_recent_actions[opponent] = []

        self.interaction_count[opponent] += 1
        self.opponent_history[opponent].append(action == 'cooperate')
        if action == 'cooperate':
            self.cooperation_count[opponent] += 1
            # Increase trust
            self.trust[opponent] = min(1.0, self.trust[opponent] + 0.1)
        else:
            self.defection_count[opponent] += 1
            # Decrease trust
            self.trust[opponent] = max(0.0, self.trust[opponent] - 0.15)

        self.opponent_recent_actions[opponent].append(action == 'cooperate')
        if len(self.opponent_recent_actions[opponent]) > 10:
            self.opponent_recent_actions[opponent].pop(0)

