        opp_rep = self.reputation.get(opponent, 0.5)
        # Personal history with opponent
        hist = self.opponent_history.get(opponent, [])

        # Start cooperative, but adapt based on reputation and history
        if not hist:
            # First encounter: cooperate if opponent has decent reputation
            return opp_rep >= 0.4
        else:
            # Check opponent's last action against us
            last_opp_action = hist[-1]
            if last_opp_action == 'cooperate':
                # If they cooperated last time, likely cooperate
                if opp_rep >= 0.3:
                    return True
                else:
                    # Low rep but cooperated - give benefit of doubt
                    return True
            else:
                # They defected last time - defect unless very high rep
                if opp_rep >= 0.8:
                    return True
                else:
                    return False

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Update reputations based on observed actions
        if donor_id != self.agent_id:
            # Update donor reputation: cooperating increases, defecting decreases
            if donor_action == 'cooperate':
                self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) + 0.1
            else:
                self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) - 0.15
        if recipient_id != self.agent_id:
            # Recipient actions also reflect character
            if recipient_action == 'cooperate':
                self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) + 0.1
            else:
                self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) - 0.15

        # Clamp reputation to [0,1]
        for key in list(self.reputation.keys()):
            self.reputation[key] = max(0.0, min(1.0, self.reputation[key]))

        # Track our own actions and opponent history if involved
        if donor_id == self.agent_id:
            self.last_action = donor_action
            if donor_action == 'cooperate':
                self.cooperation_count += 1
                self.coop_streak += 1
                self.defect_streak = 0
            else:
                self.defection_count += 1
                self.defect_streak += 1
                self.coop_streak = 0
            # Record what we did to opponent
            if recipient_id in self.opponent_history:
                self.opponent_history[recipient_id].append('cooperate' if donor_action == 'cooperate' else 'defect')
            else:
                self.opponent_history[recipient_id] = ['cooperate' if donor_action == 'cooperate' else 'defect']
        elif recipient_id == self.agent_id:
            # Record opponent's action
            if donor_id in self.opponent_history:
                self.opponent_history[donor_id].append(donor_action)
            else:
                self.opponent_history[donor_id] = [donor_action]
            # Track our own action as recipient? We didn't choose, but we know what we did from decide
            # Actually we don't have that info here, but we can infer from last_action? Not reliable.
            # We'll rely on donor_id == self check for our actions.
        # Third-party observations: just reputation update already done

    # Helper to get opponent from context (provided by framework)
    @property
    def _ctx_opponent_id(self):
        return self._opponent_id if hasattr(self, '_opponent_id') else -1

