class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.partner_history = {}
        self.my_history = {}
        self.generation = 0
        self.round = 0
        self.total_coop = 0
        self.total_defect = 0
        self.last_opponent = None
        self.last_round_opponent = None
        self.opponent_coop_count = {}
        self.opponent_defect_count = {}
        self.memory = {}
        self.trust_threshold = 0.3
        self.coop_probability = 0.5
        self.defection_penalty = 0.2
        self.cooperation_bonus = 0.1
        self.initial_trust = 0.5
        self.alpha = 0.2
        self.beta = 0.1
        self.gamma = 0.15
        self.delta = 0.05

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        self.last_opponent = opponent
        self.round += 1

        # Initialize memory for this opponent if not seen before
        if opponent not in self.reputation:
            self.reputation[opponent] = self.initial_trust
            self.opponent_coop_count[opponent] = 0
            self.opponent_defect_count[opponent] = 0
            self.partner_history[opponent] = []

        # Compute current trust based on observed behavior
        trust = self.reputation[opponent]

        # Adjust trust based on recent interactions with this opponent
        if opponent in self.partner_history and len(self.partner_history[opponent]) > 0:
            recent = self.partner_history[opponent][-5:]  # look at last 5 interactions
            coop_rate = sum(1 for action in recent if action == 'cooperate') / len(recent)
            trust = 0.3 * trust + 0.7 * coop_rate

        # Consider global reputation and my own past behavior
        global_avg_coop = 0
        if len(self.reputation) > 0:
            global_avg_coop = sum(self.reputation.values()) / len(self.reputation)

        # Simple strategy: cooperate if trust is above threshold, otherwise defect
        # Add some randomness to avoid being too predictable
        threshold = self.trust_threshold + self.delta * (self.round % 3)

        if trust > threshold:
            # More likely to cooperate if trust is high
            if random.random() < 0.9:
                return True
            else:
                return False
        else:
            # Sometimes cooperate even with low trust to probe
            if random.random() < 0.1:
                return True
            else:
                return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation based on observed actions
        # If I'm the donor, update my own history
        if donor_id == self.agent_id:
            self.my_history[recipient_id] = donor_action
            self.total_coop += (donor_action == 'cooperate')
            self.total_defect += (donor_action == 'defect')
        elif recipient_id == self.agent_id:
            # I was the recipient - record what donor did to me
            if donor_id not in self.opponent_coop_count:
                self.opponent_coop_count[donor_id] = 0
                self.opponent_defect_count[donor_id] = 0
                self.reputation[donor_id] = self.initial_trust
            if donor_action == 'cooperate':
                self.opponent_coop_count[donor_id] += 1
                self.reputation[donor_id] = min(1.0, self.reputation[donor_id] + self.cooperation_bonus)
            else:
                self.opponent_defect_count[donor_id] += 1
                self.reputation[donor_id] = max(0.0, self.reputation[donor_id] - self.defection_penalty)

        # Third-party observation: update reputation of both donor and recipient
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            # Update donor reputation
            if donor_id not in self.reputation:
                self.reputation[donor_id] = self.initial_trust
            if donor_action == 'cooperate':
                self.reputation[donor_id] = min(1.0, self.reputation[donor_id] + self.alpha)
            else:
                self.reputation[donor_id] = max(0.0, self.reputation[donor_id] - self.beta)

            # Update recipient reputation (if they cooperated, good; if defected, bad)
            if recipient_id not in self.reputation:
                self.reputation[recipient_id] = self.initial_trust
            if recipient_action == 'cooperate':
                self.reputation[recipient_id] = min(1.0, self.reputation[recipient_id] + self.gamma)
            else:
                self.reputation[recipient_id] = max(0.0, self.reputation[recipient_id] - self.delta)

        # Record direct interaction if this was my own game
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            other_id = recipient_id if donor_id == self.agent_id else donor_id
            other_action = recipient_action if donor_id == self.agent_id else donor_action
            if other_id not in self.partner_history:
                self.partner_history[other_id] = []
            self.partner_history[other_id].append(other_action)
            # Keep only recent history
            if len(self.partner_history[other_id]) > 20:
                self.partner_history[other_id] = self.partner_history[other_id][-20:]

        # Occasionally adjust trust threshold based on overall environment
        if self.round % 10 == 0:
            if self.total_coop + self.total_defect > 0:
                my_coop_rate = self.total_coop / (self.total_coop + self.total_defect)
                if my_coop_rate < 0.3:
                    self.trust_threshold = max(0.1, self.trust_threshold - 0.05)
                elif my_coop_rate > 0.7:
                    self.trust_threshold = min(0.9, self.trust_threshold + 0.05)

