        # Add generosity as an extra boost: more generous agents cooperate more
        rep_diff = self.reputation[opp] - threshold
        prob_coop = 1.0 / (1.0 + math.exp(-5 * (rep_diff + 0.3 * self.forgiveness[opp] + 0.2 * self.generosity[opp])))
        return random.random() < prob_coop

