                        self.coop_counts[agent_id] = int(self.coop_counts[agent_id] * self.reputation_decay) + 1
                    else:
                        self.coop_counts[agent_id] = 1
                # Update baseline as a moving average
                if agent_id in self.baseline_coop:
                    self.baseline_coop[agent_id] = 0.9 * self.baseline_coop[agent_id] + 0.1 * (1 if action == 'cooperate' else 0)
                else:
                    self.baseline_coop[agent_id] = 1 if action == 'cooperate' else 0

        # Record own interactions
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                my_action = donor_action == 'cooperate'
                opp = recipient_id
                opp_action = recipient_action == 'cooperate'
            else:
                my_action = recipient_action == 'cooperate'
                opp = donor_id
                opp_action = donor_action == 'cooperate'

            if opp not in self.interaction_history:
                self.interaction_history[opp] = deque(maxlen=100)
            self.interaction_history[opp].append((my_action, opp_action))

