        if opp not in self.rep_momentum:
            self.rep_momentum[opp] = 0.0

        obs_coop, obs_def = self.observed_counts[opp]
        total_obs = obs_coop + obs_def
        obs_rate = obs_coop / total_obs if total_obs > 0 else 0.5

        my_hist = self.interactions[opp]
        if my_hist:
            my_coop = sum(1 for a, b in my_hist if a == 'cooperate')
            my_rate = my_coop / len(my_hist)
        else:
            my_rate = 0.5

        blend = 0.7 * obs_rate + 0.3 * my_rate

        # New: momentum-based reputation update (faster convergence)
        target = 0.9 * self.reputation[opp] + 0.1 * blend + 0.05 * self.forgiveness[opp]
        self.rep_momentum[opp] = 0.8 * self.rep_momentum[opp] + 0.2 * (target - self.reputation[opp])
        self.reputation[opp] += self.rep_momentum[opp]
        self.reputation[opp] = max(0.0, min(1.0, self.reputation[opp]))

        recent = my_hist[-5:] if len(my_hist) >= 5 else my_hist
        if len(recent) >= 2:
