            decayed_total = 0
            decayed_coop = 0
            # Recompute with decay (simplified: use a weighted sum from stored history)
            # For simplicity, use a decay factor on the raw ratio
            raw_coop = self.coop_counts.get(opp, 0) / self.total_counts[opp]
            # Blend with a baseline to handle sparse data
            baseline = self.baseline_coop.get(opp, 0.5)
            coop_rate = self.reputation_decay * raw_coop + (1 - self.reputation_decay) * baseline

        # Personal interaction history
        hist = self.interaction_history.get(opp, [])
        if len(hist) > 0:
            recent = list(hist)[-self.recent_window:]
            my_coop = sum(1 for a, b in recent if a)
            other_coop = sum(1 for a, b in recent if b)
            my_rate = my_coop / len(recent) if recent else 0.5
            other_rate = other_coop / len(recent) if recent else 0.5
            combined = 0.4 * coop_rate + 0.6 * other_rate
        else:
            combined = coop_rate

        noise = random.uniform(-0.05, 0.05)
        combined += noise

        # Win-stay lose-shift adjustment (unchanged)
        if opp in self.win_stay_memory:
            last_outcome = self.win_stay_memory[opp]
            if last_outcome == 'win':
                combined += 0.1
            else:
