            if own_coop_rate < 0.3:
                threshold = self.coop_threshold - self.forgiveness
            else:
                threshold = self.coop_threshold
        else:
            threshold = self.coop_threshold

        # Adaptive threshold with decay-based reputation
        threshold += (0.5 - coop_rate) * self.threshold_adaptation

        return combined >= threshold

