from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.interaction_history = {}
        self.last_opponent_action = None
        self.own_recent_actions = deque(maxlen=10)
        self.generosity = 0.5
        self.trust_threshold = 0.3
        self.forgetting = 0.9
        self.rounds_played = 0
        self.punish_threshold = 2
        self.current_opponent_defections = 0
        self.recent_opponent_actions = deque(maxlen=5)
        # New: Track opponent's cooperation streak (consecutive cooperations)
        self.opponent_cooperation_streak = 0
        # New: Track our own cooperation streak
        self.own_cooperation_streak = 0
        # New: Adaptive generosity based on streak length
        self.streak_bonus = 0.0

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True

        rep = self.reputation.get(opponent, [0, 0])
        coop_count, defect_count = rep[0], rep[1]
        total = coop_count + defect_count
        if total > 0:
            coop_ratio = coop_count / total
        else:
            coop_ratio = 0.5

        history = self.interaction_history.get(opponent, deque())

        # If we have a recent cooperation streak with this opponent, be more generous
        if self.opponent_cooperation_streak >= 2:
            return True

        # If we have history, use reciprocity with streak awareness
        if len(history) > 0:
            recent = list(history)[-3:]
            their_coop = sum(1 for a in recent if a) / len(recent)
            if their_coop >= 0.5:
                return True
            else:
                # If they defected, but we have a good streak, give a second chance
                if self.opponent_cooperation_streak >= 1:
                    return random.random() < 0.4
                return random.random() < 0.2

        # Reputation-based decision with streak bonus
        if total >= 3:
            if coop_ratio >= self.trust_threshold:
                return True
            else:
                return random.random() < 0.1 + self.streak_bonus

        # Unknown opponent: use generosity plus streak bonus
        if self.rounds_played < 5:
            return True
        else:
            return random.random() < min(1.0, self.generosity + self.streak_bonus)

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        donor_rep = self.reputation.get(donor_id, [0, 0])
        if donor_action == 'cooperate':
            donor_rep[0] += 1
        else:
            donor_rep[1] += 1
        donor_rep[0] = max(1, int(donor_rep[0] * self.forgetting))
        donor_rep[1] = max(1, int(donor_rep[1] * self.forgetting))
        self.reputation[donor_id] = donor_rep

        recipient_rep = self.reputation.get(recipient_id, [0, 0])
        if recipient_action == 'cooperate':
            recipient_rep[0] += 1
        else:
            recipient_rep[1] += 1
        recipient_rep[0] = max(1, int(recipient_rep[0] * self.forgetting))
        recipient_rep[1] = max(1, int(recipient_rep[1] * self.forgetting))
        self.reputation[recipient_id] = recipient_rep

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                opponent = recipient_id
                opponent_action = recipient_action
                my_action = donor_action
            else:
                opponent = donor_id
                opponent_action = donor_action
                my_action = recipient_action

            if opponent not in self.interaction_history:
                self.interaction_history[opponent] = deque(maxlen=10)
            self.interaction_history[opponent].append(opponent_action == 'cooperate')

            self.own_recent_actions.append(my_action == 'cooperate')

            # Update streaks and streak bonus
            if opponent_action == 'cooperate':
                self.opponent_cooperation_streak += 1
            else:
                self.opponent_cooperation_streak = 0

            if my_action == 'cooperate':
                self.own_cooperation_streak += 1
            else:
                self.own_cooperation_streak = 0

            # Streak bonus: more generous if both we and opponent are cooperating
            self.streak_bonus = min(0.3, 0.05 * min(self.opponent_cooperation_streak, self.own_cooperation_streak))

            # Update generosity with streak considerations
            if my_action == 'cooperate' and opponent_action == 'defect':
                self.generosity = max(0.1, self.generosity - 0.05)
            elif my_action == 'cooperate' and opponent_action == 'cooperate':
                self.generosity = min(0.9, self.generosity + 0.02 + self.streak_bonus * 0.1)
            elif my_action == 'defect' and opponent_action == 'cooperate':
                self.generosity = min(0.9, self.generosity + 0.03)

            if opponent_action == 'defect':
                self.current_opponent_defections += 1
            else:
                self.current_opponent_defections = 0

            if self.current_opponent_defections >= self.punish_threshold:
                self.generosity = max(0.1, self.generosity - 0.1)
                self.current_opponent_defections = 0

            self.recent_opponent_actions.append(opponent_action == 'cooperate')

            if len(self.recent_opponent_actions) == 5:
                coop_fraction = sum(self.recent_opponent_actions) / 5
                if coop_fraction < 0.5:
                    self.trust_threshold = min(0.9, self.trust_threshold + 0.05)
                else:
                    self.trust_threshold = max(0.1, self.trust_threshold - 0.05)

            self.rounds_played += 1

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.coop_counts = {}
        self.total_counts = {}
        self.own_history = []
        self.interaction_history = {}
        self.round_count = 0
        self._ctx_opponent_id = None
        self.coop_threshold = 0.5
        self.recent_window = 10
        self.recent_own_actions = deque(maxlen=50)
        self.forgiveness = 0.3
        self.win_stay_memory = {}
        self.threshold_adaptation = 0.05
        self.reputation_decay = 0.95
        self.baseline_coop = {}
        # NEW: Track emotional state (anger) per opponent, decays over time
        self.anger = {}
        self.anger_decay = 0.9
        self.anger_threshold = 0.6

    def decide(self) -> bool:
        if self._ctx_opponent_id is None:
            return True
        opp = self._ctx_opponent_id

        # Get opponent's reputation with decay applied
        coop_rate = 0.5
        if self.total_counts.get(opp, 0) > 0:
            raw_coop = self.coop_counts.get(opp, 0) / self.total_counts[opp]
            baseline = self.baseline_coop.get(opp, 0.5)
            coop_rate = self.reputation_decay * raw_coop + (1 - self.reputation_decay) * baseline

        # Personal interaction history
        hist = self.interaction_history.get(opp, [])
        if len(hist) > 0:
            recent = list(hist)[-self.recent_window:]
            my_coop = sum(1 for a, b in recent if a)
            other_coop = sum(1 for a, b in recent if b)
            my_rate = my_coop / len(recent) if recent else 0.5
            other_rate = other_coop / len(recent) if recent else 0.5
            combined = 0.4 * coop_rate + 0.6 * other_rate
        else:
            combined = coop_rate

        noise = random.uniform(-0.05, 0.05)
        combined += noise

        # Win-stay lose-shift adjustment (unchanged)
        if opp in self.win_stay_memory:
            last_outcome = self.win_stay_memory[opp]
            if last_outcome == 'win':
                combined += 0.1
            else:
                combined -= 0.1

        # NEW: Anger-based penalty if opponent recently defected against us
        if opp in self.anger:
            combined -= self.anger[opp] * 0.5

        # Own recent behavior adjustment
        if self.recent_own_actions:
            own_coop_rate = sum(self.recent_own_actions[-self.recent_window:]) / len(self.recent_own_actions[-self.recent_window:])
            if own_coop_rate < 0.3:
                threshold = self.coop_threshold - self.forgiveness
            else:
                threshold = self.coop_threshold
        else:
            threshold = self.coop_threshold

        # Adaptive threshold with decay-based reputation
        threshold += (0.5 - coop_rate) * self.threshold_adaptation

        return combined >= threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update counts with decay applied to existing counts
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id != self.agent_id:
                if agent_id in self.total_counts:
                    self.total_counts[agent_id] = int(self.total_counts[agent_id] * self.reputation_decay) + 1
                else:
                    self.total_counts[agent_id] = 1
                if action == 'cooperate':
                    if agent_id in self.coop_counts:
                        self.coop_counts[agent_id] = int(self.coop_counts[agent_id] * self.reputation_decay) + 1
                    else:
                        self.coop_counts[agent_id] = 1
                if agent_id in self.baseline_coop:
                    self.baseline_coop[agent_id] = 0.9 * self.baseline_coop[agent_id] + 0.1 * (1 if action == 'cooperate' else 0)
                else:
                    self.baseline_coop[agent_id] = 1 if action == 'cooperate' else 0

        # Record own interactions and update anger
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                my_action = donor_action == 'cooperate'
                opp = recipient_id
                opp_action = recipient_action == 'cooperate'
            else:
                my_action = recipient_action == 'cooperate'
                opp = donor_id
                opp_action = donor_action == 'cooperate'

            if opp not in self.interaction_history:
                self.interaction_history[opp] = deque(maxlen=100)
            self.interaction_history[opp].append((my_action, opp_action))

            self.recent_own_actions.append(my_action)

            if my_action == opp_action:
                self.win_stay_memory[opp] = 'win'
            else:
                self.win_stay_memory[opp] = 'lose'

            # NEW: Anger update - increase when opponent defects, decay otherwise
            if opp not in self.anger:
                self.anger[opp] = 0.0
            self.anger[opp] *= self.anger_decay
            if not opp_action:
                self.anger[opp] += 0.3
            if self.anger[opp] > 1.0:
                self.anger[opp] = 1.0

            self.round_count += 1

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Reputation scores: agent_id -> [cooperation count, defection count]
        self.reputation = {}
        # Cooperation history with each agent: agent_id -> deque of bool (True if we cooperated)
        self.interaction_history = {}
        # Track opponent's last action for each round
        self.last_opponent_action = None
        # Track our own recent actions as a deque
        self.own_recent_actions = deque(maxlen=10)
        # Generosity: initial tendency to cooperate, will adjust based on experience
        self.generosity = 0.5
        # Trust threshold: how much reputation needed to trust
        self.trust_threshold = 0.3
        # Forgetting factor: how much weight to give past observations
        self.forgetting = 0.9
        # Track rounds played
        self.rounds_played = 0
        # New: punishment threshold - how many defections before we punish
        self.punish_threshold = 2
        # New: recent defection counter for current opponent
        self.current_opponent_defections = 0
        # New: mood state (positive, neutral, negative) to modulate behavior
        self.mood = 'neutral'
        # New: memory of cooperation rate from all observed interactions
        self.global_coop_rate = 0.5

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True  # Safety fallback

        # Update opponent's reputation based on what we know
        rep = self.reputation.get(opponent, [0, 0])
        coop_count, defect_count = rep[0], rep[1]
        total = coop_count + defect_count
        if total > 0:
            coop_ratio = coop_count / total
        else:
            coop_ratio = 0.5  # Unknown opponent, assume neutral

        # Check if we have history with this opponent
        history = self.interaction_history.get(opponent, deque())

        # If we've played with them before, use reciprocity
        if len(history) > 0:
            # Use last 3 interactions for reciprocity
            recent = list(history)[-3:]
            their_coop = sum(1 for a in recent if a) / len(recent)
            # Tit-for-tat with forgiveness: cooperate if they cooperated recently
            if their_coop >= 0.5:
                # Mood boost: if in positive mood, more likely to cooperate
                if self.mood == 'positive':
                    return True
                else:
                    return True
            else:
                # If they defected recently, be more cautious but still occasionally forgive
                # Mood affects forgiveness: negative mood less forgiving
                if self.mood == 'negative':
                    return random.random() < 0.05
                else:
                    return random.random() < 0.2

        # If we have reputation info, use it
        if total >= 3:  # Need enough observations to be reliable
            if coop_ratio >= self.trust_threshold:
                return True
            else:
                # Defect against known defectors, but sometimes test them
                return random.random() < 0.1

        # For unknown or insufficient info, base on our generosity
        # Early game: more generous, later: more cautious
        if self.rounds_played < 5:
            return True
        else:
            # Mood modulates base generosity
            if self.mood == 'positive':
                return random.random() < min(0.9, self.generosity + 0.15)
            elif self.mood == 'negative':
                return random.random() < max(0.0, self.generosity - 0.15)
            else:
                return random.random() < self.generosity

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Update reputation for donor
        donor_rep = self.reputation.get(donor_id, [0, 0])
        if donor_action == 'cooperate':
            donor_rep[0] += 1
        else:
            donor_rep[1] += 1
        # Apply forgetting to existing counts (but keep at least 1)
        donor_rep[0] = max(1, int(donor_rep[0] * self.forgetting))
        donor_rep[1] = max(1, int(donor_rep[1] * self.forgetting))
        self.reputation[donor_id] = donor_rep

        # Update reputation for recipient
        recipient_rep = self.reputation.get(recipient_id, [0, 0])
        if recipient_action == 'cooperate':
            recipient_rep[0] += 1
        else:
            recipient_rep[1] += 1
        recipient_rep[0] = max(1, int(recipient_rep[0] * self.forgetting))
        recipient_rep[1] = max(1, int(recipient_rep[1] * self.forgetting))
        self.reputation[recipient_id] = recipient_rep

        # Update global cooperation rate from all observed interactions
        # Use a moving average with small weight
        if donor_action == 'cooperate':
            self.global_coop_rate = self.global_coop_rate * 0.98 + 0.02
        else:
            self.global_coop_rate = self.global_coop_rate * 0.98 + 0.0
        if recipient_action == 'cooperate':
            self.global_coop_rate = self.global_coop_rate * 0.98 + 0.02
        else:
            self.global_coop_rate = self.global_coop_rate * 0.98 + 0.0

        # If this is our own interaction, update history and learning
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # Determine opponent and their action
            if donor_id == self.agent_id:
                opponent = recipient_id
                opponent_action = recipient_action
                my_action = donor_action
            else:
                opponent = donor_id
                opponent_action = donor_action
                my_action = recipient_action

            # Update interaction history using deque
            if opponent not in self.interaction_history:
                self.interaction_history[opponent] = deque(maxlen=10)
            # Record what opponent did (True if cooperate)
            self.interaction_history[opponent].append(opponent_action == 'cooperate')

            # Track our own recent actions
            self.own_recent_actions.append(my_action == 'cooperate')

            # Update generosity based on outcomes
            # If we cooperated and they defected, reduce generosity
            if my_action == 'cooperate' and opponent_action == 'defect':
                self.generosity = max(0.1, self.generosity - 0.05)
            # If we both cooperated, slightly increase generosity
            elif my_action == 'cooperate' and opponent_action == 'cooperate':
                self.generosity = min(0.9, self.generosity + 0.02)
            # If we defected and they cooperated, they were nice - maybe be more generous
            elif my_action == 'defect' and opponent_action == 'cooperate':
                self.generosity = min(0.9, self.generosity + 0.03)

            # New: track defections against us and reset when we cooperate with them
            if opponent_action == 'defect':
                self.current_opponent_defections += 1
            else:
                self.current_opponent_defections = 0

            # New: if opponent defects too many times, we become more cautious
            if self.current_opponent_defections >= self.punish_threshold:
                self.generosity = max(0.1, self.generosity - 0.1)
                self.current_opponent_defections = 0

            # New: update mood based on outcome of our interaction
            if my_action == 'cooperate' and opponent_action == 'defect':
                # Betrayed - become negative
                self.mood = 'negative'
            elif my_action == 'defect' and opponent_action == 'cooperate':
                # We exploited - become positive
                self.mood = 'positive'
            elif my_action == 'cooperate' and opponent_action == 'cooperate':
                # Mutual cooperation - stay positive if already, else neutral
                if self.mood == 'negative':
                    self.mood = 'neutral'
                else:
                    self.mood = 'positive'
            elif my_action == 'defect' and opponent_action == 'defect':
                # Mutual defection - stay negative if already, else neutral
                if self.mood == 'positive':
                    self.mood = 'neutral'
                else:
                    self.mood = 'negative'

            # New: mood decays over time (towards neutral)
            if self.mood == 'positive' and random.random() < 0.2:
                self.mood = 'neutral'
            elif self.mood == 'negative' and random.random() < 0.2:
                self.mood = 'neutral'

            self.rounds_played += 1

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.interactions = {}
        self.observed_counts = {}
        self.coop_rate = {}
        self.round_count = 0
        self.my_recent_actions = []
        self.opp_recent_actions = []
        self._ctx_opponent_id = None
        self.trust_threshold = 0.5
        self.opp_history = {}
        # New: track a per-opponent forgiveness level (0-1)
        self.forgiveness = {}
        # New: track recent opponent actions as a deque for fast sliding window
        self.recent_opp_actions = {}
        # New: momentum term for reputation update
        self.rep_momentum = {}
        # New: track cooperation streaks for alternative memory
        self.coop_streaks = {}

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return True

        if opp not in self.reputation:
            self.reputation[opp] = 0.5
        if opp not in self.interactions:
            self.interactions[opp] = []
        if opp not in self.observed_counts:
            self.observed_counts[opp] = [0, 0]
        if opp not in self.coop_rate:
            self.coop_rate[opp] = 0.5
        if opp not in self.forgiveness:
            self.forgiveness[opp] = 0.5
        if opp not in self.recent_opp_actions:
            self.recent_opp_actions[opp] = deque(maxlen=10)
        if opp not in self.rep_momentum:
            self.rep_momentum[opp] = 0.0
        if opp not in self.coop_streaks:
            self.coop_streaks[opp] = 0

        obs_coop, obs_def = self.observed_counts[opp]
        total_obs = obs_coop + obs_def
        obs_rate = obs_coop / total_obs if total_obs > 0 else 0.5

        my_hist = self.interactions[opp]
        if my_hist:
            my_coop = sum(1 for a, b in my_hist if a == 'cooperate')
            my_rate = my_coop / len(my_hist)
        else:
            my_rate = 0.5

        blend = 0.7 * obs_rate + 0.3 * my_rate

        # New: momentum-based reputation update (faster convergence)
        target = 0.9 * self.reputation[opp] + 0.1 * blend + 0.05 * self.forgiveness[opp]
        self.rep_momentum[opp] = 0.8 * self.rep_momentum[opp] + 0.2 * (target - self.reputation[opp])
        self.reputation[opp] += self.rep_momentum[opp]
        self.reputation[opp] = max(0.0, min(1.0, self.reputation[opp]))

        recent = my_hist[-5:] if len(my_hist) >= 5 else my_hist
        if len(recent) >= 2:
            betrayals = sum(1 for i in range(len(recent)-1) if recent[i][0] == 'cooperate' and recent[i+1][1] == 'defect')
            if betrayals >= 2:
                # Punish but slightly less due to forgiveness
                self.reputation[opp] -= 0.08 * (1 - self.forgiveness[opp])

        gen_factor = math.exp(-self.round_count / 30.0)
        threshold = 0.4 + 0.2 * gen_factor

        # New: incorporate recent opponent actions directly (short-term memory)
        recent_opp = self.recent_opp_actions[opp]
        short_term_coop = sum(1 for a in recent_opp if a == 'cooperate') / len(recent_opp) if recent_opp else 0.5
        rep_diff = self.reputation[opp] - threshold + 0.2 * (short_term_coop - 0.5)

        # New: use cooperation streak to boost cooperation probability (alternative memory)
        streak_bonus = min(self.coop_streaks[opp], 5) * 0.05
        prob_coop = 1.0 / (1.0 + math.exp(-5 * (rep_diff + 0.3 * self.forgiveness[opp] + streak_bonus)))
        return random.random() < prob_coop

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.observed_counts:
                self.observed_counts[agent_id] = [0, 0]
            if action == 'cooperate':
                self.observed_counts[agent_id][0] += 1
            else:
                self.observed_counts[agent_id][1] += 1

        if donor_id == self.agent_id:
            opp = recipient_id
            my_action = donor_action
            their_action = recipient_action
        elif recipient_id == self.agent_id:
            opp = donor_id
            my_action = recipient_action
            their_action = donor_action
        else:
            return

        if opp not in self.interactions:
            self.interactions[opp] = []
        self.interactions[opp].append((my_action, their_action))
        if len(self.interactions[opp]) > 20:
            self.interactions[opp] = self.interactions[opp][-20:]

        if opp not in self.opp_history:
            self.opp_history[opp] = []
        self.opp_history[opp].append(their_action)
        if len(self.opp_history[opp]) > 10:
            self.opp_history[opp] = self.opp_history[opp][-10:]

        self.round_count += 1

        self.my_recent_actions.append(my_action)
        if len(self.my_recent_actions) > 10:
            self.my_recent_actions.pop(0)
        self.opp_recent_actions.append(their_action)
        if len(self.opp_recent_actions) > 10:
            self.opp_recent_actions.pop(0)

        # New: update recent_opp_actions deque for this opponent
        if opp not in self.recent_opp_actions:
            self.recent_opp_actions[opp] = deque(maxlen=10)
        self.recent_opp_actions[opp].append(their_action)

        # Update forgiveness based on recent interactions with this opponent
        if opp not in self.forgiveness:
            self.forgiveness[opp] = 0.5
        recent_opp = self.interactions[opp][-5:] if len(self.interactions[opp]) >= 5 else self.interactions[opp]
        if recent_opp:
            coop_count = sum(1 for a, b in recent_opp if b == 'cooperate')
            # Forgiveness increases when opponent cooperates, decreases when defects
            self.forgiveness[opp] = 0.9 * self.forgiveness[opp] + 0.1 * (coop_count / len(recent_opp))
            self.forgiveness[opp] = max(0.0, min(1.0, self.forgiveness[opp]))

        # New: update cooperation streak (reset on defection, increment on cooperation)
        if opp not in self.coop_streaks:
            self.coop_streaks[opp] = 0
        if their_action == 'cooperate':
            self.coop_streaks[opp] += 1
        else:
            self.coop_streaks[opp] = 0

        # Adjust trust threshold based on overall population cooperation (modified)
        if self.my_recent_actions and self.opp_recent_actions:
            betrayals = 0
            for i in range(min(len(self.my_recent_actions)-1, len(self.opp_recent_actions)-1)):
