        def update_trust(agent_id, action):
            trust = self.trust_belief.get(agent_id, 0.5)
            # Update with a simple reinforcement: cooperate increases trust, defect decreases
            if action == 'cooperate':
                trust = trust + 0.1 * (1 - trust)
            else:
                trust = trust - 0.1 * trust
            # Apply decay to gradually forget old beliefs
            trust *= self.trust_decay
            # Keep in [0,1]
            trust = max(0.0, min(1.0, trust))
            self.trust_belief[agent_id] = trust

        # Update trust for donor and recipient
        update_trust(donor_id, donor_action)
        update_trust(recipient_id, recipient_action)

        # Update observation count
        self.observation_count[donor_id] = self.observation_count.get(donor_id, 0) + 1
        self.observation_count[recipient_id] = self.observation_count.get(recipient_id, 0) + 1

        # Update reputation with momentum (same as parent)
        def update_rep(agent_id, delta):
            current_rep = self.reputation.get(agent_id, 0)
            mom = self.reputation_momentum.get(agent_id, 0.0)
