        self.interactions = {}
        self.defected_against = set()
        self._ctx_opponent_id = None
        self.generation = 0
        self.rng = random.Random(agent_id * 12345)
        self.recent_outcomes = []
        self.reputation_momentum = {}
        self.forgiveness = {}
        # NEW: Track a belief about opponent's trustworthiness as a probability
        self.trust_belief = {}
        # NEW: Track the number of times we have observed each agent
        self.observation_count = {}
        # NEW: Track a decay factor for trust updates
        self.trust_decay = 0.95
        # NEW: Track the number of times we have cooperated with each agent
        self.coop_with = {}
        # NEW: Track the number of times we have defected with each agent
        self.defect_with = {}

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return True

        opp_rep = self.reputation.get(opp, 0)
        my_rep = self.reputation.get(self.agent_id, 0)

        # Use trust belief as a prior probability of cooperation
        trust = self.trust_belief.get(opp, 0.5)

        # Blend trust with observed cooperation rate
        coop = self.coop_count.get(opp, 0)
        defect = self.defect_count.get(opp, 0)
        if coop + defect > 0:
            observed_rate = coop / (coop + defect)
        else:
            observed_rate = 0.5

        # Weight trust more heavily when we have few observations
        obs_count = self.observation_count.get(opp, 0)
        weight_trust = 1.0 / (1.0 + obs_count * 0.2)
        cooperation_rate = weight_trust * trust + (1 - weight_trust) * observed_rate

        # Look at recent interaction history
        hist = self.interactions.get(opp, [])
        if hist:
            recent = hist[-5:]
            opp_coop = sum(1 for _, a in recent if a)
            opp_defect = sum(1 for _, a in recent if not a)
            if opp_coop + opp_defect > 0:
                recent_rate = opp_coop / (opp_coop + opp_defect)
                cooperation_rate = 0.7 * recent_rate + 0.3 * cooperation_rate

        # Count defections against us
        if hist:
            opp_def_against_us = sum(1 for my_a, opp_a in hist if not opp_a)
        else:
            opp_def_against_us = 0

        # Apply forgiveness
        forgiv = self.forgiveness.get(opp, 0)
        if forgiv > 0:
            opp_def_against_us = max(0, opp_def_against_us - forgiv)

        # Decision rules
        if opp_def_against_us >= 3:
            return False

        if opp_rep < -2:
            return False

        if cooperation_rate > 0.6:
            return True

        if cooperation_rate < 0.4:
            return False

        if my_rep < -3:
            if opp_rep < 0:
                return False
            else:
                return True

        # NEW: Sometimes cooperate despite low trust to test opponent (exploration)
        if cooperation_rate < 0.5 and self.rng.random() < 0.1:
            return True

        return opp_rep >= 0

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # NEW: Update trust belief based on observed actions using a Bayesian-like update
        def update_trust(agent_id, action):
            trust = self.trust_belief.get(agent_id, 0.5)
            # Update with a simple reinforcement: cooperate increases trust, defect decreases
            if action == 'cooperate':
                trust = trust + 0.1 * (1 - trust)
            else:
                trust = trust - 0.1 * trust
            # Apply decay to gradually forget old beliefs
            trust *= self.trust_decay
            # Keep in [0,1]
            trust = max(0.0, min(1.0, trust))
            self.trust_belief[agent_id] = trust

        # Update trust for donor and recipient
        update_trust(donor_id, donor_action)
        update_trust(recipient_id, recipient_action)

        # Update observation count
        self.observation_count[donor_id] = self.observation_count.get(donor_id, 0) + 1
        self.observation_count[recipient_id] = self.observation_count.get(recipient_id, 0) + 1

        # Update reputation with momentum (same as parent)
        def update_rep(agent_id, delta):
            current_rep = self.reputation.get(agent_id, 0)
            mom = self.reputation_momentum.get(agent_id, 0.0)
            mom = 0.8 * mom + 0.2 * delta
            new_rep = current_rep + mom
            self.reputation[agent_id] = new_rep
            self.reputation_momentum[agent_id] = mom

        if donor_action == 'cooperate':
            update_rep(donor_id, 1)
            self.coop_count[donor_id] = self.coop_count.get(donor_id, 0) + 1
        else:
            update_rep(donor_id, -1)
            self.defect_count[donor_id] = self.defect_count.get(donor_id, 0) + 1

        if recipient_action == 'cooperate':
            update_rep(recipient_id, 1)
            self.coop_count[recipient_id] = self.coop_count.get(recipient_id, 0) + 1
        else:
            update_rep(recipient_id, -1)
            self.defect_count[recipient_id] = self.defect_count.get(recipient_id, 0) + 1

        # Self-interaction handling
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                my_id = donor_id
                opp_id = recipient_id
                my_action = donor_action
                opp_action = recipient_action
            else:
                my_id = recipient_id
                opp_id = donor_id
                my_action = recipient_action
                opp_action = donor_action

            if opp_id not in self.interactions:
                self.interactions[opp_id] = []
            self.interactions[opp_id].append((my_action == 'cooperate', opp_action == 'cooperate'))
            if len(self.interactions[opp_id]) > 100:
                self.interactions[opp_id] = self.interactions[opp_id][-100:]

            if my_action == 'defect':
                self.defected_against.add(opp_id)

            if opp_action == 'cooperate':
                self.forgiveness[opp_id] = self.forgiveness.get(opp_id, 0) + 0.5
            else:
                self.forgiveness[opp_id] = self.forgiveness.get(opp_id, 0) - 0.5
            self.forgiveness[opp_id] = max(0, min(2, self.forgiveness.get(opp_id, 0)))

            self.recent_outcomes.append((opp_id, my_action == 'cooperate', opp_action == 'cooperate'))
            if len(self.recent_outcomes) > 30:
                self.recent_outcomes = self.recent_outcomes[-30:]

            # NEW: Track our own cooperation and defection counts with this opponent
            if my_action == 'cooperate':
                self.coop_with[opp_id] = self.coop_with.get(opp_id, 0) + 1
            else:
                self.defect_with[opp_id] = self.defect_with.get(opp_id, 0) + 1

            # NEW: Adjust trust belief based on our own action and the outcome
            # If we cooperated and opponent defected, trust decreases more
            # If we defected and opponent cooperated, trust increases slightly (they are forgiving)
            if my_action == 'cooperate' and opp_action == 'defect':
                current_trust = self.trust_belief.get(opp, 0.5)
                current_trust = max(0.0, current_trust - 0.2)
                self.trust_belief[opp] = current_trust
            elif my_action == 'defect' and opp_action == 'cooperate':
                current_trust = self.trust_belief.get(opp, 0.5)
                current_trust = min(1.0, current_trust + 0.1)
                self.trust_belief[opp] = current_trust

        # Third-party observations: adjust reputation with slight forgiveness
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            if donor_action == 'cooperate' and recipient_action == 'defect':
                self.reputation[donor_id] = self.reputation.get(donor_id, 0) + 0.5
            elif donor_action == 'defect' and recipient_action == 'cooperate':
                self.reputation[donor_id] = self.reputation.get(donor_id, 0) - 1.5

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Reputation scores: agent_id -> [cooperation count, defection count]
        self.reputation = {}
        # Cooperation history with each agent: agent_id -> deque of bool (True if we cooperated)
        self.interaction_history = {}
        # Track opponent's last action for each round
        self.last_opponent_action = None
        # Track our own recent actions as a deque
        self.own_recent_actions = deque(maxlen=10)
        # Generosity: initial tendency to cooperate, will adjust based on experience
        self.generosity = 0.5
        # Trust threshold: how much reputation needed to trust
        self.trust_threshold = 0.3
        # Forgetting factor: how much weight to give past observations
        self.forgetting = 0.9
        # Track rounds played
        self.rounds_played = 0
        # New: punishment threshold - how many defections before we punish
        self.punish_threshold = 2
        # New: recent defection counter for current opponent
        self.current_opponent_defections = 0
        # New: mood state (positive, neutral, negative) to modulate behavior
        self.mood = 'neutral'
        # New: memory of cooperation rate from all observed interactions
        self.global_coop_rate = 0.5

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True  # Safety fallback

        # Update opponent's reputation based on what we know
        rep = self.reputation.get(opponent, [0, 0])
        coop_count, defect_count = rep[0], rep[1]
        total = coop_count + defect_count
        if total > 0:
            coop_ratio = coop_count / total
        else:
            coop_ratio = 0.5  # Unknown opponent, assume neutral

        # Check if we have history with this opponent
        history = self.interaction_history.get(opponent, deque())

        # If we've played with them before, use reciprocity
        if len(history) > 0:
            # Use last 3 interactions for reciprocity
            recent = list(history)[-3:]
            their_coop = sum(1 for a in recent if a) / len(recent)
            # Tit-for-tat with forgiveness: cooperate if they cooperated recently
            if their_coop >= 0.5:
                # Mood boost: if in positive mood, more likely to cooperate
                if self.mood == 'positive':
                    return True
                else:
                    return True
            else:
                # If they defected recently, be more cautious but still occasionally forgive
                # Mood affects forgiveness: negative mood less forgiving
                if self.mood == 'negative':
                    return random.random() < 0.05
                else:
                    return random.random() < 0.2

        # If we have reputation info, use it
        if total >= 3:  # Need enough observations to be reliable
            if coop_ratio >= self.trust_threshold:
                return True
            else:
                # Defect against known defectors, but sometimes test them
                return random.random() < 0.1

        # For unknown or insufficient info, base on our generosity
        # Early game: more generous, later: more cautious
        if self.rounds_played < 5:
            return True
        else:
            # Mood modulates base generosity
            if self.mood == 'positive':
                return random.random() < min(0.9, self.generosity + 0.15)
            elif self.mood == 'negative':
                return random.random() < max(0.0, self.generosity - 0.15)
            else:
                return random.random() < self.generosity

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Update reputation for donor
        donor_rep = self.reputation.get(donor_id, [0, 0])
        if donor_action == 'cooperate':
            donor_rep[0] += 1
        else:
            donor_rep[1] += 1
        # Apply forgetting to existing counts (but keep at least 1)
        donor_rep[0] = max(1, int(donor_rep[0] * self.forgetting))
        donor_rep[1] = max(1, int(donor_rep[1] * self.forgetting))
        self.reputation[donor_id] = donor_rep

        # Update reputation for recipient
        recipient_rep = self.reputation.get(recipient_id, [0, 0])
        if recipient_action == 'cooperate':
            recipient_rep[0] += 1
        else:
            recipient_rep[1] += 1
        recipient_rep[0] = max(1, int(recipient_rep[0] * self.forgetting))
        recipient_rep[1] = max(1, int(recipient_rep[1] * self.forgetting))
        self.reputation[recipient_id] = recipient_rep

        # Update global cooperation rate from all observed interactions
        # Use a moving average with small weight
        if donor_action == 'cooperate':
            self.global_coop_rate = self.global_coop_rate * 0.98 + 0.02
        else:
            self.global_coop_rate = self.global_coop_rate * 0.98 + 0.0
        if recipient_action == 'cooperate':
            self.global_coop_rate = self.global_coop_rate * 0.98 + 0.02
        else:
            self.global_coop_rate = self.global_coop_rate * 0.98 + 0.0

        # If this is our own interaction, update history and learning
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # Determine opponent and their action
            if donor_id == self.agent_id:
                opponent = recipient_id
                opponent_action = recipient_action
                my_action = donor_action
            else:
                opponent = donor_id
                opponent_action = donor_action
                my_action = recipient_action

            # Update interaction history using deque
            if opponent not in self.interaction_history:
                self.interaction_history[opponent] = deque(maxlen=10)
            # Record what opponent did (True if cooperate)
            self.interaction_history[opponent].append(opponent_action == 'cooperate')

            # Track our own recent actions
            self.own_recent_actions.append(my_action == 'cooperate')

            # Update generosity based on outcomes
            # If we cooperated and they defected, reduce generosity
            if my_action == 'cooperate' and opponent_action == 'defect':
                self.generosity = max(0.1, self.generosity - 0.05)
            # If we both cooperated, slightly increase generosity
            elif my_action == 'cooperate' and opponent_action == 'cooperate':
                self.generosity = min(0.9, self.generosity + 0.02)
            # If we defected and they cooperated, they were nice - maybe be more generous
            elif my_action == 'defect' and opponent_action == 'cooperate':
                self.generosity = min(0.9, self.generosity + 0.03)

            # New: track defections against us and reset when we cooperate with them
            if opponent_action == 'defect':
                self.current_opponent_defections += 1
            else:
                self.current_opponent_defections = 0

            # New: if opponent defects too many times, we become more cautious
            if self.current_opponent_defections >= self.punish_threshold:
                self.generosity = max(0.1, self.generosity - 0.1)
                self.current_opponent_defections = 0

            # New: update mood based on outcome of our interaction
            if my_action == 'cooperate' and opponent_action == 'defect':
                # Betrayed - become negative
                self.mood = 'negative'
            elif my_action == 'defect' and opponent_action == 'cooperate':
                # We exploited - become positive
                self.mood = 'positive'
            elif my_action == 'cooperate' and opponent_action == 'cooperate':
                # Mutual cooperation - stay positive if already, else neutral
                if self.mood == 'negative':
                    self.mood = 'neutral'
                else:
                    self.mood = 'positive'
            elif my_action == 'defect' and opponent_action == 'defect':
                # Mutual defection - stay negative if already, else neutral
                if self.mood == 'positive':
                    self.mood = 'neutral'
                else:
                    self.mood = 'negative'

            # New: mood decays over time (towards neutral)
            if self.mood == 'positive' and random.random() < 0.2:
                self.mood = 'neutral'
            elif self.mood == 'negative' and random.random() < 0.2:
                self.mood = 'neutral'

            self.rounds_played += 1

import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Reputation tracking: dict mapping agent_id -> reputation score
        self.reputation = {}
        # Own interaction history: dict mapping opponent_id -> list of (my_action, their_action)
        self.interactions = {}
        # Global observed behavior counts: dict mapping agent_id -> [coops, defs]
        self.observed_counts = {}
        # Personal cooperation rate for each agent (smoothed)
        self.coop_rate = {}
        # Round number within generation (0-indexed)
        self.round_count = 0
        # Own recent actions for forgiveness logic
        self.my_recent_actions = []
        # Opponent's recent actions for forgiveness logic
        self.opp_recent_actions = []
        # Current opponent id set by framework
        self._ctx_opponent_id = None
        # Baseline trust threshold, adjusted over time
        self.trust_threshold = 0.5
        # Memory of past opponent behavior for pattern detection
        self.opp_history = {}
        # NEW: Track frequency of observed defections against cooperators
        self.defection_against_coop = {}
        # NEW: Personal memory of own cooperation rate per opponent (for asymmetry)
        self.own_coop_rate = {}

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return True

        # Initialize data structures for new opponents
        if opp not in self.reputation:
            self.reputation[opp] = 0.5
        if opp not in self.interactions:
            self.interactions[opp] = []
        if opp not in self.observed_counts:
            self.observed_counts[opp] = [0, 0]
        if opp not in self.coop_rate:
            self.coop_rate[opp] = 0.5
        if opp not in self.defection_against_coop:
            self.defection_against_coop[opp] = [0, 0]  # [defections observed, times opponent cooperated]
        if opp not in self.own_coop_rate:
            self.own_coop_rate[opp] = 0.5

        # Compute opponent's observed cooperation rate (smoothed)
        obs_coop, obs_def = self.observed_counts[opp]
        total_obs = obs_coop + obs_def
        obs_rate = obs_coop / total_obs if total_obs > 0 else 0.5

        # Compute personal interaction history-based rate
        my_hist = self.interactions[opp]
        if my_hist:
            my_coop = sum(1 for a, b in my_hist if a == 'cooperate')
            my_rate = my_coop / len(my_hist)
        else:
            my_rate = 0.5

        # Blend observed and personal rates, but weight observed more if we have little history
        history_weight = min(1.0, len(my_hist) / 10.0)
        blend = (1.0 - 0.5 * history_weight) * obs_rate + 0.5 * history_weight * my_rate

        # NEW: Incorporate defection-against-cooperation rate as a negative signal
        # If opponent frequently defects after cooperating, lower reputation
        if opp in self.defection_against_coop:
            def_count, coop_count = self.defection_against_coop[opp]
            if coop_count > 0:
                def_against_coop_rate = def_count / coop_count
                blend -= 0.2 * def_against_coop_rate

        # Update reputation with recency bias (faster adaptation)
        self.reputation[opp] = 0.7 * self.reputation[opp] + 0.3 * blend

        # Check for recent behavior patterns (last 5 interactions)
        recent = my_hist[-5:] if len(my_hist) >= 5 else my_hist
        if len(recent) >= 2:
            # Detect if opponent tends to defect after we cooperate
            betrayals = sum(1 for i in range(len(recent)-1) if recent[i][0] == 'cooperate' and recent[i+1][1] == 'defect')
            if betrayals >= 2:
                # Punish betrayals more harshly
                self.reputation[opp] -= 0.15

        # Adaptive threshold based on generation progress and own cooperation rate
        # Early generations: more trusting; later: more cautious
        gen_factor = math.exp(-self.round_count / 30.0)  # decreases over rounds
        threshold = 0.4 + 0.2 * gen_factor

        # NEW: If we have been very cooperative recently, lower threshold (forgiveness)
        if self.my_recent_actions:
            my_coop_recent = sum(1 for a in self.my_recent_actions if a == 'cooperate')
            my_recent_rate = my_coop_recent / len(self.my_recent_actions)
            if my_recent_rate > 0.7:
                threshold -= 0.05

        # Decision: cooperate if reputation above threshold
        return self.reputation[opp] > threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update observed counts for both agents
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.observed_counts:
                self.observed_counts[agent_id] = [0, 0]
            if action == 'cooperate':
                self.observed_counts[agent_id][0] += 1
            else:
                self.observed_counts[agent_id][1] += 1

        # NEW: Track defection against cooperation for all observed interactions
        # If donor cooperated and recipient defected, note this for the recipient
        if donor_action == 'cooperate' and recipient_action == 'defect':
            if recipient_id not in self.defection_against_coop:
                self.defection_against_coop[recipient_id] = [0, 0]
            self.defection_against_coop[recipient_id][0] += 1
            # Also track that the recipient cooperated (the donor's action counts as cooperation)
            if donor_id not in self.defection_against_coop:
                self.defection_against_coop[donor_id] = [0, 0]
            self.defection_against_coop[donor_id][1] += 1

        # If this is our own interaction, store it
        if donor_id == self.agent_id:
            opp = recipient_id
            my_action = donor_action
            their_action = recipient_action
        elif recipient_id == self.agent_id:
            opp = donor_id
            my_action = recipient_action
            their_action = donor_action
        else:
            return

        # Update personal interaction history
        if opp not in self.interactions:
            self.interactions[opp] = []
        self.interactions[opp].append((my_action, their_action))
        # Keep only last 20 interactions per opponent to bound memory
        if len(self.interactions[opp]) > 20:
            self.interactions[opp] = self.interactions[opp][-20:]

        # Update opponent history for pattern detection
        if opp not in self.opp_history:
            self.opp_history[opp] = []
        self.opp_history[opp].append(their_action)
        if len(self.opp_history[opp]) > 10:
            self.opp_history[opp] = self.opp_history[opp][-10:]

        # Update round counter when our interaction occurs
        self.round_count += 1

        # Update own recent actions
        self.my_recent_actions.append(my_action)
        if len(self.my_recent_actions) > 10:
            self.my_recent_actions.pop(0)
        self.opp_recent_actions.append(their_action)
        if len(self.opp_recent_actions) > 10:
            self.opp_recent_actions.pop(0)

        # NEW: Update own cooperation rate per opponent
        if opp not in self.own_coop_rate:
            self.own_coop_rate[opp] = 0.5
        # Simple update: average of own actions
        my_actions = self.interactions[opp]
        if my_actions:
            my_coop = sum(1 for a, b in my_actions if a == 'cooperate')
            self.own_coop_rate[opp] = my_coop / len(my_actions)

        # Adjust trust threshold based on overall population cooperation
        # Simple heuristic: if we've been betrayed often, become more cautious
        if self.my_recent_actions and self.opp_recent_actions:
            # Count times we cooperated and they defected next round
            betrayals = 0
            for i in range(min(len(self.my_recent_actions)-1, len(self.opp_recent_actions)-1)):
                if self.my_recent_actions[i] == 'cooperate' and self.opp_recent_actions[i+1] == 'defect':
                    betrayals += 1
            if betrayals >= 2:
                self.trust_threshold = min(0.8, self.trust_threshold + 0.05)
            else:
                self.trust_threshold = max(0.3, self.trust_threshold - 0.01)

