class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.interactions = {}
        self.observed_counts = {}
        self.coop_rate = {}
        self.round_count = 0
        self.my_recent_actions = []
        self.opp_recent_actions = []
        self._ctx_opponent_id = None
        self.trust_threshold = 0.5
        self.opp_history = {}
        # New: track a per-opponent forgiveness level (0-1)
        self.forgiveness = {}
        # New: track recent opponent actions as a deque for fast sliding window
        self.recent_opp_actions = {}
        # New: momentum term for reputation update
        self.rep_momentum = {}
        # New: track cooperation streaks for alternative memory
        self.coop_streaks = {}
        # New: track a per-opponent suspicion level (0-1) to bias decisions
        self.suspicion = {}
        # New: track the uncertainty (variance) of reputation estimates
        self.rep_variance = {}

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return True

        if opp not in self.reputation:
            self.reputation[opp] = 0.5
        if opp not in self.interactions:
            self.interactions[opp] = []
        if opp not in self.observed_counts:
            self.observed_counts[opp] = [0, 0]
        if opp not in self.coop_rate:
            self.coop_rate[opp] = 0.5
        if opp not in self.forgiveness:
            self.forgiveness[opp] = 0.5
        if opp not in self.recent_opp_actions:
            self.recent_opp_actions[opp] = deque(maxlen=10)
        if opp not in self.rep_momentum:
            self.rep_momentum[opp] = 0.0
        if opp not in self.coop_streaks:
            self.coop_streaks[opp] = 0
        if opp not in self.suspicion:
            self.suspicion[opp] = 0.0
        if opp not in self.rep_variance:
            self.rep_variance[opp] = 0.1

        obs_coop, obs_def = self.observed_counts[opp]
        total_obs = obs_coop + obs_def
        obs_rate = obs_coop / total_obs if total_obs > 0 else 0.5

        my_hist = self.interactions[opp]
        if my_hist:
            my_coop = sum(1 for a, b in my_hist if a == 'cooperate')
            my_rate = my_coop / len(my_hist)
        else:
            my_rate = 0.5

        blend = 0.7 * obs_rate + 0.3 * my_rate

        # New: suspicion-based bias - increase suspicion when opponent defects more
        suspicion_penalty = self.suspicion[opp] * 0.1
        target = 0.9 * self.reputation[opp] + 0.1 * blend + 0.05 * self.forgiveness[opp] - suspicion_penalty
        self.rep_momentum[opp] = 0.8 * self.rep_momentum[opp] + 0.2 * (target - self.reputation[opp])
        self.reputation[opp] += self.rep_momentum[opp]
        self.reputation[opp] = max(0.0, min(1.0, self.reputation[opp]))

        # New: update variance based on prediction error
        prediction_error = abs(self.reputation[opp] - blend)
        self.rep_variance[opp] = 0.9 * self.rep_variance[opp] + 0.1 * prediction_error
        self.rep_variance[opp] = max(0.01, min(0.5, self.rep_variance[opp]))

        recent = my_hist[-5:] if len(my_hist) >= 5 else my_hist
        if len(recent) >= 2:
            betrayals = sum(1 for i in range(len(recent)-1) if recent[i][0] == 'cooperate' and recent[i+1][1] == 'defect')
            if betrayals >= 2:
                # Punish but slightly less due to forgiveness
                self.reputation[opp] -= 0.08 * (1 - self.forgiveness[opp])

        gen_factor = math.exp(-self.round_count / 30.0)
        threshold = 0.4 + 0.2 * gen_factor

        # New: incorporate recent opponent actions directly (short-term memory)
        recent_opp = self.recent_opp_actions[opp]
        short_term_coop = sum(1 for a in recent_opp if a == 'cooperate') / len(recent_opp) if recent_opp else 0.5
        rep_diff = self.reputation[opp] - threshold + 0.2 * (short_term_coop - 0.5)

        # New: use cooperation streak to boost cooperation probability (alternative memory)
        streak_bonus = min(self.coop_streaks[opp], 5) * 0.05
        # New: variance-based caution - higher uncertainty makes agent more cautious
        variance_penalty = self.rep_variance[opp] * 0.5
        prob_coop = 1.0 / (1.0 + math.exp(-5 * (rep_diff + 0.3 * self.forgiveness[opp] + streak_bonus - variance_penalty)))
        return random.random() < prob_coop

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
