        self.recent_outcomes = deque(maxlen=30)

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return True

        opp_rep = self.reputation.get(opp, 0)
        my_rep = self.reputation.get(self.agent_id, 0)

        # Compute cooperation rate from all observed actions (not just our interactions)
        coop = self.coop_count.get(opp, 0)
        defect = self.defect_count.get(opp, 0)
        if coop + defect > 0:
            cooperation_rate = coop / (coop + defect)
        else:
            cooperation_rate = 0.5

        # Check our direct interaction history with this opponent (last 5)
        hist = self.interactions.get(opp, [])
        if hist:
            recent = list(hist)[-5:]
            opp_coop = sum(1 for _, a in recent if a)
            opp_defect = sum(1 for _, a in recent if not a)
            if opp_coop + opp_defect > 0:
                recent_rate = opp_coop / (opp_coop + opp_defect)
                # Blend with overall rate, but weight recent more heavily
                cooperation_rate = 0.8 * recent_rate + 0.2 * cooperation_rate

        # Count how many times opponent defected against us (in our interaction history)
        if hist:
            opp_def_against_us = sum(1 for my_a, opp_a in hist if not opp_a)
        else:
            opp_def_against_us = 0

        # Retaliation: if they defected against us at least 2 times, defect
        if opp_def_against_us >= 2:
            return False

        # If opponent reputation is clearly negative, defect
        if opp_rep < -1.5:
            return False

        # If opponent cooperation rate is high, cooperate
        if cooperation_rate > 0.6:
            return True

        # If opponent cooperation rate is low, defect
        if cooperation_rate < 0.4:
            return False

        # If my reputation is very negative, try to redeem by cooperating with good opponents
        if my_rep < -2:
            # If opponent is also bad, defect; otherwise cooperate
            if opp_rep < 0:
                return False
            else:
                return True

        # Default: cooperate if opponent reputation >= 0, but with a slight probabilistic
        # twist to explore forgiveness (sometimes cooperate even if slightly negative)
        if opp_rep < 0:
            # With small probability, forgive and cooperate
            return self.rng.random() < 0.1
        return True

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation with a forgiveness mechanism: 
        # - If donor cooperates and recipient defects, donor gets +0.5 (less harsh)
        # - If donor defects and recipient cooperates, donor gets -1.5 (harsher)
        # - Otherwise, standard +/-1
        if donor_action == 'cooperate':
            if recipient_action == 'defect':
                # Generous but not too punished
                self.reputation[donor_id] = self.reputation.get(donor_id, 0) + 0.5
            else:
                self.reputation[donor_id] = self.reputation.get(donor_id, 0) + 1
            self.coop_count[donor_id] = self.coop_count.get(donor_id, 0) + 1
        else:
            if recipient_action == 'cooperate':
                # Harsher punishment for defecting against a cooperator
                self.reputation[donor_id] = self.reputation.get(donor_id, 0) - 1.5
            else:
                self.reputation[donor_id] = self.reputation.get(donor_id, 0) - 1
            self.defect_count[donor_id] = self.defect_count.get(donor_id, 0) + 1

        # For recipient, standard update based on their action
        if recipient_action == 'cooperate':
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0) + 1
            self.coop_count[recipient_id] = self.coop_count.get(recipient_id, 0) + 1
        else:
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0) - 1
            self.defect_count[recipient_id] = self.defect_count.get(recipient_id, 0) + 1

        # If this is self-judgment, record interaction
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                my_id = donor_id
                opp_id = recipient_id
                my_action = donor_action
                opp_action = recipient_action
            else:
                my_id = recipient_id
                opp_id = donor_id
                my_action = recipient_action
                opp_action = donor_action

            if opp_id not in self.interactions:
                self.interactions[opp_id] = deque(maxlen=50)
            self.interactions[opp_id].append((my_action == 'cooperate', opp_action == 'cooperate'))

            if my_action == 'defect':
                self.defected_against.add(opp_id)

            # Update recent outcomes
            self.recent_outcomes.append((opp_id, my_action == 'cooperate', opp_action == 'cooperate'))

