        # Default to cooperate with slight suspicion
        if self.reputation > -0.5:
            self.last_action = True
            return True
        else:
            self.last_action = False
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update self-judgment for our own actions
        if donor_id == self.agent_id:
            self.last_action = (donor_action == 'cooperate')
            if donor_action == 'cooperate':
                self.coop_count += 1
            else:
                self.defect_count += 1
        if recipient_id == self.agent_id:
            if recipient_action == 'cooperate':
