            else:
                self.defect_count += 1

        # Third-party observation: update reputation of actors
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            # Reward cooperation, punish defection
            if donor_action == 'cooperate':
                self.reputation += 0.1
            else:
                self.reputation -= 0.2
            if recipient_action == 'cooperate':
                self.reputation += 0.1
            else:
                self.reputation -= 0.2
            # Update trust based on observed behavior
