        self.payoff_estimate = {}  # opponent_id -> {'coop_coop': int, 'coop_defect': int, 'defect_coop': int, 'defect_defect': int}
        # Track opponent's tendency to reciprocate (for strategy)
        self.reciprocity = {}  # opponent_id -> {'mutual_coop': int, 'mutual_defect': int, 'exploit': int}
        # Opponent context set by framework before decide()
        self._ctx_opponent_id = None
        # Flag for whether we are currently in a decision round
        self.round_counter = 0

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            # Should not happen, but safe fallback: cooperate
            return True

        # Initialize records if first time meeting this opponent
        if opponent not in self.opponent_history:
            self.opponent_history[opponent] = {'coop': 0, 'defect': 0, 'actions': []}
            self.payoff_estimate[opponent] = {'coop_coop': 0, 'coop_defect': 0, 'defect_coop': 0, 'defect_defect': 0}
            self.reciprocity[opponent] = {'mutual_coop': 0, 'mutual_defect': 0, 'exploit': 0}

        # Get opponent's cooperation rate from history
        hist = self.opponent_history[opponent]
        total = hist['coop'] + hist['defect']

        # Strategy: Start cooperative, then adapt based on opponent behavior
        if total == 0:
            # First encounter: cooperate
            return True

        coop_rate = hist['coop'] / total

        # Check reciprocity: if opponent cooperated after we cooperated, good sign
        # Look at last few interactions with this opponent
        recent_actions = [a for _, a in hist['actions'][-5:]]
        if recent_actions:
            # If opponent has been mostly cooperative recently, cooperate
            if coop_rate > 0.6:
