        self._ctx_opponent_id = None
        self.trust_threshold = 0.5
        self.opp_history = {}
        # New mechanism: track a moving average of betrayal rate over time
        self.betrayal_ema = 0.0
        self.ema_alpha = 0.1

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return True

