                self.self_actions[recipient_id] = self.self_actions.get(recipient_id, []) + ['defect']
            # Self-reputation based on consistency
            total = self.my_cooperations + self.my_defections
            self.my_reputation = self.my_cooperations / max(total, 1)
        elif recipient_id == self.agent_id:
            # Track actions towards us
            if donor_action == 'cooperate':
