            # Clamp reputation
            self.reputation[donor_id] = max(0.0, min(1.0, self.reputation[donor_id]))

            # Update partner score based on observed cooperation
            if donor_id in self.partner_scores:
                if donor_action == 'cooperate':
                    self.partner_scores[donor_id] += 1
