from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.coop_count = {}
        self.defect_count = {}
        self.interactions = {}
        self.defected_against = set()
        self._ctx_opponent_id = None
        self.generation = 0
        self.rng = random.Random(agent_id * 54321)
        self.recent_outcomes = deque(maxlen=30)
        self.adaptation_level = 0.8  # starts high, decreases over time

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return True

        opp_rep = self.reputation.get(opp, 0)
        my_rep = self.reputation.get(self.agent_id, 0)

        coop = self.coop_count.get(opp, 0)
        defect = self.defect_count.get(opp, 0)
        if coop + defect > 0:
            cooperation_rate = coop / (coop + defect)
        else:
            cooperation_rate = 0.5

        hist = self.interactions.get(opp, [])
        if hist:
            recent = list(hist)[-5:]
            opp_coop = sum(1 for _, a in recent if a)
            opp_defect = sum(1 for _, a in recent if not a)
            if opp_coop + opp_defect > 0:
                recent_rate = opp_coop / (opp_coop + opp_defect)
                cooperation_rate = 0.8 * recent_rate + 0.2 * cooperation_rate

        if hist:
            opp_def_against_us = sum(1 for my_a, opp_a in hist if not opp_a)
        else:
            opp_def_against_us = 0

        if opp_def_against_us >= 2:
            return False

        if opp_rep < -1.5:
            return False

        # Adapt thresholds based on adaptation level
        high_threshold = 0.6 + (1 - self.adaptation_level) * 0.2
        low_threshold = 0.4 - (1 - self.adaptation_level) * 0.2

        if cooperation_rate > high_threshold:
            return True

        if cooperation_rate < low_threshold:
            return False

        if my_rep < -2:
            if opp_rep < 0:
                return False
            else:
                return True

        if opp_rep < 0:
            # Adaptive forgiveness probability
            forgiveness_prob = 0.1 + (1 - self.adaptation_level) * 0.2
            return self.rng.random() < forgiveness_prob
        return True

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Soften punishment over generations to promote cooperation
        harshness = 1.0 + (1 - self.adaptation_level) * 0.5

        if donor_action == 'cooperate':
            if recipient_action == 'defect':
                self.reputation[donor_id] = self.reputation.get(donor_id, 0) + 0.5
            else:
                self.reputation[donor_id] = self.reputation.get(donor_id, 0) + 1
            self.coop_count[donor_id] = self.coop_count.get(donor_id, 0) + 1
        else:
            if recipient_action == 'cooperate':
                self.reputation[donor_id] = self.reputation.get(donor_id, 0) - 1.5 * harshness
            else:
                self.reputation[donor_id] = self.reputation.get(donor_id, 0) - 1 * harshness
            self.defect_count[donor_id] = self.defect_count.get(donor_id, 0) + 1

        if recipient_action == 'cooperate':
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0) + 1
            self.coop_count[recipient_id] = self.coop_count.get(recipient_id, 0) + 1
        else:
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0) - 1 * harshness
            self.defect_count[recipient_id] = self.defect_count.get(recipient_id, 0) + 1

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                my_id = donor_id
                opp_id = recipient_id
                my_action = donor_action
                opp_action = recipient_action
            else:
                my_id = recipient_id
                opp_id = donor_id
                my_action = recipient_action
                opp_action = donor_action

            if opp_id not in self.interactions:
                self.interactions[opp_id] = deque(maxlen=50)
            self.interactions[opp_id].append((my_action == 'cooperate', opp_action == 'cooperate'))

            if my_action == 'defect':
                self.defected_against.add(opp_id)

            self.recent_outcomes.append((opp_id, my_action == 'cooperate', opp_action == 'cooperate'))
            # Decay adaptation level based on recent outcomes
            if len(self.recent_outcomes) >= 20:
                recent_coop = sum(1 for _, my_c, _ in self.recent_outcomes if my_c)
                recent_rate = recent_coop / len(self.recent_outcomes)
                self.adaptation_level = max(0.2, self.adaptation_level - 0.01 * (1 - recent_rate))

