        # Look at last few interactions with this opponent
        recent_actions = [a for _, a in hist['actions'][-5:]]
        if recent_actions:
            # Adjust threshold based on social norm
            coop_threshold = 0.6 - trust_bonus
            defect_threshold = 0.4 + trust_bonus
            # If opponent has been mostly cooperative recently, cooperate
            if coop_rate > coop_threshold:
