class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self._ctx_opponent_id = None

        # Reputation tracking: each agent has a score initialized to 0.
        # Scores range roughly [-100, 100] and are updated based on observed actions.
        self.reputation = {}

        # Memory of interactions: opponent_id -> list of outcomes for this agent.
        # Each outcome is a tuple: (own_action, opponent_action)
        self.interaction_history = {}

        # Trust: opponent_id -> trust score. Starts neutral (0).
        self.trust = {}

        # Cooperation count for each opponent
        self.coop_count = {}

        # Defection count for each opponent
        self.defect_count = {}

        # Overall cooperation rate of the agent itself
        self.own_coop_rate = 0.5
        self.own_total_actions = 0
        self.own_coop_actions = 0

        # For deterministic randomness if needed
        self.rand = random.Random(agent_id * 12345)

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            # Should not happen, but be safe
            return True

        # Get reputation of opponent
        rep = self.reputation.get(opponent, 0)

        # Get trust
        trust = self.trust.get(opponent, 0)

        # Get history
        history = self.interaction_history.get(opponent, [])

        # Strategy: cooperate if opponent is generally cooperative or unknown.
        # If opponent has high rep and trust, cooperate.
        # If opponent has low rep or betrayed us recently, defect.

        # Start with baseline: cooperate if rep >= 0
        if rep >= 0:
            # But if we have history and they defected last time, maybe defect
            if history:
                last_own, last_opp = history[-1]
                if last_opp == 'defect' and last_own == 'cooperate':
                    # They just betrayed us, defect this time (tit-for-tat)
                    return False
            return True
        else:
            # Low reputation: defect
            return False

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Update reputation for donor and recipient based on joint action.
        # We are a third-party observer or participant.

        # Define payoff matrix: cooperate-cooperate: both good (+2)
        # cooperate-defect: donor gets +3, recipient -1
        # defect-cooperate: donor -1, recipient +3
        # defect-defect: both 0

        # Update reputation for donor
        if donor_action == 'cooperate':
            if recipient_action == 'cooperate':
                self._update_reputation(donor_id, 2)
            else:
                self._update_reputation(donor_id, -1)
        else:
            if recipient_action == 'cooperate':
                self._update_reputation(donor_id, 3)
            else:
                self._update_reputation(donor_id, 0)

        # Update reputation for recipient
        if recipient_action == 'cooperate':
            if donor_action == 'cooperate':
                self._update_reputation(recipient_id, 2)
            else:
                self._update_reputation(recipient_id, -1)
        else:
            if donor_action == 'cooperate':
                self._update_reputation(recipient_id, 3)
            else:
                self._update_reputation(recipient_id, 0)

        # If we are one of the participants, record interaction history and trust
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # Determine own action and opponent action
            if donor_id == self.agent_id:
                own_action = donor_action
                opp_action = recipient_action
                opp_id = recipient_id
            else:
                own_action = recipient_action
                opp_action = donor_action
                opp_id = donor_id

            # Update own cooperation stats
            self.own_total_actions += 1
            if own_action == 'cooperate':
                self.own_coop_actions += 1
            self.own_coop_rate = self.own_coop_actions / max(1, self.own_total_actions)

            # Update interaction history
            if opp_id not in self.interaction_history:
                self.interaction_history[opp_id] = []
            self.interaction_history[opp_id].append((own_action, opp_action))

            # Update coop/defect counts
            if opp_action == 'cooperate':
                self.coop_count[opp_id] = self.coop_count.get(opp_id, 0) + 1
            else:
                self.defect_count[opp_id] = self.defect_count.get(opp_id, 0) + 1

            # Update trust based on opponent's action relative to ours
            # Simple rule: if opponent cooperated, increase trust; if defected, decrease trust.
            # More weight if we also cooperated (mutual cooperation is best)
            if opp_action == 'cooperate':
                if own_action == 'cooperate':
                    self.trust[opp_id] = self.trust.get(opp_id, 0) + 2
                else:
                    self.trust[opp_id] = self.trust.get(opp_id, 0) + 1
            else:
                if own_action == 'cooperate':
                    self.trust[opp_id] = self.trust.get(opp_id, 0) - 3
                else:
                    self.trust[opp_id] = self.trust.get(opp_id, 0) - 1

        # Also update trust based on third-party observations? Could do, but keep simple.

    def _update_reputation(self, agent_id: int, delta: int) -> None:
        # Update reputation with a bounded scale
        current = self.reputation.get(agent_id, 0)
        new = current + delta
        # Bound between -100 and 100
        new = max(-100, min(100, new))
        self.reputation[agent_id] = new

