        blend = 0.6 * obs_rate + 0.4 * my_rate

        # Update reputation with exponential moving average
        self.reputation[opp] = 0.8 * self.reputation[opp] + 0.2 * blend

        # Retaliation mechanism: if opponent has defected consecutively too many times, defect
        if self.consecutive_defections[opp] >= self.retaliation_threshold:
            return False

        # Adaptive threshold based on generation progress and trust
        gen_factor = math.exp(-self.round_count / 30.0)
        # Incorporate trust_threshold into decision
