        self.generosity = 0.5
        self.trust_threshold = 0.3
        self.forgetting = 0.9
        self.rounds_played = 0
        self.punish_threshold = 2
        self.current_opponent_defections = 0
        self.recent_opponent_actions = deque(maxlen=5)
        # New: Track opponent's defection streak (consecutive defections)
        self.opponent_defection_streak = 0
        # New: Track our own defection streak
        self.own_defection_streak = 0
        # New: Adaptive punishment based on defection streak length
        self.streak_penalty = 0.0
        # New: Track forgiveness tendency—allows occasional cooperation despite bad streaks
        self.forgiveness = 0.2

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True

        rep = self.reputation.get(opponent, [0, 0])
        coop_count, defect_count = rep[0], rep[1]
        total = coop_count + defect_count
        if total > 0:
            coop_ratio = coop_count / total
        else:
            coop_ratio = 0.5

        history = self.interaction_history.get(opponent, deque())

        # If we have a recent defection streak with this opponent, be more cautious
        # but allow a small chance of forgiveness if we have a history of cooperation
        if self.opponent_defection_streak >= 2:
            if coop_ratio > 0.7 and len(history) >= 5:
                return random.random() < self.forgiveness
            return False

        # If we have history, use reciprocity with streak awareness
        if len(history) > 0:
            recent = list(history)[-3:]
            their_coop = sum(1 for a in recent if a) / len(recent)
            if their_coop >= 0.5:
                # If they cooperated but we have a bad streak, still give a chance
                if self.opponent_defection_streak >= 1:
                    return random.random() < 0.6
                return True
            else:
                # If they defected, and we have a bad streak, be very harsh
                if self.opponent_defection_streak >= 1:
                    return random.random() < 0.05
                return random.random() < 0.2

        # Reputation-based decision with streak penalty
        if total >= 3:
            if coop_ratio >= self.trust_threshold:
                return True
            else:
                return random.random() < 0.1 - self.streak_penalty

        # Unknown opponent: use generosity minus streak penalty
        if self.rounds_played < 5:
            return True
        else:
            return random.random() < max(0.0, self.generosity - self.streak_penalty)

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        donor_rep = self.reputation.get(donor_id, [0, 0])
        if donor_action == 'cooperate':
            donor_rep[0] += 1
        else:
            donor_rep[1] += 1
        donor_rep[0] = max(1, int(donor_rep[0] * self.forgetting))
        donor_rep[1] = max(1, int(donor_rep[1] * self.forgetting))
        self.reputation[donor_id] = donor_rep

        recipient_rep = self.reputation.get(recipient_id, [0, 0])
        if recipient_action == 'cooperate':
            recipient_rep[0] += 1
        else:
            recipient_rep[1] += 1
        recipient_rep[0] = max(1, int(recipient_rep[0] * self.forgetting))
        recipient_rep[1] = max(1, int(recipient_rep[1] * self.forgetting))
        self.reputation[recipient_id] = recipient_rep

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                opponent = recipient_id
                opponent_action = recipient_action
                my_action = donor_action
            else:
                opponent = donor_id
                opponent_action = donor_action
                my_action = recipient_action

            if opponent not in self.interaction_history:
                self.interaction_history[opponent] = deque(maxlen=10)
            self.interaction_history[opponent].append(opponent_action == 'cooperate')

            self.own_recent_actions.append(my_action == 'cooperate')

            # Update streaks and streak penalty
            if opponent_action == 'defect':
                self.opponent_defection_streak += 1
            else:
                self.opponent_defection_streak = 0

            if my_action == 'defect':
                self.own_defection_streak += 1
            else:
                self.own_defection_streak = 0

            # Streak penalty: more harsh if both we and opponent are defecting
            self.streak_penalty = min(0.3, 0.05 * min(self.opponent_defection_streak, self.own_defection_streak))

            # Update generosity with streak considerations
            if my_action == 'defect' and opponent_action == 'cooperate':
                self.generosity = max(0.1, self.generosity - 0.05)
            elif my_action == 'cooperate' and opponent_action == 'cooperate':
                self.generosity = min(0.9, self.generosity + 0.02 + self.streak_penalty * 0.1)
            elif my_action == 'defect' and opponent_action == 'defect':
                self.generosity = max(0.1, self.generosity - 0.03)

            # New: Adjust forgiveness based on interaction outcomes
            if opponent_action == 'defect' and my_action == 'cooperate':
                # Being exploited reduces forgiveness
                self.forgiveness = max(0.0, self.forgiveness - 0.05)
            elif opponent_action == 'cooperate' and my_action == 'cooperate':
                # Mutual cooperation increases forgiveness slightly
                self.forgiveness = min(0.5, self.forgiveness + 0.01)
            elif opponent_action == 'cooperate' and my_action == 'defect':
                # Defecting against a cooperator reduces forgiveness
                self.forgiveness = max(0.0, self.forgiveness - 0.03)

            if opponent_action == 'defect':
                self.current_opponent_defections += 1
            else:
                self.current_opponent_defections = 0

            if self.current_opponent_defections >= self.punish_threshold:
                self.generosity = max(0.1, self.generosity - 0.1)
                self.current_opponent_defections = 0

            self.recent_opponent_actions.append(opponent_action == 'cooperate')

            if len(self.recent_opponent_actions) == 5:
                coop_fraction = sum(self.recent_opponent_actions) / 5
                if coop_fraction < 0.5:
                    self.trust_threshold = min(0.9, self.trust_threshold + 0.05)
                else:
                    self.trust_threshold = max(0.1, self.trust_threshold - 0.05)

            self.rounds_played += 1

