                    forgive_chance = 0.1
                    if opponent in self.reputation:
                        rep = self.reputation[opponent]
                        rep_total = rep['coop'] + rep['defect']
                        if rep_total > 0:
                            rep_rate = rep['coop'] / rep_total
                            # If reputation is low, reduce forgiveness chance
                            if rep_rate < 0.4:
                                forgive_chance *= 0.5
                    return random.random() < forgive_chance
        else:
            # Not enough history, default to cooperate
            return True

