                    # Positive outcome: increase trust in opponent
                    self.trust_threshold = min(1.0, self.trust_threshold + self.outcome_impact)
                elif donor_action == 'defect' and recipient_action == 'defect':
                    self.reciprocity[donor_id]['mutual_defect'] += 1
                    # Negative outcome: decrease trust
                    self.trust_threshold = max(0.0, self.trust_threshold - self.outcome_impact)
                elif recipient_action == 'cooperate' and donor_action == 'defect':
                    self.reciprocity[donor_id]['exploit'] += 1
                    # Being exploited: decrease trust
                    self.trust_threshold = max(0.0, self.trust_threshold - 2 * self.outcome_impact)

