        hist = self.opponent_history[opponent]
        total = hist['coop'] + hist['defect']

        # First encounter: use third-party reputation, but apply bias
        if total == 0:
            if opponent in self.reputation:
                rep = self.reputation[opponent]
                rep_total = rep['coop'] + rep['defect']
