        self.round_count += 1

        self.my_recent_actions.append(my_action)
        if len(self.my_recent_actions) > 10:
            self.my_recent_actions.pop(0)
        self.opp_recent_actions.append(their_action)
        if len(self.opp_recent_actions) > 10:
            self.opp_recent_actions.pop(0)

        # Track outcome: 1 if mutual cooperation or we defected and they cooperated, 0 otherwise
        if my_action == 'cooperate' and their_action == 'cooperate':
            outcome = 1
        elif my_action == 'defect' and their_action == 'cooperate':
            outcome = 1
        else:
            outcome = 0
        self.recent_outcomes.append(outcome)

        # Adjust threshold based on recent outcomes
        if len(self.recent_outcomes) >= 5:
            avg_outcome = sum(self.recent_outcomes) / len(self.recent_outcomes)
            if avg_outcome < 0.3:
                # Become more cautious when outcomes are poor
                self.trust_threshold = min(0.85, self.trust_threshold + 0.05)
            elif avg_outcome > 0.7:
                # Become more trusting when outcomes are good
                self.trust_threshold = max(0.25, self.trust_threshold - 0.03)
            else:
                # Moderate adjustment
                self.trust_threshold = max(0.3, min(0.7, self.trust_threshold + (0.5 - avg_outcome) * 0.02))

        # New: decay emotional state over time
        if opp in self.emotional_state:
            self.emotional_state[opp] *= self.forgiveness_decay

