from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.interaction_history = {}
        self.last_opponent_action = None
        self.own_recent_actions = deque(maxlen=10)
        self.generosity = 0.5
        self.trust_threshold = 0.3
        self.forgetting = 0.9
        self.rounds_played = 0
        self.punish_threshold = 2
        self.current_opponent_defections = 0
        self.recent_opponent_actions = deque(maxlen=5)
        # New: Track opponent's defection streak (consecutive defections)
        self.opponent_defection_streak = 0
        # New: Track our own defection streak
        self.own_defection_streak = 0
        # New: Adaptive punishment based on defection streak length
        self.streak_penalty = 0.0
        # New: Track forgiveness tendency—allows occasional cooperation despite bad streaks
        self.forgiveness = 0.2

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True

        rep = self.reputation.get(opponent, [0, 0])
        coop_count, defect_count = rep[0], rep[1]
        total = coop_count + defect_count
        if total > 0:
            coop_ratio = coop_count / total
        else:
            coop_ratio = 0.5

        history = self.interaction_history.get(opponent, deque())

        # If we have a recent defection streak with this opponent, be more cautious
        # but allow a small chance of forgiveness if we have a history of cooperation
        if self.opponent_defection_streak >= 2:
            if coop_ratio > 0.7 and len(history) >= 5:
                return random.random() < self.forgiveness
            return False

        # If we have history, use reciprocity with streak awareness
        if len(history) > 0:
            recent = list(history)[-3:]
            their_coop = sum(1 for a in recent if a) / len(recent)
            if their_coop >= 0.5:
                # If they cooperated but we have a bad streak, still give a chance
                if self.opponent_defection_streak >= 1:
                    return random.random() < 0.6
                return True
            else:
                # If they defected, and we have a bad streak, be very harsh
                if self.opponent_defection_streak >= 1:
                    return random.random() < 0.05
                return random.random() < 0.2

        # Reputation-based decision with streak penalty
        if total >= 3:
            if coop_ratio >= self.trust_threshold:
                return True
            else:
                return random.random() < 0.1 - self.streak_penalty

        # Unknown opponent: use generosity minus streak penalty
        if self.rounds_played < 5:
            return True
        else:
            return random.random() < max(0.0, self.generosity - self.streak_penalty)

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        donor_rep = self.reputation.get(donor_id, [0, 0])
        if donor_action == 'cooperate':
            donor_rep[0] += 1
        else:
            donor_rep[1] += 1
        donor_rep[0] = max(1, int(donor_rep[0] * self.forgetting))
        donor_rep[1] = max(1, int(donor_rep[1] * self.forgetting))
        self.reputation[donor_id] = donor_rep

