            self.own_recent_actions.append(my_action == 'cooperate')

            # Update streaks and streak penalty
            if opponent_action == 'defect':
                self.opponent_defection_streak += 1
            else:
                self.opponent_defection_streak = 0

            if my_action == 'defect':
                self.own_defection_streak += 1
            else:
                self.own_defection_streak = 0

            # Streak penalty: more harsh if both we and opponent are defecting
            self.streak_penalty = min(0.3, 0.05 * min(self.opponent_defection_streak, self.own_defection_streak))

            # Update generosity with streak considerations
            if my_action == 'defect' and opponent_action == 'cooperate':
                self.generosity = max(0.1, self.generosity - 0.05)
            elif my_action == 'cooperate' and opponent_action == 'cooperate':
                self.generosity = min(0.9, self.generosity + 0.02 + self.streak_penalty * 0.1)
            elif my_action == 'defect' and opponent_action == 'defect':
                self.generosity = max(0.1, self.generosity - 0.03)

            # New: Adjust forgiveness based on interaction outcomes
            if opponent_action == 'defect' and my_action == 'cooperate':
                # Being exploited reduces forgiveness
                self.forgiveness = max(0.0, self.forgiveness - 0.05)
            elif opponent_action == 'cooperate' and my_action == 'cooperate':
                # Mutual cooperation increases forgiveness slightly
                self.forgiveness = min(0.5, self.forgiveness + 0.01)
            elif opponent_action == 'cooperate' and my_action == 'defect':
                # Defecting against a cooperator reduces forgiveness
                self.forgiveness = max(0.0, self.forgiveness - 0.03)

