class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.interactions = {}
        self.observed_counts = {}
        self.coop_rate = {}
        self.round_count = 0
        self.my_recent_actions = []
        self.opp_recent_actions = []
        self._ctx_opponent_id = None
        self.trust_threshold = 0.5
        self.opp_history = {}
        # Track recent outcomes for adaptive punishment
        self.recent_outcomes = deque(maxlen=10)
        self.punishment_level = 0.1
        # New: track emotional state per opponent for forgiveness
        self.emotional_state = {}
        self.base_threshold = 0.5
        self.forgiveness_decay = 0.9

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return True

        if opp not in self.reputation:
            self.reputation[opp] = 0.5
        if opp not in self.interactions:
            self.interactions[opp] = []
        if opp not in self.observed_counts:
            self.observed_counts[opp] = [0, 0]
        if opp not in self.coop_rate:
            self.coop_rate[opp] = 0.5
        if opp not in self.emotional_state:
            self.emotional_state[opp] = 0.0

        obs_coop, obs_def = self.observed_counts[opp]
        total_obs = obs_coop + obs_def
        obs_rate = obs_coop / total_obs if total_obs > 0 else 0.5

        my_hist = self.interactions[opp]
        if my_hist:
            my_coop = sum(1 for a, b in my_hist if a == 'cooperate')
            my_rate = my_coop / len(my_hist)
        else:
            my_rate = 0.5

        # More weight on personal experience
        blend = 0.4 * obs_rate + 0.6 * my_rate

        # Reputation update with adaptive punishment
        self.reputation[opp] = 0.85 * self.reputation[opp] + 0.15 * blend

        # Detect betrayals and apply adaptive punishment
        recent = my_hist[-5:] if len(my_hist) >= 5 else my_hist
        if len(recent) >= 2:
            betrayals = sum(1 for i in range(len(recent)-1) if recent[i][0] == 'cooperate' and recent[i+1][1] == 'defect')
            if betrayals >= 2:
                self.reputation[opp] -= self.punishment_level
                # Increase punishment if repeated betrayals
                if betrayals >= 3:
                    self.punishment_level = min(0.3, self.punishment_level + 0.02)

        # New: emotional forgiveness mechanism - if opponent cooperates after a betrayal, reduce punishment
        if len(recent) >= 2:
            last_actions = my_hist[-2:]
            if last_actions[0][0] == 'defect' and last_actions[0][1] == 'defect' and last_actions[1][1] == 'cooperate':
                # Opponent cooperated after we defected - forgive some reputation
                self.emotional_state[opp] = self.emotional_state[opp] * self.forgiveness_decay + 0.1
                self.reputation[opp] += self.emotional_state[opp] * 0.05

        # Adaptive threshold with both round and generation decay
        gen_factor = math.exp(-self.round_count / 30.0)
        # More volatile threshold based on recent outcomes
        if len(self.recent_outcomes) > 0:
            avg_outcome = sum(self.recent_outcomes) / len(self.recent_outcomes)
            volatility = 0.1 * (1 - avg_outcome)  # More volatility when outcomes are bad
        else:
            volatility = 0.1
        threshold = 0.4 + 0.2 * gen_factor + volatility * random.uniform(-0.05, 0.05)

        # New: adjust threshold based on emotional state towards this opponent
        emotional_threshold = threshold - self.emotional_state[opp] * 0.1
        emotional_threshold = max(0.1, min(0.9, emotional_threshold))

        return self.reputation[opp] > emotional_threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.observed_counts:
                self.observed_counts[agent_id] = [0, 0]
            if action == 'cooperate':
                self.observed_counts[agent_id][0] += 1
            else:
                self.observed_counts[agent_id][1] += 1

        if donor_id == self.agent_id:
            opp = recipient_id
            my_action = donor_action
            their_action = recipient_action
        elif recipient_id == self.agent_id:
            opp = donor_id
            my_action = recipient_action
            their_action = donor_action
        else:
            return

        if opp not in self.interactions:
            self.interactions[opp] = []
        self.interactions[opp].append((my_action, their_action))
        if len(self.interactions[opp]) > 20:
            self.interactions[opp] = self.interactions[opp][-20:]

        if opp not in self.opp_history:
            self.opp_history[opp] = []
        self.opp_history[opp].append(their_action)
        if len(self.opp_history[opp]) > 10:
            self.opp_history[opp] = self.opp_history[opp][-10:]

        self.round_count += 1

        self.my_recent_actions.append(my_action)
        if len(self.my_recent_actions) > 10:
            self.my_recent_actions.pop(0)
        self.opp_recent_actions.append(their_action)
        if len(self.opp_recent_actions) > 10:
            self.opp_recent_actions.pop(0)

        # Track outcome: 1 if mutual cooperation or we defected and they cooperated, 0 otherwise
        if my_action == 'cooperate' and their_action == 'cooperate':
            outcome = 1
        elif my_action == 'defect' and their_action == 'cooperate':
            outcome = 1
        else:
            outcome = 0
        self.recent_outcomes.append(outcome)

        # Adjust threshold based on recent outcomes
        if len(self.recent_outcomes) >= 5:
            avg_outcome = sum(self.recent_outcomes) / len(self.recent_outcomes)
            if avg_outcome < 0.3:
                # Become more cautious when outcomes are poor
                self.trust_threshold = min(0.85, self.trust_threshold + 0.05)
            elif avg_outcome > 0.7:
                # Become more trusting when outcomes are good
                self.trust_threshold = max(0.25, self.trust_threshold - 0.03)
            else:
                # Moderate adjustment
                self.trust_threshold = max(0.3, min(0.7, self.trust_threshold + (0.5 - avg_outcome) * 0.02))

        # New: decay emotional state over time
        if opp in self.emotional_state:
            self.emotional_state[opp] *= self.forgiveness_decay

