        self.opponent_history = {}  # opponent_id -> {'coop': int, 'defect': int, 'actions': list}
        # Track own recent actions
        self.own_history = []  # list of (opponent_id, action) for recent rounds
        # Reputation system: track each agent's cooperation rate
        self.reputation = {}  # agent_id -> {'coop': int, 'defect': int}
        # Third-party observations: store recent interactions to infer patterns
        self.recent_observations = deque(maxlen=100)  # deque with max length
        # Track payoff estimate for each opponent (simple count-based)
        self.payoff_estimate = {}  # opponent_id -> {'coop_coop': int, 'coop_defect': int, 'defect_coop': int, 'defect_defect': int}
        # Track opponent's tendency to reciprocate (for strategy)
        self.reciprocity = {}  # opponent_id -> {'mutual_coop': int, 'mutual_defect': int, 'exploit': int}
        # Opponent context set by framework before decide()
        self._ctx_opponent_id = None
        # Flag for whether we are currently in a decision round
        self.round_counter = 0
        # New: trust threshold based on third-party reputation
        self.trust_threshold = 0.5  # start neutral
        # New: recent outcome impact factor (for dynamic trust adjustment)
        self.outcome_impact = 0.1

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            # Should not happen, but safe fallback: cooperate
            return True

        # Initialize records if first time meeting this opponent
        if opponent not in self.opponent_history:
            self.opponent_history[opponent] = {'coop': 0, 'defect': 0, 'actions': []}
            self.payoff_estimate[opponent] = {'coop_coop': 0, 'coop_defect': 0, 'defect_coop': 0, 'defect_defect': 0}
            self.reciprocity[opponent] = {'mutual_coop': 0, 'mutual_defect': 0, 'exploit': 0}

        # Get opponent's cooperation rate from history
        hist = self.opponent_history[opponent]
        total = hist['coop'] + hist['defect']

        # Strategy: Start cooperative, then adapt based on opponent behavior
        if total == 0:
            # First encounter: use third-party reputation as prior
            if opponent in self.reputation:
                rep = self.reputation[opponent]
                rep_total = rep['coop'] + rep['defect']
                if rep_total > 0:
                    rep_rate = rep['coop'] / rep_total
                    # If third-party reputation is very low, defect first
                    if rep_rate < 0.3:
                        return False
            return True

        coop_rate = hist['coop'] / total

        # Check reciprocity: if opponent cooperated after we cooperated, good sign
        # Look at last few interactions with this opponent
        recent_actions = [a for _, a in hist['actions'][-5:]]
        if recent_actions:
            # If opponent has been mostly cooperative recently, cooperate
            if coop_rate > 0.6:
                return True
            # If opponent has been mostly defecting, defect
            elif coop_rate < 0.4:
                return False
            else:
                # Mixed: use tit-for-tat with forgiveness, but also consider third-party reputation
                # If last interaction was cooperation, cooperate; if defection, defect with small forgiveness chance
                if recent_actions[-1] == 'cooperate':
                    return True
                else:
                    # 10% chance to forgive and cooperate, but reduce if opponent has bad reputation
                    forgive_chance = 0.1
                    if opponent in self.reputation:
                        rep = self.reputation[opponent]
                        rep_total = rep['coop'] + rep['defect']
                        if rep_total > 0:
                            rep_rate = rep['coop'] / rep_total
                            # If reputation is low, reduce forgiveness chance
                            if rep_rate < 0.4:
                                forgive_chance *= 0.5
                    return random.random() < forgive_chance
        else:
            # Not enough history, default to cooperate
            return True

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation for both agents
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.reputation:
                self.reputation[agent_id] = {'coop': 0, 'defect': 0}
            if action == 'cooperate':
                self.reputation[agent_id]['coop'] += 1
            else:
                self.reputation[agent_id]['defect'] += 1

        # If this observation involves us as a player, update our own history
        if donor_id == self.agent_id:
            self.own_history.append((recipient_id, donor_action))
            # Update opponent history for recipient
            if recipient_id in self.opponent_history:
                hist = self.opponent_history[recipient_id]
                hist['actions'].append(recipient_action)
                if recipient_action == 'cooperate':
                    hist['coop'] += 1
                else:
                    hist['defect'] += 1
                # Update payoff estimates
                key = f"{donor_action}_{recipient_action}"
                self.payoff_estimate[recipient_id][key] = self.payoff_estimate[recipient_id].get(key, 0) + 1
                # Update reciprocity
                if donor_action == 'cooperate' and recipient_action == 'cooperate':
                    self.reciprocity[recipient_id]['mutual_coop'] += 1
                    # Positive outcome: increase trust in opponent
                    if recipient_id in self.opponent_history:
                        self.trust_threshold = min(1.0, self.trust_threshold + self.outcome_impact)
                elif donor_action == 'defect' and recipient_action == 'defect':
                    self.reciprocity[recipient_id]['mutual_defect'] += 1
                    # Negative outcome: decrease trust
                    self.trust_threshold = max(0.0, self.trust_threshold - self.outcome_impact)
                elif donor_action == 'cooperate' and recipient_action == 'defect':
                    self.reciprocity[recipient_id]['exploit'] += 1
                    # Being exploited: decrease trust
                    self.trust_threshold = max(0.0, self.trust_threshold - 2 * self.outcome_impact)

        elif recipient_id == self.agent_id:
            self.own_history.append((donor_id, recipient_action))
            # Update opponent history for donor
            if donor_id in self.opponent_history:
                hist = self.opponent_history[donor_id]
                hist['actions'].append(donor_action)
                if donor_action == 'cooperate':
                    hist['coop'] += 1
