                # Update payoff estimates
                key = f"{donor_action}_{recipient_action}"
                self.payoff_estimate[donor_id][key] = self.payoff_estimate[donor_id].get(key, 0) + 1
                # Update reciprocity
                if donor_action == 'cooperate' and recipient_action == 'cooperate':
                    self.reciprocity[donor_id]['mutual_coop'] += 1
                    # Positive outcome: increase trust in opponent
                    self.trust_threshold = min(1.0, self.trust_threshold + self.outcome_impact)
                elif donor_action == 'defect' and recipient_action == 'defect':
                    self.reciprocity[donor_id]['mutual_defect'] += 1
                    # Negative outcome: decrease trust
                    self.trust_threshold = max(0.0, self.trust_threshold - self.outcome_impact)
                elif recipient_action == 'cooperate' and donor_action == 'defect':
                    self.reciprocity[donor_id]['exploit'] += 1
                    # Being exploited: decrease trust
                    self.trust_threshold = max(0.0, self.trust_threshold - 2 * self.outcome_impact)

        # For third-party observations, store recent observations (keep last 100)
        self.recent_observations.append((donor_id, donor_action, recipient_id, recipient_action))
        # Also update trust threshold based on third-party observations
        # If we see an agent defecting against a cooperator, reduce trust in that agent
        if donor_action == 'defect' and recipient_action == 'cooperate':
            if donor_id in self.reputation:
                # Small reduction in trust threshold for that agent
                self.trust_threshold = max(0.0, self.trust_threshold - 0.05)
        # If we see an agent cooperating against a defector, increase trust in that agent
        elif donor_action == 'cooperate' and recipient_action == 'defect':
            if donor_id in self.reputation:
                self.trust_threshold = min(1.0, self.trust_threshold + 0.05)

