        self.agent_id = agent_id
        # Reputation tracking: for each agent, count of cooperative/defective actions observed
        self.reputation = {}  # agent_id -> [coops, defects]
        # Track interactions with each opponent: opponent_id -> list of (my_action, their_action)
        self.interactions = {}
        # Track own recent actions and outcomes
        self.recent_actions = []
        # Basic forgiveness and trust parameters
        self.forgiveness = 0.1
        self.trust_threshold = 0.5
        # Track rounds played
        self.rounds_played = 0
        # Track total payoff proxy based on cooperation rates
        self.success_rate = 0.0
        # Track last opponent for context
        self._ctx_opponent_id = None

    def decide(self) -> bool:
        # If no opponent info, cooperate initially
        if self._ctx_opponent_id is None:
            return True

        opp_id = self._ctx_opponent_id
        # Compute reputation of opponent based on observed behavior
        if opp_id in self.reputation:
            coops, defects = self.reputation[opp_id]
            total = coops + defects
            if total > 0:
                rep_score = coops / total
            else:
                rep_score = 0.5
        else:
            rep_score = 0.5  # neutral prior

        # Check direct history with this opponent
        history = self.interactions.get(opp_id, [])
        if history:
            my_coops = sum(1 for a, _ in history if a)
            their_coops = sum(1 for _, b in history if b)
            total_interact = len(history)
            # Tit-for-tat style: if they cooperated last time, cooperate; if defected, defect with some forgiveness
            last_their_action = history[-1][1]
            if last_their_action:
                # They cooperated last time
                decision = True
            else:
                # They defected last time, consider forgiveness and reputation
                if rep_score > self.trust_threshold + 0.2:
                    decision = True  # forgive if reputation good
                else:
                    decision = random.random() > self.forgiveness
        else:
            # No history: use reputation as guide
            if rep_score > self.trust_threshold:
                decision = True
            else:
                decision = random.random() > (1 - rep_score)

        # Occasionally be slightly more cooperative if overall success rate is high
        if self.success_rate > 0.7 and random.random() < 0.1:
            decision = True

        return decision

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Update reputation for donor and recipient
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.reputation:
                self.reputation[agent_id] = [0, 0]
            if action == 'cooperate':
                self.reputation[agent_id][0] += 1
            else:
                self.reputation[agent_id][1] += 1

        # If this is our own interaction, record it
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # Determine opponent
            if donor_id == self.agent_id:
                opp_id = recipient_id
                my_action = donor_action == 'cooperate'
                their_action = recipient_action == 'cooperate'
            else:
                opp_id = donor_id
                my_action = recipient_action == 'cooperate'
                their_action = donor_action == 'cooperate'

            if opp_id not in self.interactions:
                self.interactions[opp_id] = []
            self.interactions[opp_id].append((my_action, their_action))
            self.recent_actions.append(my_action)
            if len(self.recent_actions) > 30:
                self.recent_actions.pop(0)
            self.rounds_played += 1

            # Update success rate based on payoff from this interaction
            # Payoff: both cooperate -> 3, one cooperate -> 0 for defector, 5 for cooperator (but we just approximate)
            if my_action and their_action:
                payoff = 3
            elif my_action and not their_action:
                payoff = 0
            elif not my_action and their_action:
                payoff = 5
            else:
                payoff = 1
            # Simple exponential moving average
            self.success_rate = self.success_rate * 0.9 + payoff / 5 * 0.1

