        self.reputation = {}
        # Track interactions with each opponent
        self.interactions = {}
        # Track cooperation rates of others
        self.coop_rate = {}
        # Track recent defections against me
        self.recent_defections_against_me = {}
        # Track overall trust in each agent
        self.trust = {}
        # Track generation count to reset some state
        self.round_count = 0
        self.total_rounds = 0
        # Simple exploration flag
        self.exploration = 0.05

    def _init_agent_if_needed(self, agent_id: int) -> None:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.0
            self.coop_rate[agent_id] = {'coop': 0, 'total': 0}
            self.trust[agent_id] = 0.0
            self.recent_defections_against_me[agent_id] = 0
            self.interactions[agent_id] = {'coop': 0, 'defect': 0, 'total': 0}

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True  # default cooperate if no opponent
        self._init_agent_if_needed(opponent)

        # Explore occasionally
        if random.random() < self.exploration:
            return random.random() < 0.5

        # Calculate opponent's trust score
        trust_score = self.trust.get(opponent, 0.0)
        # Weight recent defections against me more heavily
        recent_def = self.recent_defections_against_me.get(opponent, 0)
        if recent_def > 0:
            trust_score -= recent_def * 0.5

        # If trust is positive, cooperate; if negative, defect
        # Slight bias towards cooperation initially
        if trust_score > 0.1:
            return True
        elif trust_score < -0.1:
            return False
        else:
            # Neutral: cooperate if opponent has cooperated more than defected
            coop_rate = self.coop_rate.get(opponent, {'coop': 0, 'total': 0})
            if coop_rate['total'] > 0:
                return coop_rate['coop'] / coop_rate['total'] >= 0.5
            else:
                return True  # default cooperate when no history

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation for both agents based on their actions
        self._init_agent_if_needed(donor_id)
        self._init_agent_if_needed(recipient_id)

        # Update cooperation rates
        if donor_action == 'cooperate':
            self.coop_rate[donor_id]['coop'] += 1
        self.coop_rate[donor_id]['total'] += 1
        if recipient_action == 'cooperate':
            self.coop_rate[recipient_id]['coop'] += 1
        self.coop_rate[recipient_id]['total'] += 1

        # Update reputation: cooperate is good, defect is bad
        if donor_action == 'cooperate':
            self.reputation[donor_id] += 0.1
        else:
            self.reputation[donor_id] -= 0.2
        if recipient_action == 'cooperate':
            self.reputation[recipient_id] += 0.1
        else:
            self.reputation[recipient_id] -= 0.2

        # Update trust based on interactions involving me
        if donor_id == self.agent_id:
            # I was the donor, opponent is recipient
            self._init_agent_if_needed(recipient_id)
            if recipient_action == 'defect' and donor_action == 'cooperate':
                # They defected against my cooperation
                self.trust[recipient_id] -= 0.3
                self.recent_defections_against_me[recipient_id] += 1
            elif recipient_action == 'cooperate':
                self.trust[recipient_id] += 0.1
                self.recent_defections_against_me[recipient_id] = max(0, self.recent_defections_against_me.get(recipient_id, 0) - 1)
            # Update interaction counts
            self.interactions[recipient_id]['total'] += 1
            if donor_action == 'cooperate':
                self.interactions[recipient_id]['coop'] += 1
            else:
                self.interactions[recipient_id]['defect'] += 1

        elif recipient_id == self.agent_id:
            # I was the recipient, donor is opponent
            self._init_agent_if_needed(donor_id)
            if donor_action == 'defect' and recipient_action == 'cooperate':
                # They defected while I cooperated
                self.trust[donor_id] -= 0.3
                self.recent_defections_against_me[donor_id] += 1
            elif donor_action == 'cooperate':
                self.trust[donor_id] += 0.1
                self.recent_defections_against_me[donor_id] = max(0, self.recent_defections_against_me.get(donor_id, 0) - 1)
            self.interactions[donor_id]['total'] += 1
            if donor_action == 'cooperate':
                self.interactions[donor_id]['coop'] += 1
            else:
                self.interactions[donor_id]['defect'] += 1
        else:
            # Third-party observation: adjust trust slightly based on observed behavior
            # Positive for mutual cooperation, negative for defection
            if donor_action == 'cooperate':
                self.trust[donor_id] += 0.02
            else:
                self.trust[donor_id] -= 0.04
            if recipient_action == 'cooperate':
                self.trust[recipient_id] += 0.02
            else:
                self.trust[recipient_id] -= 0.04

        # Clamp reputation and trust to reasonable ranges
        for aid in [donor_id, recipient_id]:
            self.reputation[aid] = max(-2.0, min(2.0, self.reputation[aid]))
            self.trust[aid] = max(-2.0, min(2.0, self.trust[aid]))

        # Track rounds
        self.round_count += 1
        self.total_rounds += 1
        # Reset recent defections every 10 rounds to allow forgiveness
        if self.round_count >= 10:
            self.recent_defections_against_me = {k: 0 for k in self.recent_defections_against_me}
            self.round_count = 0

