            self.global_defection_count += 1
        if recipient_action == 'defect':
            self.global_defection_count += 1

        # Update memory records (store cooperation boolean and a simple round counter)
        if donor_id not in self.rep_memory:
            self.rep_memory[donor_id] = deque(maxlen=20)
        self.rep_memory[donor_id].append((donor_action == 'cooperate', self.rounds_played))

        if recipient_id not in self.rep_memory:
            self.rep_memory[recipient_id] = deque(maxlen=20)
        self.rep_memory[recipient_id].append((recipient_action == 'cooperate', self.rounds_played))

