        self.recent_avg = {}
        self.aggression_level = 0.0
        # New mechanism: track a long-term average cooperation rate per opponent
        self.long_term_avg = {}
        # New mechanism: track a dynamic threshold that adjusts based on own recent outcomes
        self.dynamic_threshold = 0.5

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return True

        if opp not in self.reputation:
            self.reputation[opp] = 0.5
        if opp not in self.interactions:
            self.interactions[opp] = []
        if opp not in self.observed_counts:
            self.observed_counts[opp] = [0, 0]
        if opp not in self.coop_rate:
            self.coop_rate[opp] = 0.5
        if opp not in self.consecutive_defections:
            self.consecutive_defections[opp] = 0
        if opp not in self.last_cooperated:
            self.last_cooperated[opp] = False
        if opp not in self.defection_ratio:
            self.defection_ratio[opp] = 0.0
        if opp not in self.recent_outcomes:
            self.recent_outcomes[opp] = []
        if opp not in self.weighted_reputation:
            self.weighted_reputation[opp] = 0.5
        if opp not in self.recent_avg:
            self.recent_avg[opp] = 0.5
        if opp not in self.long_term_avg:
            self.long_term_avg[opp] = 0.5

        obs_coop, obs_def = self.observed_counts[opp]
        total_obs = obs_coop + obs_def
        obs_rate = obs_coop / total_obs if total_obs > 0 else 0.5

        my_hist = self.interactions[opp]
        if my_hist:
            my_coop = sum(1 for a, b in my_hist if a == 'cooperate')
            my_rate = my_coop / len(my_hist)
        else:
            my_rate = 0.5

        blend = 0.6 * obs_rate + 0.4 * my_rate

        self.reputation[opp] = 0.8 * self.reputation[opp] + 0.2 * blend

        if my_hist:
            recent_actions = [b for a, b in my_hist[-3:]]
            if recent_actions:
                recent_coop = sum(1 for act in recent_actions if act == 'cooperate')
                recent_rate = recent_coop / len(recent_actions)
                self.weighted_reputation[opp] = 0.7 * recent_rate + 0.3 * self.weighted_reputation[opp]
            else:
                self.weighted_reputation[opp] = self.reputation[opp]
        else:
            self.weighted_reputation[opp] = self.reputation[opp]

        # New mechanism: long-term average updates with a slower decay
        if my_hist:
            total_coop = sum(1 for a, b in my_hist if a == 'cooperate')
            total_rate = total_coop / len(my_hist)
            self.long_term_avg[opp] = 0.95 * self.long_term_avg[opp] + 0.05 * total_rate
        else:
            self.long_term_avg[opp] = self.reputation[opp]

        self.aggression_level = min(1.0, self.consecutive_defections[opp] / 5.0)

        if self.aggression_level > 0.6:
            return False

        if self.consecutive_defections[opp] >= self.retaliation_threshold:
            if self.recent_outcomes[opp] and len(self.recent_outcomes[opp]) >= self.forgiveness_window:
                recent_coops = sum(1 for outcome in self.recent_outcomes[opp] if outcome == 'cooperate')
                if recent_coops / len(self.recent_outcomes[opp]) > 0.6:
