        threshold = (self.trust_threshold + self.dynamic_threshold) / 2 + 0.1 * gen_factor

        rep_to_use = self.long_term_avg[opp]

        if rep_to_use > threshold:
            return True
        elif random.random() < self.exploration_prob:
            return True
        else:
            return False

