            if action == 'cooperate':
                self.observed_counts[agent_id][0] += 1
            else:
                self.observed_counts[agent_id][1] += 1

        if donor_id == self.agent_id:
            opp = recipient_id
            my_action = donor_action
            their_action = recipient_action
        elif recipient_id == self.agent_id:
            opp = donor_id
            my_action = recipient_action
            their_action = donor_action
        else:
            return

        if opp not in self.interactions:
            self.interactions[opp] = []
        self.interactions[opp].append((my_action, their_action))
        if len(self.interactions[opp]) > 20:
            self.interactions[opp] = self.interactions[opp][-20:]

        if opp not in self.opp_history:
            self.opp_history[opp] = []
        self.opp_history[opp].append(their_action)
        if len(self.opp_history[opp]) > 10:
            self.opp_history[opp] = self.opp_history[opp][-10:]

        if opp not in self.consecutive_defections:
            self.consecutive_defections[opp] = 0
        if their_action == 'defect':
            self.consecutive_defections[opp] += 1
        else:
            self.consecutive_defections[opp] = 0

        if opp not in self.defection_ratio:
            self.defection_ratio[opp] = 0.0
        recent = self.opp_history[opp]
        if recent:
            defections = sum(1 for a in recent if a == 'defect')
            self.defection_ratio[opp] = defections / len(recent)

        if opp not in self.recent_avg:
            self.recent_avg[opp] = 0.5
        recent_actions = [b for a, b in self.interactions[opp][-3:]]
        if recent_actions:
            coop_count = sum(1 for act in recent_actions if act == 'cooperate')
            self.recent_avg[opp] = coop_count / len(recent_actions)

        self.last_cooperated[opp] = (my_action == 'cooperate')

        self.round_count += 1

        self.my_recent_actions.append(my_action)
        if len(self.my_recent_actions) > 10:
            self.my_recent_actions.pop(0)
        self.opp_recent_actions.append(their_action)
        if len(self.opp_recent_actions) > 10:
            self.opp_recent_actions.pop(0)

        if opp not in self.recent_outcomes:
            self.recent_outcomes[opp] = []
        self.recent_outcomes[opp].append(their_action)
        if len(self.recent_outcomes[opp]) > self.forgiveness_window:
            self.recent_outcomes[opp] = self.recent_outcomes[opp][-self.forgiveness_window:]

        # New mechanism: dynamic threshold adjusts based on how often we cooperate vs defect
        if self.my_recent_actions:
            my_coop_count = sum(1 for a in self.my_recent_actions if a == 'cooperate')
            my_coop_rate = my_coop_count / len(self.my_recent_actions)
            # If we cooperate a lot, we become more trusting; if we defect a lot, more cautious
            self.dynamic_threshold = 0.5 - 0.3 * (my_coop_rate - 0.5)

        if self.last_cooperated[opp] and their_action == 'defect':
            self.trust_threshold = min(0.9, self.trust_threshold + 0.08)
        else:
            self.trust_threshold = max(0.2, self.trust_threshold - 0.02)

