        self.trust_boost_coop = 0.15
        self.trust_boost_defect = 0.05
        self.trust_penalty_betrayal = 0.25
        # New mechanism: forgiveness counter and a lower retaliation threshold
        self.forgiveness = {}
        self.forgiveness_rate = 0.1
        self.retaliation_threshold = 1  # changed from 2 to 1

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return True

        if opp not in self.reputation:
            self.reputation[opp] = 0.5
        if opp not in self.interactions:
            self.interactions[opp] = []
        if opp not in self.observed_counts:
            self.observed_counts[opp] = [0, 0]
        if opp not in self.coop_rate:
            self.coop_rate[opp] = 0.5
        if opp not in self.consecutive_defections:
            self.consecutive_defections[opp] = 0
        if opp not in self.last_cooperated:
            self.last_cooperated[opp] = False
        if opp not in self.trust_scores:
            self.trust_scores[opp] = 0.5
        if opp not in self.forgiveness:
            self.forgiveness[opp] = 0.0

        # Decay trust score over time (faster than parent)
        self.trust_scores[opp] *= self.trust_decay

        obs_coop, obs_def = self.observed_counts[opp]
        total_obs = obs_coop + obs_def
        obs_rate = obs_coop / total_obs if total_obs > 0 else 0.5

        my_hist = self.interactions[opp]
        if my_hist:
            my_coop = sum(1 for a, b in my_hist if a == 'cooperate')
            my_rate = my_coop / len(my_hist)
        else:
            my_rate = 0.5

        # Changed blend weights: more weight on observed behavior
        blend = 0.7 * obs_rate + 0.3 * my_rate

        self.reputation[opp] = 0.7 * self.reputation[opp] + 0.3 * blend

        # Combine reputation and trust score with different weighting
        combined_score = 0.6 * self.reputation[opp] + 0.4 * self.trust_scores[opp]

        # Forgiveness mechanism: if we've forgiven, reduce retaliation tendency
        if self.forgiveness[opp] > 0:
            self.forgiveness[opp] = max(0.0, self.forgiveness[opp] - self.forgiveness_rate)
            effective_consecutive = max(0, self.consecutive_defections[opp] - 1)
        else:
            effective_consecutive = self.consecutive_defections[opp]

        if effective_consecutive >= self.retaliation_threshold:
            return False

        gen_factor = math.exp(-self.round_count / 30.0)
        threshold = self.trust_threshold + 0.1 * gen_factor

        if combined_score > threshold:
            return True
        elif random.random() < self.exploration_prob:
            return True
        else:
            return False

