        if len(self.opp_history[opp]) > 10:
            self.opp_history[opp] = self.opp_history[opp][-10:]

        if opp not in self.consecutive_defections:
            self.consecutive_defections[opp] = 0
        if their_action == 'defect':
            self.consecutive_defections[opp] += 1
        else:
            self.consecutive_defections[opp] = 0

        self.last_cooperated[opp] = (my_action == 'cooperate')

        # Update trust score based on opponent's action relative to ours
        if opp not in self.trust_scores:
            self.trust_scores[opp] = 0.5

        if my_action == 'cooperate':
            if their_action == 'cooperate':
                self.trust_scores[opp] += self.trust_boost
