        if opp not in self.alpha:
            self.alpha[opp] = 1.0
        if opp not in self.beta:
            self.beta[opp] = 1.0

        # Decay trust score and momentum over time
        self.trust_scores[opp] *= self.trust_decay
        self.momentum[opp] *= self.momentum_decay

