                self.trust_scores[opp] -= self.trust_penalty
        else:  # we defected
            if their_action == 'cooperate':
                self.trust_scores[opp] += self.trust_boost * 0.5
            # if both defect, no change

        self.trust_scores[opp] = max(0.0, min(1.0, self.trust_scores[opp]))

        # Update forgiveness: gain forgiveness when opponent cooperates after we defected
        if opp not in self.forgiveness:
            self.forgiveness[opp] = 0
        if my_action == 'defect' and their_action == 'cooperate':
            self.forgiveness[opp] = min(self.forgiveness_limit, self.forgiveness[opp] + 1)

        self.round_count += 1

        self.my_recent_actions.append(my_action)
        if len(self.my_recent_actions) > 10:
            self.my_recent_actions.pop(0)
        self.opp_recent_actions.append(their_action)
        if len(self.opp_recent_actions) > 10:
            self.opp_recent_actions.pop(0)

        if self.last_cooperated[opp] and their_action == 'defect':
            self.trust_threshold = min(0.9, self.trust_threshold + 0.08)
        else:
            self.trust_threshold = max(0.2, self.trust_threshold - 0.02)

        # Child modification: adaptive exploration based on performance
        if self.adaptive_exploration:
            # Track recent cooperation rate with this opponent
            if opp in self.interactions and len(self.interactions[opp]) >= 5:
                recent = self.interactions[opp][-5:]
                coop_count = sum(1 for a, b in recent if a == 'cooperate')
                recent_coop_rate = coop_count / len(recent)
                # Increase exploration when cooperation rate is low (struggling)
                if recent_coop_rate < 0.3:
                    self.exploration_prob = min(self.exploration_upper, self.exploration_prob + 0.02)
                elif recent_coop_rate > 0.7:
                    self.exploration_prob = max(self.exploration_lower, self.exploration_prob - 0.01)

