from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.interaction_history = {}
        self.last_opponent_action = None
        self.own_recent_actions = deque(maxlen=10)
        self.generosity = 0.5
        self.trust_threshold = 0.3
        self.forgetting = 0.9
        self.rounds_played = 0
        self.punish_threshold = 2
        self.current_opponent_defections = 0
        self.recent_opponent_actions = deque(maxlen=5)
        self.opponent_cooperation_streak = 0
        self.own_cooperation_streak = 0
        self.streak_bonus = 0.0
        self.global_defection_count = 0
        self.rep_memory = {}
        # New: Track the number of times we've been exploited (opponent defected when we cooperated)
        self.exploitation_count = 0
        # New: Adaptive trust threshold based on exploitation frequency
        self.exploitation_rate = 0.0

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True

        rep = self.reputation.get(opponent, [0, 0])
        coop_count, defect_count = rep[0], rep[1]
        total = coop_count + defect_count
        if total > 0:
            coop_ratio = coop_count / total
        else:
            coop_ratio = 0.5

        history = self.interaction_history.get(opponent, deque())

        # If we have a recent cooperation streak, but have been exploited frequently, be more cautious
        if self.opponent_cooperation_streak >= 2:
            if self.exploitation_rate > 0.3:
                return random.random() < 0.7
            return True

        # If we have history, use reciprocity with streak awareness and exploitation adjustment
        if len(history) > 0:
            recent = list(history)[-3:]
            their_coop = sum(1 for a in recent if a) / len(recent)
            if their_coop >= 0.5:
                return True
            else:
                if self.opponent_cooperation_streak >= 1:
                    return random.random() < 0.4
                # If we've been exploited a lot, punish more harshly
                if self.exploitation_rate > 0.3:
                    return random.random() < 0.05
                return random.random() < 0.2

        # Reputation-based decision with streak bonus and memory-weighted ratio
        if total >= 3:
            if opponent in self.rep_memory:
                mem = self.rep_memory[opponent]
                if len(mem) > 0:
                    weights = [0.5 ** (len(mem) - i) for i in range(len(mem))]
                    coop_sum = sum(w for (coop, _), w in zip(mem, weights) if coop)
                    total_weighted = sum(weights)
                    mem_ratio = coop_sum / total_weighted if total_weighted > 0 else 0.5
                else:
                    mem_ratio = 0.5
            else:
                mem_ratio = coop_ratio

            # Adjust trust threshold based on exploitation rate
            adjusted_threshold = self.trust_threshold + self.exploitation_rate * 0.2
            if mem_ratio >= adjusted_threshold:
                return True
            else:
                return random.random() < 0.1 + self.streak_bonus

        # Unknown opponent: use generosity plus streak bonus, but less generous if exploited often
        if self.rounds_played < 5:
            return True
        else:
            return random.random() < min(1.0, self.generosity + self.streak_bonus - self.exploitation_rate * 0.1)

