import random
import math
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputations = {}
        self.my_reputation = 0.0
        self.generosity = 0.5
        self.forgiveness = 0.5
        self.rounds_played = 0
        self.rounds_observed = 0
        self.suspiciousness = 0.0
        self.partner_history = {}
        self.opponent_id = None
        self._ctx_opponent_id = None
        self.recent_my_actions = deque(maxlen=10)
        self.recent_other_actions = deque(maxlen=10)
        self.window_size = 10
        self.rep_estimates = {}
        self.rep_alpha = 0.3
        # New: track a decayed trust score for each partner
        self.trust_scores = {}
        self.trust_decay = 0.95

    def decide(self) -> bool:
        if self.opponent_id is None:
            self.opponent_id = self._ctx_opponent_id
        if self.opponent_id is None:
            return True
        # Use the decayed trust score if available, else fallback to rolling estimate
        if self.opponent_id in self.trust_scores:
            trust = self.trust_scores[self.opponent_id]
        else:
            trust = self.rep_estimates.get(self.opponent_id, self.reputations.get(self.opponent_id, 0.5))
        # Adjust based on history with this partner
        if self.opponent_id in self.partner_history:
            coop, defect = self.partner_history[self.opponent_id]
            total = coop + defect
            if total > 0:
                hist_ratio = coop / total
                trust = 0.6 * trust + 0.4 * hist_ratio
        # Add slight randomness for exploration
        noise = random.uniform(-0.05, 0.05)
        trust = max(0.0, min(1.0, trust + noise))
        # My reputation and forgiveness influence decision
        if self.my_reputation > 0.7:
            trust += 0.1
        elif self.my_reputation < 0.3:
            trust -= 0.1
        # Use forgiveness to be more lenient after defections
        threshold = 0.5 - self.generosity * 0.2 + self.suspiciousness * 0.1 - self.forgiveness * 0.1
        return trust > threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update rolling reputation estimates with exponential moving average
        delta = 0.0
        if donor_action == 'cooperate':
            delta += 0.1
        else:
            delta -= 0.1
        if recipient_action == 'cooperate':
            delta += 0.05
        else:
            delta -= 0.05
        if donor_action == 'cooperate' and recipient_action == 'cooperate':
            delta += 0.1
        elif donor_action == 'defect' and recipient_action == 'defect':
            delta -= 0.1

        # Update donor's rolling estimate
        if donor_id in self.rep_estimates:
            self.rep_estimates[donor_id] = (1 - self.rep_alpha) * self.rep_estimates[donor_id] + self.rep_alpha * (0.5 + delta)
        else:
            self.rep_estimates[donor_id] = 0.5 + delta
        # Update recipient's rolling estimate (slight)
        if recipient_id in self.rep_estimates:
            self.rep_estimates[recipient_id] = (1 - self.rep_alpha) * self.rep_estimates[recipient_id] + self.rep_alpha * (0.5 + delta * 0.5)
        else:
            self.rep_estimates[recipient_id] = 0.5 + delta * 0.5

        # Also update static reputations for compatibility
        if donor_id in self.reputations:
            self.reputations[donor_id] = max(0.0, min(1.0, self.reputations[donor_id] + delta))
        else:
            self.reputations[donor_id] = max(0.0, min(1.0, 0.5 + delta))
        if recipient_id in self.reputations:
            self.reputations[recipient_id] = max(0.0, min(1.0, self.reputations[recipient_id] + delta * 0.5))
        else:
            self.reputations[recipient_id] = max(0.0, min(1.0, 0.5 + delta * 0.5))

        # Update decayed trust scores for both donor and recipient
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id in self.trust_scores:
                self.trust_scores[agent_id] *= self.trust_decay
            else:
                self.trust_scores[agent_id] = 0.5
            if action == 'cooperate':
                self.trust_scores[agent_id] += 0.1
            else:
                self.trust_scores[agent_id] -= 0.1
            self.trust_scores[agent_id] = max(0.0, min(1.0, self.trust_scores[agent_id]))

        # Track self-judgments
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self.rounds_played += 1
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            other_action = recipient_action if donor_id == self.agent_id else donor_action
            self.recent_my_actions.append(1 if my_action == 'cooperate' else 0)
            self.recent_other_actions.append(1 if other_action == 'cooperate' else 0)
            # Update my reputation based on my action
            if my_action == 'cooperate':
                self.my_reputation = min(1.0, self.my_reputation + 0.1)
            else:
                self.my_reputation = max(0.0, self.my_reputation - 0.1)
            # Track partner history
            partner = self._ctx_opponent_id if self._ctx_opponent_id is not None else self.opponent_id
            if partner is not None:
                if partner not in self.partner_history:
                    self.partner_history[partner] = [0, 0]
                if my_action == 'cooperate':
                    self.partner_history[partner][0] += 1
                else:
                    self.partner_history[partner][1] += 1
            # Adapt generosity based on recent outcomes
            if len(self.recent_my_actions) >= 5:
                my_coop_rate = sum(self.recent_my_actions) / len(self.recent_my_actions)
                other_coop_rate = sum(self.recent_other_actions) / len(self.recent_other_actions)
                if other_coop_rate > 0.7:
                    self.generosity = min(1.0, self.generosity + 0.02)
                elif other_coop_rate < 0.3:
                    self.generosity = max(0.0, self.generosity - 0.02)
                # Adjust forgiveness based on my cooperation vs others
                if my_coop_rate > other_coop_rate + 0.2:
                    self.forgiveness = max(0.0, self.forgiveness - 0.01)
                elif other_coop_rate > my_coop_rate + 0.2:
                    self.forgiveness = min(1.0, self.forgiveness + 0.01)
        else:
            self.rounds_observed += 1
            # Update suspiciousness based on observed defections
            if donor_action == 'defect' or recipient_action == 'defect':
                self.suspiciousness = min(1.0, self.suspiciousness + 0.01)
            else:
                self.suspiciousness = max(0.0, self.suspiciousness - 0.005)
        self.suspiciousness *= 0.999

import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.interactions = {}
        self.observed_counts = {}
        self.coop_rate = {}
        self.round_count = 0
        self.my_recent_actions = []
        self.opp_recent_actions = []
        self._ctx_opponent_id = None
        self.trust_threshold = 0.5
        self.opp_history = {}
        self.consecutive_defections = {}
        self.last_cooperated = {}
        self.retaliation_threshold = 2
        self.exploration_prob = 0.15
        # New mechanism: trust scores that decay over time
        self.trust_scores = {}
        self.trust_decay = 0.95
        self.trust_boost = 0.1
        self.trust_penalty = 0.2
        # Child addition: adaptive thresholds per opponent
        self.opp_adaptive_threshold = {}
        self.threshold_adapt_rate = 0.1
        # Child modification: use a forgetting factor for reputation updates
        self.reputation_forgetting = 0.7
        # Child modification: add a forgiveness counter to reduce retaliation
        self.forgiveness_count = {}
        self.forgiveness_reset = 3

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return True

        if opp not in self.reputation:
            self.reputation[opp] = 0.5
        if opp not in self.interactions:
            self.interactions[opp] = []
        if opp not in self.observed_counts:
            self.observed_counts[opp] = [0, 0]
        if opp not in self.coop_rate:
            self.coop_rate[opp] = 0.5
        if opp not in self.consecutive_defections:
            self.consecutive_defections[opp] = 0
        if opp not in self.last_cooperated:
            self.last_cooperated[opp] = False
        if opp not in self.trust_scores:
            self.trust_scores[opp] = 0.5
        if opp not in self.opp_adaptive_threshold:
            self.opp_adaptive_threshold[opp] = self.trust_threshold
        if opp not in self.forgiveness_count:
            self.forgiveness_count[opp] = 0

        # Decay trust score over time
        self.trust_scores[opp] *= self.trust_decay

        obs_coop, obs_def = self.observed_counts[opp]
        total_obs = obs_coop + obs_def
        obs_rate = obs_coop / total_obs if total_obs > 0 else 0.5

        my_hist = self.interactions[opp]
        if my_hist:
            my_coop = sum(1 for a, b in my_hist if a == 'cooperate')
            my_rate = my_coop / len(my_hist)
        else:
            my_rate = 0.5

        blend = 0.6 * obs_rate + 0.4 * my_rate

        # Child modification: use a stronger forgetting factor to favor recent info
        self.reputation[opp] = self.reputation_forgetting * self.reputation[opp] + (1 - self.reputation_forgetting) * blend

        # Combine reputation and trust score
        combined_score = 0.7 * self.reputation[opp] + 0.3 * self.trust_scores[opp]

        # Child modification: forgiveness mechanism - if we have forgiven recently, reduce retaliation
        if self.consecutive_defections[opp] >= self.retaliation_threshold:
            if self.forgiveness_count[opp] > 0:
                # Temporary forgiveness, ignore defection streak
                return True
            else:
                return False

        gen_factor = math.exp(-self.round_count / 30.0)
        threshold = self.opp_adaptive_threshold[opp] + 0.1 * gen_factor

        if combined_score > threshold:
            return True
        elif random.random() < self.exploration_prob:
            return True
        else:
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.observed_counts:
                self.observed_counts[agent_id] = [0, 0]
            if action == 'cooperate':
                self.observed_counts[agent_id][0] += 1
            else:
                self.observed_counts[agent_id][1] += 1

        if donor_id == self.agent_id:
            opp = recipient_id
            my_action = donor_action
            their_action = recipient_action
        elif recipient_id == self.agent_id:
            opp = donor_id
            my_action = recipient_action
            their_action = donor_action
        else:
            return

        if opp not in self.interactions:
            self.interactions[opp] = []
        self.interactions[opp].append((my_action, their_action))
        if len(self.interactions[opp]) > 20:
            self.interactions[opp] = self.interactions[opp][-20:]

        if opp not in self.opp_history:
            self.opp_history[opp] = []
        self.opp_history[opp].append(their_action)
        if len(self.opp_history[opp]) > 10:
            self.opp_history[opp] = self.opp_history[opp][-10:]

        if opp not in self.consecutive_defections:
            self.consecutive_defections[opp] = 0
        if their_action == 'defect':
            self.consecutive_defections[opp] += 1
        else:
            self.consecutive_defections[opp] = 0

        # Child modification: forgiveness counter - if opponent cooperates after defection streak, we forgive
        if opp not in self.forgiveness_count:
            self.forgiveness_count[opp] = 0
        if their_action == 'cooperate' and self.consecutive_defections[opp] == 0:
            # Reset forgiveness counter when opponent cooperates after a streak
            self.forgiveness_count[opp] = 0
        elif their_action == 'cooperate' and self.consecutive_defections[opp] > 0:
            # Give forgiveness if they cooperate after some defections
            self.forgiveness_count[opp] += 1
        else:
            # Defection, decrement forgiveness
            self.forgiveness_count[opp] = max(0, self.forgiveness_count[opp] - 1)

        self.last_cooperated[opp] = (my_action == 'cooperate')

        # Update trust score based on opponent's action relative to ours
        if opp not in self.trust_scores:
            self.trust_scores[opp] = 0.5

        if my_action == 'cooperate':
            if their_action == 'cooperate':
                self.trust_scores[opp] += self.trust_boost
            else:  # they defected after we cooperated
                self.trust_scores[opp] -= self.trust_penalty
        else:  # we defected
            if their_action == 'cooperate':
                self.trust_scores[opp] += self.trust_boost * 0.5
            # if both defect, no change

        self.trust_scores[opp] = max(0.0, min(1.0, self.trust_scores[opp]))

        # Child addition: adapt the opponent-specific threshold based on outcomes
        if opp not in self.opp_adaptive_threshold:
            self.opp_adaptive_threshold[opp] = self.trust_threshold
        # If we cooperated and they defected, raise threshold (less trusting)
        if my_action == 'cooperate' and their_action == 'defect':
            self.opp_adaptive_threshold[opp] = min(0.9, self.opp_adaptive_threshold[opp] + self.threshold_adapt_rate)
        # If we defected and they cooperated, lower threshold (more trusting)
        elif my_action == 'defect' and their_action == 'cooperate':
            self.opp_adaptive_threshold[opp] = max(0.2, self.opp_adaptive_threshold[opp] - self.threshold_adapt_rate)

        self.round_count += 1

        self.my_recent_actions.append(my_action)
        if len(self.my_recent_actions) > 10:
            self.my_recent_actions.pop(0)
        self.opp_recent_actions.append(their_action)
        if len(self.opp_recent_actions) > 10:
            self.opp_recent_actions.pop(0)

        if self.last_cooperated[opp] and their_action == 'defect':
            self.trust_threshold = min(0.9, self.trust_threshold + 0.08)
        else:
            self.trust_threshold = max(0.2, self.trust_threshold - 0.02)

