            coop_rate = sum(opp_history) / len(opp_history)
        else:
            coop_rate = 0.5

        # Combine reputation and direct history, with recency bias
        combined = 0.7 * coop_rate + 0.3 * opp_rep

        # Adaptive threshold based on generosity and round number
        threshold = 0.5 - self.generosity * 0.2

        # In early rounds, be more cooperative to build trust
        if self.rounds_played < 5:
            threshold -= 0.1

        # Slight deterministic noise based on agent id to avoid symmetry
        threshold += (self.agent_id % 3 - 1) * 0.02

        decision = combined > threshold
        if decision:
            self.total_cooperate += 1
        self.total_decisions += 1

        # Update own recent actions
        self.own_recent.append(decision)
        if len(self.own_recent) > self.memory:
            self.own_recent.pop(0)

        return decision

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation for both actors
        self._update_reputation(donor_id, donor_action, recipient_id, recipient_action)

        # Update history if it's our interaction
        if donor_id == self.agent_id:
            self._record_interaction(recipient_id, recipient_action)
        elif recipient_id == self.agent_id:
            self._record_interaction(donor_id, donor_action)

        # Record recent actions for third-party observation
        self._record_recent_action(donor_id, donor_action)
        self._record_recent_action(recipient_id, recipient_action)

        # Adjust generosity based on observed outcomes
        self._adapt_generosity(donor_id, donor_action, recipient_id, recipient_action)

    def _update_reputation(self, donor_id, donor_action, recipient_id, recipient_action):
        # Simple reputation: cooperate good, defect bad
        if donor_action == 'cooperate':
            self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) + 0.05
        else:
            self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) - 0.08

        if recipient_action == 'cooperate':
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) + 0.05
        else:
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) - 0.08

        # Clamp to [0,1]
        for aid in [donor_id, recipient_id]:
            self.reputation[aid] = max(0.0, min(1.0, self.reputation[aid]))

    def _record_interaction(self, other_id, action):
        if other_id not in self.history:
            self.history[other_id] = []
        self.history[other_id].append(action == 'cooperate')
        # Keep only recent history
        if len(self.history[other_id]) > self.memory:
            self.history[other_id].pop(0)

    def _record_recent_action(self, agent_id, action):
        if agent_id not in self.recent_actions:
            self.recent_actions[agent_id] = []
        self.recent_actions[agent_id].append(action)
        if len(self.recent_actions[agent_id]) > self.memory:
            self.recent_actions[agent_id].pop(0)

    def _adapt_generosity(self, donor_id, donor_action, recipient_id, recipient_action):
        # If we're involved, adjust based on outcome
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # Determine if we were exploited or not
            if donor_id == self.agent_id:
                my_action = donor_action
                other_action = recipient_action
            else:
                my_action = recipient_action
                other_action = donor_action

            if my_action == 'cooperate' and other_action == 'defect':
                # We were exploited, reduce generosity
                self.generosity = max(0.0, self.generosity - 0.05)
            elif my_action == 'defect' and other_action == 'cooperate':
                # We exploited them, increase generosity slightly
                self.generosity = min(1.0, self.generosity + 0.02)
            else:
                # Mutual cooperation or both defect
                self.generosity = min(1.0, self.generosity + 0.01)

