            if opponent not in self.recent_coop_rate:
                self.recent_coop_rate[opponent] = deque(maxlen=10)
            self.recent_coop_rate[opponent].append(opponent_action == 'cooperate')

            # New: Modify generosity based on opponent's best streak - reward long-term cooperation
            if opponent in self.best_streak and self.best_streak[opponent] >= 3:
                self.generosity = min(0.9, self.generosity + 0.01)  # Slight boost for proven cooperators

            # Modified generosity update: less harsh when global defections are high
            if my_action == 'cooperate' and opponent_action == 'defect':
                penalty = 0.05 if self.global_defection_count < 50 else 0.02
                # New: Reduce penalty if we have seen this opponent cooperate a lot recently
                if opponent in self.recent_coop_rate and len(self.recent_coop_rate[opponent]) > 0:
                    recent_coop = sum(self.recent_coop_rate[opponent]) / len(self.recent_coop_rate[opponent])
                    if recent_coop > 0.7:
                        penalty *= 0.5  # More forgiving to generally cooperative opponents
                self.generosity = max(0.1, self.generosity - penalty)
            elif my_action == 'cooperate' and opponent_action == 'cooperate':
                self.generosity = min(0.9, self.generosity + 0.02 + self.streak_bonus * 0.1)
            elif my_action == 'defect' and opponent_action == 'cooperate':
                self.generosity = min(0.9, self.generosity + 0.03)

            if opponent_action == 'defect':
                self.current_opponent_defections += 1
            else:
                self.current_opponent_defections = 0

            if self.current_opponent_defections >= self.punish_threshold:
                self.generosity = max(0.1, self.generosity - 0.1)
                self.current_opponent_defections = 0

            self.recent_opponent_actions.append(opponent_action == 'cooperate')

            if len(self.recent_opponent_actions) == 5:
                coop_fraction = sum(self.recent_opponent_actions) / 5
                if coop_fraction < 0.5:
                    self.trust_threshold = min(0.9, self.trust_threshold + 0.05)
                else:
                    self.trust_threshold = max(0.1, self.trust_threshold - 0.05)

            # New: Update reputation trend based on recent actions
            if opponent not in self.rep_trend:
                self.rep_trend[opponent] = 0.0
            if opponent_action == 'cooperate':
                self.rep_trend[opponent] = min(1.0, self.rep_trend[opponent] + 0.1)
            else:
                self.rep_trend[opponent] = max(-1.0, self.rep_trend[opponent] - 0.1)

            self.rounds_played += 1

import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputations = {}
        self.my_reputation = 0.0
        self.generosity = 0.5
        self.forgiveness = 0.5
        self.rounds_played = 0
        self.rounds_observed = 0
        self.suspiciousness = 0.0
        self.partner_history = {}
        self.opponent_id = None
        self._ctx_opponent_id = None
        self.recent_my_actions = deque(maxlen=10)
        self.recent_other_actions = deque(maxlen=10)
        self.window_size = 10
        self.rep_estimates = {}
        self.rep_alpha = 0.3
        # New: track a decayed trust score for each partner
        self.trust_scores = {}
        self.trust_decay = 0.95
        # New: track a "social credit" score based on observed behavior
        self.social_credit = {}
        self.social_credit_alpha = 0.1
        self.social_credit_baseline = 0.5
        self.social_credit_boost = 0.2
        self.social_credit_penalty = 0.3

    def decide(self) -> bool:
        if self.opponent_id is None:
            self.opponent_id = self._ctx_opponent_id
        if self.opponent_id is None:
            return True
        # Use the decayed trust score if available, else fallback to social credit
        if self.opponent_id in self.trust_scores:
            trust = self.trust_scores[self.opponent_id]
        else:
            trust = self.social_credit.get(self.opponent_id, self.reputations.get(self.opponent_id, 0.5))
        # Adjust based on history with this partner
        if self.opponent_id in self.partner_history:
            coop, defect = self.partner_history[self.opponent_id]
            total = coop + defect
            if total > 0:
                hist_ratio = coop / total
                trust = 0.6 * trust + 0.4 * hist_ratio
        # Add slight randomness for exploration
        noise = random.uniform(-0.05, 0.05)
        trust = max(0.0, min(1.0, trust + noise))
        # My reputation and forgiveness influence decision
        if self.my_reputation > 0.7:
            trust += 0.1
        elif self.my_reputation < 0.3:
            trust -= 0.1
        # Use forgiveness to be more lenient after defections
        threshold = 0.5 - self.generosity * 0.2 + self.suspiciousness * 0.1 - self.forgiveness * 0.1
        return trust > threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update rolling reputation estimates with exponential moving average
        delta = 0.0
        if donor_action == 'cooperate':
            delta += 0.1
        else:
            delta -= 0.1
        if recipient_action == 'cooperate':
            delta += 0.05
        else:
            delta -= 0.05
        if donor_action == 'cooperate' and recipient_action == 'cooperate':
            delta += 0.1
        elif donor_action == 'defect' and recipient_action == 'defect':
            delta -= 0.1

        # Update donor's rolling estimate
        if donor_id in self.rep_estimates:
            self.rep_estimates[donor_id] = (1 - self.rep_alpha) * self.rep_estimates[donor_id] + self.rep_alpha * (0.5 + delta)
        else:
            self.rep_estimates[donor_id] = 0.5 + delta
        # Update recipient's rolling estimate (slight)
        if recipient_id in self.rep_estimates:
            self.rep_estimates[recipient_id] = (1 - self.rep_alpha) * self.rep_estimates[recipient_id] + self.rep_alpha * (0.5 + delta * 0.5)
        else:
            self.rep_estimates[recipient_id] = 0.5 + delta * 0.5

        # Also update static reputations for compatibility
        if donor_id in self.reputations:
            self.reputations[donor_id] = max(0.0, min(1.0, self.reputations[donor_id] + delta))
        else:
            self.reputations[donor_id] = max(0.0, min(1.0, 0.5 + delta))
        if recipient_id in self.reputations:
            self.reputations[recipient_id] = max(0.0, min(1.0, self.reputations[recipient_id] + delta * 0.5))
        else:
            self.reputations[recipient_id] = max(0.0, min(1.0, 0.5 + delta * 0.5))

        # Update decayed trust scores for both donor and recipient
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id in self.trust_scores:
                self.trust_scores[agent_id] *= self.trust_decay
            else:
                self.trust_scores[agent_id] = 0.5
            if action == 'cooperate':
                self.trust_scores[agent_id] += 0.1
            else:
                self.trust_scores[agent_id] -= 0.1
            self.trust_scores[agent_id] = max(0.0, min(1.0, self.trust_scores[agent_id]))

        # NEW: Update social credit scores based on observed behavior
        # Social credit is a public reputation that is more sensitive to defections
        # and less to cooperation, to punish free-riders more heavily.
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.social_credit:
                self.social_credit[agent_id] = self.social_credit_baseline
            if action == 'cooperate':
                # Cooperation gives a small boost, but not as much as the penalty for defection
                self.social_credit[agent_id] += self.social_credit_boost * self.social_credit_alpha
            else:
                # Defection gives a large penalty to discourage bad behavior
                self.social_credit[agent_id] -= self.social_credit_penalty * self.social_credit_alpha
            # Clamp to [0,1]
            self.social_credit[agent_id] = max(0.0, min(1.0, self.social_credit[agent_id]))
            # Exponential decay towards baseline to gradually forget old behavior
            self.social_credit[agent_id] = self.social_credit[agent_id] * (1 - self.social_credit_alpha) + self.social_credit_baseline * self.social_credit_alpha

        # Track self-judgments
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self.rounds_played += 1
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            other_action = recipient_action if donor_id == self.agent_id else donor_action
            self.recent_my_actions.append(1 if my_action == 'cooperate' else 0)
            self.recent_other_actions.append(1 if other_action == 'cooperate' else 0)
            # Update my reputation based on my action
            if my_action == 'cooperate':
                self.my_reputation = min(1.0, self.my_reputation + 0.1)
            else:
                self.my_reputation = max(0.0, self.my_reputation - 0.1)
            # Track partner history
            partner = self._ctx_opponent_id if self._ctx_opponent_id is not None else self.opponent_id
            if partner is not None:
                if partner not in self.partner_history:
                    self.partner_history[partner] = [0, 0]
                if my_action == 'cooperate':
                    self.partner_history[partner][0] += 1
                else:
                    self.partner_history[partner][1] += 1
            # Adapt generosity based on recent outcomes
            if len(self.recent_my_actions) >= 5:
                my_coop_rate = sum(self.recent_my_actions) / len(self.recent_my_actions)
                other_coop_rate = sum(self.recent_other_actions) / len(self.recent_other_actions)
                if other_coop_rate > 0.7:
                    self.generosity = min(1.0, self.generosity + 0.02)
                elif other_coop_rate < 0.3:
                    self.generosity = max(0.0, self.generosity - 0.02)
                # Adjust forgiveness based on my cooperation vs others
                if my_coop_rate > other_coop_rate + 0.2:
                    self.forgiveness = max(0.0, self.forgiveness - 0.01)
                elif other_coop_rate > my_coop_rate + 0.2:
                    self.forgiveness = min(1.0, self.forgiveness + 0.01)
        else:
            self.rounds_observed += 1
            # Update suspiciousness based on observed defections
            if donor_action == 'defect' or recipient_action == 'defect':
                self.suspiciousness = min(1.0, self.suspiciousness + 0.01)
            else:
                self.suspiciousness = max(0.0, self.suspiciousness - 0.005)
        self.suspiciousness *= 0.999

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.interaction_history = {}
        self.last_opponent_action = None
        self.own_recent_actions = deque(maxlen=10)
        self.generosity = 0.5
        self.trust_threshold = 0.3
        self.forgetting = 0.9
        self.rounds_played = 0
        self.punish_threshold = 2
        self.current_opponent_defections = 0
        self.recent_opponent_actions = deque(maxlen=5)
        # New: Track opponent's cooperation streak (consecutive cooperations)
        self.opponent_cooperation_streak = 0
        # New: Track our own cooperation streak
        self.own_cooperation_streak = 0
        # New: Adaptive generosity based on streak length
        self.streak_bonus = 0.0
        # New: Track total defections observed from any agent to adjust forgiveness
        self.global_defection_count = 0
        # New: Track opponent's recent cooperation frequency for adaptive threshold
        self.opponent_recent_coop_freq = 0.5

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True

        rep = self.reputation.get(opponent, [0, 0])
        coop_count, defect_count = rep[0], rep[1]
        total = coop_count + defect_count
        if total > 0:
            coop_ratio = coop_count / total
        else:
            coop_ratio = 0.5

        history = self.interaction_history.get(opponent, deque())

        # If we have a recent cooperation streak with this opponent, be more generous
        if self.opponent_cooperation_streak >= 2:
            # But only if opponent's recent cooperation frequency is high enough
            if self.opponent_recent_coop_freq >= 0.5:
                return True
            else:
                # If freq is low, still be generous but with a chance
                return random.random() < 0.7

        # If we have history, use reciprocity with streak awareness
        if len(history) > 0:
            recent = list(history)[-3:]
            their_coop = sum(1 for a in recent if a) / len(recent)
            if their_coop >= 0.5:
                return True
            else:
                # If they defected, but we have a good streak, give a second chance
                if self.opponent_cooperation_streak >= 1:
                    return random.random() < 0.4
                return random.random() < 0.2

        # Reputation-based decision with streak bonus and adaptive threshold
        if total >= 3:
            # Adjust threshold based on opponent's recent frequency
            adaptive_threshold = self.trust_threshold * (1 - self.opponent_recent_coop_freq * 0.3)
            if coop_ratio >= adaptive_threshold:
                return True
            else:
                return random.random() < 0.1 + self.streak_bonus

        # Unknown opponent: use generosity plus streak bonus
        if self.rounds_played < 5:
            return True
        else:
            return random.random() < min(1.0, self.generosity + self.streak_bonus)

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Track global defections
        if donor_action == 'defect':
            self.global_defection_count += 1
        if recipient_action == 'defect':
            self.global_defection_count += 1

        donor_rep = self.reputation.get(donor_id, [0, 0])
        if donor_action == 'cooperate':
            donor_rep[0] += 1
        else:
            donor_rep[1] += 1
        donor_rep[0] = max(1, int(donor_rep[0] * self.forgetting))
        donor_rep[1] = max(1, int(donor_rep[1] * self.forgetting))
        self.reputation[donor_id] = donor_rep

        recipient_rep = self.reputation.get(recipient_id, [0, 0])
        if recipient_action == 'cooperate':
            recipient_rep[0] += 1
        else:
            recipient_rep[1] += 1
        recipient_rep[0] = max(1, int(recipient_rep[0] * self.forgetting))
        recipient_rep[1] = max(1, int(recipient_rep[1] * self.forgetting))
        self.reputation[recipient_id] = recipient_rep

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                opponent = recipient_id
                opponent_action = recipient_action
                my_action = donor_action
            else:
                opponent = donor_id
                opponent_action = donor_action
                my_action = recipient_action

            if opponent not in self.interaction_history:
                self.interaction_history[opponent] = deque(maxlen=10)
            self.interaction_history[opponent].append(opponent_action == 'cooperate')

            self.own_recent_actions.append(my_action == 'cooperate')

            # Update streaks and streak bonus
            if opponent_action == 'cooperate':
                self.opponent_cooperation_streak += 1
            else:
                self.opponent_cooperation_streak = 0

            if my_action == 'cooperate':
                self.own_cooperation_streak += 1
            else:
                self.own_cooperation_streak = 0

            # Streak bonus: more generous if both we and opponent are cooperating
            self.streak_bonus = min(0.3, 0.05 * min(self.opponent_cooperation_streak, self.own_cooperation_streak))

            # Update opponent's recent cooperation frequency
            recent_actions = list(self.interaction_history[opponent])[-5:]
            if recent_actions:
                self.opponent_recent_coop_freq = sum(1 for a in recent_actions if a) / len(recent_actions)
            else:
                self.opponent_recent_coop_freq = 0.5

            # Modified generosity update: less harsh when global defections are high
            if my_action == 'cooperate' and opponent_action == 'defect':
                penalty = 0.05 if self.global_defection_count < 50 else 0.02
                self.generosity = max(0.1, self.generosity - penalty)
            elif my_action == 'cooperate' and opponent_action == 'cooperate':
                self.generosity = min(0.9, self.generosity + 0.02 + self.streak_bonus * 0.1)
            elif my_action == 'defect' and opponent_action == 'cooperate':
                self.generosity = min(0.9, self.generosity + 0.03)

            if opponent_action == 'defect':
                self.current_opponent_defections += 1
            else:
                self.current_opponent_defections = 0

            if self.current_opponent_defections >= self.punish_threshold:
                self.generosity = max(0.1, self.generosity - 0.1)
                self.current_opponent_defections = 0

            self.recent_opponent_actions.append(opponent_action == 'cooperate')

            if len(self.recent_opponent_actions) == 5:
                coop_fraction = sum(self.recent_opponent_actions) / 5
                if coop_fraction < 0.5:
                    self.trust_threshold = min(0.9, self.trust_threshold + 0.05)
                else:
                    self.trust_threshold = max(0.1, self.trust_threshold - 0.05)

            self.rounds_played += 1

import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.interactions = {}
        self.observed_counts = {}
        self.coop_rate = {}
        self.round_count = 0
        self.my_recent_actions = []
        self.opp_recent_actions = []
        self._ctx_opponent_id = None
        self.trust_threshold = 0.5
        self.opp_history = {}
        self.consecutive_defections = {}
        self.last_cooperated = {}
        self.retaliation_threshold = 2
        self.exploration_prob = 0.15
        self.trust_scores = {}
        self.trust_decay = 0.95
        self.trust_boost = 0.1
        self.trust_penalty = 0.2
        self.opp_adaptive_threshold = {}
        self.threshold_adapt_rate = 0.1
        # Child addition: momentum-based trust adjustment
        self.momentum = {}
        self.momentum_decay = 0.9
        self.momentum_boost = 0.2
        # Child addition: bayesian belief parameters
        self.alpha = {}
        self.beta = {}

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return True

        if opp not in self.reputation:
            self.reputation[opp] = 0.5
        if opp not in self.interactions:
            self.interactions[opp] = []
        if opp not in self.observed_counts:
            self.observed_counts[opp] = [0, 0]
        if opp not in self.coop_rate:
            self.coop_rate[opp] = 0.5
        if opp not in self.consecutive_defections:
            self.consecutive_defections[opp] = 0
        if opp not in self.last_cooperated:
            self.last_cooperated[opp] = False
        if opp not in self.trust_scores:
            self.trust_scores[opp] = 0.5
        if opp not in self.opp_adaptive_threshold:
            self.opp_adaptive_threshold[opp] = self.trust_threshold
        if opp not in self.momentum:
            self.momentum[opp] = 0.0
        if opp not in self.alpha:
            self.alpha[opp] = 1.0
        if opp not in self.beta:
            self.beta[opp] = 1.0

        # Decay trust score and momentum over time
        self.trust_scores[opp] *= self.trust_decay
        self.momentum[opp] *= self.momentum_decay

        obs_coop, obs_def = self.observed_counts[opp]
        total_obs = obs_coop + obs_def
        obs_rate = obs_coop / total_obs if total_obs > 0 else 0.5

        my_hist = self.interactions[opp]
        if my_hist:
            my_coop = sum(1 for a, b in my_hist if a == 'cooperate')
            my_rate = my_coop / len(my_hist)
        else:
            my_rate = 0.5

        blend = 0.6 * obs_rate + 0.4 * my_rate

        self.reputation[opp] = 0.8 * self.reputation[opp] + 0.2 * blend

        # Bayesian posterior mean as an additional component
        bayesian_score = self.alpha[opp] / (self.alpha[opp] + self.beta[opp])

        # Combine reputation, trust score, momentum, and bayesian belief
        combined_score = 0.5 * self.reputation[opp] + 0.2 * self.trust_scores[opp] + 0.2 * self.momentum[opp] + 0.1 * bayesian_score

        if self.consecutive_defections[opp] >= self.retaliation_threshold:
            return False

        gen_factor = math.exp(-self.round_count / 30.0)
        threshold = self.opp_adaptive_threshold[opp] + 0.1 * gen_factor

        if combined_score > threshold:
            return True
        elif random.random() < self.exploration_prob:
            return True
        else:
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.observed_counts:
                self.observed_counts[agent_id] = [0, 0]
            if action == 'cooperate':
                self.observed_counts[agent_id][0] += 1
            else:
                self.observed_counts[agent_id][1] += 1

        if donor_id == self.agent_id:
            opp = recipient_id
            my_action = donor_action
            their_action = recipient_action
        elif recipient_id == self.agent_id:
            opp = donor_id
            my_action = recipient_action
            their_action = donor_action
        else:
            return

        if opp not in self.interactions:
            self.interactions[opp] = []
        self.interactions[opp].append((my_action, their_action))
        if len(self.interactions[opp]) > 20:
            self.interactions[opp] = self.interactions[opp][-20:]

        if opp not in self.opp_history:
            self.opp_history[opp] = []
        self.opp_history[opp].append(their_action)
        if len(self.opp_history[opp]) > 10:
            self.opp_history[opp] = self.opp_history[opp][-10:]

        if opp not in self.consecutive_defections:
            self.consecutive_defections[opp] = 0
        if their_action == 'defect':
            self.consecutive_defections[opp] += 1
        else:
            self.consecutive_defections[opp] = 0

        self.last_cooperated[opp] = (my_action == 'cooperate')

        if opp not in self.trust_scores:
            self.trust_scores[opp] = 0.5
        if opp not in self.momentum:
            self.momentum[opp] = 0.0
        if opp not in self.alpha:
            self.alpha[opp] = 1.0
        if opp not in self.beta:
            self.beta[opp] = 1.0

        # Update trust score and momentum based on relative actions
        if my_action == 'cooperate':
            if their_action == 'cooperate':
                self.trust_scores[opp] += self.trust_boost
                self.momentum[opp] += self.momentum_boost
            else:
                self.trust_scores[opp] -= self.trust_penalty
                self.momentum[opp] -= self.momentum_boost * 1.5
        else:
            if their_action == 'cooperate':
                self.trust_scores[opp] += self.trust_boost * 0.5
                self.momentum[opp] += self.momentum_boost * 0.5
            else:
                self.momentum[opp] -= self.momentum_boost * 0.5

        self.trust_scores[opp] = max(0.0, min(1.0, self.trust_scores[opp]))
        self.momentum[opp] = max(-1.0, min(1.0, self.momentum[opp]))

        # Update Bayesian belief based on opponent's action
        if their_action == 'cooperate':
            self.alpha[opp] += 1.0
        else:
            self.beta[opp] += 1.0
        # Cap the influence of very high counts to avoid overconfidence
        total_updates = self.alpha[opp] + self.beta[opp]
        if total_updates > 30:
            scale = 30.0 / total_updates
            self.alpha[opp] = 1.0 + (self.alpha[opp] - 1.0) * scale
            self.beta[opp] = 1.0 + (self.beta[opp] - 1.0) * scale

        if opp not in self.opp_adaptive_threshold:
            self.opp_adaptive_threshold[opp] = self.trust_threshold
        if my_action == 'cooperate' and their_action == 'defect':
            self.opp_adaptive_threshold[opp] = min(0.9, self.opp_adaptive_threshold[opp] + self.threshold_adapt_rate)
        elif my_action == 'defect' and their_action == 'cooperate':
            self.opp_adaptive_threshold[opp] = max(0.2, self.opp_adaptive_threshold[opp] - self.threshold_adapt_rate)

        self.round_count += 1

        self.my_recent_actions.append(my_action)
        if len(self.my_recent_actions) > 10:
            self.my_recent_actions.pop(0)
        self.opp_recent_actions.append(their_action)
