        if opp not in self.stubbornness:
            self.stubbornness[opp] = self.stubbornness_init
        if their_action == 'defect':
            self.stubbornness[opp] = min(self.stubbornness_cap, self.stubbornness[opp] + self.stubbornness_increment)
        else:
            self.stubbornness[opp] = max(self.stubbornness_init, self.stubbornness[opp] - self.stubbornness_increment)

