        self.opponent_coop_moving_avg = {}
        # New: Weight for recency in reputation decisions
        self.recency_weight = 0.7
        # New: Track opponent's forgiveness tendency (how often they cooperate after we defect)
        self.opponent_forgiveness = {}
        # New: Pessimism factor - increases threshold when we've been exploited recently
        self.pessimism = 0.0
        # New: Decay rate for pessimism
        self.pessimism_decay = 0.1

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True

        rep = self.reputation.get(opponent, [0, 0])
        coop_count, defect_count = rep[0], rep[1]
        total = coop_count + defect_count
        if total > 0:
            coop_ratio = coop_count / total
        else:
            coop_ratio = 0.5

        history = self.interaction_history.get(opponent, deque())

        # If we have a recent cooperation streak, but have been exploited frequently, be more cautious
        if self.opponent_cooperation_streak >= 2:
            if self.exploitation_rate > 0.3:
                return random.random() < 0.7
            return True

        # If we have history, use reciprocity with streak awareness and exploitation adjustment
        if len(history) > 0:
            recent = list(history)[-3:]
            their_coop = sum(1 for a in recent if a) / len(recent)
            if their_coop >= 0.5:
                return True
            else:
                if self.opponent_cooperation_streak >= 1:
                    return random.random() < 0.4
                if self.exploitation_rate > 0.3:
                    return random.random() < 0.05
                return random.random() < 0.2

        # Reputation-based decision with moving average and recency weighting
        if total >= 3:
            # Use moving average if available, otherwise fall back to overall ratio
            if opponent in self.opponent_coop_moving_avg:
                moving_avg = self.opponent_coop_moving_avg[opponent]
            else:
                moving_avg = coop_ratio

            # Blend overall and moving average with recency weight
            blended_ratio = self.recency_weight * moving_avg + (1 - self.recency_weight) * coop_ratio

            # Adjusted threshold includes pessimism from recent exploitation
            adjusted_threshold = self.trust_threshold + self.exploitation_rate * 0.2 + self.pessimism
            if blended_ratio >= adjusted_threshold:
                return True
            else:
                return random.random() < 0.1 + self.streak_bonus

        # Unknown opponent: use generosity plus streak bonus, but less generous if exploited often
        if self.rounds_played < 5:
            return True
        else:
            return random.random() < min(1.0, self.generosity + self.streak_bonus - self.exploitation_rate * 0.1)

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        if donor_action == 'defect':
            self.global_defection_count += 1
        if recipient_action == 'defect':
            self.global_defection_count += 1

        if donor_id not in self.rep_memory:
            self.rep_memory[donor_id] = deque(maxlen=20)
