import math

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputations = {}
        self.my_reputation = 0.0
        self.generosity = 0.5
        self.forgiveness = 0.5
        self.rounds_played = 0
        self.rounds_observed = 0
        self.suspiciousness = 0.0
        # Track partner history: partner_id -> (coop_count, defect_count)
        self.partner_history = {}
        self.opponent_id = None
        self._ctx_opponent_id = None
        # Track recent actions for adaptive parameters
        self.recent_my_actions = []
        self.recent_other_actions = []
        self.window_size = 10

    def decide(self) -> bool:
        if self.opponent_id is None:
            self.opponent_id = self._ctx_opponent_id
        if self.opponent_id is None:
            return True  # no opponent, cooperate
        opp_rep = self.reputations.get(self.opponent_id, 0.5)
        # Base trust on opponent's reputation
        trust = opp_rep
        # Adjust based on history with this partner
        if self.opponent_id in self.partner_history:
            coop, defect = self.partner_history[self.opponent_id]
            total = coop + defect
            if total > 0:
                hist_ratio = coop / total
                trust = 0.7 * trust + 0.3 * hist_ratio
        # Add slight randomness for exploration
        noise = random.uniform(-0.05, 0.05)
        trust = max(0.0, min(1.0, trust + noise))
        # My reputation influences how bold I can be
        if self.my_reputation > 0.7:
            trust += 0.1
        elif self.my_reputation < 0.3:
            trust -= 0.1
        # Also consider overall generosity
        threshold = 0.5 - self.generosity * 0.2 + self.suspiciousness * 0.1
        return trust > threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation based on observed actions
        # Helping (cooperate) increases reputation, defecting decreases
        delta = 0.0
        if donor_action == 'cooperate':
            delta += 0.1
        else:
            delta -= 0.1
        if recipient_action == 'cooperate':
            delta += 0.05
        else:
            delta -= 0.05
        # Bilateral cooperation is good, mutual defection is bad
        if donor_action == 'cooperate' and recipient_action == 'cooperate':
            delta += 0.1
        elif donor_action == 'defect' and recipient_action == 'defect':
            delta -= 0.1
        # Update donor's reputation
        if donor_id in self.reputations:
            self.reputations[donor_id] = max(0.0, min(1.0, self.reputations[donor_id] + delta))
        else:
            self.reputations[donor_id] = max(0.0, min(1.0, 0.5 + delta))
        # Update recipient's reputation (slight)
        if recipient_id in self.reputations:
            self.reputations[recipient_id] = max(0.0, min(1.0, self.reputations[recipient_id] + delta * 0.5))
        else:
            self.reputations[recipient_id] = max(0.0, min(1.0, 0.5 + delta * 0.5))

        # Track self-judgments
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self.rounds_played += 1
            # Update my own reputation based on my actions
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            other_action = recipient_action if donor_id == self.agent_id else donor_action
            self.recent_my_actions.append(1 if my_action == 'cooperate' else 0)
            self.recent_other_actions.append(1 if other_action == 'cooperate' else 0)
            if len(self.recent_my_actions) > self.window_size:
                self.recent_my_actions.pop(0)
                self.recent_other_actions.pop(0)
            # Update my reputation based on my action
            if my_action == 'cooperate':
                self.my_reputation = min(1.0, self.my_reputation + 0.1)
            else:
                self.my_reputation = max(0.0, self.my_reputation - 0.1)
            # Track partner history
            partner = self._ctx_opponent_id if self._ctx_opponent_id is not None else self.opponent_id
            if partner is not None:
                if partner not in self.partner_history:
                    self.partner_history[partner] = [0, 0]
                if my_action == 'cooperate':
                    self.partner_history[partner][0] += 1
                else:
                    self.partner_history[partner][1] += 1
            # Adapt generosity based on recent outcomes
            if len(self.recent_my_actions) >= 5:
                my_coop_rate = sum(self.recent_my_actions) / len(self.recent_my_actions)
                other_coop_rate = sum(self.recent_other_actions) / len(self.recent_other_actions)
                # If others cooperate more, be more generous; if they defect, be less
                if other_coop_rate > 0.7:
                    self.generosity = min(1.0, self.generosity + 0.02)
                elif other_coop_rate < 0.3:
                    self.generosity = max(0.0, self.generosity - 0.02)
                # Adjust forgiveness based on my own cooperation vs others
                if my_coop_rate > other_coop_rate + 0.2:
                    self.forgiveness = max(0.0, self.forgiveness - 0.01)
                elif other_coop_rate > my_coop_rate + 0.2:
                    self.forgiveness = min(1.0, self.forgiveness + 0.01)
        else:
            self.rounds_observed += 1
            # Update suspiciousness based on observed defections
            if donor_action == 'defect' or recipient_action == 'defect':
                self.suspiciousness = min(1.0, self.suspiciousness + 0.01)
            else:
                self.suspiciousness = max(0.0, self.suspiciousness - 0.005)
        # Decay suspiciousness slowly over time
        self.suspiciousness *= 0.999

