        self.forgetting = 0.9
        self.rounds_played = 0
        self.punish_threshold = 2
        self.current_opponent_defections = 0
        self.recent_opponent_actions = deque(maxlen=5)
        # Track opponent's cooperation streak (consecutive cooperations)
        self.opponent_cooperation_streak = 0
        # Track our own cooperation streak
        self.own_cooperation_streak = 0
        # Adaptive generosity based on streak length
        self.streak_bonus = 0.0
        # Track total defections observed from any agent to adjust forgiveness
        self.global_defection_count = 0
        # Track opponent's recent cooperation frequency for adaptive threshold
        self.opponent_recent_coop_freq = 0.5
        # NEW: Track opponent's cooperation streak length across all observations
        self.opponent_streaks = {}
        # NEW: Track our own recent behavior to adjust trust threshold
        self.own_recent_coop_freq = 0.5

