        if len(history) > 0:
            recent = list(history)[-3:]
            their_coop = sum(1 for a in recent if a) / len(recent)
            if their_coop >= 0.5:
                return True
            else:
                # If they defected, but we have a good streak, give a second chance
                if self.opponent_cooperation_streak >= 1:
                    return random.random() < 0.4
                return random.random() < 0.2

        # Reputation-based decision with streak bonus and adaptive threshold
        if total >= 3:
            # Adjust threshold based on opponent's recent frequency and our own behavior
            adaptive_threshold = self.trust_threshold * (1 - self.opponent_recent_coop_freq * 0.3)
            # NEW: If we've been cooperating recently, be more forgiving
            if self.own_recent_coop_freq > 0.7:
                adaptive_threshold *= 0.8
            if coop_ratio >= adaptive_threshold:
                return True
            else:
                return random.random() < 0.1 + self.streak_bonus

        # Unknown opponent: use generosity plus streak bonus
        if self.rounds_played < 5:
