            self.opponent_streaks[donor_id] = self.opponent_streaks.get(donor_id, 0) + 1
        else:
            self.opponent_streaks[donor_id] = 0
        if recipient_action == 'cooperate':
            self.opponent_streaks[recipient_id] = self.opponent_streaks.get(recipient_id, 0) + 1
