        self.trust_scores[opp] = max(0.0, min(1.0, self.trust_scores[opp]))

        # Child addition: adapt the opponent-specific threshold based on outcomes
        if opp not in self.opp_adaptive_threshold:
            self.opp_adaptive_threshold[opp] = self.trust_threshold
        # If we cooperated and they defected, raise threshold (less trusting)
