from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.interaction_history = {}
        self.last_opponent_action = None
        self.own_recent_actions = deque(maxlen=10)
        self.generosity = 0.5
        self.trust_threshold = 0.3
        self.forgetting = 0.9
        self.rounds_played = 0
        self.punish_threshold = 2
        self.current_opponent_defections = 0
        self.recent_opponent_actions = deque(maxlen=5)
        self.opponent_cooperation_streak = 0
        self.own_cooperation_streak = 0
        self.streak_bonus = 0.0
        self.global_defection_count = 0
        self.rep_memory = {}
        self.exploitation_count = 0
        self.exploitation_rate = 0.0
        # New: Track a moving average of opponent cooperation for a more nuanced view
        self.opponent_coop_moving_avg = {}
        # New: Weight for recency in reputation decisions
        self.recency_weight = 0.7
        # New: Track opponent's forgiveness tendency (how often they cooperate after we defect)
        self.opponent_forgiveness = {}
        # New: Pessimism factor - increases threshold when we've been exploited recently
        self.pessimism = 0.0
        # New: Decay rate for pessimism
        self.pessimism_decay = 0.1

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True

        rep = self.reputation.get(opponent, [0, 0])
        coop_count, defect_count = rep[0], rep[1]
        total = coop_count + defect_count
        if total > 0:
            coop_ratio = coop_count / total
        else:
            coop_ratio = 0.5

        history = self.interaction_history.get(opponent, deque())

        # If we have a recent cooperation streak, but have been exploited frequently, be more cautious
        if self.opponent_cooperation_streak >= 2:
            if self.exploitation_rate > 0.3:
                return random.random() < 0.7
            return True

        # If we have history, use reciprocity with streak awareness and exploitation adjustment
        if len(history) > 0:
            recent = list(history)[-3:]
            their_coop = sum(1 for a in recent if a) / len(recent)
            if their_coop >= 0.5:
                return True
            else:
                if self.opponent_cooperation_streak >= 1:
                    return random.random() < 0.4
                if self.exploitation_rate > 0.3:
                    return random.random() < 0.05
                return random.random() < 0.2

        # Reputation-based decision with moving average and recency weighting
        if total >= 3:
            # Use moving average if available, otherwise fall back to overall ratio
            if opponent in self.opponent_coop_moving_avg:
                moving_avg = self.opponent_coop_moving_avg[opponent]
            else:
                moving_avg = coop_ratio

            # Blend overall and moving average with recency weight
            blended_ratio = self.recency_weight * moving_avg + (1 - self.recency_weight) * coop_ratio

            # Adjusted threshold includes pessimism from recent exploitation
            adjusted_threshold = self.trust_threshold + self.exploitation_rate * 0.2 + self.pessimism
            if blended_ratio >= adjusted_threshold:
                return True
            else:
                return random.random() < 0.1 + self.streak_bonus

        # Unknown opponent: use generosity plus streak bonus, but less generous if exploited often
        if self.rounds_played < 5:
            return True
        else:
            return random.random() < min(1.0, self.generosity + self.streak_bonus - self.exploitation_rate * 0.1)

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        if donor_action == 'defect':
            self.global_defection_count += 1
        if recipient_action == 'defect':
            self.global_defection_count += 1

        if donor_id not in self.rep_memory:
            self.rep_memory[donor_id] = deque(maxlen=20)
        self.rep_memory[donor_id].append((donor_action == 'cooperate', self.rounds_played))

        if recipient_id not in self.rep_memory:
            self.rep_memory[recipient_id] = deque(maxlen=20)
        self.rep_memory[recipient_id].append((recipient_action == 'cooperate', self.rounds_played))

        donor_rep = self.reputation.get(donor_id, [0, 0])
        if donor_action == 'cooperate':
            donor_rep[0] += 1
        else:
            donor_rep[1] += 1
        donor_rep[0] = max(1, int(donor_rep[0] * self.forgetting))
        donor_rep[1] = max(1, int(donor_rep[1] * self.forgetting))
        self.reputation[donor_id] = donor_rep

        recipient_rep = self.reputation.get(recipient_id, [0, 0])
        if recipient_action == 'cooperate':
            recipient_rep[0] += 1
        else:
            recipient_rep[1] += 1
        recipient_rep[0] = max(1, int(recipient_rep[0] * self.forgetting))
        recipient_rep[1] = max(1, int(recipient_rep[1] * self.forgetting))
        self.reputation[recipient_id] = recipient_rep

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                opponent = recipient_id
                opponent_action = recipient_action
                my_action = donor_action
            else:
                opponent = donor_id
                opponent_action = donor_action
                my_action = recipient_action

            if opponent not in self.interaction_history:
                self.interaction_history[opponent] = deque(maxlen=10)
            self.interaction_history[opponent].append(opponent_action == 'cooperate')

            # Update moving average for opponent
            if opponent not in self.opponent_coop_moving_avg:
                self.opponent_coop_moving_avg[opponent] = 0.5
            # Exponential moving average with alpha=0.3
            self.opponent_coop_moving_avg[opponent] = (
                0.3 * (opponent_action == 'cooperate') +
                0.7 * self.opponent_coop_moving_avg[opponent]
            )

            self.own_recent_actions.append(my_action == 'cooperate')

            if opponent_action == 'cooperate':
                self.opponent_cooperation_streak += 1
            else:
                self.opponent_cooperation_streak = 0

            if my_action == 'cooperate':
                self.own_cooperation_streak += 1
            else:
                self.own_cooperation_streak = 0

            self.streak_bonus = min(0.3, 0.05 * min(self.opponent_cooperation_streak, self.own_cooperation_streak))

            # New: Track opponent's forgiveness - do they cooperate after we defect?
            if my_action == 'defect' and opponent_action == 'cooperate':
                # Opponent forgave our defection
                if opponent not in self.opponent_forgiveness:
                    self.opponent_forgiveness[opponent] = [0, 0]  # [forgive_count, total_defect_against_them]
                self.opponent_forgiveness[opponent][0] += 1
                self.opponent_forgiveness[opponent][1] += 1
            elif my_action == 'defect' and opponent_action == 'defect':
                if opponent not in self.opponent_forgiveness:
                    self.opponent_forgiveness[opponent] = [0, 0]
                self.opponent_forgiveness[opponent][1] += 1

            # Update pessimism: increase when exploited, decay otherwise
            if my_action == 'cooperate' and opponent_action == 'defect':
                self.pessimism = min(0.5, self.pessimism + 0.15)
            else:
                self.pessimism = max(0.0, self.pessimism - self.pessimism_decay)

            if my_action == 'cooperate' and opponent_action == 'defect':
                self.exploitation_count += 1
                self.exploitation_rate = self.exploitation_count / (self.rounds_played + 1)
                penalty = 0.05 if self.global_defection_count < 50 else 0.02
                self.generosity = max(0.1, self.generosity - penalty)
            elif my_action == 'cooperate' and opponent_action == 'cooperate':
                self.generosity = min(0.9, self.generosity + 0.02 + self.streak_bonus * 0.1)
            elif my_action == 'defect' and opponent_action == 'cooperate':
                self.generosity = min(0.9, self.generosity + 0.03)

            if opponent_action == 'defect':
                self.current_opponent_defections += 1
            else:
                self.current_opponent_defections = 0

            if self.current_opponent_defections >= self.punish_threshold:
                self.generosity = max(0.1, self.generosity - 0.1)
                self.current_opponent_defections = 0

            self.recent_opponent_actions.append(opponent_action == 'cooperate')

            if len(self.recent_opponent_actions) == 5:
                coop_fraction = sum(self.recent_opponent_actions) / 5
                if coop_fraction < 0.5:
                    self.trust_threshold = min(0.9, self.trust_threshold + 0.05)
                else:
                    self.trust_threshold = max(0.1, self.trust_threshold - 0.05)

            self.rounds_played += 1

import random
import math

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputations = {}
        self.my_reputation = 0.0
        self.generosity = 0.5
        self.forgiveness = 0.5
        self.rounds_played = 0
        self.rounds_observed = 0
        self.suspiciousness = 0.0
        # Track partner history: partner_id -> (coop_count, defect_count)
        self.partner_history = {}
        self.opponent_id = None
        self._ctx_opponent_id = None
        # Track recent actions for adaptive parameters
        self.recent_my_actions = []
        self.recent_other_actions = []
        self.window_size = 10

    def decide(self) -> bool:
        if self.opponent_id is None:
            self.opponent_id = self._ctx_opponent_id
        if self.opponent_id is None:
            return True  # no opponent, cooperate
        opp_rep = self.reputations.get(self.opponent_id, 0.5)
        # Base trust on opponent's reputation
        trust = opp_rep
        # Adjust based on history with this partner
        if self.opponent_id in self.partner_history:
            coop, defect = self.partner_history[self.opponent_id]
            total = coop + defect
            if total > 0:
                hist_ratio = coop / total
                trust = 0.7 * trust + 0.3 * hist_ratio
        # Add slight randomness for exploration
        noise = random.uniform(-0.05, 0.05)
        trust = max(0.0, min(1.0, trust + noise))
        # My reputation influences how bold I can be
        if self.my_reputation > 0.7:
            trust += 0.1
        elif self.my_reputation < 0.3:
            trust -= 0.1
        # Also consider overall generosity
        threshold = 0.5 - self.generosity * 0.2 + self.suspiciousness * 0.1
        return trust > threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation based on observed actions
        # Helping (cooperate) increases reputation, defecting decreases
        delta = 0.0
        if donor_action == 'cooperate':
            delta += 0.1
        else:
            delta -= 0.1
        if recipient_action == 'cooperate':
            delta += 0.05
        else:
            delta -= 0.05
        # Bilateral cooperation is good, mutual defection is bad
        if donor_action == 'cooperate' and recipient_action == 'cooperate':
            delta += 0.1
        elif donor_action == 'defect' and recipient_action == 'defect':
            delta -= 0.1
        # Update donor's reputation
        if donor_id in self.reputations:
            self.reputations[donor_id] = max(0.0, min(1.0, self.reputations[donor_id] + delta))
        else:
            self.reputations[donor_id] = max(0.0, min(1.0, 0.5 + delta))
        # Update recipient's reputation (slight)
        if recipient_id in self.reputations:
            self.reputations[recipient_id] = max(0.0, min(1.0, self.reputations[recipient_id] + delta * 0.5))
        else:
            self.reputations[recipient_id] = max(0.0, min(1.0, 0.5 + delta * 0.5))

        # Track self-judgments
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self.rounds_played += 1
            # Update my own reputation based on my actions
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            other_action = recipient_action if donor_id == self.agent_id else donor_action
            self.recent_my_actions.append(1 if my_action == 'cooperate' else 0)
            self.recent_other_actions.append(1 if other_action == 'cooperate' else 0)
            if len(self.recent_my_actions) > self.window_size:
                self.recent_my_actions.pop(0)
                self.recent_other_actions.pop(0)
            # Update my reputation based on my action
            if my_action == 'cooperate':
                self.my_reputation = min(1.0, self.my_reputation + 0.1)
            else:
                self.my_reputation = max(0.0, self.my_reputation - 0.1)
            # Track partner history
            partner = self._ctx_opponent_id if self._ctx_opponent_id is not None else self.opponent_id
            if partner is not None:
                if partner not in self.partner_history:
                    self.partner_history[partner] = [0, 0]
                if my_action == 'cooperate':
                    self.partner_history[partner][0] += 1
                else:
                    self.partner_history[partner][1] += 1
            # Adapt generosity based on recent outcomes
            if len(self.recent_my_actions) >= 5:
                my_coop_rate = sum(self.recent_my_actions) / len(self.recent_my_actions)
                other_coop_rate = sum(self.recent_other_actions) / len(self.recent_other_actions)
                # If others cooperate more, be more generous; if they defect, be less
                if other_coop_rate > 0.7:
                    self.generosity = min(1.0, self.generosity + 0.02)
                elif other_coop_rate < 0.3:
                    self.generosity = max(0.0, self.generosity - 0.02)
                # Adjust forgiveness based on my own cooperation vs others
                if my_coop_rate > other_coop_rate + 0.2:
                    self.forgiveness = max(0.0, self.forgiveness - 0.01)
                elif other_coop_rate > my_coop_rate + 0.2:
                    self.forgiveness = min(1.0, self.forgiveness + 0.01)
        else:
            self.rounds_observed += 1
            # Update suspiciousness based on observed defections
            if donor_action == 'defect' or recipient_action == 'defect':
                self.suspiciousness = min(1.0, self.suspiciousness + 0.01)
            else:
                self.suspiciousness = max(0.0, self.suspiciousness - 0.005)
        # Decay suspiciousness slowly over time
        self.suspiciousness *= 0.999

