import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.interactions = {}
        self.observed_counts = {}
        self.coop_rate = {}
        self.round_count = 0
        self.my_recent_actions = deque(maxlen=10)
        self.opp_recent_actions = deque(maxlen=10)
        self._ctx_opponent_id = None
        self.trust_threshold = 0.5
        self.opp_history = {}
        self.consecutive_defections = {}
        self.last_cooperated = {}
        self.retaliation_threshold = 2
        self.exploration_prob = 0.15
        # Keep trust scores and decay but replace boost/penalty with a gradient-based update
        self.trust_scores = {}
        self.trust_decay = 0.95
        self.trust_boost = 0.1
        self.trust_penalty = 0.2
        # Replace forgiveness counter with a sliding window of recent cooperation signals
        self.coop_signal_window = {}
        self.window_size = 5
        self.coop_signal_threshold = 0.6
        # New mechanism: reputation momentum and adaptive exploration (kept from parent)
        self.reputation_momentum = 0.1
        self.adaptive_exploration = True
        self.exploration_lower = 0.05
        self.exploration_upper = 0.25
        # Additional mechanism: a per-opponent "stubbornness" factor that reduces exploration
        self.stubbornness = {}
        self.stubbornness_init = 0.0
        self.stubbornness_increment = 0.02
        self.stubbornness_cap = 0.3

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return True

        if opp not in self.reputation:
            self.reputation[opp] = 0.5
        if opp not in self.interactions:
            self.interactions[opp] = []
        if opp not in self.observed_counts:
            self.observed_counts[opp] = [0, 0]
        if opp not in self.coop_rate:
            self.coop_rate[opp] = 0.5
        if opp not in self.consecutive_defections:
            self.consecutive_defections[opp] = 0
        if opp not in self.last_cooperated:
            self.last_cooperated[opp] = False
        if opp not in self.trust_scores:
            self.trust_scores[opp] = 0.5
        if opp not in self.coop_signal_window:
            self.coop_signal_window[opp] = deque(maxlen=self.window_size)
        if opp not in self.stubbornness:
            self.stubbornness[opp] = self.stubbornness_init

        # Decay trust score over time
        self.trust_scores[opp] *= self.trust_decay

        obs_coop, obs_def = self.observed_counts[opp]
        total_obs = obs_coop + obs_def
        obs_rate = obs_coop / total_obs if total_obs > 0 else 0.5

        my_hist = self.interactions[opp]
        if my_hist:
            my_coop = sum(1 for a, b in my_hist if a == 'cooperate')
            my_rate = my_coop / len(my_hist)
        else:
            my_rate = 0.5

        blend = 0.6 * obs_rate + 0.4 * my_rate

        # Reputation update with momentum (same as parent)
        old_rep = self.reputation[opp]
        new_rep = 0.8 * old_rep + 0.2 * blend
        self.reputation[opp] = new_rep + self.reputation_momentum * (new_rep - old_rep)

        # Combine reputation and trust score (no forgiveness factor now)
        combined_score = 0.7 * self.reputation[opp] + 0.3 * self.trust_scores[opp]

        if self.consecutive_defections[opp] >= self.retaliation_threshold:
            # Use cooperation signal window instead of forgiveness counter
            window = self.coop_signal_window[opp]
            if len(window) > 0:
                coop_fraction = sum(window) / len(window)
                if coop_fraction >= self.coop_signal_threshold:
                    return True  # Override retaliation if recent cooperation is strong
            return False

        gen_factor = math.exp(-self.round_count / 30.0)
        threshold = self.trust_threshold + 0.1 * gen_factor

        # Stubbornness reduces willingness to explore
        adjusted_exploration = max(0.0, self.exploration_prob - self.stubbornness[opp])

        if combined_score > threshold:
            return True
        elif random.random() < adjusted_exploration:
            return True
        else:
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.observed_counts:
                self.observed_counts[agent_id] = [0, 0]
            if action == 'cooperate':
                self.observed_counts[agent_id][0] += 1
            else:
                self.observed_counts[agent_id][1] += 1

        if donor_id == self.agent_id:
            opp = recipient_id
            my_action = donor_action
            their_action = recipient_action
        elif recipient_id == self.agent_id:
            opp = donor_id
            my_action = recipient_action
            their_action = donor_action
        else:
            return

        if opp not in self.interactions:
            self.interactions[opp] = []
        self.interactions[opp].append((my_action, their_action))
        if len(self.interactions[opp]) > 20:
            self.interactions[opp] = self.interactions[opp][-20:]

        if opp not in self.opp_history:
            self.opp_history[opp] = []
        self.opp_history[opp].append(their_action)
        if len(self.opp_history[opp]) > 10:
            self.opp_history[opp] = self.opp_history[opp][-10:]

        if opp not in self.consecutive_defections:
            self.consecutive_defections[opp] = 0
        if their_action == 'defect':
            self.consecutive_defections[opp] += 1
        else:
            self.consecutive_defections[opp] = 0

        self.last_cooperated[opp] = (my_action == 'cooperate')

        # Update trust score with a more nuanced rule: reward mutual cooperation, penalize exploitation more
        if opp not in self.trust_scores:
            self.trust_scores[opp] = 0.5

        if my_action == 'cooperate':
            if their_action == 'cooperate':
                self.trust_scores[opp] += self.trust_boost
            else:  # they defected after we cooperated
                self.trust_scores[opp] -= self.trust_penalty * 1.5  # amplified penalty
        else:  # we defected
            if their_action == 'cooperate':
                self.trust_scores[opp] += self.trust_boost * 0.5
            # if both defect, no change

        self.trust_scores[opp] = max(0.0, min(1.0, self.trust_scores[opp]))

        # Update cooperation signal window (replaces forgiveness counter)
        if opp not in self.coop_signal_window:
            self.coop_signal_window[opp] = deque(maxlen=self.window_size)
        self.coop_signal_window[opp].append(1 if their_action == 'cooperate' else 0)

        # Update stubbornness: increases when opponent defects often, decreases when they cooperate
        if opp not in self.stubbornness:
            self.stubbornness[opp] = self.stubbornness_init
        if their_action == 'defect':
            self.stubbornness[opp] = min(self.stubbornness_cap, self.stubbornness[opp] + self.stubbornness_increment)
        else:
            self.stubbornness[opp] = max(self.stubbornness_init, self.stubbornness[opp] - self.stubbornness_increment)

        self.round_count += 1

        self.my_recent_actions.append(my_action)
        self.opp_recent_actions.append(their_action)

        if self.last_cooperated[opp] and their_action == 'defect':
            self.trust_threshold = min(0.9, self.trust_threshold + 0.08)
        else:
            self.trust_threshold = max(0.2, self.trust_threshold - 0.02)

        # Adaptive exploration (same as parent but also affected by stubbornness)
        if self.adaptive_exploration:
            if opp in self.interactions and len(self.interactions[opp]) >= 5:
                recent = self.interactions[opp][-5:]
                coop_count = sum(1 for a, b in recent if a == 'cooperate')
                recent_coop_rate = coop_count / len(recent)
                if recent_coop_rate < 0.3:
                    self.exploration_prob = min(self.exploration_upper, self.exploration_prob + 0.02)
                elif recent_coop_rate > 0.7:
                    self.exploration_prob = max(self.exploration_lower, self.exploration_prob - 0.01)

