            return True

        rep = self.reputation.get(opponent, [0, 0])
        coop_count, defect_count = rep[0], rep[1]
        total = coop_count + defect_count
        if total > 0:
            coop_ratio = coop_count / total
        else:
            coop_ratio = 0.5

        history = self.interaction_history.get(opponent, deque())

        # If we have a recent cooperation streak, but have been exploited frequently, be more cautious
        if self.opponent_cooperation_streak >= 2:
            if self.exploitation_rate > 0.3:
                return random.random() < 0.7
            return True

        # If we have history, use reciprocity with streak awareness and exploitation adjustment
        if len(history) > 0:
