import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.interactions = {}
        self.observed_counts = {}
        self.coop_rate = {}
        self.round_count = 0
        self.my_recent_actions = []
        self.opp_recent_actions = []
        self._ctx_opponent_id = None
        self.trust_threshold = 0.5
        self.opp_history = {}
        self.consecutive_defections = {}
        self.last_cooperated = {}
        self.retaliation_threshold = 2
        self.exploration_prob = 0.15
        # New mechanism: trust scores that decay over time
        self.trust_scores = {}
        self.trust_decay = 0.95
        self.trust_boost = 0.1
        self.trust_penalty = 0.2
        # Additional structural choice: a per-opponent forgiveness counter
        self.forgiveness = {}
        self.forgiveness_limit = 2
        self.forgiveness_reset = 0.2
        # Child modification: replace momentum with a "reputation volatility" mechanism
        # and add a more aggressive exploration schedule based on uncertainty
        self.volatility = {}
        self.volatility_initial = 0.1
        self.volatility_scale = 0.05
        self.volatility_decay = 0.9
        self.exploration_base = 0.15
        self.exploration_uncertainty_weight = 2.0

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return True

        if opp not in self.reputation:
            self.reputation[opp] = 0.5
        if opp not in self.interactions:
            self.interactions[opp] = []
        if opp not in self.observed_counts:
            self.observed_counts[opp] = [0, 0]
        if opp not in self.coop_rate:
            self.coop_rate[opp] = 0.5
        if opp not in self.consecutive_defections:
            self.consecutive_defections[opp] = 0
        if opp not in self.last_cooperated:
            self.last_cooperated[opp] = False
        if opp not in self.trust_scores:
            self.trust_scores[opp] = 0.5
        if opp not in self.forgiveness:
            self.forgiveness[opp] = 0
        if opp not in self.volatility:
            self.volatility[opp] = self.volatility_initial

        # Decay trust score over time
        self.trust_scores[opp] *= self.trust_decay

        obs_coop, obs_def = self.observed_counts[opp]
        total_obs = obs_coop + obs_def
        obs_rate = obs_coop / total_obs if total_obs > 0 else 0.5

        my_hist = self.interactions[opp]
        if my_hist:
            my_coop = sum(1 for a, b in my_hist if a == 'cooperate')
            my_rate = my_coop / len(my_hist)
        else:
            my_rate = 0.5

        blend = 0.6 * obs_rate + 0.4 * my_rate

        # Child modification: use volatility to widen the effective reputation difference
        # instead of momentum. Volatility represents uncertainty about the opponent.
        old_rep = self.reputation[opp]
        new_rep = 0.8 * old_rep + 0.2 * blend
        # Update volatility based on how much the new blend deviates from expectation
        deviation = abs(blend - old_rep)
        self.volatility[opp] = self.volatility[opp] * self.volatility_decay + deviation * self.volatility_scale
        self.volatility[opp] = max(0.05, min(0.5, self.volatility[opp]))
        # Incorporate volatility into reputation: more volatility causes a larger pull toward blend
        effective_rep = old_rep + (new_rep - old_rep) * (1 + self.volatility[opp])
        self.reputation[opp] = max(0.0, min(1.0, effective_rep))

        # Combine reputation and trust score, but also add forgiveness factor
        combined_score = 0.7 * self.reputation[opp] + 0.3 * self.trust_scores[opp]
        combined_score += self.forgiveness[opp] * self.forgiveness_reset

        if self.consecutive_defections[opp] >= self.retaliation_threshold:
            # If we have forgiveness remaining, override retaliation
            if self.forgiveness[opp] > 0:
                self.forgiveness[opp] -= 1
                return True
            return False

        gen_factor = math.exp(-self.round_count / 30.0)
        threshold = self.trust_threshold + 0.1 * gen_factor

        # Child modification: exploration probability depends on volatility (uncertainty)
        # and also on how close we are to the threshold (marginal decisions)
        margin = abs(combined_score - threshold)
        uncertainty_factor = 1.0 if margin > 0.2 else (margin / 0.2)
        exploration = self.exploration_base + self.exploration_uncertainty_weight * self.volatility[opp] * uncertainty_factor
        exploration = min(0.4, max(0.02, exploration))

        if combined_score > threshold:
            return True
        elif random.random() < exploration:
            return True
        else:
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.observed_counts:
                self.observed_counts[agent_id] = [0, 0]
            if action == 'cooperate':
                self.observed_counts[agent_id][0] += 1
            else:
                self.observed_counts[agent_id][1] += 1

        if donor_id == self.agent_id:
            opp = recipient_id
            my_action = donor_action
            their_action = recipient_action
        elif recipient_id == self.agent_id:
            opp = donor_id
            my_action = recipient_action
            their_action = donor_action
        else:
            return

        if opp not in self.interactions:
            self.interactions[opp] = []
        self.interactions[opp].append((my_action, their_action))
        if len(self.interactions[opp]) > 20:
            self.interactions[opp] = self.interactions[opp][-20:]

        if opp not in self.opp_history:
            self.opp_history[opp] = []
        self.opp_history[opp].append(their_action)
        if len(self.opp_history[opp]) > 10:
            self.opp_history[opp] = self.opp_history[opp][-10:]

        if opp not in self.consecutive_defections:
            self.consecutive_defections[opp] = 0
        if their_action == 'defect':
            self.consecutive_defections[opp] += 1
        else:
            self.consecutive_defections[opp] = 0

        self.last_cooperated[opp] = (my_action == 'cooperate')

        # Update trust score based on opponent's action relative to ours
        if opp not in self.trust_scores:
            self.trust_scores[opp] = 0.5

        if my_action == 'cooperate':
            if their_action == 'cooperate':
                self.trust_scores[opp] += self.trust_boost
            else:  # they defected after we cooperated
                self.trust_scores[opp] -= self.trust_penalty
        else:  # we defected
            if their_action == 'cooperate':
                self.trust_scores[opp] += self.trust_boost * 0.5
            # if both defect, no change

        self.trust_scores[opp] = max(0.0, min(1.0, self.trust_scores[opp]))

        # Update forgiveness: gain forgiveness when opponent cooperates after we defected
        if opp not in self.forgiveness:
            self.forgiveness[opp] = 0
        if my_action == 'defect' and their_action == 'cooperate':
            self.forgiveness[opp] = min(self.forgiveness_limit, self.forgiveness[opp] + 1)

        self.round_count += 1

        self.my_recent_actions.append(my_action)
        if len(self.my_recent_actions) > 10:
            self.my_recent_actions.pop(0)
        self.opp_recent_actions.append(their_action)
        if len(self.opp_recent_actions) > 10:
            self.opp_recent_actions.pop(0)

        if self.last_cooperated[opp] and their_action == 'defect':
            self.trust_threshold = min(0.9, self.trust_threshold + 0.08)
        else:
            self.trust_threshold = max(0.2, self.trust_threshold - 0.02)

        # Child modification: update volatility based on recent outcome consistency
        if opp not in self.volatility:
            self.volatility[opp] = self.volatility_initial
        # If our action and their action are consistent (both cooperate or both defect),
        # reduce volatility; otherwise increase it
        if (my_action == 'cooperate' and their_action == 'cooperate') or (my_action == 'defect' and their_action == 'defect'):
            self.volatility[opp] *= 0.95
        else:
            self.volatility[opp] += 0.02
        self.volatility[opp] = max(0.05, min(0.5, self.volatility[opp]))

