class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.interaction_memory = {}
        self.my_history = []
        self.coop_count = 0
        self.defect_count = 0
        self.coop_with = {}
        self.defect_with = {}
        self.opp_coop_rate = {}
        self.obs_count = {}
        self.round_num = 0
        # New: track recent actions to detect patterns (e.g., tit-for-tat)
        self.recent_opponent_actions = {}  # opponent_id -> list of recent actions (max length 3)
        # New: forgiveness factor - how quickly we forgive defections
        self.forgiveness = 0.3

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', -1)
        if opponent == -1:
            return True
        # Base reputation probability
        rep = self.reputation.get(opponent, 0.0)
        rep_prob = (rep + 1) / 2.0
        # Personal experience probability
        my_coop_rate = self.coop_with.get(opponent, 0)
        my_defect_rate = self.defect_with.get(opponent, 0)
        if my_coop_rate + my_defect_rate > 0:
            personal = my_coop_rate / (my_coop_rate + my_defect_rate)
        else:
            personal = 0.5
        personal_weight = min(1.0, (my_coop_rate + my_defect_rate) / 10.0)
        combined = (1 - personal_weight) * rep_prob + personal_weight * personal
        # New: Tit-for-tat component - if opponent defected recently, reduce cooperation
        recent_actions = self.recent_opponent_actions.get(opponent, [])
        if recent_actions and recent_actions[-1] == 'defect':
            combined *= (1 - self.forgiveness)  # punish recent defection
        # Add noise
        noise = 0.02 * math.sin(self.round_num * 0.5 + opponent)
        combined = min(0.95, max(0.05, combined + noise))
        return random.random() < combined

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        key = (donor_id, recipient_id)
        self.interaction_memory[key] = (donor_action, recipient_action)
        if donor_id != self.agent_id:
            self._update_reputation(donor_id, donor_action)
        if recipient_id != self.agent_id:
            self._update_reputation(recipient_id, recipient_action)
        if donor_id == self.agent_id:
            self._record_my_action(recipient_id, donor_action)
            self._record_opponent_action(recipient_id, recipient_action)
            # Update recent opponent actions when we are donor
            self._update_recent_opponent_actions(recipient_id, recipient_action)
        if recipient_id == self.agent_id:
            self._record_my_action(donor_id, recipient_action)
            self._record_opponent_action(donor_id, donor_action)
            # Update recent opponent actions when we are recipient
            self._update_recent_opponent_actions(donor_id, donor_action)
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self.round_num += 1

    def _update_reputation(self, agent_id: int, action: str):
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.0
        # Modified: asymmetric update - cooperation gives smaller positive, defection larger negative
        if action == 'cooperate':
            self.reputation[agent_id] += 0.05
        else:
            self.reputation[agent_id] -= 0.15
        self.reputation[agent_id] = max(-1.0, min(1.0, self.reputation[agent_id]))

    def _record_my_action(self, opponent_id: int, action: str):
        if action == 'cooperate':
            self.coop_count += 1
            self.coop_with[opponent_id] = self.coop_with.get(opponent_id, 0) + 1
        else:
            self.defect_count += 1
            self.defect_with[opponent_id] = self.defect_with.get(opponent_id, 0) + 1
        self.my_history.append((opponent_id, action))

    def _record_opponent_action(self, opponent_id: int, action: str):
        if opponent_id not in self.opp_coop_rate:
            self.opp_coop_rate[opponent_id] = {'coop': 0, 'defect': 0}
        if action == 'cooperate':
            self.opp_coop_rate[opponent_id]['coop'] += 1
        else:
            self.opp_coop_rate[opponent_id]['defect'] += 1
        self.obs_count[opponent_id] = self.obs_count.get(opponent_id, 0) + 1

    def _update_recent_opponent_actions(self, opponent_id: int, action: str):
        if opponent_id not in self.recent_opponent_actions:
            self.recent_opponent_actions[opponent_id] = []
        # Keep only last 3 actions
        self.recent_opponent_actions[opponent_id].append(action)
        if len(self.recent_opponent_actions[opponent_id]) > 3:
            self.recent_opponent_actions[opponent_id].pop(0)

