            else:
                self.coop_momentum[agent_id] -= self.momentum_alpha * self.coop_momentum[agent_id]
            self.coop_momentum[agent_id] = max(0.0, min(1.0, self.coop_momentum[agent_id]))

        # Update social credit scores based on observed behavior
        # Social credit is a public reputation that is more sensitive to defections
        # and less to cooperation, to punish free-riders more heavily.
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.social_credit:
                self.social_credit[agent_id] = self.social_credit_baseline
            if action == 'cooperate':
                # Cooperation gives a small boost, but not as much as the penalty for defection
                self.social_credit[agent_id] += self.social_credit_boost * self.social_credit_alpha
            else:
