class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}  # agent_id -> reputation score
        self.partner_history = {}  # opponent_id -> list of (my_action, their_action)
        self.own_coop_count = 0
        self.own_defect_count = 0
        self.round_num = 0
        self.generation_num = 0
        self.partner_rep_cache = {}

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True

        # Update round counter based on number of decisions made
        total_actions = self.own_coop_count + self.own_defect_count
        self.round_num = total_actions

        # Initialize reputation for unknown agents
        if opponent not in self.reputation:
            self.reputation[opponent] = 0.5

        # Get opponent reputation
        opp_rep = self.reputation.get(opponent, 0.5)

        # Get interaction history with this opponent
        history = self.partner_history.get(opponent, [])

        # Strategy: Tit-for-tat with forgiveness and reputation adjustment
        if not history:
            # First interaction: cooperate if reputation is decent
            return opp_rep >= 0.4

        # Look at last interaction
        last_my, last_their = history[-1]

        # If opponent defected last time, cooperate with probability based on reputation
        if last_their == 'defect':
            # Forgive with probability based on opponent's reputation
            forgiveness_prob = opp_rep * 0.3
            if random.random() < forgiveness_prob:
                return True
            else:
                return False
        else:
            # If opponent cooperated, cooperate unless very low reputation
            if opp_rep < 0.2:
                return random.random() < 0.3
            return True

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update own action counts if we are involved
        if donor_id == self.agent_id:
            if donor_action == 'cooperate':
                self.own_coop_count += 1
            else:
                self.own_defect_count += 1
        if recipient_id == self.agent_id:
            if recipient_action == 'cooperate':
                self.own_coop_count += 1
            else:
                self.own_defect_count += 1

        # Update partner history if we are involved in the interaction
        if donor_id == self.agent_id and recipient_id != self.agent_id:
            # We are donor, opponent is recipient
            opponent = recipient_id
            my_action = donor_action
            their_action = recipient_action
            self._update_partner_history(opponent, my_action, their_action)
        elif recipient_id == self.agent_id and donor_id != self.agent_id:
            # We are recipient, opponent is donor
            opponent = donor_id
            my_action = recipient_action
            their_action = donor_action
            self._update_partner_history(opponent, my_action, their_action)

        # Update reputation for all observed actions
        self._update_reputation(donor_id, donor_action, recipient_id, recipient_action)

    def _update_partner_history(self, opponent, my_action, their_action):
        if opponent not in self.partner_history:
            self.partner_history[opponent] = []
        self.partner_history[opponent].append((my_action, their_action))
        # Keep only last 10 interactions
        if len(self.partner_history[opponent]) > 10:
            self.partner_history[opponent] = self.partner_history[opponent][-10:]

    def _update_reputation(self, donor_id, donor_action, recipient_id, recipient_action):
        # Update donor reputation based on action
        donor_rep = self.reputation.get(donor_id, 0.5)
        if donor_action == 'cooperate':
            donor_rep += 0.05
        else:
            donor_rep -= 0.1
        self.reputation[donor_id] = max(0.0, min(1.0, donor_rep))

        # Update recipient reputation based on action
        recipient_rep = self.reputation.get(recipient_id, 0.5)
        if recipient_action == 'cooperate':
            recipient_rep += 0.05
        else:
            recipient_rep -= 0.1
        self.reputation[recipient_id] = max(0.0, min(1.0, recipient_rep))

