        self.generosity_decay = 0.99
        self.generosity_floor = 0.0
        self.generosity_cap = 0.4
        # New mechanism: a "forgiveness" counter that resets after cooperation, but with a different trigger
        self.forgiveness_counter = {}
        self.forgiveness_threshold = 3
        self.forgiveness_reset = 0

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return True

        if opp not in self.reputation:
            self.reputation[opp] = 0.5
        if opp not in self.interactions:
            self.interactions[opp] = []
        if opp not in self.observed_counts:
            self.observed_counts[opp] = [0, 0]
        if opp not in self.coop_rate:
