            else:
                self.trust[recipient_id] = self.trust.get(recipient_id, 0.5) - 0.05

            # Clamp trust
            self.trust[donor_id] = max(0.0, min(1.0, self.trust[donor_id]))
            self.trust[recipient_id] = max(0.0, min(1.0, self.trust[recipient_id]))

            # Also update reputation in a simpler way (for compatibility)
            delta_d = 0.05 if donor_action == 'cooperate' else -0.05
            self.reputation[donor_id] = max(0.0, min(1.0, self.reputation.get(donor_id, 0.5) + delta_d))
            delta_r = 0.05 if recipient_action == 'cooperate' else -0.05
            self.reputation[recipient_id] = max(0.0, min(1.0, self.reputation.get(recipient_id, 0.5) + delta_r))

            # Self-judgment: record interaction
            if donor_id == self.agent_id or recipient_id == self.agent_id:
                if donor_id == self.agent_id:
                    opponent = recipient_id
                    my_action = donor_action == 'cooperate'
                    their_action = recipient_action == 'cooperate'
                else:
                    opponent = donor_id
                    my_action = recipient_action == 'cooperate'
                    their_action = donor_action == 'cooperate'

                if opponent not in self.interactions:
                    self.interactions[opponent] = []
                self.interactions[opponent].append((my_action, their_action))
                if len(self.interactions[opponent]) > 20:
                    self.interactions[opponent] = self.interactions[opponent][-20:]

                # Forgiveness: if they defect, we increase forgiveness but with a cap
                if not their_action:
                    self.forgiveness[opponent] = min(5, self.forgiveness.get(opponent, 0) + 1)
                else:
                    self.forgiveness[opponent] = max(0, self.forgiveness.get(opponent, 0) - 1)

                # Direct trust adjustment based on their action: stronger for direct interactions
                if their_action:
                    self.trust[opponent] = min(1.0, self.trust.get(opponent, 0.5) + 0.15)
                else:
                    self.trust[opponent] = max(0.0, self.trust.get(opponent, 0.5) - 0.1)

            self.rounds_observed += 1

            # Decay trust slowly toward neutral every 100 observations
            if self.rounds_observed % 100 == 0:
                for agent in self.trust:
                    self.trust[agent] = 0.95 * self.trust.get(agent, 0.5) + 0.05 * 0.5

        except Exception:
            pass

