        self.my_recent_actions = []
        self.rounds_played = 0
        self.generosity = 0.9
        self.forgetting = 0.95
        self.trust_threshold = 0.5  # dynamic threshold
        self.recent_observed_cooperation = []  # track recent third-party observations

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True
        if opponent not in self.history:
            opp_rep = self.reputation.get(opponent, 0.5)
            return opp_rep >= self.trust_threshold
        my_actions, their_actions = zip(*self.history[opponent])
        recent_len = min(5, len(their_actions))
        recent_their = their_actions[-recent_len:]
        recent_my = my_actions[-recent_len:]
        my_coop_rate = sum(recent_my) / len(recent_my) if recent_my else 0.5
        their_coop_rate = sum(recent_their) / len(recent_their) if recent_their else 0.5
        # Use dynamic trust threshold based on overall observed cooperation
        if their_coop_rate > my_coop_rate:
            return random.random() < (0.7 + 0.3 * their_coop_rate)
        elif their_coop_rate < my_coop_rate - 0.2:
            return random.random() < 0.3
        else:
            if their_actions and their_actions[-1]:
                return random.random() < self.generosity
            else:
                return random.random() < 0.2

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        donor_coop = (donor_action == 'cooperate')
        recipient_coop = (recipient_action == 'cooperate')

        self._update_reputation(donor_id, donor_coop)
        self._update_reputation(recipient_id, recipient_coop)

        self.total_count[donor_id] = self.total_count.get(donor_id, 0) + 1
        if donor_coop:
            self.coop_count[donor_id] = self.coop_count.get(donor_id, 0) + 1
        self.total_count[recipient_id] = self.total_count.get(recipient_id, 0) + 1
        if recipient_coop:
            self.coop_count[recipient_id] = self.coop_count.get(recipient_id, 0) + 1

        # Track observed cooperation for trust threshold adjustment
        self.recent_observed_cooperation.append((donor_coop, recipient_coop))
        if len(self.recent_observed_cooperation) > 20:
            self.recent_observed_cooperation.pop(0)
        # Recalculate trust threshold based on recent observed cooperation rate
        if len(self.recent_observed_cooperation) >= 10:
            coop_events = sum(x for pair in self.recent_observed_cooperation for x in pair)
            total_events = len(self.recent_observed_cooperation) * 2
            observed_coop_rate = coop_events / total_events
            # Trust threshold inversely related to observed cooperation: if others cooperate a lot, be more trusting
            self.trust_threshold = max(0.3, min(0.7, 0.5 - (observed_coop_rate - 0.5)))

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                opponent = recipient_id
                my_action = donor_coop
                their_action = recipient_coop
            else:
                opponent = donor_id
                my_action = recipient_coop
                their_action = donor_coop
            if opponent not in self.history:
                self.history[opponent] = []
            self.history[opponent].append((my_action, their_action))
            if not their_action:
                self.defections_against_me[opponent] = self.defections_against_me.get(opponent, 0) + 1
            self.rounds_played += 1
            self.my_recent_actions.append(my_action)
            if len(self.my_recent_actions) > 10:
                self.my_recent_actions.pop(0)
            recent_defections = sum(1 for a in self.my_recent_actions if not a)
            if recent_defections > 5:
                self.generosity = max(0.5, self.generosity - 0.05)
            else:
                self.generosity = min(0.95, self.generosity + 0.01)

    def _update_reputation(self, agent_id: int, cooperated: bool) -> None:
        current = self.reputation.get(agent_id, 0.5)
        if cooperated:
            new = current * self.forgetting + 0.1
        else:
            new = current * self.forgetting - 0.1
        self.reputation[agent_id] = max(0.0, min(1.0, new))

