            else:
                self.trust[recipient_id] = self.trust.get(recipient_id, 0.5) - 0.05

            # Clamp trust
            self.trust[donor_id] = max(0.0, min(1.0, self.trust[donor_id]))
            self.trust[recipient_id] = max(0.0, min(1.0, self.trust[recipient_id]))

            # Also update reputation in a simpler way (for compatibility)
