        # New mechanism: an opponent-specific "memory" vector that tracks
        # the ratio of cooperation to defection in a sliding window,
        # but with a different aggregation: use exponential moving average
        # with a faster decay for recent events.
        self.ema_coop = {}
        self.ema_alpha = 0.3  # higher alpha = more weight on recent
        # New mechanism: a "flexibility" factor that adjusts the threshold
        # based on how often we've been exploited vs. how often we exploit.
        # This is a meta-learning parameter that changes the threshold
        # asymmetrically.
        self.flexibility = 0.2
        self.flexibility_decay = 0.98
        self.flexibility_floor = 0.0
        self.flexibility_cap = 0.5

    def decide(self) -> bool:
