            if len(window) > 0:
                coop_fraction = sum(window) / len(window)
                if coop_fraction >= self.coop_signal_threshold:
                    return True
            return False

        gen_factor = math.exp(-self.round_count / 30.0)
        # Flexibility adjusts threshold asymmetrically: if we've been exploited,
        # threshold increases more; if we've exploited, threshold decreases less.
        threshold = self.trust_threshold + 0.1 * gen_factor - self.generosity + self.flexibility

        # Stubbornness reduces willingness to explore
        adjusted_exploration = max(0.0, self.exploration_prob - self.stubbornness[opp])

        if combined_score > threshold:
            return True
        elif random.random() < adjusted_exploration:
            return True
        else:
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.observed_counts:
                self.observed_counts[agent_id] = [0, 0]
            if action == 'cooperate':
                self.observed_counts[agent_id][0] += 1
            else:
                self.observed_counts[agent_id][1] += 1

        if donor_id == self.agent_id:
            opp = recipient_id
            my_action = donor_action
            their_action = recipient_action
        elif recipient_id == self.agent_id:
            opp = donor_id
            my_action = recipient_action
            their_action = donor_action
        else:
            return

        if opp not in self.interactions:
            self.interactions[opp] = []
        self.interactions[opp].append((my_action, their_action))
        if len(self.interactions[opp]) > 20:
            self.interactions[opp] = self.interactions[opp][-20:]

        if opp not in self.opp_history:
            self.opp_history[opp] = []
        self.opp_history[opp].append(their_action)
        if len(self.opp_history[opp]) > 10:
            self.opp_history[opp] = self.opp_history[opp][-10:]

        if opp not in self.consecutive_defections:
            self.consecutive_defections[opp] = 0
        if their_action == 'defect':
            self.consecutive_defections[opp] += 1
        else:
            self.consecutive_defections[opp] = 0

        self.last_cooperated[opp] = (my_action == 'cooperate')

        # Update trust score with a more nuanced rule: reward mutual cooperation, penalize exploitation more
        if opp not in self.trust_scores:
            self.trust_scores[opp] = 0.5

        if my_action == 'cooperate':
            if their_action == 'cooperate':
                self.trust_scores[opp] += self.trust_boost
            else:  # they defected after we cooperated
                self.trust_scores[opp] -= self.trust_penalty * 1.5
        else:  # we defected
            if their_action == 'cooperate':
                self.trust_scores[opp] += self.trust_boost * 0.5

        self.trust_scores[opp] = max(0.0, min(1.0, self.trust_scores[opp]))

        # Update cooperation signal window
        if opp not in self.coop_signal_window:
            self.coop_signal_window[opp] = deque(maxlen=self.window_size)
        self.coop_signal_window[opp].append(1 if their_action == 'cooperate' else 0)

        # Update EMA of cooperation rate
        if opp not in self.ema_coop:
            self.ema_coop[opp] = 0.5
        self.ema_coop[opp] = (1 - self.ema_alpha) * self.ema_coop[opp] + self.ema_alpha * (1 if their_action == 'cooperate' else 0)

        # Update stubbornness
        if opp not in self.stubbornness:
            self.stubbornness[opp] = self.stubbornness_init
        if their_action == 'defect':
            self.stubbornness[opp] = min(self.stubbornness_cap, self.stubbornness[opp] + self.stubbornness_increment)
        else:
            self.stubbornness[opp] = max(self.stubbornness_init, self.stubbornness[opp] - self.stubbornness_increment)

        self.round_count += 1

        self.my_recent_actions.append(my_action)
        self.opp_recent_actions.append(their_action)

        # Update generosity: increase when we cooperate and they defect, decrease otherwise
        if my_action == 'cooperate' and their_action == 'defect':
            self.generosity = min(self.generosity_cap, self.generosity + 0.02)
        else:
            self.generosity = max(self.generosity_floor, self.generosity * self.generosity_decay)

        # Update flexibility: if we've been exploited, increase flexibility (higher threshold);
        # if we've exploited, decrease flexibility (lower threshold, but less extreme)
        if my_action == 'cooperate' and their_action == 'defect':
            self.flexibility = min(self.flexibility_cap, self.flexibility + 0.03)
        elif my_action == 'defect' and their_action == 'cooperate':
            self.flexibility = max(self.flexibility_floor, self.flexibility - 0.01)
        else:
            self.flexibility *= self.flexibility_decay

        if self.last_cooperated[opp] and their_action == 'defect':
            self.trust_threshold = min(0.9, self.trust_threshold + 0.08)
        else:
            self.trust_threshold = max(0.2, self.trust_threshold - 0.02)

        # Adaptive exploration (same as parent but also affected by stubbornness)
        if self.adaptive_exploration:
            if opp in self.interactions and len(self.interactions[opp]) >= 5:
                recent = self.interactions[opp][-5:]
                coop_count = sum(1 for a, b in recent if a == 'cooperate')
                recent_coop_rate = coop_count / len(recent)
                if recent_coop_rate < 0.3:
                    self.exploration_prob = min(self.exploration_upper, self.exploration_prob + 0.02)
                elif recent_coop_rate > 0.7:
                    self.exploration_prob = max(self.exploration_lower, self.exploration_prob - 0.01)

