import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Reputation scores for each agent: start neutral at 0
        self.reputation = {}
        # Cooperation counts and total interactions for each agent
        self.coop_count = {}
        self.total_count = {}
        # Memory of last actions with each opponent: agent_id -> (my_action, opp_action)
        self.last_actions = {}
        # Track how many times we've seen each agent cooperate/defect
        self.seen_coop = {}
        self.seen_defect = {}
        # Track forgiveness level (how much we forgive defections)
        self.forgiveness = 0.5
        # Track our own recent actions for adaptive behavior
        self.my_recent_actions = []
        # Track opponent's recent actions for pattern detection
        self.opp_recent_actions = {}

    def _get_reputation(self, agent_id: int) -> float:
        """Get reputation score (range roughly -1 to 1)"""
        return self.reputation.get(agent_id, 0.0)

    def _update_reputation(self, agent_id: int, delta: float) -> None:
        """Update reputation score, clamped to [-1, 1]"""
        current = self.reputation.get(agent_id, 0.0)
        new_val = max(-1.0, min(1.0, current + delta))
        self.reputation[agent_id] = new_val

    def _cooperation_rate(self, agent_id: int) -> float:
        """Estimate cooperation rate based on observations"""
        coop = self.seen_coop.get(agent_id, 0)
        defect = self.seen_defect.get(agent_id, 0)
        total = coop + defect
        if total == 0:
            return 0.5  # unknown
        return coop / total

    def decide(self) -> bool:
        opponent_id = getattr(self, '_ctx_opponent_id', None)
        if opponent_id is None:
            return True  # default cooperate

        # Get opponent reputation and cooperation rate
        opp_rep = self._get_reputation(opponent_id)
        opp_coop_rate = self._cooperation_rate(opponent_id)

        # Check if we have past interaction with this opponent
        last = self.last_actions.get(opponent_id)
        if last is not None:
            my_last, opp_last = last
            # If opponent defected last time, consider forgiveness
            if opp_last == 'defect':
                # Forgive with some probability, but less if they have bad reputation
                forgive_prob = self.forgiveness * (1 - max(0, opp_rep))
                if random.random() < forgive_prob:
                    return True
                else:
                    return False
            else:
                # Opponent cooperated last time, likely cooperate
                return True
        else:
            # First interaction: cooperate if reputation not too bad
            # Start with a trustful approach but be cautious with very bad rep
            if opp_rep < -0.5:
                return False
            else:
                return True

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update global reputation scores based on observed actions
        # Cooperation increases reputation, defection decreases it
        if donor_action == 'cooperate':
            self._update_reputation(donor_id, 0.1)
            self.seen_coop[donor_id] = self.seen_coop.get(donor_id, 0) + 1
        else:
            self._update_reputation(donor_id, -0.1)
            self.seen_defect[donor_id] = self.seen_defect.get(donor_id, 0) + 1

        if recipient_action == 'cooperate':
            self._update_reputation(recipient_id, 0.1)
            self.seen_coop[recipient_id] = self.seen_coop.get(recipient_id, 0) + 1
        else:
            self._update_reputation(recipient_id, -0.1)
            self.seen_defect[recipient_id] = self.seen_defect.get(recipient_id, 0) + 1

        # Track interactions if we are involved
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # Determine who we are and who the opponent is
            if donor_id == self.agent_id:
                my_action = donor_action
                opp_action = recipient_action
                opp_id = recipient_id
            else:
                my_action = recipient_action
                opp_action = donor_action
                opp_id = donor_id

            # Update last actions with this opponent
            self.last_actions[opp_id] = (my_action, opp_action)

            # Track our recent actions
            self.my_recent_actions.append(my_action)
            if len(self.my_recent_actions) > 20:
                self.my_recent_actions.pop(0)

            # Track opponent's recent actions
            opp_recent = self.opp_recent_actions.setdefault(opp_id, [])
            opp_recent.append(opp_action)
            if len(opp_recent) > 20:
                opp_recent.pop(0)

            # Adapt forgiveness based on how often we've been exploited
            # If we have been defected against a lot recently, reduce forgiveness
            if len(opp_recent) >= 5:
                recent_defects = sum(1 for a in opp_recent[-5:] if a == 'defect')
                if recent_defects >= 4:
                    self.forgiveness = max(0.1, self.forgiveness - 0.1)
                elif recent_defects <= 1:
                    self.forgiveness = min(0.9, self.forgiveness + 0.1)

        # Also track third-party interactions for pattern detection
        # Update cooperation counts for both agents
        self.total_count[donor_id] = self.total_count.get(donor_id, 0) + 1
        self.total_count[recipient_id] = self.total_count.get(recipient_id, 0) + 1

        if donor_action == 'cooperate':
            self.coop_count[donor_id] = self.coop_count.get(donor_id, 0) + 1
        if recipient_action == 'cooperate':
            self.coop_count[recipient_id] = self.coop_count.get(recipient_id, 0) + 1

