        else:
            self.stubbornness[opp] = max(self.stubbornness_init, self.stubbornness[opp] - self.stubbornness_increment)

        # Update forgiveness counter: increases when opponent cooperates, resets when they defect
        if opp not in self.forgiveness_counter:
            self.forgiveness_counter[opp] = 0
        if their_action == 'cooperate':
            self.forgiveness_counter[opp] += 1
        else:
            self.forgiveness_counter[opp] = 0

        self.round_count += 1

        self.my_recent_actions.append(my_action)
        self.opp_recent_actions.append(their_action)

        # Update generosity: increase when we cooperate and they defect, decrease otherwise
        if my_action == 'cooperate' and their_action == 'defect':
            self.generosity = min(self.generosity_cap, self.generosity + 0.02)
        else:
            self.generosity = max(self.generosity_floor, self.generosity * self.generosity_decay)

        if self.last_cooperated[opp] and their_action == 'defect':
            self.trust_threshold = min(0.9, self.trust_threshold + 0.08)
        else:
            self.trust_threshold = max(0.2, self.trust_threshold - 0.02)

        # Adaptive exploration (same as parent but also affected by stubbornness)
