        self.last_actions = {}
        # Track how many times we've seen each agent cooperate/defect
        self.seen_coop = {}
        self.seen_defect = {}
        # Track forgiveness level (how much we forgive defections)
        self.forgiveness = 0.5
        # Track our own recent actions for adaptive behavior
        self.my_recent_actions = []
        # Track opponent's recent actions for pattern detection
        self.opp_recent_actions = {}

    def _get_reputation(self, agent_id: int) -> float:
        """Get reputation score (range roughly -1 to 1)"""
        return self.reputation.get(agent_id, 0.0)

    def _update_reputation(self, agent_id: int, delta: float) -> None:
        """Update reputation score, clamped to [-1, 1]"""
        current = self.reputation.get(agent_id, 0.0)
        new_val = max(-1.0, min(1.0, current + delta))
        self.reputation[agent_id] = new_val

    def _cooperation_rate(self, agent_id: int) -> float:
        """Estimate cooperation rate based on observations"""
        coop = self.seen_coop.get(agent_id, 0)
        defect = self.seen_defect.get(agent_id, 0)
        total = coop + defect
        if total == 0:
            return 0.5  # unknown
        return coop / total

    def decide(self) -> bool:
        opponent_id = getattr(self, '_ctx_opponent_id', None)
        if opponent_id is None:
            return True  # default cooperate

        # Get opponent reputation and cooperation rate
        opp_rep = self._get_reputation(opponent_id)
        opp_coop_rate = self._cooperation_rate(opponent_id)

        # Check if we have past interaction with this opponent
        last = self.last_actions.get(opponent_id)
        if last is not None:
            my_last, opp_last = last
            # If opponent defected last time, consider forgiveness
            if opp_last == 'defect':
                # Forgive with some probability, but less if they have bad reputation
                forgive_prob = self.forgiveness * (1 - max(0, opp_rep))
                if random.random() < forgive_prob:
                    return True
                else:
                    return False
            else:
                # Opponent cooperated last time, likely cooperate
                return True
        else:
            # First interaction: cooperate if reputation not too bad
            # Start with a trustful approach but be cautious with very bad rep
            if opp_rep < -0.5:
                return False
            else:
                return True

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update global reputation scores based on observed actions
        # Cooperation increases reputation, defection decreases it
        if donor_action == 'cooperate':
            self._update_reputation(donor_id, 0.1)
            self.seen_coop[donor_id] = self.seen_coop.get(donor_id, 0) + 1
        else:
            self._update_reputation(donor_id, -0.1)
