        if recipient_action == 'cooperate':
            self._update_reputation(recipient_id, 0.1)
            self.seen_coop[recipient_id] = self.seen_coop.get(recipient_id, 0) + 1
        else:
            self._update_reputation(recipient_id, -0.1)
            self.seen_defect[recipient_id] = self.seen_defect.get(recipient_id, 0) + 1

        # Track interactions if we are involved
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # Determine who we are and who the opponent is
            if donor_id == self.agent_id:
                my_action = donor_action
                opp_action = recipient_action
                opp_id = recipient_id
            else:
                my_action = recipient_action
                opp_action = donor_action
                opp_id = donor_id

            # Update last actions with this opponent
            self.last_actions[opp_id] = (my_action, opp_action)

            # Track our recent actions
            self.my_recent_actions.append(my_action)
            if len(self.my_recent_actions) > 20:
