                if coop_fraction >= self.coop_signal_threshold:
                    return True  # Override retaliation if recent cooperation is strong
            # New: forgiveness counter allows occasional cooperation even when retaliating
            if self.forgiveness_counter[opp] >= self.forgiveness_threshold:
                self.forgiveness_counter[opp] = self.forgiveness_reset
                return True
