        gen_factor = math.exp(-self.round_count / 30.0)
        threshold = self.trust_threshold + 0.1 * gen_factor - self.generosity

        # Stubbornness reduces willingness to explore
        adjusted_exploration = max(0.0, self.exploration_prob - self.stubbornness[opp])

