        self.generosity_cap = 0.4
        self.ema_coop = {}
        self.ema_alpha = 0.3
        self.flexibility = 0.2
        self.flexibility_decay = 0.98
        self.flexibility_floor = 0.0
        self.flexibility_cap = 0.5
        # New mechanism: a "forgiveness" counter that resets after mutual cooperation
        self.forgiveness = {}
        self.forgiveness_init = 0.0
        self.forgiveness_increment = 0.05
        self.forgiveness_cap = 0.3
        # New mechanism: a "betrayal memory" that stores recent defections against us
        self.betrayal_memory = {}
        self.betrayal_window = 5

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return True

        if opp not in self.reputation:
            self.reputation[opp] = 0.5
        if opp not in self.interactions:
            self.interactions[opp] = []
        if opp not in self.observed_counts:
            self.observed_counts[opp] = [0, 0]
        if opp not in self.coop_rate:
            self.coop_rate[opp] = 0.5
        if opp not in self.consecutive_defections:
