        if opp not in self.stubbornness:
            self.stubbornness[opp] = self.stubbornness_init
        if opp not in self.reputation_gradient:
            self.reputation_gradient[opp] = 0.0
        if opp not in self.ema_coop:
            self.ema_coop[opp] = 0.5
        if opp not in self.forgiveness:
            self.forgiveness[opp] = self.forgiveness_init
        if opp not in self.betrayal_memory:
            self.betrayal_memory[opp] = deque(maxlen=self.betrayal_window)

        # Decay trust score and gradient over time
        self.trust_scores[opp] *= self.trust_decay
        self.reputation_gradient[opp] *= self.gradient_decay

        obs_coop, obs_def = self.observed_counts[opp]
        total_obs = obs_coop + obs_def
        obs_rate = obs_coop / total_obs if total_obs > 0 else 0.5

        my_hist = self.interactions[opp]
        if my_hist:
            my_coop = sum(1 for a, b in my_hist if a == 'cooperate')
            my_rate = my_coop / len(my_hist)
        else:
            my_rate = 0.5

        ema_rate = self.ema_coop[opp]
        blend = 0.4 * obs_rate + 0.3 * my_rate + 0.3 * ema_rate

        old_rep = self.reputation[opp]
        new_rep = 0.8 * old_rep + 0.2 * blend
        grad = new_rep - old_rep
        self.reputation_gradient[opp] += self.gradient_learning_rate * grad
        self.reputation[opp] = new_rep + self.reputation_momentum * self.reputation_gradient[opp]

        combined_score = 0.7 * self.reputation[opp] + 0.3 * self.trust_scores[opp]

