import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.interactions = {}
        self.observed_coop = {}
        self.observed_defect = {}
        self.coop_rate = {}
        self.forgiveness = {}
        self.rounds_played = 0
        self.rounds_observed = 0
        self.recent_actions = deque(maxlen=100)
        # New: track a per-agent "trust" that updates asymmetrically
        self.trust = {}
        for i in range(15):
            self.reputation[i] = 0.5
            self.observed_coop[i] = 0
            self.observed_defect[i] = 0
            self.coop_rate[i] = 0.5
            self.forgiveness[i] = 0
            self.interactions[i] = []
            self.trust[i] = 0.5

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True

        # Use trust as primary signal, with a steeper threshold
        opp_trust = self.trust.get(opponent, 0.5)

        # Direct history penalty: if they defected against us recently, reduce trust
        direct_history = self.interactions.get(opponent, [])
        if direct_history:
            recent_defects = sum(1 for my, their in direct_history[-5:] if not their)
            opp_trust -= 0.15 * recent_defects
        opp_trust = max(0.0, min(1.0, opp_trust))

        # Observed behavior is weighted less than in parent
        total_obs = self.observed_coop.get(opponent, 0) + self.observed_defect.get(opponent, 0)
        obs_coop_rate = self.observed_coop.get(opponent, 0) / total_obs if total_obs > 0 else 0.5
        effective = 0.8 * opp_trust + 0.2 * obs_coop_rate

        # Much higher threshold: only cooperate with well-trusted agents
        threshold = 0.65
        # Add a small chance to cooperate even if below threshold, but lower than parent
        if effective > threshold:
            return True
        else:
            # If we have forgiven them many times and they haven't recently defected, give a chance
            if self.forgiveness.get(opponent, 0) > 3 and effective > 0.4:
                return random.random() < 0.3
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        try:
            # Update observation counts
            if donor_action == 'cooperate':
                self.observed_coop[donor_id] = self.observed_coop.get(donor_id, 0) + 1
            elif donor_action == 'defect':
                self.observed_defect[donor_id] = self.observed_defect.get(donor_id, 0) + 1

            if recipient_action == 'cooperate':
                self.observed_coop[recipient_id] = self.observed_coop.get(recipient_id, 0) + 1
            elif recipient_action == 'defect':
                self.observed_defect[recipient_id] = self.observed_defect.get(recipient_id, 0) + 1

            # Asymmetric trust update: cooperation increases trust more than defection decreases it
            # This makes the agent more forgiving of defection but slow to trust
            if donor_action == 'cooperate':
                self.trust[donor_id] = self.trust.get(donor_id, 0.5) + 0.1
            else:
                self.trust[donor_id] = self.trust.get(donor_id, 0.5) - 0.05
            if recipient_action == 'cooperate':
                self.trust[recipient_id] = self.trust.get(recipient_id, 0.5) + 0.1
            else:
                self.trust[recipient_id] = self.trust.get(recipient_id, 0.5) - 0.05

            # Clamp trust
            self.trust[donor_id] = max(0.0, min(1.0, self.trust[donor_id]))
            self.trust[recipient_id] = max(0.0, min(1.0, self.trust[recipient_id]))

            # Also update reputation in a simpler way (for compatibility)
            delta_d = 0.05 if donor_action == 'cooperate' else -0.05
            self.reputation[donor_id] = max(0.0, min(1.0, self.reputation.get(donor_id, 0.5) + delta_d))
            delta_r = 0.05 if recipient_action == 'cooperate' else -0.05
            self.reputation[recipient_id] = max(0.0, min(1.0, self.reputation.get(recipient_id, 0.5) + delta_r))

            # Self-judgment: record interaction
            if donor_id == self.agent_id or recipient_id == self.agent_id:
                if donor_id == self.agent_id:
                    opponent = recipient_id
                    my_action = donor_action == 'cooperate'
                    their_action = recipient_action == 'cooperate'
                else:
                    opponent = donor_id
                    my_action = recipient_action == 'cooperate'
                    their_action = donor_action == 'cooperate'

                if opponent not in self.interactions:
                    self.interactions[opponent] = []
                self.interactions[opponent].append((my_action, their_action))
                if len(self.interactions[opponent]) > 20:
                    self.interactions[opponent] = self.interactions[opponent][-20:]

                # Forgiveness: if they defect, we increase forgiveness but with a cap
                if not their_action:
                    self.forgiveness[opponent] = min(5, self.forgiveness.get(opponent, 0) + 1)
                else:
                    self.forgiveness[opponent] = max(0, self.forgiveness.get(opponent, 0) - 1)

                # Direct trust adjustment based on their action: stronger for direct interactions
                if their_action:
                    self.trust[opponent] = min(1.0, self.trust.get(opponent, 0.5) + 0.15)
                else:
                    self.trust[opponent] = max(0.0, self.trust.get(opponent, 0.5) - 0.1)

            self.rounds_observed += 1

            # Decay trust slowly toward neutral every 100 observations
            if self.rounds_observed % 100 == 0:
                for agent in self.trust:
                    self.trust[agent] = 0.95 * self.trust.get(agent, 0.5) + 0.05 * 0.5

        except Exception:
            pass

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.interaction_history = {}
        self.global_coop_count = 0
        self.global_total_count = 0
        self.my_coop_count = 0
        self.my_total_count = 0
        self.generation_count = 0
        self.forget_factor = 0.9
        self.coop_threshold = 0.3
        self._ctx_opponent_id = None
        self.recent_actions = deque(maxlen=10)
        self.reputation_volatility = {}
        self.last_opponent_reputation = {}
        self.uncertainty_threshold = 0.5

    def _get_reputation(self, agent_id: int) -> float:
        return self.reputation.get(agent_id, 0.5)

    def _update_reputation(self, agent_id: int, delta: float) -> None:
        old = self._get_reputation(agent_id)
        old *= self.forget_factor
        new = old + delta
        new = max(0.0, min(1.0, new))
        self.reputation[agent_id] = new
        # Track volatility as absolute change from last known reputation
        if agent_id in self.last_opponent_reputation:
            change = abs(new - self.last_opponent_reputation[agent_id])
            self.reputation_volatility[agent_id] = self.reputation_volatility.get(agent_id, 0.0) + change
        else:
            self.reputation_volatility[agent_id] = 0.0
        self.last_opponent_reputation[agent_id] = new

    def _record_interaction(self, other_id: int, my_action: str, other_action: str) -> None:
        key = (self.agent_id, other_id)
        if key not in self.interaction_history:
            self.interaction_history[key] = deque(maxlen=20)
        self.interaction_history[key].append((my_action, other_action))
        self.recent_actions.append(my_action)

    def _opponent_coop_rate(self, opponent_id: int) -> float:
        key = (self.agent_id, opponent_id)
        hist = self.interaction_history.get(key, [])
        if not hist:
            return 0.5
        coop = sum(1 for _, other in hist if other == 'cooperate')
        return coop / len(hist)

    def _own_coop_rate_recent(self) -> float:
        if not self.recent_actions:
            return 0.5
        coop = sum(1 for a in self.recent_actions if a == 'cooperate')
        return coop / len(self.recent_actions)

    def _uncertainty_bonus(self, opponent_id: int) -> float:
        # If reputation is volatile, we are less certain, so be more cautious (lower threshold)
        vol = self.reputation_volatility.get(opponent_id, 0.0)
        # Normalize volatility based on number of observations (global_total_count)
        if self.global_total_count > 0:
            avg_vol = vol / max(1, self.global_total_count)
            # Return a bonus between -0.2 and 0.2
            return max(-0.2, min(0.2, avg_vol * 2 - 0.1))
        return 0.0

    def decide(self) -> bool:
        opponent_id = self._ctx_opponent_id
        if opponent_id is None:
            return True

        opp_rep = self._get_reputation(opponent_id)
        direct_coop = self._opponent_coop_rate(opponent_id)

