import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.coop_count = {}
        self.total_count = {}
        self.last_actions = {}
        self.seen_coop = {}
        self.seen_defect = {}
        self.forgiveness = 0.5
        self.my_recent_actions = deque(maxlen=20)
        self.opp_recent_actions = {}
        self.generosity = 0.5
        self.trust_history = {}
        self.default_cooperate_threshold = 0.0

    def _get_reputation(self, agent_id: int) -> float:
        return self.reputation.get(agent_id, 0.0)

    def _update_reputation(self, agent_id: int, delta: float) -> None:
        current = self.reputation.get(agent_id, 0.0)
        new_val = max(-1.0, min(1.0, current + delta))
        self.reputation[agent_id] = new_val

    def _cooperation_rate(self, agent_id: int) -> float:
        coop = self.seen_coop.get(agent_id, 0)
        defect = self.seen_defect.get(agent_id, 0)
        total = coop + defect
        if total == 0:
            return 0.5
        return coop / total

    def decide(self) -> bool:
        opponent_id = getattr(self, '_ctx_opponent_id', None)
        if opponent_id is None:
            return True

        opp_rep = self._get_reputation(opponent_id)
        opp_coop_rate = self._cooperation_rate(opponent_id)

        # Weighted combination of reputation and observed cooperation rate
        # Generosity parameter controls how much we rely on reputation vs observed behavior
        trust_score = self.generosity * opp_rep + (1 - self.generosity) * (2 * opp_coop_rate - 1)

        last = self.last_actions.get(opponent_id)
        if last is not None:
            my_last, opp_last = last
            if opp_last == 'defect':
                # Forgive with probability based on trust score and forgiveness level
                forgive_prob = self.forgiveness * max(0, (1 - trust_score))
                if random.random() < forgive_prob:
                    return True
                else:
                    return False
            else:
                # If opponent cooperated last time, cooperate with high probability
                # but still consider trust score
                if trust_score > -0.2:
                    return True
                else:
                    return random.random() < 0.7
        else:
            # First interaction: cooperate if trust score is not too negative
            if trust_score < -0.5:
                return False
            else:
                return True

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation with action-based deltas
        if donor_action == 'cooperate':
            self._update_reputation(donor_id, 0.1)
            self.seen_coop[donor_id] = self.seen_coop.get(donor_id, 0) + 1
        else:
            self._update_reputation(donor_id, -0.1)
            self.seen_defect[donor_id] = self.seen_defect.get(donor_id, 0) + 1

        if recipient_action == 'cooperate':
            self._update_reputation(recipient_id, 0.1)
            self.seen_coop[recipient_id] = self.seen_coop.get(recipient_id, 0) + 1
        else:
            self._update_reputation(recipient_id, -0.1)
            self.seen_defect[recipient_id] = self.seen_defect.get(recipient_id, 0) + 1

        # Track interactions if we are involved
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                my_action = donor_action
                opp_action = recipient_action
                opp_id = recipient_id
            else:
                my_action = recipient_action
                opp_action = donor_action
                opp_id = donor_id

            self.last_actions[opp_id] = (my_action, opp_action)
            self.my_recent_actions.append(my_action)
            opp_recent = self.opp_recent_actions.setdefault(opp_id, deque(maxlen=20))
            opp_recent.append(opp_action)

            # Update trust_history: track how many times we've cooperated/defected with this opponent
            trust = self.trust_history.setdefault(opp_id, {'coop': 0, 'defect': 0})
            if opp_action == 'cooperate':
                trust['coop'] += 1
            else:
                trust['defect'] += 1

            # Adapt generosity based on overall interaction pattern
            if len(self.my_recent_actions) >= 5:
                recent_my_defects = sum(1 for a in self.my_recent_actions if a == 'defect')
                if recent_my_defects >= 3:
                    # We've been defecting a lot, maybe we should be more generous to rebuild trust
                    self.generosity = min(0.9, self.generosity + 0.05)
                elif recent_my_defects <= 1:
                    # We've been cooperative, maybe we can be a bit more cautious
                    self.generosity = max(0.1, self.generosity - 0.05)

            # Adapt forgiveness based on opponent's recent behavior
            if len(opp_recent) >= 5:
                recent_defects = sum(1 for a in opp_recent if a == 'defect')
                if recent_defects >= 4:
                    self.forgiveness = max(0.1, self.forgiveness - 0.1)
                elif recent_defects <= 1:
                    self.forgiveness = min(0.9, self.forgiveness + 0.1)

        # Update total and coop counts for all observed interactions
        self.total_count[donor_id] = self.total_count.get(donor_id, 0) + 1
        self.total_count[recipient_id] = self.total_count.get(recipient_id, 0) + 1

        if donor_action == 'cooperate':
            self.coop_count[donor_id] = self.coop_count.get(donor_id, 0) + 1
        if recipient_action == 'cooperate':
            self.coop_count[recipient_id] = self.coop_count.get(recipient_id, 0) + 1

        # Adaptive generosity based on global cooperation rates
        total_observations = sum(self.total_count.values())
        if total_observations > 0:
            total_coop = sum(self.coop_count.values())
            global_coop_rate = total_coop / total_observations
            # If global cooperation is low, increase generosity slightly to encourage cooperation
            if global_coop_rate < 0.4:
                self.generosity = min(0.9, self.generosity + 0.02)
            elif global_coop_rate > 0.6:
                self.generosity = max(0.1, self.generosity - 0.02)

