import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Track cooperation reputation for each agent (0 to 1)
        self.reputation = {}
        # Track own history of interactions per opponent
        self.own_history = {}
        # Track how often I cooperated/defected
        self.my_coop_count = 0
        self.my_defect_count = 0
        # Track overall cooperation rate for others
        self.other_coop_count = 0
        self.other_total_count = 0
        # Track number of observations per agent
        self.obs_count = {}
        # Default reputation for unknown agents
        self.default_rep = 0.5
        # Track my last action against each opponent
        self.last_action = {}
        # Track opponent's last action against me
        self.opp_last_action = {}
        # Track total rounds played
        self.rounds_played = 0

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True
        # Simple tit-for-tat with forgiveness and reputation-based adjustment
        # Get opponent's reputation
        opp_rep = self.reputation.get(opponent, self.default_rep)
        # Check if opponent defected last time against me
        last_opp_action = self.opp_last_action.get(opponent)
        if last_opp_action == 'defect':
            # If they defected, forgive with probability based on reputation
            # Higher reputation -> more likely to forgive
            if random.random() < opp_rep:
                return True
            else:
                return False
        else:
            # If no prior interaction or they cooperated, cooperate
            return True

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Update reputation based on observed actions
        # Simple: cooperation increases reputation, defection decreases
        # Use a moving average with weight 0.1
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id == self.agent_id:
                # Self-judgment: update own history
                if donor_id == self.agent_id:
                    self.my_coop_count += 1 if donor_action == 'cooperate' else 0
                    self.my_defect_count += 1 if donor_action == 'defect' else 0
                    self.own_history.setdefault(recipient_id, []).append(donor_action)
                    self.last_action[recipient_id] = donor_action
                if recipient_id == self.agent_id:
                    self.opp_last_action[donor_id] = donor_action
            else:
                # Update reputation for other agents
                self.obs_count[agent_id] = self.obs_count.get(agent_id, 0) + 1
                old_rep = self.reputation.get(agent_id, self.default_rep)
                if action == 'cooperate':
                    new_rep = old_rep + 0.1 * (1.0 - old_rep)
                else:
                    new_rep = old_rep + 0.1 * (0.0 - old_rep)
                self.reputation[agent_id] = new_rep
                # Update overall stats
                if agent_id != self.agent_id:
                    self.other_total_count += 1
                    if action == 'cooperate':
                        self.other_coop_count += 1
        # Track rounds played
        self.rounds_played += 1

