class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.opponent_id = None
        self.round_num = 0
        self.generation = 0
        self.cooperation_scores = {}
        self.defection_scores = {}
        self.interaction_history = {}
        self.reputation = {}
        self.trust = {}
        self.strategy = 'tit_for_tat'
        self.my_actions = []
        self.opponent_actions = []
        self.all_agents = set()
        self.total_rounds = 0
        self.my_score = 0
        self.opponent_scores = {}
        self.cooperation_count = 0
        self.defection_count = 0
        self.recent_actions = []
        self.observed_actions = {}
        self.trust_threshold = 0.5
        self.retaliation_threshold = 0.3
        self.personality = random.uniform(0.1, 0.9)
        self.aggression = random.uniform(0.1, 0.9)
        self.forgiveness = random.uniform(0.1, 0.9)
        self.memory = 5
        self.last_opponent_actions = {}
        self.opponent_cooperation_rates = {}
        self.opponent_defection_rates = {}
        self.interaction_weights = {}
        self.strategy_weights = {'tit_for_tat': 0.4, 'forgiving_tit_for_tat': 0.3, 'generous': 0.2, 'suspicious': 0.1}
        self.strategy_performance = {'tit_for_tat': 0.0, 'forgiving_tit_for_tat': 0.0, 'generous': 0.0, 'suspicious': 0.0}
        self.strategy_rounds = {'tit_for_tat': 0, 'forgiving_tit_for_tat': 0, 'generous': 0, 'suspicious': 0}

    def decide(self) -> bool:
        if self.round_num == 0:
            self.strategy = 'tit_for_tat'
            return True

        opponent = self._ctx_opponent_id
        self.opponent_id = opponent

        # Update all_agents set
        if opponent is not None:
            self.all_agents.add(opponent)

        # Get opponent's history and reputation
        opp_coop_rate = self.opponent_cooperation_rates.get(opponent, 0.5)
        opp_def_rate = self.opponent_defection_rates.get(opponent, 0.5)
        trust = self.trust.get(opponent, 0.5)

        # Dynamic strategy selection based on performance and opponent behavior
        if self.total_rounds > 10:
            best_strategy = max(self.strategy_performance, key=self.strategy_performance.get)
            if self.strategy_rounds[best_strategy] > 5:
                self.strategy = best_strategy

        # Adjust strategy based on opponent's cooperation rate and trust
        if opp_coop_rate > 0.7 and trust > 0.6:
            self.strategy = 'generous'
        elif opp_def_rate > 0.5 or trust < 0.3:
            self.strategy = 'suspicious'
        elif self.personality > 0.7:
            self.strategy = 'forgiving_tit_for_tat'

        # Decision logic based on chosen strategy
        if self.strategy == 'tit_for_tat':
            # Tit-for-tat: cooperate if opponent cooperated last time, otherwise defect
            if opponent in self.last_opponent_actions:
                return self.last_opponent_actions[opponent]
            else:
                return True
        elif self.strategy == 'forgiving_tit_for_tat':
            # Forgiving tit-for-tat: cooperate after opponent's defection sometimes
            if opponent in self.last_opponent_actions:
                if not self.last_opponent_actions[opponent]:
                    # Randomly forgive based on forgiveness trait
                    if random.random() < self.forgiveness:
                        return True
                    else:
                        return False
                else:
                    return True
            else:
                return True
        elif self.strategy == 'generous':
            # Generous: cooperate most of the time, but defect if opponent defects too often
            if opp_def_rate > 0.6:
                return False
            elif trust < 0.3:
                return False
            else:
                return True
        elif self.strategy == 'suspicious':
            # Suspicious: start with defection, but can learn to cooperate
            if self.total_rounds < 2:
                return False
            elif opp_coop_rate > 0.8 and trust > 0.7:
                return True
            else:
                return False

        # Default: tit-for-tat
        if opponent in self.last_opponent_actions:
            return self.last_opponent_actions[opponent]
        return True

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update all_agents set
        self.all_agents.add(donor_id)
        self.all_agents.add(recipient_id)

        # Update round counts
        self.round_num += 1
        self.total_rounds += 1

        # Track observed actions
        pair_key = (donor_id, recipient_id)
        if pair_key not in self.observed_actions:
            self.observed_actions[pair_key] = []
        self.observed_actions[pair_key].append((donor_action, recipient_action))

        # Update cooperation and defection scores for agents
        if donor_action == 'cooperate':
            self.cooperation_scores[donor_id] = self.cooperation_scores.get(donor_id, 0) + 1
        else:
            self.defection_scores[donor_id] = self.defection_scores.get(donor_id, 0) + 1

        if recipient_action == 'cooperate':
            self.cooperation_scores[recipient_id] = self.cooperation_scores.get(recipient_id, 0) + 1
        else:
            self.defection_scores[recipient_id] = self.defection_scores.get(recipient_id, 0) + 1

        # Update reputation based on actions (cooperation increases, defection decreases)
        self.reputation[donor_id] = self.reputation.get(donor_id, 0.5)
        self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5)

        if donor_action == 'cooperate':
            self.reputation[donor_id] = min(1.0, self.reputation[donor_id] + 0.1)
        else:
            self.reputation[donor_id] = max(0.0, self.reputation[donor_id] - 0.15)

        if recipient_action == 'cooperate':
            self.reputation[recipient_id] = min(1.0, self.reputation[recipient_id] + 0.1)
        else:
            self.reputation[recipient_id] = max(0.0, self.reputation[recipient_id] - 0.15)

        # Update trust based on interactions
        if donor_id == self.agent_id and recipient_id in self.all_agents:
            # Self as donor - update trust based on recipient's action
            if recipient_action == 'cooperate':
                self.trust[recipient_id] = self.trust.get(recipient_id, 0.5) + 0.1
            else:
                self.trust[recipient_id] = self.trust.get(recipient_id, 0.5) - 0.15
            self.trust[recipient_id] = max(0.0, min(1.0, self.trust[recipient_id]))

        if recipient_id == self.agent_id and donor_id in self.all_agents:
            # Self as recipient - update trust based on donor's action
            if donor_action == 'cooperate':
                self.trust[donor_id] = self.trust.get(donor_id, 0.5) + 0.1
            else:
                self.trust[donor_id] = self.trust.get(donor_id, 0.5) - 0.15
            self.trust[donor_id] = max(0.0, min(1.0, self.trust[donor_id]))

        # Update cooperation rates for agents
        for agent_id in [donor_id, recipient_id]:
            coop = self.cooperation_scores.get(agent_id, 0)
            defec = self.defection_scores.get(agent_id, 0)
            total = coop + defec
            if total > 0:
                self.opponent_cooperation_rates[agent_id] = coop / total
                self.opponent_defection_rates[agent_id] = defec / total
            else:
                self.opponent_cooperation_rates[agent_id] = 0.5
                self.opponent_defection_rates[agent_id] = 0.5

        # Track interaction history for pairs
        if donor_id == self.agent_id:
            self.my_actions.append(donor_action == 'cooperate')
            self.opponent_actions.append(recipient_action == 'cooperate')
            self.last_opponent_actions[recipient_id] = recipient_action == 'cooperate'
        elif recipient_id == self.agent_id:
            self.my_actions.append(recipient_action == 'cooperate')
            self.opponent_actions.append(donor_action == 'cooperate')
            self.last_opponent_actions[donor_id] = donor_action == 'cooperate'

        # Update strategy performance based on outcomes where I'm involved
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            opp_action = recipient_action if donor_id == self.agent_id else donor_action

            # Determine my payoff (simplified: cooperate=1, defect=0, with mutual cooperation bonus)
            if my_action == 'cooperate' and opp_action == 'cooperate':
                payoff = 3
            elif my_action == 'cooperate' and opp_action == 'defect':
                payoff = 0
            elif my_action == 'defect' and opp_action == 'cooperate':
                payoff = 5
            else:  # both defect
                payoff = 1

            # Update performance for current strategy
            current_strategy = self.strategy
            self.strategy_performance[current_strategy] = self.strategy_performance.get(current_strategy, 0) * 0.9 + payoff * 0.1
            self.strategy_rounds[current_strategy] = self.strategy_rounds.get(current_strategy, 0) + 1

            # Update my score
            self.my_score += payoff

        # Update interaction weights (recent interactions matter more)
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            other = recipient_id if donor_id == self.agent_id else donor_id
            self.interaction_weights[other] = self.interaction_weights.get(other, 0) + 1

        # Forgetting mechanism: occasionally reduce trust for all agents to adapt over time
        if self.total_rounds % 10 == 0:
            for agent in self.trust:
                self.trust[agent] = max(0.0, self.trust[agent] * 0.95)

        # Keep only recent actions for opponent behavior tracking
        if self.total_rounds > 100:
            # Periodically reset cooperation rates to adapt to changing behavior
            if self.total_rounds % 50 == 0:
                self.opponent_cooperation_rates = {}
                self.opponent_defection_rates = {}

