class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.coop_count = {}
        self.defect_count = {}
        self.my_history = {}
        self.opponent_actions = {}
        self.last_observed = {}
        self.forgiveness = 0.2
        self.base_coop = 0.7
        self.round = 0
        self.my_coop = 0
        self.my_defect = 0
        self.recent_defections = {}
        self.punishment_threshold = 0.3
        self.self_coop_rate = 0.5
        self.recent_self_actions = []
        self.adaptive_forgiveness = 0.2
        self.rounds_since_forgive = 0
        # NEW: Track a short-term reputation bias for each agent (e.g., recent trend)
        self.short_term_bias = {}
        # NEW: Decay factor for short-term bias
        self.bias_decay = 0.9
        # NEW: Counter for how many times I've been exploited (opponent defected when I cooperated)
        self.exploitation_count = 0

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True

        opp_rep = self.reputation.get(opponent, 0.5)
        opp_actions = self.opponent_actions.get(opponent, [])

        # Incorporate short-term bias to adapt quickly to recent behavior
        bias = self.short_term_bias.get(opponent, 0.0)
        effective_rep = opp_rep + bias

        effective_base = 0.5 + (self.self_coop_rate - 0.5) * 0.3
        p_coop = effective_base + (effective_rep - 0.5) * 1.2

        my_hist = self.my_history.get(opponent, [])
        if my_hist:
            my_coop_rate = sum(1 for a in my_hist if a) / len(my_hist)
            if my_coop_rate > 0.7 and opp_actions and sum(opp_actions)/len(opp_actions) < 0.3:
                p_coop -= 0.4
            if opp_actions and sum(opp_actions[-3:]) >= 2:
                p_coop += 0.15

        # NEW: If I've been exploited a lot recently, increase punishment overall
        if self.exploitation_count > 5:
            p_coop -= 0.1

        if effective_rep < 0.2 and self.self_coop_rate > 0.6:
            p_coop -= 0.2

        p_coop = max(0.05, min(0.95, p_coop))
        return random.random() < p_coop

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        for actor_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if actor_id == self.agent_id:
                continue
            if action == 'cooperate':
                self.coop_count[actor_id] = self.coop_count.get(actor_id, 0) + 1
            else:
                self.defect_count[actor_id] = self.defect_count.get(actor_id, 0) + 1
                if actor_id not in self.recent_defections:
                    self.recent_defections[actor_id] = []
                self.recent_defections[actor_id].append(1)
                if len(self.recent_defections[actor_id]) > 10:
                    self.recent_defections[actor_id].pop(0)

            coop = self.coop_count.get(actor_id, 0)
            defect = self.defect_count.get(actor_id, 0)
            total = coop + defect
            if total == 0:
                rep = 0.5
            else:
                recent_defect_rate = sum(self.recent_defections.get(actor_id, [])) / 10 if actor_id in self.recent_defections else 0
                rep = 0.3 * 0.5 + 0.7 * (coop / total) - 0.2 * recent_defect_rate
            if action == 'defect':
                rep *= 0.9
            self.reputation[actor_id] = rep

            # NEW: Update short-term bias based on recent action (positive for cooperate, negative for defect)
            if action == 'cooperate':
                bias_update = 0.1
            else:
                bias_update = -0.15
            self.short_term_bias[actor_id] = self.short_term_bias.get(actor_id, 0.0) * self.bias_decay + bias_update

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            other = recipient_id if donor_id == self.agent_id else donor_id
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            other_action = recipient_action if donor_id == self.agent_id else donor_action

            if other not in self.my_history:
                self.my_history[other] = []
            self.my_history[other].append(my_action == 'cooperate')

            if other not in self.opponent_actions:
                self.opponent_actions[other] = []
            self.opponent_actions[other].append(other_action == 'cooperate')

            if my_action == 'cooperate':
                self.my_coop += 1
            else:
                self.my_defect += 1

            # NEW: Track exploitation count: I cooperated, opponent defected
            if my_action == 'cooperate' and other_action == 'defect':
                self.exploitation_count += 1
            else:
                # Decay exploitation count over time to avoid permanent punishment
                self.exploitation_count = max(0, self.exploitation_count - 1)

            self.recent_self_actions.append(1 if my_action == 'cooperate' else 0)
            if len(self.recent_self_actions) > 20:
                self.recent_self_actions.pop(0)
            if self.recent_self_actions:
                self.self_coop_rate = sum(self.recent_self_actions) / len(self.recent_self_actions)

        self.last_observed[(donor_id, recipient_id)] = (donor_action, recipient_action)

        self.round += 1
        self.rounds_since_forgive += 1
        if self.self_coop_rate > 0.7:
            self.adaptive_forgiveness = 0.3
        elif self.self_coop_rate < 0.4:
            self.adaptive_forgiveness = 0.1
        else:
            self.adaptive_forgiveness = 0.2

        if self.rounds_since_forgive >= 50:
            for agent in self.reputation:
                self.reputation[agent] = 0.5 + (self.reputation[agent] - 0.5) * (1 - self.adaptive_forgiveness)
            for agent in self.recent_defections:
                self.recent_defections[agent] = [x * 0.8 for x in self.recent_defections[agent]]
            # NEW: Also decay short-term bias on forgiveness
            for agent in self.short_term_bias:
                self.short_term_bias[agent] *= 0.5
            self.rounds_since_forgive = 0

