from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.interactions = {}
        self.observed_coop = {}
        self.observed_defect = {}
        self.coop_rate = {}
        self.forgiveness = {}
        self.rounds_played = 0
        self.rounds_observed = 0
        self.recent_actions = deque(maxlen=10)
        for i in range(15):
            self.reputation[i] = 0.5
            self.observed_coop[i] = 0
            self.observed_defect[i] = 0
            self.coop_rate[i] = 0.5
            self.forgiveness[i] = 0
            self.interactions[i] = deque(maxlen=20)
        self.last_defect_round = {}
        self.last_observed_action = {}
        self.bias = random.uniform(-0.1, 0.1)
        # NEW: Track a separate "trust" score that updates more aggressively
        self.trust = {}
        for i in range(15):
            self.trust[i] = 0.5
        # NEW: Track a longer-term cooperation memory for each agent
        self.coop_memory = {}
        for i in range(15):
            self.coop_memory[i] = deque(maxlen=50)
        # NEW: Track reputation volatility to adjust decision threshold
        self.rep_volatility = {}
        for i in range(15):
            self.rep_volatility[i] = 0.0

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True

        opp_rep = self.reputation.get(opponent, 0.5)
        direct_history = self.interactions.get(opponent, [])
        if direct_history:
            mutual_coop = sum(1 for my, their in direct_history if my and their)
            my_coop_their_defect = sum(1 for my, their in direct_history if my and not their)
            if my_coop_their_defect > 0:
                opp_rep -= 0.1 * my_coop_their_defect
            if mutual_coop > 0:
                opp_rep += 0.05 * mutual_coop
        opp_rep = max(0.0, min(1.0, opp_rep))

        total_obs = self.observed_coop.get(opponent, 0) + self.observed_defect.get(opponent, 0)
        if total_obs > 0:
            obs_coop_rate = self.observed_coop.get(opponent, 0) / total_obs
        else:
            obs_coop_rate = 0.5
        effective_rep = 0.7 * opp_rep + 0.3 * obs_coop_rate

        last_action = self.last_observed_action.get(opponent, None)
        if last_action == 'defect':
            effective_rep -= 0.1
        elif last_action == 'cooperate':
            effective_rep += 0.05

        last_defect = self.last_defect_round.get(opponent, -100)
        rounds_since_defect = self.rounds_played - last_defect
        if rounds_since_defect < 3:
            effective_rep -= 0.2
        elif rounds_since_defect > 10:
            effective_rep += 0.1

        forgiveness_count = self.forgiveness.get(opponent, 0)
        threshold = 0.4 + self.bias - 0.05 * forgiveness_count
        # NEW: Adjust threshold based on reputation volatility
        # If reputation is volatile, be more cautious (higher threshold)
        volatility = self.rep_volatility.get(opponent, 0.0)
        threshold += volatility * 0.3
        threshold = max(0.1, min(0.9, threshold))

        # NEW: Incorporate trust score into decision
        trust_score = self.trust.get(opponent, 0.5)
        # If trust is high, be more lenient; if low, be stricter
        effective_rep += (trust_score - 0.5) * 0.4

        # NEW: Use a probabilistic threshold that varies based on trust
        # If trust is low, we are more likely to defect even if rep is borderline
        if effective_rep > threshold:
            return True
        else:
            # With low trust, sometimes defect even if rep is okay
            if trust_score < 0.3 and random.random() < 0.3:
                return False
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        try:
            self.last_observed_action[donor_id] = donor_action
            self.last_observed_action[recipient_id] = recipient_action

            if donor_action == 'cooperate':
                self.observed_coop[donor_id] = self.observed_coop.get(donor_id, 0) + 1
            elif donor_action == 'defect':
                self.observed_defect[donor_id] = self.observed_defect.get(donor_id, 0) + 1
                self.last_defect_round[donor_id] = self.rounds_observed

            if recipient_action == 'cooperate':
                self.observed_coop[recipient_id] = self.observed_coop.get(recipient_id, 0) + 1
            elif recipient_action == 'defect':
                self.observed_defect[recipient_id] = self.observed_defect.get(recipient_id, 0) + 1
                self.last_defect_round[recipient_id] = self.rounds_observed

            # NEW: Track reputation volatility based on changes
            old_rep_donor = self.reputation.get(donor_id, 0.5)
            old_rep_recipient = self.reputation.get(recipient_id, 0.5)

            delta_d = 0.05 if donor_action == 'cooperate' else -0.05
            self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) + delta_d
            self.reputation[donor_id] = max(0.0, min(1.0, self.reputation[donor_id]))

            delta_r = 0.05 if recipient_action == 'cooperate' else -0.05
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) + delta_r
            self.reputation[recipient_id] = max(0.0, min(1.0, self.reputation[recipient_id]))

            # NEW: Update volatility as absolute change in reputation
            self.rep_volatility[donor_id] = abs(self.reputation[donor_id] - old_rep_donor)
            self.rep_volatility[recipient_id] = abs(self.reputation[recipient_id] - old_rep_recipient)

            # NEW: Update trust score more aggressively based on observed actions
            # Cooperation increases trust by 0.1, defection decreases by 0.15
            trust_delta = 0.1 if donor_action == 'cooperate' else -0.15
            self.trust[donor_id] = self.trust.get(donor_id, 0.5) + trust_delta
            self.trust[donor_id] = max(0.0, min(1.0, self.trust[donor_id]))

            trust_delta_r = 0.1 if recipient_action == 'cooperate' else -0.15
            self.trust[recipient_id] = self.trust.get(recipient_id, 0.5) + trust_delta_r
            self.trust[recipient_id] = max(0.0, min(1.0, self.trust[recipient_id]))

            # NEW: Store action in long-term memory for both parties
            self.coop_memory[donor_id].append(1 if donor_action == 'cooperate' else 0)
            self.coop_memory[recipient_id].append(1 if recipient_action == 'cooperate' else 0)

            if donor_id == self.agent_id or recipient_id == self.agent_id:
                if donor_id == self.agent_id:
                    opponent = recipient_id
                    my_action = donor_action == 'cooperate'
                    their_action = recipient_action == 'cooperate'
                else:
                    opponent = donor_id
                    my_action = recipient_action == 'cooperate'
                    their_action = donor_action == 'cooperate'

                if opponent not in self.interactions:
                    self.interactions[opponent] = deque(maxlen=20)
                self.interactions[opponent].append((my_action, their_action))

                if not their_action:
                    self.forgiveness[opponent] = self.forgiveness.get(opponent, 0) + 1
                    self.last_defect_round[opponent] = self.rounds_played
                else:
                    self.forgiveness[opponent] = max(0, self.forgiveness.get(opponent, 0) - 1)

                self.rounds_played += 1

            self.rounds_observed += 1

            if self.rounds_observed % 50 == 0:
                for agent in self.reputation:
                    self.reputation[agent] = 0.9 * self.reputation.get(agent, 0.5) + 0.1 * 0.5
                # Also decay trust toward neutral
                for agent in self.trust:
                    self.trust[agent] = 0.9 * self.trust.get(agent, 0.5) + 0.1 * 0.5
                # Decay volatility
                for agent in self.rep_volatility:
                    self.rep_volatility[agent] *= 0.9

        except Exception:
            pass

import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.coop_count = 0
        self.def_count = 0
        self.round_num = 0
        self.reputation = {}  # agent_id -> list of recent cooperation rates (0..1)
        self.own_reputation = 0.5
        self.trust = {}  # agent_id -> trust score (0..1)
        self.forgiveness = 0.3
        self.memory = 30  # how many recent observations to keep per agent

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        # Default: cooperate if opponent has good reputation or unknown
        if opponent not in self.reputation or len(self.reputation[opponent]) == 0:
            return True

        avg_reputation = sum(self.reputation[opponent]) / len(self.reputation[opponent])
        # Threshold: cooperate if reputation > 0.4, with some noise
        threshold = 0.4
        # If we've cooperated a lot and been exploited, be more cautious
        if self.def_count > self.coop_count * 2:
            threshold = 0.6
        # If we're being generous, lower threshold
        if self.forgiveness > 0.5:
            threshold = 0.3

        return avg_reputation > threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update own behavior counts if we are donor or recipient
        if donor_id == self.agent_id:
            if donor_action == 'cooperate':
                self.coop_count += 1
            else:
                self.def_count += 1
        if recipient_id == self.agent_id:
            if recipient_action == 'cooperate':
                self.coop_count += 1
            else:
                self.def_count += 1

        # Update reputation for donor and recipient (for others and self)
        for target_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if target_id == self.agent_id:
                # Update own reputation based on our average cooperation
                total_actions = self.coop_count + self.def_count
                if total_actions > 0:
                    self.own_reputation = self.coop_count / total_actions
            else:
                if target_id not in self.reputation:
                    self.reputation[target_id] = []
                # Append 1 for cooperate, 0 for defect
                val = 1.0 if action == 'cooperate' else 0.0
                self.reputation[target_id].append(val)
                # Keep memory limited
                if len(self.reputation[target_id]) > self.memory:
                    self.reputation[target_id].pop(0)

        # Update trust for the pair based on joint outcomes
        # Trust increases if both cooperate, decreases if we're exploited
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            # Third-party: just track joint behavior
            if donor_action == 'cooperate' and recipient_action == 'cooperate':
                # Both good, increase trust for both slightly
                for pid in [donor_id, recipient_id]:
                    if pid not in self.trust:
                        self.trust[pid] = 0.5
                    self.trust[pid] = min(1.0, self.trust[pid] + 0.02)
            elif donor_action == 'defect' and recipient_action == 'defect':
                # Both bad, decrease trust slightly
                for pid in [donor_id, recipient_id]:
                    if pid not in self.trust:
                        self.trust[pid] = 0.5
                    self.trust[pid] = max(0.0, self.trust[pid] - 0.02)
        else:
            # Self-involved: adjust trust more strongly based on outcome
            other_id = donor_id if donor_id != self.agent_id else recipient_id
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            other_action = recipient_action if donor_id == self.agent_id else donor_action

            if other_id not in self.trust:
                self.trust[other_id] = 0.5

            if my_action == 'cooperate' and other_action == 'defect':
                # Exploited: lower trust significantly
                self.trust[other_id] = max(0.0, self.trust[other_id] - 0.15)
            elif my_action == 'defect' and other_action == 'cooperate':
                # We exploited: lower trust a bit (guilt)
                self.trust[other_id] = max(0.0, self.trust[other_id] - 0.05)
            elif my_action == 'cooperate' and other_action == 'cooperate':
                # Mutual cooperation: increase trust
                self.trust[other_id] = min(1.0, self.trust[other_id] + 0.1)
            # Defect-defect: no change

        # Update forgiveness slowly based on overall cooperation
        total = self.coop_count + self.def_count
        if total > 0:
            coop_rate = self.coop_count / total
            # If we're cooperating a lot, be more forgiving; if exploited, less
            if coop_rate > 0.7:
                self.forgiveness = min(0.8, self.forgiveness + 0.01)
            elif coop_rate < 0.3:
                self.forgiveness = max(0.1, self.forgiveness - 0.01)

        # Increment round counter (roughly)
        self.round_num += 0.5  # since each observe may be called multiple times per round

