from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.interactions = {}
        self.observed_coop = {}
        self.observed_defect = {}
        self.coop_rate = {}
        self.forgiveness = {}
        self.rounds_played = 0
        self.rounds_observed = 0
        self.recent_actions = deque(maxlen=100)
        # New: track a per-agent "trust" that updates asymmetrically
        self.trust = {}
        # New: track a per-agent "uncertainty" that increases with conflicting observations
        self.uncertainty = {}
        for i in range(15):
            self.reputation[i] = 0.5
            self.observed_coop[i] = 0
            self.observed_defect[i] = 0
            self.coop_rate[i] = 0.5
            self.forgiveness[i] = 0
            self.interactions[i] = []
            self.trust[i] = 0.5
            self.uncertainty[i] = 0.0

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True

        # Use trust as primary signal, with a steeper threshold
        opp_trust = self.trust.get(opponent, 0.5)

        # Direct history penalty: if they defected against us recently, reduce trust
        direct_history = self.interactions.get(opponent, [])
        if direct_history:
            recent_defects = sum(1 for my, their in direct_history[-5:] if not their)
            opp_trust -= 0.15 * recent_defects
        opp_trust = max(0.0, min(1.0, opp_trust))

        # Observed behavior is weighted less than in parent
        total_obs = self.observed_coop.get(opponent, 0) + self.observed_defect.get(opponent, 0)
        obs_coop_rate = self.observed_coop.get(opponent, 0) / total_obs if total_obs > 0 else 0.5
        effective = 0.8 * opp_trust + 0.2 * obs_coop_rate

        # Much higher threshold: only cooperate with well-trusted agents
        threshold = 0.65
        # Add a small chance to cooperate even if below threshold, but lower than parent
        if effective > threshold:
            return True
        else:
            # If we have forgiven them many times and they haven't recently defected, give a chance
            if self.forgiveness.get(opponent, 0) > 3 and effective > 0.4:
                return random.random() < 0.3
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        try:
            # Update observation counts
            if donor_action == 'cooperate':
                self.observed_coop[donor_id] = self.observed_coop.get(donor_id, 0) + 1
            elif donor_action == 'defect':
                self.observed_defect[donor_id] = self.observed_defect.get(donor_id, 0) + 1

            if recipient_action == 'cooperate':
                self.observed_coop[recipient_id] = self.observed_coop.get(recipient_id, 0) + 1
            elif recipient_action == 'defect':
                self.observed_defect[recipient_id] = self.observed_defect.get(recipient_id, 0) + 1

            # Asymmetric trust update: cooperation increases trust more than defection decreases it
            # This makes the agent more forgiving of defection but slow to trust
            if donor_action == 'cooperate':
                self.trust[donor_id] = self.trust.get(donor_id, 0.5) + 0.1
                # Decrease uncertainty on cooperation
                self.uncertainty[donor_id] = max(0.0, self.uncertainty.get(donor_id, 0.0) - 0.05)
            else:
                self.trust[donor_id] = self.trust.get(donor_id, 0.5) - 0.05
                # Increase uncertainty on defection
                self.uncertainty[donor_id] = min(1.0, self.uncertainty.get(donor_id, 0.0) + 0.1)
            if recipient_action == 'cooperate':
                self.trust[recipient_id] = self.trust.get(recipient_id, 0.5) + 0.1
                self.uncertainty[recipient_id] = max(0.0, self.uncertainty.get(recipient_id, 0.0) - 0.05)
            else:
                self.trust[recipient_id] = self.trust.get(recipient_id, 0.5) - 0.05
                self.uncertainty[recipient_id] = min(1.0, self.uncertainty.get(recipient_id, 0.0) + 0.1)

            # Clamp trust
