                vol = self.volatility.get(opponent, 0.0)
                if vol > 0.5:
                    # More volatile opponents require higher reputation to cooperate
                    self.bias -= 0.02
                elif vol < 0.2:
                    # Stable opponents are more predictable, slightly more lenient
                    self.bias += 0.01
                self.bias = max(-0.3, min(0.3, self.bias))

                self.rounds_played += 1

            self.rounds_observed += 1

            if self.rounds_observed % 50 == 0:
                for agent in self.reputation:
                    self.reputation[agent] = 0.9 * self.reputation.get(agent, 0.5) + 0.1 * 0.5
                # Also decay trust toward neutral
                for agent in self.trust:
                    self.trust[agent] = 0.9 * self.trust.get(agent, 0.5) + 0.1 * 0.5
                # Decay volatility slowly
                for agent in self.volatility:
                    self.volatility[agent] *= 0.95
                # NEW: Decay grudges over time
                for agent in self.grudge:
                    if self.grudge[agent] > 0:
                        self.grudge[agent] -= 1

        except Exception:
