        threshold = 0.4 + uncertainty_penalty * (2 - decay_factor)

        # NEW: Cooperative momentum - if we've been cooperating recently,
        # slightly lower threshold (more trusting mood)
        if self.coop_momentum > 0.6:
            threshold -= 0.05
        elif self.coop_momentum < 0.4:
            threshold += 0.05

