import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.coop_count = 0
        self.def_count = 0
        self.round_num = 0
        self.reputation = {}  # agent_id -> list of recent cooperation rates (0..1)
        self.own_reputation = 0.5
        self.trust = {}  # agent_id -> trust score (0..1)
        self.forgiveness = 0.3
        self.memory = 30  # how many recent observations to keep per agent

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        # Default: cooperate if opponent has good reputation or unknown
        if opponent not in self.reputation or len(self.reputation[opponent]) == 0:
            return True

        avg_reputation = sum(self.reputation[opponent]) / len(self.reputation[opponent])
        # Threshold: cooperate if reputation > 0.4, with some noise
        threshold = 0.4
        # If we've cooperated a lot and been exploited, be more cautious
        if self.def_count > self.coop_count * 2:
            threshold = 0.6
        # If we're being generous, lower threshold
        if self.forgiveness > 0.5:
            threshold = 0.3

        return avg_reputation > threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update own behavior counts if we are donor or recipient
        if donor_id == self.agent_id:
            if donor_action == 'cooperate':
                self.coop_count += 1
            else:
                self.def_count += 1
        if recipient_id == self.agent_id:
            if recipient_action == 'cooperate':
                self.coop_count += 1
            else:
                self.def_count += 1

        # Update reputation for donor and recipient (for others and self)
        for target_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if target_id == self.agent_id:
                # Update own reputation based on our average cooperation
                total_actions = self.coop_count + self.def_count
                if total_actions > 0:
                    self.own_reputation = self.coop_count / total_actions
            else:
                if target_id not in self.reputation:
                    self.reputation[target_id] = []
                # Append 1 for cooperate, 0 for defect
                val = 1.0 if action == 'cooperate' else 0.0
                self.reputation[target_id].append(val)
                # Keep memory limited
                if len(self.reputation[target_id]) > self.memory:
                    self.reputation[target_id].pop(0)

        # Update trust for the pair based on joint outcomes
        # Trust increases if both cooperate, decreases if we're exploited
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            # Third-party: just track joint behavior
            if donor_action == 'cooperate' and recipient_action == 'cooperate':
                # Both good, increase trust for both slightly
                for pid in [donor_id, recipient_id]:
                    if pid not in self.trust:
                        self.trust[pid] = 0.5
                    self.trust[pid] = min(1.0, self.trust[pid] + 0.02)
            elif donor_action == 'defect' and recipient_action == 'defect':
                # Both bad, decrease trust slightly
                for pid in [donor_id, recipient_id]:
                    if pid not in self.trust:
                        self.trust[pid] = 0.5
                    self.trust[pid] = max(0.0, self.trust[pid] - 0.02)
        else:
            # Self-involved: adjust trust more strongly based on outcome
            other_id = donor_id if donor_id != self.agent_id else recipient_id
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            other_action = recipient_action if donor_id == self.agent_id else donor_action

            if other_id not in self.trust:
                self.trust[other_id] = 0.5

            if my_action == 'cooperate' and other_action == 'defect':
                # Exploited: lower trust significantly
                self.trust[other_id] = max(0.0, self.trust[other_id] - 0.15)
            elif my_action == 'defect' and other_action == 'cooperate':
                # We exploited: lower trust a bit (guilt)
                self.trust[other_id] = max(0.0, self.trust[other_id] - 0.05)
            elif my_action == 'cooperate' and other_action == 'cooperate':
                # Mutual cooperation: increase trust
                self.trust[other_id] = min(1.0, self.trust[other_id] + 0.1)
            # Defect-defect: no change

        # Update forgiveness slowly based on overall cooperation
        total = self.coop_count + self.def_count
        if total > 0:
            coop_rate = self.coop_count / total
            # If we're cooperating a lot, be more forgiving; if exploited, less
            if coop_rate > 0.7:
                self.forgiveness = min(0.8, self.forgiveness + 0.01)
            elif coop_rate < 0.3:
                self.forgiveness = max(0.1, self.forgiveness - 0.01)

        # Increment round counter (roughly)
        self.round_num += 0.5  # since each observe may be called multiple times per round

