class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Reputation tracking: map each other agent to a score between -1 and 1
        self.reputation = {}
        # Cooperation history for each agent: count of cooperations and defections observed
        self.history = {}
        # Track interaction counts for frequency weighting
        self.interaction_count = {}
        # Track own performance
        self.own_cooperations = 0
        self.own_defections = 0
        # Track opponent ID for current decision
        self._ctx_opponent_id = None
        # Last own action for potential reference
        self.last_action = None
        # Initialize reputation for all possible IDs (0-14)
        for i in range(15):
            self.reputation[i] = 0.0
            self.history[i] = {'coop': 0, 'defect': 0}
            self.interaction_count[i] = 0

    def decide(self) -> bool:
        # If no opponent info, cooperate by default
        if self._ctx_opponent_id is None:
            self.last_action = True
            return True

        opp_id = self._ctx_opponent_id
        # Get opponent's reputation, default to neutral 0.5 if unknown
        rep = self.reputation.get(opp_id, 0.5)

        # Adaptive threshold: start with 0.0 (cooperate if rep >= 0)
        # but become more forgiving over time with our own cooperation rate
        threshold = 0.0
        total_own = self.own_cooperations + self.own_defections
        if total_own > 5:
            # If we've been cooperating a lot, lower threshold (more trusting)
            # If we've been defecting a lot, raise threshold (more cautious)
            coop_rate = self.own_cooperations / total_own
            threshold = 0.2 - 0.4 * coop_rate  # range -0.2 to 0.2

        # Add small random exploration to avoid getting stuck
        # Only explore with low probability
        if random.random() < 0.05:
            action = random.random() > 0.5
        else:
            action = rep >= threshold

        self.last_action = action
        return action

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Update history for both agents
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id != self.agent_id:
                if action == 'cooperate':
                    self.history[agent_id]['coop'] += 1
                else:
                    self.history[agent_id]['defect'] += 1

        # Update interaction counts
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            # Third-party observation
            self.interaction_count[donor_id] += 1
            self.interaction_count[recipient_id] += 1

        # Update reputation based on actions
        # For donor: cooperation is good, defection is bad
        if donor_id != self.agent_id:
            delta = 0.1 if donor_action == 'cooperate' else -0.1
            self.reputation[donor_id] = max(-1.0, min(1.0, self.reputation[donor_id] + delta))

        # For recipient: cooperation received is good, defection received is bad
        if recipient_id != self.agent_id:
            delta = 0.1 if recipient_action == 'cooperate' else -0.1
            self.reputation[recipient_id] = max(-1.0, min(1.0, self.reputation[recipient_id] + delta))

        # If we are a participant, update own stats and potentially adjust reputation weighting
        if donor_id == self.agent_id:
            if donor_action == 'cooperate':
                self.own_cooperations += 1
            else:
                self.own_defections += 1
            # When we act, also update opponent's reputation based on their response to us
            # This gives extra weight to direct interactions
            if recipient_id != self.agent_id:
                # If they cooperated with us, boost reputation more
                if recipient_action == 'cooperate':
                    self.reputation[recipient_id] = max(-1.0, min(1.0, self.reputation[recipient_id] + 0.2))
                else:
                    self.reputation[recipient_id] = max(-1.0, min(1.0, self.reputation[recipient_id] - 0.2))

        if recipient_id == self.agent_id:
            if recipient_action == 'cooperate':
                self.own_cooperations += 1
            else:
                self.own_defections += 1
            # When we receive, also update donor reputation based on their action toward us
            if donor_id != self.agent_id:
                if donor_action == 'cooperate':
                    self.reputation[donor_id] = max(-1.0, min(1.0, self.reputation[donor_id] + 0.2))
                else:
                    self.reputation[donor_id] = max(-1.0, min(1.0, self.reputation[donor_id] - 0.2))

        # Occasionally normalize reputations to keep them bounded
        if random.random() < 0.01:
            # Decay old reputations slightly to forget ancient history
            for agent in self.reputation:
                self.reputation[agent] *= 0.99

