    def decide(self) -> bool:
        if self._ctx_opponent_id is None:
            return True
        opponent = self._ctx_opponent_id
        opp_rep = self.reputation.get(opponent, 0.5)
        history = self.interactions.get(opponent, [])
        if not history:
            prob_coop = 0.5 + (opp_rep - 0.5) * 0.5 + (self.coop_bias - 0.5) * 0.3
        else:
            recent = history[-5:]
            coop_rate = sum(1 for _, other in recent if other) / len(recent)
            my_coop_rate = sum(1 for me, _ in recent if me) / len(recent)
            base = coop_rate
            if len(recent) >= 2 and not recent[-1][1] and self.forgiveness > 0:
                prob_coop = base * 0.5 + 0.3 * self.forgiveness
            else:
                prob_coop = base
            prob_coop = 0.7 * prob_coop + 0.3 * opp_rep
            if my_coop_rate > 0.8:
                prob_coop += 0.1
            elif my_coop_rate < 0.2:
                prob_coop -= 0.1
            prob_coop = max(0.05, min(0.95, prob_coop))
        # New mechanism: mood adjustment based on recent outcomes
        if len(self.recent_outcomes) >= 5:
            avg_recent = sum(self.recent_outcomes[-5:]) / 5
            if avg_recent < 1.5:
                prob_coop -= 0.15  # more pessimistic
            elif avg_recent > 3.0:
                prob_coop += 0.1  # more optimistic
        prob_coop = max(0.05, min(0.95, prob_coop))
        if random.random() < prob_coop:
            return True
        else:
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        try:
            donor_coop = 1 if donor_action == 'cooperate' else 0
