                prob_coop -= 0.15  # more pessimistic
            elif avg_recent > 3.0:
                prob_coop += 0.1  # more optimistic
        prob_coop = max(0.05, min(0.95, prob_coop))
        if random.random() < prob_coop:
            return True
        else:
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        try:
