class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Track reputation of each agent: how often they cooperated relative to opportunities
        self.coop_count = {}
        self.defect_count = {}
        self.partner_history = {}
        self.round_num = 0
        self.generation = 0

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
