        elif conf < 0.2:
            trust_level = 0.8 * est_coop + 0.2 * rep
        else:
            trust_level = 0.5 * est_coop + 0.5 * rep

        # More aggressive self-adjustment based on recent actions
        if self.my_recent_actions:
            recent_me = list(self.my_recent_actions)[-5:]
            my_coop_rate = sum(recent_me) / len(recent_me)
            if my_coop_rate > 0.8:
                trust_level -= 0.25
            elif my_coop_rate < 0.2:
                trust_level += 0.25

        # New mechanism: mood affects decision, but dampened over time
        self.mood *= 0.9  # mood decay
        if self.mood > 0.5:
            trust_level += 0.1  # optimistic mood boosts cooperation
        elif self.mood < -0.5:
            trust_level -= 0.1  # pessimistic mood reduces cooperation

        # Adaptive learning rate based on recent outcome variance
        if len(self.recent_outcomes) >= 3:
            variance = sum((x - sum(self.recent_outcomes)/len(self.recent_outcomes))**2 for x in self.recent_outcomes) / len(self.recent_outcomes)
            # More uncertainty → more exploration (higher noise)
            noise_std = 0.05 + variance * 0.1
        else:
            noise_std = 0.05

        noise = random.gauss(0, noise_std)
        trust_level = max(0, min(1, trust_level + noise))
        return random.random() < trust_level

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id in self.cooperation_scores:
            self.cooperation_scores[donor_id].append(1 if donor_action == 'cooperate' else 0)
        else:
            self.cooperation_scores[donor_id] = deque([1 if donor_action == 'cooperate' else 0], maxlen=30)

        if recipient_id in self.cooperation_scores:
            self.cooperation_scores[recipient_id].append(1 if recipient_action == 'cooperate' else 0)
        else:
            self.cooperation_scores[recipient_id] = deque([1 if recipient_action == 'cooperate' else 0], maxlen=30)

        if donor_id == self.agent_id:
            self.interactions[recipient_id].append((1 if donor_action == 'cooperate' else 0,
                                                    1 if recipient_action == 'cooperate' else 0))
            self.my_recent_actions.append(1 if donor_action == 'cooperate' else 0)
        elif recipient_id == self.agent_id:
            self.interactions[donor_id].append((1 if recipient_action == 'cooperate' else 0,
                                                1 if donor_action == 'cooperate' else 0))
            self.my_recent_actions.append(1 if recipient_action == 'cooperate' else 0)

        # Update reputation with confidence tracking
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            current_rep = self.reputation.get(agent_id, 0.5)
            current_conf = self.reputation_confidence.get(agent_id, 0.0)
            current_rep *= self.decay_factor
            if action == 'cooperate':
                current_rep = min(1, current_rep + 0.1)
            else:
                current_rep = max(0, current_rep - 0.1)
            self.reputation[agent_id] = current_rep
            # Confidence increases with observations, bounded
            current_conf = min(1, current_conf + 0.05)
            self.reputation_confidence[agent_id] = current_conf

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            my_coop = (donor_action if donor_id == self.agent_id else recipient_action) == 'cooperate'
            other_coop = (recipient_action if donor_id == self.agent_id else donor_action) == 'cooperate'
            # Record outcome for adaptive learning
            outcome = 1 if (my_coop and other_coop) else 0
            self.recent_outcomes.append(outcome)

            if my_coop and other_coop:
                self.generosity = min(1, self.generosity + self.learning_rate)
                self.mood += 0.2  # positive experience
            elif my_coop and not other_coop:
                self.generosity = max(0, self.generosity - 2 * self.learning_rate)
                self.mood -= 0.3  # negative experience
            elif not my_coop and other_coop:
                self.generosity = min(1, self.generosity + 0.2 * self.learning_rate)
                self.mood += 0.1  # small positive
            else:
                self.mood -= 0.1  # both defect, slight negative

        # Mood only updated for self-involved interactions, bounded
        self.mood = max(-1, min(1, self.mood))

