        self.max_penalty = 0.5
        # New: track opponent's recent defection streak length
        self.defection_streak = {}
        # New: memory of opponent's last action (for recency-weighted trust)
        self.last_opponent_actions = {}
        # New: track the opponent's cooperation history as a weighted average
        self.opponent_coop_avg = {}
        # New: track the opponent's cooperation trend (increasing or decreasing)
        self.opponent_trend = {}
        # New: track the opponent's cooperation variance to detect erratic behavior
        self.opponent_var = {}
        for i in range(15):
            self.cooperation_scores[i] = deque([0.5], maxlen=30)
            self.reputation[i] = 0.5
            self.interactions[i] = deque(maxlen=30)
            self.defection_count[i] = 0
            self.defection_streak[i] = 0
            self.last_opponent_actions[i] = None
            self.opponent_coop_avg[i] = 0.5
            self.opponent_trend[i] = 0.0
            self.opponent_var[i] = 0.0

    def decide(self) -> bool:
        self.round_count += 1
        self.opponent_id = getattr(self, '_ctx_opponent_id', None)
        if self.opponent_id is None:
            return random.random() < 0.5

        opp_scores = self.cooperation_scores.get(self.opponent_id, deque([0.5], maxlen=30))
        if len(opp_scores) > 0:
            decay = 0.9
            est_coop = 0.0
            weight_sum = 0.0
            for i, score in enumerate(opp_scores):
                weight = decay ** (len(opp_scores) - i - 1)
                est_coop += score * weight
                weight_sum += weight
            est_coop /= weight_sum
        else:
            est_coop = 0.5

        rep = self.reputation.get(self.opponent_id, 0.5)
        trust_level = self.coop_weight * est_coop + self.reputation_weight * rep

        # New mechanism: escalate penalty based on repeated defections
        defections = self.defection_count.get(self.opponent_id, 0)
        if defections > 0:
            # Penalty grows with each defection, capped at max_penalty
            penalty = min(self.altruism_penalty * defections, self.max_penalty)
            trust_level -= penalty

        # New mechanism: additional penalty for long defection streaks
        streak = self.defection_streak.get(self.opponent_id, 0)
        if streak >= 3:
            trust_level -= 0.15  # extra penalty for consecutive defections

        if self.interactions.get(self.opponent_id):
            my_actions = [i[0] for i in self.interactions[self.opponent_id]]
            if my_actions and sum(my_actions) / len(my_actions) > 0.5 and rep < 0.3:
                trust_level -= self.altruism_penalty

        if self.my_recent_actions:
            recent_me = list(self.my_recent_actions)[-5:]
            my_coop_rate = sum(recent_me) / len(recent_me)
            if my_coop_rate > 0.8:
                trust_level -= 0.1
            elif my_coop_rate < 0.2:
                trust_level += 0.1

        # New mechanism: if opponent just defected last turn, lower trust slightly
        last_action = self.last_opponent_actions.get(self.opponent_id)
        if last_action == 'defect':
            trust_level -= 0.05

        # New mechanism: incorporate opponent's trend and variance
        # If opponent is becoming more cooperative over time, boost trust
        # If opponent is erratic (high variance), reduce trust
        trend = self.opponent_trend.get(self.opponent_id, 0.0)
        var = self.opponent_var.get(self.opponent_id, 0.0)
        if trend > 0.1:
            trust_level += 0.05
        elif trend < -0.1:
            trust_level -= 0.05
        if var > 0.2:
            trust_level -= 0.1

        noise = random.gauss(0, 0.05)
        trust_level = max(0, min(1, trust_level + noise))

