            # Update running average
            old_avg = self.opponent_coop_avg.get(agent_id, 0.5)
            # Use a small learning rate for the average
            self.opponent_coop_avg[agent_id] = old_avg + 0.1 * (coop_val - old_avg)
            # Update variance (simple running variance)
            old_var = self.opponent_var.get(agent_id, 0.0)
            # Variance update formula
            self.opponent_var[agent_id] = old_var + 0.1 * ((coop_val - old_avg)**2 - old_var)
