        opp_scores = self.cooperation_scores.get(self.opponent_id, deque([0.5], maxlen=30))
        if opp_scores:
            weights = [self.decay_factor ** (len(opp_scores) - i - 1) for i in range(len(opp_scores))]
            total_weight = sum(weights)
            est_coop = sum(s * w for s, w in zip(opp_scores, weights)) / total_weight if total_weight > 0 else 0.5
        else:
            est_coop = 0.5

        rep = self.reputation.get(self.opponent_id, 0.5)
        conf = self.reputation_confidence.get(self.opponent_id, 0.0)
        # Combine with confidence: high confidence means trust reputation more
        if conf > 0.5:
            trust_level = 0.3 * est_coop + 0.7 * rep
        elif conf < 0.2:
            trust_level = 0.8 * est_coop + 0.2 * rep
        else:
            trust_level = 0.5 * est_coop + 0.5 * rep

        # More aggressive self-adjustment based on recent actions
        if self.my_recent_actions:
            recent_me = list(self.my_recent_actions)[-5:]
            my_coop_rate = sum(recent_me) / len(recent_me)
            if my_coop_rate > 0.8:
