            self.cooperation_scores[recipient_id].append(1 if recipient_action == 'cooperate' else 0)
        else:
            self.cooperation_scores[recipient_id] = deque([1 if recipient_action == 'cooperate' else 0], maxlen=30)

        # New: increment interaction frequency for both observed agents
        self.interaction_frequency[donor_id] = self.interaction_frequency.get(donor_id, 0) + 1
        self.interaction_frequency[recipient_id] = self.interaction_frequency.get(recipient_id, 0) + 1

        if donor_id == self.agent_id:
            self.interactions[recipient_id].append((1 if donor_action == 'cooperate' else 0,
                                                    1 if recipient_action == 'cooperate' else 0))
            self.my_recent_actions.append(1 if donor_action == 'cooperate' else 0)
            self.last_coop_with[recipient_id] = (donor_action == 'cooperate')
        elif recipient_id == self.agent_id:
            self.interactions[donor_id].append((1 if recipient_action == 'cooperate' else 0,
                                                1 if donor_action == 'cooperate' else 0))
            self.my_recent_actions.append(1 if recipient_action == 'cooperate' else 0)
            self.last_coop_with[donor_id] = (recipient_action == 'cooperate')

        for agent_id, action, other_id in [(donor_id, donor_action, recipient_id), (recipient_id, recipient_action, donor_id)]:
            current_rep = self.reputation.get(agent_id, 0.5)
            other_rep = self.reputation.get(other_id, 0.5)
            if action == 'cooperate':
                if other_rep < 0.3:
                    delta = 0.03
                elif other_rep > 0.7:
                    delta = 0.07
                else:
                    delta = 0.05
            else:
                if other_rep > 0.7:
                    delta = -0.07
                elif other_rep < 0.3:
                    delta = -0.03
                else:
                    delta = -0.05
            # New: momentum-based reputation update
            momentum = self.rep_momentum.get(agent_id, 0.0)
            momentum = 0.7 * momentum + 0.3 * delta
            self.rep_momentum[agent_id] = momentum
            current_rep += momentum
            self.reputation[agent_id] = max(0, min(1, current_rep))

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            my_coop = (donor_action if donor_id == self.agent_id else recipient_action) == 'cooperate'
            other_coop = (recipient_action if donor_id == self.agent_id else donor_action) == 'cooperate'
            if my_coop and other_coop:
                self.generosity = min(1, self.generosity + self.learning_rate)
            elif my_coop and not other_coop:
                self.generosity = max(0, self.generosity - 2 * self.learning_rate)
                if donor_id == self.agent_id:
                    self.betrayal_memory.append(recipient_id)
                else:
                    self.betrayal_memory.append(donor_id)
            elif not my_coop and other_coop:
                self.generosity = min(1, self.generosity + 0.5 * self.learning_rate)

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.interactions = {}
        self.observed_coop = {}
        self.observed_defect = {}
        self.coop_rate = {}
        self.forgiveness = {}
        self.rounds_played = 0
        self.rounds_observed = 0
        self.recent_actions = deque(maxlen=10)
        self.last_observed = {}
        self.direct_coop_rate = {}
        self.defection_streak = {}
        self.punishment_level = {}
        self.memory_weight = {}
        self.trust_shift = {}  # tracks recent changes in reputation for each agent
        self.reciprocity = {}  # tracks whether we tend to mirror opponent's last action
        for i in range(15):
            self.reputation[i] = 0.5
            self.observed_coop[i] = 0
            self.observed_defect[i] = 0
            self.coop_rate[i] = 0.5
            self.forgiveness[i] = 0
            self.interactions[i] = []
            self.last_observed[i] = 0
            self.direct_coop_rate[i] = 0.5
            self.defection_streak[i] = 0
            self.punishment_level[i] = 0.0
            self.memory_weight[i] = 0.3
            self.trust_shift[i] = 0.0
            self.reciprocity[i] = 0.0

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True

        opp_rep = self.reputation.get(opponent, 0.5)
        direct_history = self.interactions.get(opponent, [])
        if direct_history:
            mutual_coop = sum(1 for my, their in direct_history if my and their)
            my_coop_their_defect = sum(1 for my, their in direct_history if my and not their)
            if my_coop_their_defect > 0:
                opp_rep -= 0.1 * my_coop_their_defect
            if mutual_coop > 0:
                opp_rep += 0.05 * mutual_coop
        opp_rep = max(0.0, min(1.0, opp_rep))

        # Use dynamic weight between direct and observed reputation
        n_direct = len(direct_history)
        if n_direct > 0:
            weight = min(0.9, 0.3 + n_direct * 0.05)
        else:
            weight = 0.3
        obs_coop_rate = 0.5
        total_obs = self.observed_coop.get(opponent, 0) + self.observed_defect.get(opponent, 0)
        if total_obs > 0:
            obs_coop_rate = self.observed_coop.get(opponent, 0) / total_obs
        effective_rep = weight * opp_rep + (1 - weight) * obs_coop_rate

        # NEW: Incorporate trust_shift - if opponent's reputation has recently fluctuated
        # significantly, we become more cautious (lower effective reputation)
        shift = self.trust_shift.get(opponent, 0.0)
        if shift > 0.15:  # significant recent change
            effective_rep -= min(0.3, shift * 0.5)

        # Punishment with forgiveness
        streak = self.defection_streak.get(opponent, 0)
        if streak > 0:
            recent_coop = sum(1 for my, their in direct_history[-3:] if their)
            if recent_coop > 0:
                streak_penalty = max(0.0, streak - recent_coop) * 0.1
            else:
                streak_penalty = min(0.5, streak * 0.1)
            effective_rep -= streak_penalty

        punishment = self.punishment_level.get(opponent, 0.0)
        if punishment > 0 and effective_rep > 0.35:
            effective_rep += punishment * 0.2
            self.punishment_level[opponent] = max(0.0, punishment - 0.05)

        # NEW: Reciprocity bias - if we have a strong tendency to mirror opponent's last action,
        # and that action was cooperation, we are more likely to cooperate.
        recip = self.reciprocity.get(opponent, 0.0)
        if direct_history and recip > 0.3 and direct_history[-1][1]:
            effective_rep += 0.1 * recip

        threshold = 0.4
        if effective_rep > threshold:
            return True
        else:
            if direct_history and len(direct_history) >= 10:
                mutual_coop_ratio = sum(1 for my, their in direct_history if my and their) / len(direct_history)
                if mutual_coop_ratio > 0.8 and random.random() < 0.3:
                    return True
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        try:
            if donor_action == 'cooperate':
                self.observed_coop[donor_id] = self.observed_coop.get(donor_id, 0) + 1
            elif donor_action == 'defect':
                self.observed_defect[donor_id] = self.observed_defect.get(donor_id, 0) + 1

            if recipient_action == 'cooperate':
                self.observed_coop[recipient_id] = self.observed_coop.get(recipient_id, 0) + 1
            elif recipient_action == 'defect':
                self.observed_defect[recipient_id] = self.observed_defect.get(recipient_id, 0) + 1

            # Update memory weight (same as parent)
            for agent_id in [donor_id, recipient_id]:
                self.memory_weight[agent_id] = self.memory_weight.get(agent_id, 0.3)
                if agent_id == donor_id:
                    action = donor_action
                else:
                    action = recipient_action
                if action == 'defect':
                    self.memory_weight[agent_id] = min(0.9, self.memory_weight[agent_id] + 0.05)
                else:
                    self.memory_weight[agent_id] = max(0.1, self.memory_weight[agent_id] - 0.02)
                self.memory_weight[agent_id] = 0.9 * self.memory_weight[agent_id] + 0.1 * 0.3

            # Compute reputation delta before updating (to track changes)
            old_donor_rep = self.reputation.get(donor_id, 0.5)
            old_recip_rep = self.reputation.get(recipient_id, 0.5)

            delta_d = 0.05 * (1.0 + self.memory_weight.get(donor_id, 0.3)) if donor_action == 'cooperate' else -0.05 * (1.0 + self.memory_weight.get(donor_id, 0.3))
            self.reputation[donor_id] = max(0.0, min(1.0, old_donor_rep + delta_d))

            delta_r = 0.05 * (1.0 + self.memory_weight.get(recipient_id, 0.3)) if recipient_action == 'cooperate' else -0.05 * (1.0 + self.memory_weight.get(recipient_id, 0.3))
            self.reputation[recipient_id] = max(0.0, min(1.0, old_recip_rep + delta_r))

            # NEW: Update trust_shift based on absolute change in reputation
            # This measures how volatile an agent's behavior appears
            for agent_id, old_rep, new_rep in [(donor_id, old_donor_rep, self.reputation[donor_id]),
                                               (recipient_id, old_recip_rep, self.reputation[recipient_id])]:
                change = abs(new_rep - old_rep)
                # Exponentially weighted moving average of change
                self.trust_shift[agent_id] = 0.9 * self.trust_shift.get(agent_id, 0.0) + 0.1 * change

            self.last_observed[donor_id] = self.rounds_observed
            self.last_observed[recipient_id] = self.rounds_observed

            if donor_id == self.agent_id or recipient_id == self.agent_id:
                if donor_id == self.agent_id:
                    opponent = recipient_id
                    my_action = donor_action == 'cooperate'
                    their_action = recipient_action == 'cooperate'
                else:
                    opponent = donor_id
                    my_action = recipient_action == 'cooperate'
                    their_action = donor_action == 'cooperate'

                if opponent not in self.interactions:
                    self.interactions[opponent] = []
                self.interactions[opponent].append((my_action, their_action))
                if len(self.interactions[opponent]) > 20:
                    self.interactions[opponent] = self.interactions[opponent][-20:]

                # NEW: Update reciprocity based on whether we matched opponent's last action
                # If we cooperated when they cooperated (or defected when they defected), increase reciprocity
                if my_action == their_action:
                    self.reciprocity[opponent] = min(1.0, self.reciprocity.get(opponent, 0.0) + 0.1)
                else:
                    self.reciprocity[opponent] = max(0.0, self.reciprocity.get(opponent, 0.0) - 0.05)

                if not their_action:
                    self.defection_streak[opponent] = self.defection_streak.get(opponent, 0) + 1
                    self.punishment_level[opponent] = self.punishment_level.get(opponent, 0.0) + 0.1
                else:
                    self.defection_streak[opponent] = 0
                    if self.punishment_level.get(opponent, 0.0) > 0:
                        self.punishment_level[opponent] = max(0.0, self.punishment_level[opponent] - 0.05)

                if not their_action:
                    self.forgiveness[opponent] = self.forgiveness.get(opponent, 0) + 1
                else:
                    self.forgiveness[opponent] = max(0, self.forgiveness.get(opponent, 0) - 1)

            self.rounds_observed += 1

            if self.rounds_observed % 50 == 0:
                for agent in self.reputation:
                    self.reputation[agent] = 0.9 * self.reputation.get(agent, 0.5) + 0.1 * 0.5
                    # Also decay trust_shift toward zero
                    self.trust_shift[agent] = 0.9 * self.trust_shift.get(agent, 0.0)

        except Exception:
            pass

