import random
import math
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Track reputation scores for all agents: -1 (bad), 0 (unknown), 1 (good)
        self.reputation = {}
        # Track cooperation history for each agent: deque of actions observed (maxlen=30)
        self.history = {}
        # Track my own cooperation rate
        self.my_cooperations = 0
        self.my_defections = 0
        # Track overall cooperation rate in population
        self.total_cooperations = 0
        self.total_actions = 0
        # Track recent performance to adapt (deque with maxlen=20)
        self.recent_rounds = deque(maxlen=20)
        # Initialize all possible agent IDs (0-14)
        for i in range(15):
            self.reputation[i] = 0
            self.history[i] = deque(maxlen=30)
        # For tracking opponent tendencies (deque with maxlen=20)
        self.opponent_coop_rate = {}
        # Track how many times I have been wronged (recipient defected against me)
        self.wronged_count = 0
        # Track forgiveness threshold: after this many good deeds, forgive a bad rep
        self.forgiveness_threshold = 3

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        # If unknown opponent, cooperate initially
        if opponent not in self.reputation or self.reputation[opponent] == 0:
            # Cooperate with high probability initially
            return random.random() < 0.8

        # Based on opponent's reputation
        rep = self.reputation[opponent]
        # Calculate population cooperation rate
        pop_coop_rate = self.total_cooperations / max(1, self.total_actions)

        # If opponent has good reputation, cooperate
        if rep > 0:
            # But also consider overall population trust
            if pop_coop_rate > 0.3:
                return True
            else:
                # If population is defecting a lot, be more cautious
                return random.random() < 0.7
        # If opponent has bad reputation, defect
        elif rep < 0:
            # But allow forgiveness: if opponent has been cooperating recently, give a chance
            recent_actions = self.history[opponent]
            if len(recent_actions) > 0:
                recent_coop_count = sum(1 for a in recent_actions if a == 'cooperate')
                recent_coop_rate = recent_coop_count / len(recent_actions)
                if recent_coop_rate > 0.7:
                    # Opponent has reformed, cooperate with some probability
                    return random.random() < 0.6
            return False
        else:
            # Unknown, use population average
            return random.random() < pop_coop_rate

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update history for both agents (deque auto-truncates)
        if donor_id not in self.history:
            self.history[donor_id] = deque(maxlen=30)
        if recipient_id not in self.history:
            self.history[recipient_id] = deque(maxlen=30)
        self.history[donor_id].append(donor_action)
        self.history[recipient_id].append(recipient_action)

        # Update total stats
        self.total_actions += 2
        if donor_action == 'cooperate':
            self.total_cooperations += 1
        if recipient_action == 'cooperate':
            self.total_cooperations += 1

        # Update my own counts if I'm involved
        if donor_id == self.agent_id:
            if donor_action == 'cooperate':
                self.my_cooperations += 1
            else:
                self.my_defections += 1
        if recipient_id == self.agent_id:
            if recipient_action == 'cooperate':
                self.my_cooperations += 1
            else:
                self.my_defections += 1
                # Track being wronged: someone defected against me
                self.wronged_count += 1

        # Update reputation based on observed actions
        # Modified rule: forgiveness mechanism - if an agent with bad rep cooperates consistently, recover faster
        # Also, defecting against a known defector is penalized less, but if I've been wronged a lot, be harsher
        if donor_action == 'cooperate':
            # Cooperation improves rep, but if bad rep, recover faster (forgiveness)
            if self.reputation[donor_id] < 0:
                self.reputation[donor_id] = min(1, self.reputation[donor_id] + 0.2)  # Faster recovery
            else:
                self.reputation[donor_id] = min(1, self.reputation[donor_id] + 0.1)
        else:
            # Check if the recipient was a known defector
            recipient_rep = self.reputation.get(recipient_id, 0)
            if recipient_rep < 0:
                # Defecting against a defector is acceptable, but harsher if I've been wronged often
                penalty = 0.05 if self.wronged_count < 5 else 0.1
                self.reputation[donor_id] = max(-1, self.reputation[donor_id] - penalty)
