            # Cooperate with high probability initially
            return random.random() < 0.8

        # Based on opponent's reputation
        rep = self.reputation[opponent]
        # Calculate population cooperation rate
        pop_coop_rate = self.total_cooperations / max(1, self.total_actions)

        # If opponent has good reputation, cooperate
        if rep > 0:
            # But also consider overall population trust
            if pop_coop_rate > 0.3:
                return True
            else:
                # If population is defecting a lot, be more cautious
