                recent_coop_count = sum(1 for a in recent_actions if a == 'cooperate')
                recent_coop_rate = recent_coop_count / len(recent_actions)
                if recent_coop_rate > 0.7:
                    # Opponent has reformed, cooperate with some probability
                    return random.random() < 0.6
            return False
        else:
            # Unknown, use population average
            return random.random() < pop_coop_rate

