        self.round_count += 1
        self.opponent_id = getattr(self, '_ctx_opponent_id', None)
        if self.opponent_id is None:
            return random.random() < 0.5

        opp_scores = self.cooperation_scores.get(self.opponent_id, deque([0.5], maxlen=30))
        if len(opp_scores) > 0:
            decay = 0.9
            est_coop = 0.0
            weight_sum = 0.0
            for i, score in enumerate(opp_scores):
                weight = decay ** (len(opp_scores) - i - 1)
                est_coop += score * weight
                weight_sum += weight
            est_coop /= weight_sum
        else:
            est_coop = 0.5

        rep = self.reputation.get(self.opponent_id, 0.5)
        # Use a blend of short-term and long-term reputation
        long_rep = self.long_term_reputation.get(self.opponent_id, 0.5)
        blended_rep = 0.6 * rep + 0.4 * long_rep

        trust_level = self.coop_weight * est_coop + self.reputation_weight * blended_rep

        # New mechanism: escalate penalty based on repeated defections, but with decay
        defections = self.defection_count.get(self.opponent_id, 0)
        if defections > 0:
            # Penalty grows with each defection, capped at max_penalty
            penalty = min(self.altruism_penalty * defections, self.max_penalty)
            trust_level -= penalty

        # New mechanism: also consider my own defections against this opponent
        # If I have defected a lot, I might expect retaliation and be more cautious
        my_defections = self.my_defection_count.get(self.opponent_id, 0)
        if my_defections > 0:
            # Small penalty for my own past defections (guilt/expectation)
            trust_level -= min(0.1 * my_defections, 0.3)

