import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.interactions = {}
        self.defection_count = 0
        self.cooperation_count = 0
        self.total_rounds = 0
        self.last_opponent = None
        self.trust_threshold = 0.3
        self.initial_trust = 0.5
        self.memory = 5
        self.forgiveness = 0.2

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        self.last_opponent = opponent
        if opponent is None:
            return True

        # Get reputation of opponent
        rep = self.reputation.get(opponent, self.initial_trust)

        # Check history with this opponent
        history = self.interactions.get(opponent, [])

        # If we have history, adjust based on recent actions
        if history:
            recent = history[-self.memory:]
            coop_count = sum(1 for h in recent if h)
            coop_ratio = coop_count / len(recent)
            # Combine reputation and direct experience
            trust = 0.6 * rep + 0.4 * coop_ratio
        else:
            trust = rep

        # Add slight randomness to break ties
        noise = random.uniform(-0.02, 0.02)
        trust += noise

        # Decision: cooperate if trust is above threshold
        return trust >= self.trust_threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update own experience
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # Self observation
            if donor_id == self.agent_id:
                if donor_action == 'cooperate':
                    self.cooperation_count += 1
                else:
                    self.defection_count += 1
                # Update opponent reputation based on their action
                if recipient_action == 'cooperate':
                    self._update_reputation(recipient_id, 0.1)
                else:
                    self._update_reputation(recipient_id, -0.2)
                # Record interaction
                if recipient_id in self.interactions:
                    self.interactions[recipient_id].append(recipient_action == 'cooperate')
                else:
                    self.interactions[recipient_id] = [recipient_action == 'cooperate']
            else:
                if recipient_action == 'cooperate':
                    self.cooperation_count += 1
                else:
                    self.defection_count += 1
                if donor_action == 'cooperate':
                    self._update_reputation(donor_id, 0.1)
                else:
                    self._update_reputation(donor_id, -0.2)
                if donor_id in self.interactions:
                    self.interactions[donor_id].append(donor_action == 'cooperate')
                else:
                    self.interactions[donor_id] = [donor_action == 'cooperate']
        else:
            # Third party observation
            # Update reputation of both agents
            if donor_action == 'cooperate':
                self._update_reputation(donor_id, 0.05)
            else:
                self._update_reputation(donor_id, -0.15)

            if recipient_action == 'cooperate':
                self._update_reputation(recipient_id, 0.05)
            else:
                self._update_reputation(recipient_id, -0.15)

        self.total_rounds += 1

        # Apply forgiveness slowly
        for key in list(self.reputation.keys()):
            if self.reputation[key] < self.initial_trust:
                self.reputation[key] += self.forgiveness * 0.01
            elif self.reputation[key] > self.initial_trust:
                self.reputation[key] -= self.forgiveness * 0.01

    def _update_reputation(self, agent_id: int, delta: float) -> None:
        if agent_id not in self.reputation:
            self.reputation[agent_id] = self.initial_trust
        self.reputation[agent_id] += delta
        # Clamp reputation between 0 and 1
        self.reputation[agent_id] = max(0.0, min(1.0, self.reputation[agent_id]))

