        for i in range(15):
            self.reputation[i] = 0
            self.history[i] = deque(maxlen=30)
        # For tracking opponent tendencies (deque with maxlen=20)
        self.opponent_coop_rate = {}
        # Track how many times I have been wronged (recipient defected against me)
        self.wronged_count = 0
        # Track forgiveness threshold: after this many good deeds, forgive a bad rep
        self.forgiveness_threshold = 3

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        # If unknown opponent, cooperate initially
        if opponent not in self.reputation or self.reputation[opponent] == 0:
            # Cooperate with high probability initially
            return random.random() < 0.8

        # Based on opponent's reputation
        rep = self.reputation[opponent]
        # Calculate population cooperation rate
        pop_coop_rate = self.total_cooperations / max(1, self.total_actions)

        # If opponent has good reputation, cooperate
        if rep > 0:
            # But also consider overall population trust
            if pop_coop_rate > 0.3:
                return True
            else:
                # If population is defecting a lot, be more cautious
                return random.random() < 0.7
        # If opponent has bad reputation, defect
        elif rep < 0:
            # But allow forgiveness: if opponent has been cooperating recently, give a chance
            recent_actions = self.history[opponent]
            if len(recent_actions) > 0:
                recent_coop_count = sum(1 for a in recent_actions if a == 'cooperate')
                recent_coop_rate = recent_coop_count / len(recent_actions)
                if recent_coop_rate > 0.7:
                    # Opponent has reformed, cooperate with some probability
                    return random.random() < 0.6
            return False
        else:
            # Unknown, use population average
            return random.random() < pop_coop_rate

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update history for both agents (deque auto-truncates)
        if donor_id not in self.history:
            self.history[donor_id] = deque(maxlen=30)
        if recipient_id not in self.history:
            self.history[recipient_id] = deque(maxlen=30)
        self.history[donor_id].append(donor_action)
        self.history[recipient_id].append(recipient_action)

        # Update total stats
        self.total_actions += 2
        if donor_action == 'cooperate':
            self.total_cooperations += 1
        if recipient_action == 'cooperate':
            self.total_cooperations += 1

