            if my_coop_their_defect > 0:
                opp_rep -= 0.1 * my_coop_their_defect
            if mutual_coop > 0:
                opp_rep += 0.05 * mutual_coop
        opp_rep = max(0.0, min(1.0, opp_rep))

        # Use dynamic weight between direct and observed reputation
        n_direct = len(direct_history)
        if n_direct > 0:
            weight = min(0.9, 0.3 + n_direct * 0.05)
        else:
            weight = 0.3
        obs_coop_rate = 0.5
        total_obs = self.observed_coop.get(opponent, 0) + self.observed_defect.get(opponent, 0)
        if total_obs > 0:
            obs_coop_rate = self.observed_coop.get(opponent, 0) / total_obs
        effective_rep = weight * opp_rep + (1 - weight) * obs_coop_rate

        # Incorporate uncertainty - if we are uncertain about opponent's behavior,
        # we become more cautious
        uncertainty = self.uncertainty.get(opponent, 0.0)
        if uncertainty > 0.2:
            effective_rep -= min(0.4, uncertainty * 0.5)

        # Incorporate trust_shift - if opponent's reputation has recently fluctuated
        shift = self.trust_shift.get(opponent, 0.0)
        if shift > 0.15:
            effective_rep -= min(0.3, shift * 0.5)

        # NEW: Implement "promise keeping" - if we cooperated last time and they defected,
        # we are more likely to defect now (this is a form of conditional cooperation)
        last_my = self.last_action_towards.get(opponent)
        last_their = direct_history[-1][1] if direct_history else None
        if last_my is not None and last_their is not None:
            if last_my and not last_their:
                # We cooperated, they defected - break trust
                effective_rep -= 0.15
            elif not last_my and last_their:
                # We defected, they cooperated - they are forgiving, we might reciprocate
                effective_rep += 0.05

        # NEW: Penalize behavioral flip-flopping - if they switch between cooperation and defection
        # frequently, we see them as unpredictable
        flip = self.behavior_flip.get(opponent, 0.0)
        if flip > 0.3:
            effective_rep -= min(0.3, flip * 0.3)

        # Punishment with forgiveness
        streak = self.defection_streak.get(opponent, 0)
        if streak > 0:
            recent_coop = sum(1 for my, their in direct_history[-3:] if their)
            if recent_coop > 0:
                streak_penalty = max(0.0, streak - recent_coop) * 0.1
            else:
                streak_penalty = min(0.5, streak * 0.1)
            effective_rep -= streak_penalty

        punishment = self.punishment_level.get(opponent, 0.0)
        if punishment > 0 and effective_rep > 0.35:
            effective_rep += punishment * 0.2
            self.punishment_level[opponent] = max(0.0, punishment - 0.05)

        # Reciprocity bias - if we have a strong tendency to mirror opponent's last action,
        # and that action was cooperation, we are more likely to cooperate.
        recip = self.reciprocity.get(opponent, 0.0)
        if direct_history and recip > 0.3 and direct_history[-1][1]:
            effective_rep += 0.1 * recip

        # NEW: Adaptive threshold based on social norm - if we value reciprocity highly,
        # we demand more from opponents who don't reciprocate
        threshold = 0.4
        adaptive_threshold = threshold + 0.1 * uncertainty
        # If we value reciprocity, we are stricter with opponents who don't match our actions
        if self.social_norm > 0.5 and direct_history:
            mismatches = sum(1 for my, their in direct_history if my != their)
            if len(direct_history) > 0:
                mismatch_ratio = mismatches / len(direct_history)
                adaptive_threshold += 0.1 * (mismatch_ratio - 0.5) * (self.social_norm - 0.5) * 2

        if effective_rep > adaptive_threshold:
            return True
        else:
            if direct_history and len(direct_history) >= 10:
                mutual_coop_ratio = sum(1 for my, their in direct_history if my and their) / len(direct_history)
                if mutual_coop_ratio > 0.8 and random.random() < 0.3:
                    return True
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        try:
            if donor_action == 'cooperate':
                self.observed_coop[donor_id] = self.observed_coop.get(donor_id, 0) + 1
            elif donor_action == 'defect':
                self.observed_defect[donor_id] = self.observed_defect.get(donor_id, 0) + 1

            if recipient_action == 'cooperate':
                self.observed_coop[recipient_id] = self.observed_coop.get(recipient_id, 0) + 1
            elif recipient_action == 'defect':
                self.observed_defect[recipient_id] = self.observed_defect.get(recipient_id, 0) + 1

            # Update memory weight
            for agent_id in [donor_id, recipient_id]:
                self.memory_weight[agent_id] = self.memory_weight.get(agent_id, 0.3)
                if agent_id == donor_id:
                    action = donor_action
                else:
                    action = recipient_action
                if action == 'defect':
                    self.memory_weight[agent_id] = min(0.9, self.memory_weight[agent_id] + 0.05)
                else:
                    self.memory_weight[agent_id] = max(0.1, self.memory_weight[agent_id] - 0.02)
                self.memory_weight[agent_id] = 0.9 * self.memory_weight[agent_id] + 0.1 * 0.3

            # Compute reputation delta before updating
            old_donor_rep = self.reputation.get(donor_id, 0.5)
            old_recip_rep = self.reputation.get(recipient_id, 0.5)

            delta_d = 0.05 * (1.0 + self.memory_weight.get(donor_id, 0.3)) if donor_action == 'cooperate' else -0.05 * (1.0 + self.memory_weight.get(donor_id, 0.3))
            self.reputation[donor_id] = max(0.0, min(1.0, old_donor_rep + delta_d))

            delta_r = 0.05 * (1.0 + self.memory_weight.get(recipient_id, 0.3)) if recipient_action == 'cooperate' else -0.05 * (1.0 + self.memory_weight.get(recipient_id, 0.3))
            self.reputation[recipient_id] = max(0.0, min(1.0, old_recip_rep + delta_r))

            # Update uncertainty based on the deviation of observed actions from expected reputation
            for agent_id, action, old_rep in [(donor_id, donor_action, old_donor_rep),
                                              (recipient_id, recipient_action, old_recip_rep)]:
                expected_coop = old_rep
                if action == 'cooperate':
                    deviation = 1.0 - expected_coop
                else:
                    deviation = expected_coop - 0.0
                new_uncertainty = self.uncertainty.get(agent_id, 0.0) * 0.95 + 0.05 * max(0.0, deviation)
                self.uncertainty[agent_id] = min(1.0, new_uncertainty)

            # Update trust_shift based on absolute change in reputation
            for agent_id, old_rep, new_rep in [(donor_id, old_donor_rep, self.reputation[donor_id]),
                                               (recipient_id, old_recip_rep, self.reputation[recipient_id])]:
                change = abs(new_rep - old_rep)
                self.trust_shift[agent_id] = 0.9 * self.trust_shift.get(agent_id, 0.0) + 0.1 * change

            # NEW: Update behavior_flip based on whether the action deviates from the last observed action
            # for that agent. If they switch, increase flip, if consistent, decrease.
            for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
                last_observed_action = self.last_observed.get(agent_id)
                if last_observed_action is not None:
                    if (action == 'cooperate' and last_observed_action == 'defect') or \
                       (action == 'defect' and last_observed_action == 'cooperate'):
                        self.behavior_flip[agent_id] = min(1.0, self.behavior_flip.get(agent_id, 0.0) + 0.2)
                    else:
                        self.behavior_flip[agent_id] = max(0.0, self.behavior_flip.get(agent_id, 0.0) - 0.1)
                else:
                    self.behavior_flip[agent_id] = self.behavior_flip.get(agent_id, 0.0)
                self.last_observed[agent_id] = action

            self.last_observed[donor_id] = self.rounds_observed
            self.last_observed[recipient_id] = self.rounds_observed

            if donor_id == self.agent_id or recipient_id == self.agent_id:
                if donor_id == self.agent_id:
                    opponent = recipient_id
                    my_action = donor_action == 'cooperate'
                    their_action = recipient_action == 'cooperate'
                else:
                    opponent = donor_id
                    my_action = recipient_action == 'cooperate'
                    their_action = donor_action == 'cooperate'

                if opponent not in self.interactions:
                    self.interactions[opponent] = []
                self.interactions[opponent].append((my_action, their_action))
                if len(self.interactions[opponent]) > 20:
                    self.interactions[opponent] = self.interactions[opponent][-20:]

                # Update reciprocity
                if my_action == their_action:
                    self.reciprocity[opponent] = min(1.0, self.reciprocity.get(opponent, 0.0) + 0.1)
                else:
                    self.reciprocity[opponent] = max(0.0, self.reciprocity.get(opponent, 0.0) - 0.05)

                # NEW: Track our last action towards this opponent
                self.last_action_towards[opponent] = my_action

                if not their_action:
                    self.defection_streak[opponent] = self.defection_streak.get(opponent, 0) + 1
                    self.punishment_level[opponent] = self.punishment_level.get(opponent, 0.0) + 0.1
                else:
                    self.defection_streak[opponent] = 0
                    if self.punishment_level.get(opponent, 0.0) > 0:
                        self.punishment_level[opponent] = max(0.0, self.punishment_level[opponent] - 0.05)

                if not their_action:
                    self.forgiveness[opponent] = self.forgiveness.get(opponent, 0) + 1
                else:
                    self.forgiveness[opponent] = max(0, self.forgiveness.get(opponent, 0) - 1)

            self.rounds_observed += 1

            if self.rounds_observed % 50 == 0:
                for agent in self.reputation:
                    self.reputation[agent] = 0.9 * self.reputation.get(agent, 0.5) + 0.1 * 0.5
                    self.trust_shift[agent] = 0.9 * self.trust_shift.get(agent, 0.0)
                    self.uncertainty[agent] = 0.9 * self.uncertainty.get(agent, 0.0)
                    # NEW: Decay behavior_flip toward zero
                    self.behavior_flip[agent] = 0.9 * self.behavior_flip.get(agent, 0.0)

        except Exception:
            pass

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.cooperation_scores = {}
        self.reputation = {}
        self.interactions = {}
        self.generosity = 0.5
        self.trust = 0.5
        self.learning_rate = 0.1
        self.my_recent_actions = deque(maxlen=30)
        self.round_count = 0
        self.opponent_id = None
        self.altruism_penalty = 0.2
        self.reputation_weight = 0.6
        self.coop_weight = 0.4
        self.last_coop_with = {}
        self.forgiveness = 0.3
        self.betrayal_memory = deque(maxlen=10)
        self.rep_momentum = {}
        self.interaction_frequency = {}
        # New: track recent cooperation against each opponent for reciprocity adjustment
        self.recent_opponent_coop = {}
        # New: limit on how much reputation can change in one observation
        self.rep_change_cap = 0.02
        for i in range(15):
            self.cooperation_scores[i] = deque([0.5], maxlen=30)
            self.reputation[i] = 0.5
            self.interactions[i] = deque(maxlen=30)
            self.last_coop_with[i] = None
            self.rep_momentum[i] = 0.0
            self.interaction_frequency[i] = 0
            self.recent_opponent_coop[i] = deque(maxlen=5)

    def decide(self) -> bool:
        self.round_count += 1
        self.opponent_id = getattr(self, '_ctx_opponent_id', None)
        if self.opponent_id is None:
            return random.random() < 0.5

        opp_scores = self.cooperation_scores.get(self.opponent_id, deque([0.5], maxlen=30))
        if len(opp_scores) > 0:
            decay = 0.9
            est_coop = 0.0
            weight_sum = 0.0
            for i, score in enumerate(opp_scores):
                weight = decay ** (len(opp_scores) - i - 1)
                est_coop += score * weight
                weight_sum += weight
            est_coop /= weight_sum
        else:
            est_coop = 0.5

        rep = self.reputation.get(self.opponent_id, 0.5)
        trust_level = self.coop_weight * est_coop + self.reputation_weight * rep

        if self.interactions.get(self.opponent_id):
            my_actions = [i[0] for i in self.interactions[self.opponent_id]]
            if my_actions and sum(my_actions) / len(my_actions) > 0.5 and rep < 0.3:
                trust_level -= self.altruism_penalty

        last_coop = self.last_coop_with.get(self.opponent_id)
        if last_coop is not None and not last_coop:
            trust_level += self.forgiveness * 0.1

        if self.my_recent_actions:
            recent_me = list(self.my_recent_actions)[-5:]
            my_coop_rate = sum(recent_me) / len(recent_me)
            if my_coop_rate > 0.8:
                trust_level -= 0.1
            elif my_coop_rate < 0.2:
                trust_level += 0.1

        if len(self.betrayal_memory) > 0 and self.opponent_id in self.betrayal_memory:
            recent_betrayals = sum(1 for b in self.betrayal_memory if b == self.opponent_id)
            if recent_betrayals >= 3:
                trust_level -= 0.15

        freq = self.interaction_frequency.get(self.opponent_id, 0)
        if freq > 5:
            if self.generosity > 0.7:
                trust_level += 0.05 * self.generosity
            elif self.generosity < 0.3:
                trust_level -= 0.05 * (1 - self.generosity)

        # New: reciprocity adjustment based on recent opponent actions
        recent_opp = self.recent_opponent_coop.get(self.opponent_id, deque(maxlen=5))
        if len(recent_opp) > 0:
            opp_coop_rate = sum(recent_opp) / len(recent_opp)
            if opp_coop_rate > 0.7:
                trust_level += 0.1 * opp_coop_rate
            elif opp_coop_rate < 0.3:
                trust_level -= 0.1 * (1 - opp_coop_rate)

        noise = random.gauss(0, 0.05)
        trust_level = max(0, min(1, trust_level + noise))

        return random.random() < trust_level

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id in self.cooperation_scores:
            self.cooperation_scores[donor_id].append(1 if donor_action == 'cooperate' else 0)
        else:
            self.cooperation_scores[donor_id] = deque([1 if donor_action == 'cooperate' else 0], maxlen=30)

        if recipient_id in self.cooperation_scores:
            self.cooperation_scores[recipient_id].append(1 if recipient_action == 'cooperate' else 0)
        else:
            self.cooperation_scores[recipient_id] = deque([1 if recipient_action == 'cooperate' else 0], maxlen=30)

        self.interaction_frequency[donor_id] = self.interaction_frequency.get(donor_id, 0) + 1
        self.interaction_frequency[recipient_id] = self.interaction_frequency.get(recipient_id, 0) + 1

        if donor_id == self.agent_id:
            self.interactions[recipient_id].append((1 if donor_action == 'cooperate' else 0,
                                                    1 if recipient_action == 'cooperate' else 0))
            self.my_recent_actions.append(1 if donor_action == 'cooperate' else 0)
            self.last_coop_with[recipient_id] = (donor_action == 'cooperate')
        elif recipient_id == self.agent_id:
            self.interactions[donor_id].append((1 if recipient_action == 'cooperate' else 0,
                                                1 if donor_action == 'cooperate' else 0))
            self.my_recent_actions.append(1 if recipient_action == 'cooperate' else 0)
            self.last_coop_with[donor_id] = (recipient_action == 'cooperate')

        # New: track recent cooperation of observed agents for reciprocity
        self.recent_opponent_coop[donor_id].append(1 if donor_action == 'cooperate' else 0)
        self.recent_opponent_coop[recipient_id].append(1 if recipient_action == 'cooperate' else 0)

        for agent_id, action, other_id in [(donor_id, donor_action, recipient_id), (recipient_id, recipient_action, donor_id)]:
            current_rep = self.reputation.get(agent_id, 0.5)
            other_rep = self.reputation.get(other_id, 0.5)
            if action == 'cooperate':
                if other_rep < 0.3:
                    raw_delta = 0.03
                elif other_rep > 0.7:
                    raw_delta = 0.07
                else:
                    raw_delta = 0.05
            else:
                if other_rep > 0.7:
                    raw_delta = -0.07
                elif other_rep < 0.3:
                    raw_delta = -0.03
                else:
                    raw_delta = -0.05
            # New: cap the magnitude of reputation change to prevent rapid swings
            delta = max(-self.rep_change_cap, min(self.rep_change_cap, raw_delta))
            momentum = self.rep_momentum.get(agent_id, 0.0)
            momentum = 0.7 * momentum + 0.3 * delta
            self.rep_momentum[agent_id] = momentum
            current_rep += momentum
            self.reputation[agent_id] = max(0, min(1, current_rep))

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            my_coop = (donor_action if donor_id == self.agent_id else recipient_action) == 'cooperate'
            other_coop = (recipient_action if donor_id == self.agent_id else donor_action) == 'cooperate'
            if my_coop and other_coop:
                self.generosity = min(1, self.generosity + self.learning_rate)
            elif my_coop and not other_coop:
                self.generosity = max(0, self.generosity - 2 * self.learning_rate)
                if donor_id == self.agent_id:
                    self.betrayal_memory.append(recipient_id)
                else:
                    self.betrayal_memory.append(donor_id)
            elif not my_coop and other_coop:
                self.generosity = min(1, self.generosity + 0.5 * self.learning_rate)

