        opponent = self._ctx_opponent_id
        # If unknown opponent, cooperate with high probability
        if opponent not in self.reputation or self.reputation[opponent] == 0:
            return random.random() < 0.8

        rep = self.reputation[opponent]
        # Get opponent's recent cooperation rate from history
        opp_history = self.history.get(opponent, deque())
        if len(opp_history) > 0:
            opp_coop_rate = sum(1 for a in opp_history if a == 'cooperate') / len(opp_history)
        else:
            opp_coop_rate = 0.5

        # Adjust threshold based on my own recent performance
        if len(self.my_recent_actions) >= 5:
            my_coop_rate = sum(1 for a in self.my_recent_actions if a == 'cooperate') / len(self.my_recent_actions)
            # If I've been exploited (cooperating while others defect), raise threshold
            if my_coop_rate > 0.7 and opp_coop_rate < 0.4:
                self.coop_threshold = min(0.9, self.coop_threshold + 0.05)
            # If I've been too cautious, lower threshold
            elif my_coop_rate < 0.3 and opp_coop_rate > 0.6:
                self.coop_threshold = max(0.1, self.coop_threshold - 0.05)

        # Combine reputation and observed behavior
        if rep > 0:
            # Good reputation, but require recent behavior to match
            return opp_coop_rate >= self.coop_threshold or random.random() < 0.4
        elif rep < 0:
            # Bad reputation, defect unless recent behavior shows improvement
            return opp_coop_rate > 0.7 and random.random() < 0.5
        else:
            # Unknown, use population average
            pop_coop_rate = self.total_cooperations / max(1, self.total_actions)
            return random.random() < pop_coop_rate

