import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Reputation tracking: for each agent, count cooperative and defective actions observed
        self.reputation = {}  # agent_id -> {'coop': int, 'defect': int}
        # Track direct interaction outcomes with each opponent
        self.interactions = {}  # opponent_id -> {'coop': int, 'defect': int, 'opp_coop': int, 'opp_defect': int}
        # Track my own action history
        self.my_actions = []
        # Track opponent's last action for each agent
        self.last_action = {}  # agent_id -> 'cooperate' or 'defect'
        # For randomness in early rounds, use a simple deterministic seed
        self.round_num = 0

    def decide(self) -> bool:
        # Get opponent ID from context
        opp_id = getattr(self, '_ctx_opponent_id', None)
        if opp_id is None:
            return True

        # First round: cooperate with high probability but not always
        if self.round_num < 3:
            # Deterministic based on agent_id to avoid randomness issues
            return (self.agent_id + opp_id) % 3 != 0

        # Gather reputation info about opponent
        rep = self.reputation.get(opp_id, {'coop': 0, 'defect': 0})
        total_obs = rep['coop'] + rep['defect']

        # Direct interaction history
        inter = self.interactions.get(opp_id, {'coop': 0, 'defect': 0, 'opp_coop': 0, 'opp_defect': 0})

        # If we have direct history, heavily weight it
        if inter['coop'] + inter['defect'] > 0:
            my_defect_rate = inter['defect'] / (inter['coop'] + inter['defect'])
            opp_defect_rate = inter['opp_defect'] / (inter['opp_coop'] + inter['opp_defect'])

            # If opponent defects a lot against me, defect
            if opp_defect_rate > 0.6:
                return False
            # If opponent cooperates a lot and I've been defecting, switch to cooperate
            if opp_defect_rate < 0.2 and my_defect_rate > 0.5:
                return True
            # Tit-for-tat with some forgiveness
            last = self.last_action.get(opp_id, 'cooperate')
            if last == 'defect' and my_defect_rate < 0.8:
                return False

        # If no direct history, use reputation
        if total_obs > 0:
            coop_rate = rep['coop'] / total_obs
            # Cooperate if reputation is good, defect if bad
            if coop_rate > 0.7:
                return True
            elif coop_rate < 0.3:
                return False
            else:
                # Mixed reputation: use a deterministic threshold based on agent IDs
                return (self.agent_id * 7 + opp_id * 3) % 10 < 6
        else:
            # No information: cooperate initially, but be slightly suspicious
            return True

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update round number on self-observation
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self.round_num += 1

        # Update reputation for donor
        if donor_id != self.agent_id:  # Don't track own reputation from own actions
            rep = self.reputation.get(donor_id, {'coop': 0, 'defect': 0})
            if donor_action == 'cooperate':
                rep['coop'] += 1
            else:
                rep['defect'] += 1
            self.reputation[donor_id] = rep

        # Update reputation for recipient (their action also matters)
        if recipient_id != self.agent_id:
            rep = self.reputation.get(recipient_id, {'coop': 0, 'defect': 0})
            if recipient_action == 'cooperate':
                rep['coop'] += 1
            else:
                rep['defect'] += 1
            self.reputation[recipient_id] = rep

        # Track last action for each agent (from observations)
        if donor_id != self.agent_id:
            self.last_action[donor_id] = donor_action
        if recipient_id != self.agent_id:
            self.last_action[recipient_id] = recipient_action

        # If I'm involved in this interaction, update direct interaction records
        if donor_id == self.agent_id:
            # I am the donor
            opp_id = recipient_id
            inter = self.interactions.get(opp_id, {'coop': 0, 'defect': 0, 'opp_coop': 0, 'opp_defect': 0})
            if donor_action == 'cooperate':
                inter['coop'] += 1
            else:
                inter['defect'] += 1
            if recipient_action == 'cooperate':
                inter['opp_coop'] += 1
            else:
                inter['opp_defect'] += 1
            self.interactions[opp_id] = inter
            self.my_actions.append(donor_action)
            self.last_action[opp_id] = recipient_action
        elif recipient_id == self.agent_id:
            # I am the recipient
            opp_id = donor_id
            inter = self.interactions.get(opp_id, {'coop': 0, 'defect': 0, 'opp_coop': 0, 'opp_defect': 0})
            if recipient_action == 'cooperate':
                inter['coop'] += 1
            else:
                inter['defect'] += 1
            if donor_action == 'cooperate':
                inter['opp_coop'] += 1
            else:
                inter['opp_defect'] += 1
            self.interactions[opp_id] = inter
            self.my_actions.append(recipient_action)
            self.last_action[opp_id] = donor_action

