        trend = self.rep_trend.get(self.opponent_id, 0.0)
        trust_level += 0.2 * trend

        vol = self.rep_volatility.get(self.opponent_id, deque(maxlen=10))
        if len(vol) > 0:
            avg_vol = sum(vol) / len(vol)
            if avg_vol > self.volatility_threshold:
                trust_level -= 0.1 * avg_vol

        # New: Punish inconsistent cooperation behavior (unpredictable agents)
        consistency = self.coop_consistency.get(self.opponent_id, deque(maxlen=10))
        if len(consistency) > 1:
            # Count transitions between cooperation and defection
            transitions = sum(1 for i in range(1, len(consistency)) if consistency[i] != consistency[i-1])
            inconsistency_rate = transitions / (len(consistency) - 1)
            if inconsistency_rate > 0.5:
                trust_level -= self.inconsistency_penalty * inconsistency_rate

        noise = random.gauss(0, 0.05)
        trust_level = max(0, min(1, trust_level + noise))

        # New: Use a sigmoid function to make decisions less binary
        decision_prob = 1 / (1 + math.exp(-8 * (trust_level - 0.5)))
        return random.random() < decision_prob

