        self.round_count += 1
        self.opponent_id = getattr(self, '_ctx_opponent_id', None)
        if self.opponent_id is None:
            return random.random() < 0.5

        opp_scores = self.cooperation_scores.get(self.opponent_id, deque([0.5], maxlen=30))
        if len(opp_scores) > 0:
            decay = 0.9
            est_coop = 0.0
            weight_sum = 0.0
            for i, score in enumerate(opp_scores):
                weight = decay ** (len(opp_scores) - i - 1)
                est_coop += score * weight
                weight_sum += weight
            est_coop /= weight_sum
        else:
            est_coop = 0.5

        rep = self.reputation.get(self.opponent_id, 0.5)
        trust_level = self.coop_weight * est_coop + self.reputation_weight * rep

        if self.interactions.get(self.opponent_id):
            my_actions = [i[0] for i in self.interactions[self.opponent_id]]
            if my_actions and sum(my_actions) / len(my_actions) > 0.5 and rep < 0.3:
                trust_level -= self.altruism_penalty

        last_coop = self.last_coop_with.get(self.opponent_id)
        if last_coop is not None and not last_coop:
            trust_level += self.forgiveness * 0.1

        if self.my_recent_actions:
            recent_me = list(self.my_recent_actions)[-5:]
            my_coop_rate = sum(recent_me) / len(recent_me)
            # New: Adapt threshold based on own recent cooperation rate
            if my_coop_rate > self.overly_generous_threshold:
                trust_level -= self.self_coop_adjustment * (my_coop_rate - self.overly_generous_threshold) / (1 - self.overly_generous_threshold)
            elif my_coop_rate < 0.2:
                trust_level += self.self_coop_adjustment * (0.2 - my_coop_rate) / 0.2

        if len(self.betrayal_memory) > 0 and self.opponent_id in self.betrayal_memory:
            recent_betrayals = sum(1 for b in self.betrayal_memory if b == self.opponent_id)
            if recent_betrayals >= 3:
                trust_level -= 0.15

        freq = self.interaction_frequency.get(self.opponent_id, 0)
        if freq > 5:
            if self.generosity > 0.7:
                trust_level += 0.05 * self.generosity
            elif self.generosity < 0.3:
                trust_level -= 0.05 * (1 - self.generosity)

        recent_opp = self.recent_opponent_coop.get(self.opponent_id, deque(maxlen=5))
        if len(recent_opp) > 0:
            opp_coop_rate = sum(recent_opp) / len(recent_opp)
            if opp_coop_rate > 0.7:
                trust_level += 0.1 * opp_coop_rate
            elif opp_coop_rate < 0.3:
                trust_level -= 0.1 * (1 - opp_coop_rate)

        # New: Incorporate reputation trend and volatility into decision
        trend = self.rep_trend.get(self.opponent_id, 0.0)
        trust_level += 0.2 * trend

        vol = self.rep_volatility.get(self.opponent_id, deque(maxlen=10))
        if len(vol) > 0:
            avg_vol = sum(vol) / len(vol)
            if avg_vol > self.volatility_threshold:
                trust_level -= 0.1 * avg_vol

        # New: Punish inconsistent cooperation behavior (unpredictable agents)
        consistency = self.coop_consistency.get(self.opponent_id, deque(maxlen=10))
        if len(consistency) > 1:
            # Count transitions between cooperation and defection
            transitions = sum(1 for i in range(1, len(consistency)) if consistency[i] != consistency[i-1])
            inconsistency_rate = transitions / (len(consistency) - 1)
            if inconsistency_rate > 0.5:
                trust_level -= self.inconsistency_penalty * inconsistency_rate

        noise = random.gauss(0, 0.05)
        trust_level = max(0, min(1, trust_level + noise))

        # New: Use a sigmoid function to make decisions less binary
        decision_prob = 1 / (1 + math.exp(-8 * (trust_level - 0.5)))
        return random.random() < decision_prob

