from collections import deque


class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self._ctx_opponent_id = None
        self.reputation = {}
        self.coop_count = 0
        self.defect_count = 0
        self.total_actions = 0
        self.opponent_history = {}
        self.self_history = deque(maxlen=20)
        self.generation = 0
        self.round_num = 0
        self.last_opponent = None
        self.trust_factor = 1.0
        self.defection_penalty = 0.5
        self.initial_threshold = 0.5
        self.reciprocity = {}
        self.reputation_momentum = {}

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        self.last_opponent = opponent
        if opponent is None:
            return True

        opp_rep = self.reputation.get(opponent, 0.5)
        own_rep = self.reputation.get(self.agent_id, 0.5)

        threshold = 0.4 + 0.1 * (1 - own_rep)

        if opponent in self.opponent_history:
            hist = self.opponent_history[opponent]
            if len(hist) >= 5:
                coop_rate = sum(hist) / len(hist)
                threshold = 0.3 + 0.2 * (1 - coop_rate)

        # Reciprocity adjustment: if we cooperated last time with opponent, be more likely to cooperate
        if opponent in self.reciprocity:
            last_opponent_action = self.reciprocity[opponent][-1] if self.reciprocity[opponent] else None
            if last_opponent_action == 'cooperate':
                threshold -= 0.1
            elif last_opponent_action == 'defect':
                threshold += 0.1

        decision = opp_rep >= threshold

        if random.random() < 0.05:
            decision = not decision

        return decision

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        donor_val = 1.0 if donor_action == 'cooperate' else 0.0
        recipient_val = 1.0 if recipient_action == 'cooperate' else 0.0

        # Update donor's reputation with momentum to smooth changes
        if donor_id in self.reputation:
            self.reputation_momentum[donor_id] = 0.8 * self.reputation_momentum.get(donor_id, 0) + 0.2 * donor_val
            self.reputation[donor_id] = 0.9 * self.reputation[donor_id] + 0.1 * donor_val
        else:
            self.reputation[donor_id] = donor_val
            self.reputation_momentum[donor_id] = donor_val

        if recipient_id in self.reputation:
            self.reputation_momentum[recipient_id] = 0.8 * self.reputation_momentum.get(recipient_id, 0) + 0.2 * recipient_val
            self.reputation[recipient_id] = 0.9 * self.reputation[recipient_id] + 0.1 * recipient_val
        else:
            self.reputation[recipient_id] = recipient_val
            self.reputation_momentum[recipient_id] = recipient_val

        if donor_id == self.agent_id:
            self.total_actions += 1
            if donor_action == 'cooperate':
                self.coop_count += 1
            else:
                self.defect_count += 1
            self.self_history.append(1 if donor_action == 'cooperate' else 0)

        if recipient_id == self.agent_id:
            self.total_actions += 1
            if recipient_action == 'cooperate':
