        momentum = self.trust_momentum.get(self.opponent_id, 0.0)
        trust_level += momentum
        # Update momentum for next round (decay)
        self.trust_momentum[self.opponent_id] = momentum * 0.9

        noise = random.gauss(0, 0.05)
        trust_level = max(0, min(1, trust_level + noise))

        # Mutation: adaptive threshold - adjust based on recent outcomes
        if random.random() < self.exploration:
            return random.random() < 0.5

        # Use adaptive threshold instead of fixed 0.5
        return random.random() < (trust_level + self.adaptive_threshold) / 2

