import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.history = {}
        self.trust = {}
        self.interaction_count = {}
        self.population_coop_rate = 0.5
        self.observation_count = 0
        self.my_recent_actions = deque(maxlen=30)
        self.recent_opponent_coop = {}
        self.alpha = 0.2  # increased forgetting factor for faster adaptation
        self.default_trust = 0.5  # higher baseline trust
        self.aggression = 0.1  # lower initial aggression
        self.recent_coop_ratio = {}
        self.self_reputation = 0.0
        self.meta_reputation = 0.0
        self.my_decision_history = deque(maxlen=50)
        # New: track a reputation "bonus" based on third-party judgments
        self.third_party_reputation = {}
        # New: track the number of times I've been observed cooperating/defecting
        self.my_observed_actions = {'cooperate': 0, 'defect': 0}

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent not in self.trust:
            self.trust[opponent] = self.default_trust
        trust_score = self.trust[opponent]
        opp_rep = self.reputation.get(opponent, 0.0)
        recent_ratio = self.recent_coop_ratio.get(opponent, 0.5)
        # Add third-party reputation component
        third_party = self.third_party_reputation.get(opponent, 0.0)
        combined = 0.3 * trust_score + 0.2 * (opp_rep + 1) / 2 + 0.3 * recent_ratio + 0.2 * third_party
        noise = random.uniform(-0.1, 0.1)
        prob_cooperate = combined + noise - self.aggression
        if self.self_reputation < 0:
            prob_cooperate += 0.1
        if self.meta_reputation < 0:
            prob_cooperate += 0.1
        prob_cooperate = max(0.0, min(1.0, prob_cooperate))
        decision = random.random() < prob_cooperate
        self.my_decision_history.append(1 if decision else 0)
        return decision

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.observation_count += 1
        actions = [donor_action, recipient_action]
        coop_count = sum(1 for a in actions if a == 'cooperate')
        self.population_coop_rate = self.population_coop_rate * 0.95 + (coop_count / 2) * 0.05

        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.history:
                self.history[agent_id] = deque(maxlen=50)
            self.history[agent_id].append(action)
            delta = 0.1 if action == 'cooperate' else -0.2
            self.reputation[agent_id] = self.reputation.get(agent_id, 0.0) * (1 - self.alpha) + delta * self.alpha
            self.reputation[agent_id] = max(-1.0, min(1.0, self.reputation[agent_id]))

            if agent_id not in self.recent_coop_ratio:
                self.recent_coop_ratio[agent_id] = 0.5
            self.recent_coop_ratio[agent_id] = self.recent_coop_ratio[agent_id] * 0.9 + (1 if action == 'cooperate' else 0) * 0.1

        # Update trust based on observed interactions
        if donor_id != self.agent_id:
            trust_delta = 0.1 if donor_action == 'cooperate' else -0.2
            self.trust[donor_id] = self.trust.get(donor_id, self.default_trust) + trust_delta
            self.trust[donor_id] = max(0.0, min(1.0, self.trust[donor_id]))
        if recipient_id != self.agent_id:
            trust_delta = 0.1 if recipient_action == 'cooperate' else -0.2
            self.trust[recipient_id] = self.trust.get(recipient_id, self.default_trust) + trust_delta
            self.trust[recipient_id] = max(0.0, min(1.0, self.trust[recipient_id]))

        # Track interactions with self
        if donor_id == self.agent_id:
            self.my_recent_actions.append(donor_action)
            self.my_observed_actions[donor_action] += 1
            if recipient_id != self.agent_id:
                if donor_action == 'cooperate' and recipient_action == 'defect':
                    self.trust[recipient_id] = self.trust.get(recipient_id, self.default_trust) - 0.2
                elif donor_action == 'defect' and recipient_action == 'cooperate':
                    self.trust[recipient_id] = self.trust.get(recipient_id, self.default_trust) + 0.15
                self.trust[recipient_id] = max(0.0, min(1.0, self.trust[recipient_id]))
        if recipient_id == self.agent_id:
            self.my_recent_actions.append(recipient_action)
            self.my_observed_actions[recipient_action] += 1
            if donor_id != self.agent_id:
                if recipient_action == 'cooperate' and donor_action == 'defect':
                    self.trust[donor_id] = self.trust.get(donor_id, self.default_trust) - 0.2
                elif recipient_action == 'defect' and donor_action == 'cooperate':
                    self.trust[donor_id] = self.trust.get(donor_id, self.default_trust) + 0.15
                self.trust[donor_id] = max(0.0, min(1.0, self.trust[donor_id]))

        # Update recent opponent cooperation stats
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id != self.agent_id:
                if agent_id not in self.recent_opponent_coop:
                    self.recent_opponent_coop[agent_id] = deque(maxlen=20)
                self.recent_opponent_coop[agent_id].append(1 if action == 'cooperate' else 0)

        # New: update third-party reputation. When I observe an interaction between two others,
        # I update my impression of the donor based on the recipient's reaction.
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            if recipient_action == 'cooperate':
                # Recipient cooperated, likely thinks well of donor
                self.third_party_reputation[donor_id] = self.third_party_reputation.get(donor_id, 0.0) + 0.1
            else:
                # Recipient defected, likely thinks poorly of donor
                self.third_party_reputation[donor_id] = self.third_party_reputation.get(donor_id, 0.0) - 0.1
            self.third_party_reputation[donor_id] = max(-1.0, min(1.0, self.third_party_reputation[donor_id]))

        # Update self-reputation based on my own actions
        if donor_id == self.agent_id:
            self.self_reputation = self.self_reputation * 0.9 + (0.1 if donor_action == 'cooperate' else -0.2) * 0.1
            if recipient_id != self.agent_id:
                if recipient_action == 'cooperate':
                    self.self_reputation += 0.05
                else:
                    self.self_reputation -= 0.05
                self.self_reputation = max(-1.0, min(1.0, self.self_reputation))
        if recipient_id == self.agent_id:
            if donor_action == 'cooperate':
                self.self_reputation += 0.05
            else:
                self.self_reputation -= 0.05
            self.self_reputation = max(-1.0, min(1.0, self.self_reputation))

        # Update meta-reputation based on how others treat me
        if donor_id == self.agent_id:
            if recipient_id != self.agent_id:
                if recipient_action == 'cooperate':
                    self.meta_reputation += 0.05
                else:
                    self.meta_reputation -= 0.05
                self.meta_reputation = max(-1.0, min(1.0, self.meta_reputation))
        if recipient_id == self.agent_id:
            if donor_action == 'cooperate':
                self.meta_reputation += 0.1
            else:
                self.meta_reputation -= 0.1
            self.meta_reputation = max(-1.0, min(1.0, self.meta_reputation))

        # Adapt aggression based on population cooperation
        if self.observation_count % 5 == 0:
            if self.population_coop_rate < 0.4:
                self.aggression = min(0.7, self.aggression + 0.1)
            elif self.population_coop_rate > 0.6:
                self.aggression = max(0.0, self.aggression - 0.1)

