                elif other_rep < 0.3:
                    delta = -0.03
                else:
                    delta = -0.05
            # Apply momentum: if previous delta had same sign, amplify
            if (self.rep_momentum[agent_id] > 0 and delta > 0) or (self.rep_momentum[agent_id] < 0 and delta < 0):
