            self.reciprocity[recipient_id].append(recipient_action)
            # NEW: Track when we see this opponent defect
            if recipient_action == 'defect':
                self.last_defection_seen[recipient_id] = self.round_num
        elif recipient_id == self.agent_id:
            if donor_id in self.opponent_history:
                self.opponent_history[donor_id].append(1 if donor_action == 'cooperate' else 0)
