class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Reputation memory: for each other agent, count of cooperative and total interactions observed
        self.rep = {}  # agent_id -> (coop_count, total_count)
        # Track own interaction outcomes
        self.own_coop = 0
        self.own_total = 0
        # Track how many times we've been defected against by each agent
        self.defections_against = {}
        # Forgiving memory: recent cooperation rate of each agent (sliding window)
        self.recent_coop = {}  # agent_id -> deque of last 10 actions (True/False)
        from collections import deque
        self.deque = deque

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True  # Default cooperate if no opponent info

        # Baseline: cooperate if opponent's reputation is good
        if opponent not in self.rep:
            # Unknown opponent, start with cooperation
            return True

        coop_count, total = self.rep[opponent]
        if total == 0:
            return True

        coop_rate = coop_count / total
        # If opponent cooperates more than 50% of the time, cooperate; else defect
        return coop_rate > 0.5

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Track reputation for both participants (if not self)
        for pid, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if pid == self.agent_id:
                continue
            if pid not in self.rep:
                self.rep[pid] = [0, 0]
            self.rep[pid][0] += 1 if action == 'cooperate' else 0
            self.rep[pid][1] += 1

            # Update recent cooperation window
            if pid not in self.recent_coop:
                self.recent_coop[pid] = self.deque(maxlen=10)
            self.recent_coop[pid].append(action == 'cooperate')

        # Self-judgment: update own stats and defection tracking
        if donor_id == self.agent_id:
            self.own_total += 1
            if donor_action == 'cooperate':
                self.own_coop += 1
            if recipient_action == 'defect':
                self.defections_against[recipient_id] = self.defections_against.get(recipient_id, 0) + 1
        elif recipient_id == self.agent_id:
            self.own_total += 1
            if recipient_action == 'cooperate':
                self.own_coop += 1
            if donor_action == 'defect':
                self.defections_against[donor_id] = self.defections_against.get(donor_id, 0) + 1

