from collections import deque


class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self._ctx_opponent_id = None
        self.reputation = {}
        self.coop_count = 0
        self.defect_count = 0
        self.total_actions = 0
        self.opponent_history = {}
        self.self_history = deque(maxlen=20)
        self.generation = 0
        self.round_num = 0
        self.last_opponent = None
        self.trust_factor = 1.0
        self.defection_penalty = 0.5
        self.initial_threshold = 0.5
        self.reciprocity = {}
        self.reputation_momentum = {}
        self.last_defection_seen = {}
        # New: track the last round we saw each agent cooperate to implement trust decay
        self.last_cooperation_seen = {}

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        self.last_opponent = opponent
        if opponent is None:
            return True

        opp_rep = self.reputation.get(opponent, 0.5)
        own_rep = self.reputation.get(self.agent_id, 0.5)

        # Use a higher base threshold, but reduce it based on own reputation more strongly
        threshold = 0.5 + 0.15 * (1 - own_rep)

        if opponent in self.opponent_history:
            hist = self.opponent_history[opponent]
            if len(hist) >= 5:
                coop_rate = sum(hist) / len(hist)
                threshold = 0.4 + 0.25 * (1 - coop_rate)

        # Reciprocity adjustment: be more forgiving if we cooperated last time, but also
        # be more cautious if we defected last time (self-referential reciprocity)
        if opponent in self.reciprocity:
            my_last_action = self.reciprocity[opponent][-1] if self.reciprocity[opponent] else None
            if my_last_action == 'cooperate':
                threshold -= 0.15
            elif my_last_action == 'defect':
                threshold += 0.15

        # NEW: Trust decay - if we haven't seen the opponent cooperate recently, increase threshold
        if opponent in self.last_cooperation_seen:
            rounds_since = self.round_num - self.last_cooperation_seen[opponent]
            if rounds_since > 0:
                # The more rounds since last cooperation, the more distrustful (higher threshold)
                distrust = min(0.25, rounds_since * 0.025)
                threshold += distrust
        else:
            # If we've never seen them cooperate, apply a small distrust penalty
            threshold += 0.05

        decision = opp_rep >= threshold

        # Keep the same small exploration noise as parent
        if random.random() < 0.03:
            decision = not decision

        return decision

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        donor_val = 1.0 if donor_action == 'cooperate' else 0.0
        recipient_val = 1.0 if recipient_action == 'cooperate' else 0.0

        # Update donor's reputation with momentum, but use a different smoothing factor
        if donor_id in self.reputation:
            self.reputation_momentum[donor_id] = 0.7 * self.reputation_momentum.get(donor_id, 0) + 0.3 * donor_val
            self.reputation[donor_id] = 0.85 * self.reputation[donor_id] + 0.15 * donor_val
        else:
            self.reputation[donor_id] = donor_val
            self.reputation_momentum[donor_id] = donor_val

        if recipient_id in self.reputation:
            self.reputation_momentum[recipient_id] = 0.7 * self.reputation_momentum.get(recipient_id, 0) + 0.3 * recipient_val
            self.reputation[recipient_id] = 0.85 * self.reputation[recipient_id] + 0.15 * recipient_val
        else:
            self.reputation[recipient_id] = recipient_val
            self.reputation_momentum[recipient_id] = recipient_val

        if donor_id == self.agent_id:
            self.total_actions += 1
            if donor_action == 'cooperate':
                self.coop_count += 1
            else:
                self.defect_count += 1
            self.self_history.append(1 if donor_action == 'cooperate' else 0)

        if recipient_id == self.agent_id:
            self.total_actions += 1
            if recipient_action == 'cooperate':
                self.coop_count += 1
            else:
                self.defect_count += 1
            self.self_history.append(1 if recipient_action == 'cooperate' else 0)

        if donor_id == self.agent_id:
            if recipient_id in self.opponent_history:
                self.opponent_history[recipient_id].append(1 if recipient_action == 'cooperate' else 0)
            else:
                self.opponent_history[recipient_id] = [1 if recipient_action == 'cooperate' else 0]
            if recipient_id not in self.reciprocity:
                self.reciprocity[recipient_id] = []
            self.reciprocity[recipient_id].append(recipient_action)
            # NEW: Track when we see this opponent cooperate (for trust decay)
            if recipient_action == 'cooperate':
                self.last_cooperation_seen[recipient_id] = self.round_num
        elif recipient_id == self.agent_id:
            if donor_id in self.opponent_history:
                self.opponent_history[donor_id].append(1 if donor_action == 'cooperate' else 0)
            else:
                self.opponent_history[donor_id] = [1 if donor_action == 'cooperate' else 0]
            if donor_id not in self.reciprocity:
                self.reciprocity[donor_id] = []
            self.reciprocity[donor_id].append(donor_action)
            # NEW: Track when we see this opponent cooperate (for trust decay)
            if donor_action == 'cooperate':
                self.last_cooperation_seen[donor_id] = self.round_num

import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Reputation as a value from -1 (bad) to 1 (good) for each agent
        self.reputation = {}
        # Track cooperation/defection history for each opponent
        self.history = {}
        # Track my own actions and outcomes
        self.my_actions = []
        # Track what I've observed about each agent's behavior
        self.observed_actions = {}
        # Track whether I've interacted with each agent before
        self.interacted = set()
        # Track recent defections by each agent to punish them
        self.recent_defections = {}
        # Track cooperation level of the entire population
        self.population_cooperation = []
        # Track my own payoff proxy (cooperation count minus defection count)
        self.my_coop_count = 0
        self.my_defect_count = 0
        # Track how many times each agent has defected vs cooperated overall
        self.overall_coop = {}
        self.overall_defect = {}
        # Track whether I am currently paired with someone (set by framework)
        self._ctx_opponent_id = None
        # New: Track the number of times each opponent has defected against me
        self.defections_against_me = {}

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True  # shouldn't happen, but be safe

        # If I have interacted with this opponent before, use history
        if opponent in self.interacted:
            # Check my history with this opponent
            my_coop_with_them = 0
            my_defect_with_them = 0
            for (d, r, da, ra) in self.history.get(opponent, []):
                if d == self.agent_id:
                    if da == 'cooperate':
                        my_coop_with_them += 1
                    else:
                        my_defect_with_them += 1
                elif r == self.agent_id:
                    if ra == 'cooperate':
                        my_coop_with_them += 1
                    else:
                        my_defect_with_them += 1
            # If they have defected against me more than cooperated, defect
            if my_defect_with_them > my_coop_with_them:
                return False

        # Check opponent's reputation
        rep = self.reputation.get(opponent, 0.0)
        # New: Add a forgiveness mechanism - if they have defected against me many times, be less forgiving
        defections_against = self.defections_against_me.get(opponent, 0)
        if rep < -0.2 or defections_against > 2:
            # Bad reputation or too many defections against me, defect
            return False
        elif rep > 0.3:
            # Good reputation, cooperate
            return True
        else:
            # Uncertain, use a deterministic pattern based on round number
            # We'll use a pseudo-random but deterministic decision based on
            # the opponent id and our own id and a time counter
            # Use sum of ids to create a deterministic pattern
            # For simplicity, default to cooperate if we have no strong signal
            # New: Add a risk-taking tendency - if I've been cooperating a lot, sometimes defect to test
            if self.my_coop_count > self.my_defect_count + 5:
                return random.random() > 0.7
            return True

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Record overall counts
        self.overall_coop[donor_id] = self.overall_coop.get(donor_id, 0) + (1 if donor_action == 'cooperate' else 0)
        self.overall_defect[donor_id] = self.overall_defect.get(donor_id, 0) + (1 if donor_action == 'defect' else 0)
        self.overall_coop[recipient_id] = self.overall_coop.get(recipient_id, 0) + (1 if recipient_action == 'cooperate' else 0)
        self.overall_defect[recipient_id] = self.overall_defect.get(recipient_id, 0) + (1 if recipient_action == 'defect' else 0)

        # Update reputation based on actions - New: Asymmetric update, defection is punished more strongly
        if donor_action == 'cooperate':
            self.reputation[donor_id] = self.reputation.get(donor_id, 0.0) + 0.1
        else:
            self.reputation[donor_id] = self.reputation.get(donor_id, 0.0) - 0.3
        if recipient_action == 'cooperate':
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.0) + 0.1
        else:
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.0) - 0.3

        # Clamp reputation to [-1, 1]
        for agent in [donor_id, recipient_id]:
            self.reputation[agent] = max(-1.0, min(1.0, self.reputation[agent]))

        # If I am part of the pair, record this interaction in my history
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # Determine who is the opponent
            opponent = recipient_id if donor_id == self.agent_id else donor_id
            self.interacted.add(opponent)
            # Record the joint action in my history with this opponent
            if opponent not in self.history:
                self.history[opponent] = []
            self.history[opponent].append((donor_id, recipient_id, donor_action, recipient_action))
            # Update my own action counts
            if donor_id == self.agent_id:
                if donor_action == 'cooperate':
                    self.my_coop_count += 1
                else:
                    self.my_defect_count += 1
            elif recipient_id == self.agent_id:
                if recipient_action == 'cooperate':
                    self.my_coop_count += 1
                else:
                    self.my_defect_count += 1
            # New: Track defections against me specifically
            if donor_id == self.agent_id and recipient_action == 'defect':
                self.defections_against_me[recipient_id] = self.defections_against_me.get(recipient_id, 0) + 1
            elif recipient_id == self.agent_id and donor_action == 'defect':
                self.defections_against_me[donor_id] = self.defections_against_me.get(donor_id, 0) + 1

        # Track recent defections for punishment
        if donor_action == 'defect':
            self.recent_defections[donor_id] = self.recent_defections.get(donor_id, 0) + 1
        if recipient_action == 'defect':
            self.recent_defections[recipient_id] = self.recent_defections.get(recipient_id, 0) + 1

        # Decay recent_defections over time to avoid holding grudges forever
        # We'll do a simple decay on each observe call
        for agent in list(self.recent_defections.keys()):
            self.recent_defections[agent] = self.recent_defections[agent] * 0.95
            if self.recent_defections[agent] < 0.1:
                del self.recent_defections[agent]

        # Update population cooperation statistic (optional)
        # Keep it simple: just track moving average
        # No need to do heavy computation here

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.cooperation_scores = {}
        self.reputation = {}
        self.interactions = {}
        self.generosity = 0.5
        self.trust = 0.5
        self.learning_rate = 0.1
        self.my_recent_actions = deque(maxlen=30)
        self.round_count = 0
        self.opponent_id = None
        self.altruism_penalty = 0.2
        self.reputation_weight = 0.6
        self.coop_weight = 0.4
        self.last_coop_with = {}
        self.forgiveness = 0.3
        self.last_defect_against_me = {}
        self.spite = 0.2
        self.risk_aversion = 0.15
        self.coop_variances = {}
        self.base_coop_rates = {}
        self.generosity_decay = 0.05
        self.exploit_threshold = 0.3
        self.last_action_against_me = {}
        self.exploration = 0.1
        self.reputation_horizon = 10
        self.reputation_trends = {}
        # Mutation: self-doubt factor - reduces trust when own recent cooperation is low
        self.self_doubt_factor = 0.15
        # Mutation: reciprocal generosity - track how much I've cooperated with each agent
        self.my_coop_frequency = {}
        # Mutation: trust decay - gradually reduce trust with opponents who haven't been seen recently
        self.trust_decay = 0.02
        self.last_seen = {}
        # Mutation: memory of observed third-party cooperation for reputation weighting
        self.third_party_coop_counts = {}
        for i in range(15):
            self.cooperation_scores[i] = deque([0.5], maxlen=30)
            self.reputation[i] = 0.5
            self.interactions[i] = deque(maxlen=30)
            self.last_coop_with[i] = None
            self.last_defect_against_me[i] = False
            self.coop_variances[i] = 0.0
            self.base_coop_rates[i] = 0.5
            self.last_action_against_me[i] = 'cooperate'
            self.reputation_trends[i] = deque(maxlen=10)
            self.my_coop_frequency[i] = deque(maxlen=30)
            self.last_seen[i] = 0
            self.third_party_coop_counts[i] = deque(maxlen=30)

    def decide(self) -> bool:
        self.round_count += 1
        self.opponent_id = getattr(self, '_ctx_opponent_id', None)
        if self.opponent_id is None:
            return random.random() < 0.5

        opp_scores = self.cooperation_scores.get(self.opponent_id, deque([0.5], maxlen=30))
        if len(opp_scores) > 0:
            decay = 0.9
            est_coop = 0.0
            weight_sum = 0.0
            for i, score in enumerate(opp_scores):
                weight = decay ** (len(opp_scores) - i - 1)
                est_coop += score * weight
                weight_sum += weight
            est_coop /= weight_sum
            if len(opp_scores) > 1:
                mean = sum(opp_scores) / len(opp_scores)
                var = sum((s - mean) ** 2 for s in opp_scores) / len(opp_scores)
                self.coop_variances[self.opponent_id] = var
        else:
            est_coop = 0.5

        rep = self.reputation.get(self.opponent_id, 0.5)
        trust_level = self.coop_weight * est_coop + self.reputation_weight * rep

        variance = self.coop_variances.get(self.opponent_id, 0.0)
        trust_level -= self.risk_aversion * variance

        if self.interactions.get(self.opponent_id):
            my_actions = [i[0] for i in self.interactions[self.opponent_id]]
            if my_actions and sum(my_actions) / len(my_actions) > 0.5 and rep < 0.3:
                trust_level -= self.altruism_penalty

        last_coop = self.last_coop_with.get(self.opponent_id)
        if last_coop is not None and not last_coop:
            trust_level += self.forgiveness * 0.1

        if self.last_defect_against_me.get(self.opponent_id, False):
            trust_level -= self.spite

        base_rate = self.base_coop_rates.get(self.opponent_id, 0.5)
        if base_rate < self.exploit_threshold:
            trust_level -= 0.1

        if self.last_defect_against_me.get(self.opponent_id, False):
            self.generosity = max(0, self.generosity - self.generosity_decay)

        # Mutation: self-doubt - if I've been cooperating less with this opponent, reduce trust
        my_freq = self.my_coop_frequency.get(self.opponent_id, deque([0.5], maxlen=30))
        if len(my_freq) > 0:
            my_coop_rate = sum(my_freq) / len(my_freq)
            if my_coop_rate < 0.3:
                trust_level -= self.self_doubt_factor * (1 - my_coop_rate)

        if self.my_recent_actions:
            recent_me = list(self.my_recent_actions)[-5:]
            my_coop_rate = sum(recent_me) / len(recent_me)
            if my_coop_rate > 0.8:
                trust_level -= 0.1
            elif my_coop_rate < 0.2:
                trust_level += 0.1

        trend = self.reputation_trends.get(self.opponent_id, deque())
        if len(trend) >= 2:
            recent_change = trend[-1] - trend[0]
            if recent_change > 0.05:
                trust_level += 0.05
            elif recent_change < -0.05:
                trust_level -= 0.05

        # Mutation: trust decay for opponents not seen recently
        rounds_since_last = self.round_count - self.last_seen.get(self.opponent_id, 0)
        if rounds_since_last > 5:
            trust_level -= self.trust_decay * (rounds_since_last - 5)

        # Mutation: incorporate third-party observed cooperation into trust
        third_party_scores = self.third_party_coop_counts.get(self.opponent_id, deque())
        if len(third_party_scores) > 0:
            third_party_coop_rate = sum(third_party_scores) / len(third_party_scores)
            trust_level += 0.1 * third_party_coop_rate

        noise = random.gauss(0, 0.05)
        trust_level = max(0, min(1, trust_level + noise))

        if random.random() < self.exploration:
            return random.random() < 0.5

        return random.random() < trust_level

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update last seen for both agents
        self.last_seen[donor_id] = self.round_count
        self.last_seen[recipient_id] = self.round_count

        # Track third-party observations (actions where I'm not involved)
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            self.third_party_coop_counts[donor_id].append(1 if donor_action == 'cooperate' else 0)
            self.third_party_coop_counts[recipient_id].append(1 if recipient_action == 'cooperate' else 0)

        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id in self.cooperation_scores:
                self.cooperation_scores[agent_id].append(1 if action == 'cooperate' else 0)
            else:
                self.cooperation_scores[agent_id] = deque([1 if action == 'cooperate' else 0], maxlen=30)
            scores = list(self.cooperation_scores[agent_id])
            if len(scores) > 1:
                mean = sum(scores) / len(scores)
                self.coop_variances[agent_id] = sum((s - mean) ** 2 for s in scores) / len(scores)
            old_rate = self.base_coop_rates.get(agent_id, 0.5)
            new_rate = old_rate * 0.9 + (1 if action == 'cooperate' else 0) * 0.1
            self.base_coop_rates[agent_id] = new_rate

        if donor_id in self.reputation_trends and recipient_id in self.reputation_trends:
            self.reputation_trends[donor_id].append(self.reputation.get(donor_id, 0.5))
            self.reputation_trends[recipient_id].append(self.reputation.get(recipient_id, 0.5))

        if donor_id == self.agent_id:
            self.interactions[recipient_id].append((1 if donor_action == 'cooperate' else 0,
                                                    1 if recipient_action == 'cooperate' else 0))
            self.my_recent_actions.append(1 if donor_action == 'cooperate' else 0)
            self.my_coop_frequency[recipient_id].append(1 if donor_action == 'cooperate' else 0)
            self.last_coop_with[recipient_id] = (donor_action == 'cooperate')
            self.last_defect_against_me[recipient_id] = (recipient_action == 'defect')
        elif recipient_id == self.agent_id:
            self.interactions[donor_id].append((1 if recipient_action == 'cooperate' else 0,
                                                1 if donor_action == 'cooperate' else 0))
            self.my_recent_actions.append(1 if recipient_action == 'cooperate' else 0)
            self.my_coop_frequency[donor_id].append(1 if recipient_action == 'cooperate' else 0)
            self.last_coop_with[donor_id] = (recipient_action == 'cooperate')
            self.last_defect_against_me[donor_id] = (donor_action == 'defect')
            self.last_action_against_me[donor_id] = donor_action

        for agent_id, action, other_id in [(donor_id, donor_action, recipient_id), (recipient_id, recipient_action, donor_id)]:
            current_rep = self.reputation.get(agent_id, 0.5)
            other_rep = self.reputation.get(other_id, 0.5)
            if action == 'cooperate':
                if other_rep < 0.3:
                    current_rep += 0.03
                elif other_rep > 0.7:
                    current_rep += 0.07
                else:
                    current_rep += 0.05
            else:
                if other_rep > 0.7:
                    current_rep -= 0.07
                elif other_rep < 0.3:
                    current_rep -= 0.03
                else:
                    current_rep -= 0.05
            self.reputation[agent_id] = max(0, min(1, current_rep))

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            my_coop = (donor_action if donor_id == self.agent_id else recipient_action) == 'cooperate'
            other_coop = (recipient_action if donor_id == self.agent_id else donor_action) == 'cooperate'
            if my_coop and other_coop:
                self.generosity = min(1, self.generosity + self.learning_rate)
            elif my_coop and not other_coop:
                self.generosity = max(0, self.generosity - 2 * self.learning_rate)
            elif not my_coop and other_coop:
                self.generosity = min(1, self.generosity + 0.5 * self.learning_rate)

import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Track reputation: dict of agent_id -> [cooperation_count, total_observed]
        self.reputation = {}
        # Track direct interactions: dict of opponent_id -> [cooperate_count, defect_count]
        self.interactions = {}
        # Track own recent actions for forgiveness
        self.own_history = []
        # Trust threshold based on reputation
        self.trust_threshold = 0.5
        # Generosity factor: how forgiving we are of defects
        self.generosity = 0.3
        # Memory of last few outcomes for adaptive behavior
        self.last_outcomes = []
        # Current opponent id set by framework
        self._ctx_opponent_id = None

    def _get_reputation_score(self, agent_id: int) -> float:
        """Return cooperation rate for an agent, default 0.5 if unknown."""
        if agent_id in self.reputation:
            coop, total = self.reputation[agent_id]
            if total == 0:
                return 0.5
            return coop / total
        return 0.5

    def _get_interaction_bias(self, opponent_id: int) -> float:
        """Return bias based on direct history: positive if they cooperated more."""
        if opponent_id not in self.interactions:
            return 0.0
        coop, defect = self.interactions[opponent_id]
        total = coop + defect
        if total == 0:
            return 0.0
        return (coop - defect) / total

    def decide(self) -> bool:
        # Default to cooperate if no opponent info
        opponent_id = self._ctx_opponent_id
        if opponent_id is None:
            return True

        # Get reputation and interaction bias
        rep_score = self._get_reputation_score(opponent_id)
        interaction_bias = self._get_interaction_bias(opponent_id)

        # Combine with weights: reputation more important for strangers, interaction for known
        if opponent_id in self.interactions:
            total_interactions = sum(self.interactions[opponent_id])
            if total_interactions > 5:
                # Trust direct experience more after several interactions
                combined = 0.3 * rep_score + 0.7 * (0.5 + interaction_bias/2)
            else:
                combined = 0.7 * rep_score + 0.3 * (0.5 + interaction_bias/2)
        else:
            combined = rep_score

        # Add slight randomness to avoid predictability, but keep mostly deterministic
        noise = random.uniform(-0.05, 0.05)
        effective = combined + noise

        # Decide to cooperate if effective trust is above threshold
        return effective >= self.trust_threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation for both agents involved
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id != self.agent_id:  # Don't update own reputation based on self
                if agent_id not in self.reputation:
                    self.reputation[agent_id] = [0, 0]
                coop, total = self.reputation[agent_id]
                if action == 'cooperate':
                    coop += 1
                total += 1
                self.reputation[agent_id] = [coop, total]

        # Update direct interaction history if this agent is involved
        if donor_id == self.agent_id:
            opponent = recipient_id
            my_action = donor_action
            opp_action = recipient_action
            self._record_interaction(opponent, my_action, opp_action)
        elif recipient_id == self.agent_id:
            opponent = donor_id
            my_action = recipient_action
            opp_action = donor_action
            self._record_interaction(opponent, my_action, opp_action)

        # Track own actions for adaptation
        if donor_id == self.agent_id:
            self.own_history.append(donor_action)
            if len(self.own_history) > 20:
                self.own_history.pop(0)

        # Record outcomes for adaptive threshold adjustment
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                my_action = donor_action
                opp_action = recipient_action
            else:
                my_action = recipient_action
                opp_action = donor_action
            # Outcome: 1 if both cooperate, 0.5 if one cooperates, 0 if both defect
            if my_action == 'cooperate' and opp_action == 'cooperate':
                outcome = 1.0
            elif my_action == 'defect' and opp_action == 'defect':
                outcome = 0.0
            else:
                outcome = 0.5
            self.last_outcomes.append(outcome)
            if len(self.last_outcomes) > 20:
                self.last_outcomes.pop(0)
            # Adapt trust threshold slightly based on recent outcomes
            if len(self.last_outcomes) >= 5:
                avg_outcome = sum(self.last_outcomes) / len(self.last_outcomes)
                # If we're being exploited (low outcomes), raise threshold (more cautious)
                # If we're doing well, lower threshold slightly (more trusting)
                if avg_outcome < 0.4:
                    self.trust_threshold = min(0.8, self.trust_threshold + 0.01)
                elif avg_outcome > 0.7:
                    self.trust_threshold = max(0.2, self.trust_threshold - 0.01)
                # Reset after adaptation to avoid overshooting
                if len(self.last_outcomes) % 10 == 0:
                    self.trust_threshold = 0.5  # periodic reset to base

    def _record_interaction(self, opponent: int, my_action: str, opp_action: str) -> None:
        """Record a direct interaction outcome."""
        if opponent not in self.interactions:
            self.interactions[opponent] = [0, 0]
        coop, defect = self.interactions[opponent]
        # Count opponent's cooperation/defection
        if opp_action == 'cooperate':
            coop += 1
        else:
            defect += 1
        self.interactions[opponent] = [coop, defect]

