import math
import random
from collections import deque


class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.cooperation_scores = {}
        self.reputation = {}
        self.interactions = {}
        self.generosity = 0.5
        self.trust = 0.5
        self.learning_rate = 0.1
        self.my_recent_actions = deque(maxlen=30)
        self.round_count = 0
        self.opponent_id = None
        self.altruism_penalty = 0.2
        self.reputation_weight = 0.6
        self.coop_weight = 0.4
        self.last_coop_with = {}
        self.forgiveness = 0.3
        self.betrayal_memory = deque(maxlen=10)
        self.rep_momentum = {}
        self.interaction_frequency = {}
        self.recent_opponent_coop = {}
        self.rep_change_cap = 0.02
        self.rep_volatility = {}
        self.base_learning_rate = 0.1
        self.volatility_threshold = 0.05
        self.rep_trend = {}
        # New: Track the number of times we've cooperated with each agent
        self.coop_count_with = {}
        # New: Overconfidence parameter - makes agent more aggressive when winning
        self.overconfidence = 0.15
        # New: Memory of opponent's last actions for dynamic reciprocity
        self.opponent_last_actions = {}
        # New: Dynamic forgiveness based on opponent's recent cooperation
        self.dynamic_forgiveness = 0.5
        # New: Exploration rate for occasional random decisions
        self.exploration_rate = 0.1
        # New: Inertia parameter - how much past trust is carried forward
        self.inertia = 0.9
        self.trust_history = {}
        # New: Regret tracking - how often we were betrayed after cooperating
        self.regret_count = {}
        # New: Tit-for-tat memory - remember exact responses to our actions
        self.tit_for_tat = {}
        for i in range(15):
            self.cooperation_scores[i] = deque([0.5], maxlen=30)
            self.reputation[i] = 0.5
            self.interactions[i] = deque(maxlen=30)
            self.last_coop_with[i] = None
            self.rep_momentum[i] = 0.0
            self.interaction_frequency[i] = 0
            self.recent_opponent_coop[i] = deque(maxlen=5)
            self.rep_volatility[i] = deque(maxlen=10)
            self.rep_trend[i] = 0.0
            self.coop_count_with[i] = 0
            self.opponent_last_actions[i] = deque(maxlen=5)
            self.trust_history[i] = 0.5
            self.regret_count[i] = 0
            self.tit_for_tat[i] = deque(maxlen=5)

    def decide(self) -> bool:
        self.round_count += 1
        self.opponent_id = getattr(self, '_ctx_opponent_id', None)
        if self.opponent_id is None:
            return random.random() < 0.5

        # Exploration: occasionally make a random decision
        if random.random() < self.exploration_rate:
            return random.random() < 0.5

        opp_scores = self.cooperation_scores.get(self.opponent_id, deque([0.5], maxlen=30))
        if len(opp_scores) > 0:
            decay = 0.9
            est_coop = 0.0
            weight_sum = 0.0
            for i, score in enumerate(opp_scores):
                weight = decay ** (len(opp_scores) - i - 1)
                est_coop += score * weight
                weight_sum += weight
            est_coop /= weight_sum
        else:
            est_coop = 0.5

        rep = self.reputation.get(self.opponent_id, 0.5)
        trust_level = self.coop_weight * est_coop + self.reputation_weight * rep

        if self.interactions.get(self.opponent_id):
            my_actions = [i[0] for i in self.interactions[self.opponent_id]]
            if my_actions and sum(my_actions) / len(my_actions) > 0.5 and rep < 0.3:
                trust_level -= self.altruism_penalty

        last_coop = self.last_coop_with.get(self.opponent_id)
        if last_coop is not None and not last_coop:
            # Dynamic forgiveness: if opponent has been cooperative recently, forgive more
            recent_opp_actions = self.opponent_last_actions.get(self.opponent_id, deque(maxlen=5))
            if len(recent_opp_actions) > 0:
                coop_rate = sum(recent_opp_actions) / len(recent_opp_actions)
                forgiveness_boost = self.dynamic_forgiveness * coop_rate
            else:
                forgiveness_boost = self.forgiveness * 0.1
            trust_level += forgiveness_boost

        if self.my_recent_actions:
            recent_me = list(self.my_recent_actions)[-5:]
            my_coop_rate = sum(recent_me) / len(recent_me)
            if my_coop_rate > 0.8:
                trust_level -= 0.1
            elif my_coop_rate < 0.2:
                trust_level += 0.1

        if len(self.betrayal_memory) > 0 and self.opponent_id in self.betrayal_memory:
            recent_betrayals = sum(1 for b in self.betrayal_memory if b == self.opponent_id)
            if recent_betrayals >= 3:
                trust_level -= 0.15

        freq = self.interaction_frequency.get(self.opponent_id, 0)
        if freq > 5:
            if self.generosity > 0.7:
                trust_level += 0.05 * self.generosity
            elif self.generosity < 0.3:
                trust_level -= 0.05 * (1 - self.generosity)

        recent_opp = self.recent_opponent_coop.get(self.opponent_id, deque(maxlen=5))
        if len(recent_opp) > 0:
            opp_coop_rate = sum(recent_opp) / len(recent_opp)
            if opp_coop_rate > 0.7:
                trust_level += 0.1 * opp_coop_rate
            elif opp_coop_rate < 0.3:
                trust_level -= 0.1 * (1 - opp_coop_rate)

        trend = self.rep_trend.get(self.opponent_id, 0.0)
        trust_level += 0.2 * trend

        vol = self.rep_volatility.get(self.opponent_id, deque(maxlen=10))
        if len(vol) > 0:
            avg_vol = sum(vol) / len(vol)
            if avg_vol > self.volatility_threshold:
                trust_level -= 0.1 * avg_vol

        # New: Overconfidence based on our history with this opponent
        coop_count = self.coop_count_with.get(self.opponent_id, 0)
        if coop_count > 5:
            # If we've cooperated a lot, we get overconfident and cooperate more
            trust_level += self.overconfidence * min(1, coop_count / 10)
        elif coop_count == 0 and freq > 0:
            # If we've never cooperated but interacted, we are cautious
            trust_level -= 0.1

        # New: Dynamic reciprocity - adjust trust based on opponent's last action
        last_actions = self.opponent_last_actions.get(self.opponent_id, deque(maxlen=5))
        if len(last_actions) > 0:
            last_action = last_actions[-1]
            if last_action == 1:
                # Opponent cooperated last time, increase trust
                trust_level += 0.05
            else:
                # Opponent defected last time, decrease trust
                trust_level -= 0.1

        # NEW: Inertia - blend current trust with past trust for this opponent
        past_trust = self.trust_history.get(self.opponent_id, 0.5)
        trust_level = self.inertia * past_trust + (1 - self.inertia) * trust_level

        # NEW: Regret avoidance - if we've been betrayed often after cooperating, reduce trust
        regret = self.regret_count.get(self.opponent_id, 0)
        if regret > 2:
            trust_level -= 0.1 * min(1, regret / 5)

        # NEW: Tit-for-tat - if opponent tended to defect after we cooperated, reduce trust
        tft = self.tit_for_tat.get(self.opponent_id, deque(maxlen=5))
        if len(tft) > 0:
            coop_then = [x for x in tft if x[0] == 1]
            if coop_then:
                coop_response_rate = sum(x[1] for x in coop_then) / len(coop_then)
                if coop_response_rate < 0.3:
                    trust_level -= 0.15
                elif coop_response_rate > 0.7:
                    trust_level += 0.05

        noise = random.gauss(0, 0.05)
        trust_level = max(0, min(1, trust_level + noise))

        return random.random() < trust_level

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id in self.cooperation_scores:
            self.cooperation_scores[donor_id].append(1 if donor_action == 'cooperate' else 0)
        else:
            self.cooperation_scores[donor_id] = deque([1 if donor_action == 'cooperate' else 0], maxlen=30)

        if recipient_id in self.cooperation_scores:
            self.cooperation_scores[recipient_id].append(1 if recipient_action == 'cooperate' else 0)
        else:
            self.cooperation_scores[recipient_id] = deque([1 if recipient_action == 'cooperate' else 0], maxlen=30)

        self.interaction_frequency[donor_id] = self.interaction_frequency.get(donor_id, 0) + 1
        self.interaction_frequency[recipient_id] = self.interaction_frequency.get(recipient_id, 0) + 1

        # New: Track opponent's last actions for dynamic reciprocity
        self.opponent_last_actions[donor_id].append(1 if donor_action == 'cooperate' else 0)
        self.opponent_last_actions[recipient_id].append(1 if recipient_action == 'cooperate' else 0)

        if donor_id == self.agent_id:
            self.interactions[recipient_id].append((1 if donor_action == 'cooperate' else 0,
                                                    1 if recipient_action == 'cooperate' else 0))
            self.my_recent_actions.append(1 if donor_action == 'cooperate' else 0)
            self.last_coop_with[recipient_id] = (donor_action == 'cooperate')
            # New: Update coop count
            if donor_action == 'cooperate':
                self.coop_count_with[recipient_id] = self.coop_count_with.get(recipient_id, 0) + 1
            # NEW: Track tit-for-tat - my action, opponent's response
            self.tit_for_tat[recipient_id].append((1 if donor_action == 'cooperate' else 0,
                                                   1 if recipient_action == 'cooperate' else 0))
            # NEW: If I cooperated and opponent defected, increase regret
            if donor_action == 'cooperate' and recipient_action == 'defect':
                self.regret_count[recipient_id] = self.regret_count.get(recipient_id, 0) + 1
        elif recipient_id == self.agent_id:
            self.interactions[donor_id].append((1 if recipient_action == 'cooperate' else 0,
                                                1 if donor_action == 'cooperate' else 0))
            self.my_recent_actions.append(1 if recipient_action == 'cooperate' else 0)
            self.last_coop_with[donor_id] = (recipient_action == 'cooperate')
            # New: Update coop count
            if recipient_action == 'cooperate':
                self.coop_count_with[donor_id] = self.coop_count_with.get(donor_id, 0) + 1
            # NEW: Track tit-for-tat - my action, opponent's response (inverse roles)
            self.tit_for_tat[donor_id].append((1 if recipient_action == 'cooperate' else 0,
                                               1 if donor_action == 'cooperate' else 0))
            # NEW: If I cooperated and opponent defected, increase regret
            if recipient_action == 'cooperate' and donor_action == 'defect':
                self.regret_count[donor_id] = self.regret_count.get(donor_id, 0) + 1

        self.recent_opponent_coop[donor_id].append(1 if donor_action == 'cooperate' else 0)
        self.recent_opponent_coop[recipient_id].append(1 if recipient_action == 'cooperate' else 0)

        for agent_id, action, other_id in [(donor_id, donor_action, recipient_id), (recipient_id, recipient_action, donor_id)]:
            current_rep = self.reputation.get(agent_id, 0.5)
            other_rep = self.reputation.get(other_id, 0.5)
            if action == 'cooperate':
                if other_rep < 0.3:
                    raw_delta = 0.03
                elif other_rep > 0.7:
                    raw_delta = 0.07
                else:
                    raw_delta = 0.05
            else:
                if other_rep > 0.7:
                    raw_delta = -0.07
                elif other_rep < 0.3:
                    raw_delta = -0.03
                else:
                    raw_delta = -0.05
            delta = max(-self.rep_change_cap, min(self.rep_change_cap, raw_delta))
            momentum = self.rep_momentum.get(agent_id, 0.0)
            momentum = 0.7 * momentum + 0.3 * delta
            self.rep_momentum[agent_id] = momentum
            current_rep += momentum
            self.reputation[agent_id] = max(0, min(1, current_rep))

            vol_deque = self.rep_volatility.get(agent_id, deque(maxlen=10))
            vol_deque.append(abs(delta))
            self.rep_volatility[agent_id] = vol_deque
            self.rep_trend[agent_id] = 0.8 * self.rep_trend.get(agent_id, 0.0) + 0.2 * delta

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            my_coop = (donor_action if donor_id == self.agent_id else recipient_action) == 'cooperate'
            other_coop = (recipient_action if donor_id == self.agent_id else donor_action) == 'cooperate'
            if my_coop and other_coop:
                self.generosity = min(1, self.generosity + self.learning_rate)
            elif my_coop and not other_coop:
                self.generosity = max(0, self.generosity - 2 * self.learning_rate)
                if donor_id == self.agent_id:
                    self.betrayal_memory.append(recipient_id)
                else:
                    self.betrayal_memory.append(donor_id)
            elif not my_coop and other_coop:
                self.generosity = min(1, self.generosity + 0.5 * self.learning_rate)

        # NEW: Update trust history for self-involved interactions
