        self.last_opponent = opponent
        if opponent is None:
            return True

        # Use both reputation and reliability: reliability is a more stable measure
        opp_rep = self.reputation.get(opponent, 0.5)
        opp_rel = self.reliability.get(opponent, 0.5)
        # Combine: weighted average, reliability has slightly more weight for stable behavior
        combined = 0.4 * opp_rep + 0.6 * opp_rel

        own_rep = self.reputation.get(self.agent_id, 0.5)
        threshold = 0.4 + 0.1 * (1 - own_rep)

        if opponent in self.opponent_history:
            hist = self.opponent_history[opponent]
            if len(hist) >= 5:
                coop_rate = sum(hist) / len(hist)
                threshold = 0.3 + 0.2 * (1 - coop_rate)

        # Reciprocity adjustment: if we cooperated last time with opponent, be more likely to cooperate
        if opponent in self.reciprocity:
            last_opponent_action = self.reciprocity[opponent][-1] if self.reciprocity[opponent] else None
            if last_opponent_action == 'cooperate':
                threshold -= 0.1
            elif last_opponent_action == 'defect':
                threshold += 0.1

        # NEW: Forgive past defections that are old (decay penalty)
        if opponent in self.last_defection_seen:
            rounds_since = self.round_num - self.last_defection_seen[opponent]
            if rounds_since > 0:
                forgiveness = min(0.2, rounds_since * 0.02)
                threshold -= forgiveness

        # NEW: Adaptive threshold based on our own recent cooperation rate
        if len(self.self_history) > 0:
            own_coop_rate = sum(self.self_history) / len(self.self_history)
            # If we've been cooperating a lot, be more cautious (raise threshold)
            # If we've been defecting a lot, be more generous (lower threshold)
            threshold += 0.15 * (own_coop_rate - 0.5)

        decision = combined >= threshold

        # Slightly lower exploration noise to make decisions more stable
        if random.random() < 0.03:
            decision = not decision

        return decision

