                        recent = hist[-10:]
                        coop_count = sum(recent)
                        coop_ratio = coop_count / len(recent)
                        # Trust increases if they cooperate often, decreases if defect often
                        self.trust[agent_id] = 0.3 * self.trust.get(agent_id, 0.5) + 0.7 * coop_ratio
        except Exception:
            pass

