                if other_rep > 0.7:
                    current_rep -= 0.07
                elif other_rep < 0.3:
                    current_rep -= 0.03
                else:
                    current_rep -= 0.05
            current_rep = max(0, min(1, current_rep))
            self.reputation[agent_id] = current_rep
