import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.own_coop_count = 0
        self.own_defect_count = 0
        self.round = 0
        self.generation = 0
        self.opponent_id = None
        self.opponent_history = {}
        self.reciprocity = {}
        self.trust = {}
        self._ctx_opponent_id = None
        for i in range(15):
            self.reputation[i] = 0.5
            self.reciprocity[i] = 0.5
            self.trust[i] = 0.5
            self.opponent_history[i] = []

    def decide(self) -> bool:
        self.round += 1
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True
        self.opponent_id = opponent

        # Reputation-based trust
        rep = self.reputation.get(opponent, 0.5)
        trust = self.trust.get(opponent, 0.5)
        reciprocity = self.reciprocity.get(opponent, 0.5)

        # Own recent behavior: if we've defected a lot, be more cooperative to repair
        total_own = self.own_coop_count + self.own_defect_count
        own_coop_ratio = self.own_coop_count / max(1, total_own)

        # Start with trust as main factor
        coop_prob = trust * 0.7 + rep * 0.2 + own_coop_ratio * 0.1

        # If opponent has a history with us, adjust based on reciprocity
        if self.opponent_history[opponent]:
            last_actions = self.opponent_history[opponent][-5:]
            coop_freq = sum(1 for a in last_actions if a) / len(last_actions)
            coop_prob = coop_prob * 0.8 + coop_freq * 0.2

        # Add slight randomness to avoid being too predictable
        noise = random.uniform(-0.05, 0.05)
        coop_prob = max(0.0, min(1.0, coop_prob + noise))

        # Deterministic threshold for reproducibility
        return random.random() < coop_prob

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        try:
            # Update own action counts
            if donor_id == self.agent_id:
                if donor_action == 'cooperate':
                    self.own_coop_count += 1
                else:
                    self.own_defect_count += 1
            if recipient_id == self.agent_id:
                if recipient_action == 'cooperate':
                    self.own_coop_count += 1
                else:
                    self.own_defect_count += 1

            # Update reputation of observed agents
            if donor_id != self.agent_id:
                if donor_action == 'cooperate':
                    self.reputation[donor_id] = min(1.0, self.reputation.get(donor_id, 0.5) + 0.02)
                else:
                    self.reputation[donor_id] = max(0.0, self.reputation.get(donor_id, 0.5) - 0.02)
            if recipient_id != self.agent_id:
                if recipient_action == 'cooperate':
                    self.reputation[recipient_id] = min(1.0, self.reputation.get(recipient_id, 0.5) + 0.02)
                else:
                    self.reputation[recipient_id] = max(0.0, self.reputation.get(recipient_id, 0.5) - 0.02)

            # Update reciprocity/trust based on interactions with us
            if donor_id == self.agent_id:
                # We cooperated/defected with recipient
                if donor_action == 'cooperate':
                    # We cooperated, see if they cooperated back
                    if recipient_action == 'cooperate':
                        self.reciprocity[recipient_id] = min(1.0, self.reciprocity.get(recipient_id, 0.5) + 0.1)
                    else:
                        self.reciprocity[recipient_id] = max(0.0, self.reciprocity.get(recipient_id, 0.5) - 0.1)
            if recipient_id == self.agent_id:
                # They cooperated/defected with us
                if recipient_action == 'cooperate':
                    self.reciprocity[donor_id] = min(1.0, self.reciprocity.get(donor_id, 0.5) + 0.1)
                else:
                    self.reciprocity[donor_id] = max(0.0, self.reciprocity.get(donor_id, 0.5) - 0.1)

            # Track opponent history for actual interactions with us
            if donor_id == self.agent_id:
                self.opponent_history[recipient_id].append(recipient_action == 'cooperate')
            if recipient_id == self.agent_id:
                self.opponent_history[donor_id].append(donor_action == 'cooperate')

            # Update trust based on consistency of behavior
            for agent_id in [donor_id, recipient_id]:
                if agent_id != self.agent_id:
                    # Count recent behaviors
                    hist = self.opponent_history.get(agent_id, [])
                    if len(hist) > 0:
                        recent = hist[-10:]
                        coop_count = sum(recent)
                        coop_ratio = coop_count / len(recent)
                        # Trust increases if they cooperate often, decreases if defect often
                        self.trust[agent_id] = 0.3 * self.trust.get(agent_id, 0.5) + 0.7 * coop_ratio
        except Exception:
            pass

