        self.exploit_threshold = 0.3
        self.last_action_against_me = {}
        self.exploration = 0.1
        self.reputation_horizon = 10
        self.reputation_trends = {}
        # Mutations: Add a "grudge" mechanism - prolonged defection leads to stronger punishment
        self.grudge_factor = 0.5
        self.defect_streak = {}
        # Mutations: Add a "reputation confidence" - based on number of observations, modulates reputation influence
        self.reputation_confidence = {}
        self.confidence_threshold = 5
        # Mutations: Add a "reciprocity bonus" - if I cooperated last time and they cooperated, boost trust
        self.reciprocity_bonus = 0.1
        # Mutations: Add a "betrayal penalty" - if they defected after I cooperated, extra penalty
        self.betrayal_penalty = 0.2
        # Mutations: Add a "generosity momentum" - track recent generosity changes
        self.generosity_momentum = deque(maxlen=10)
        # Mutations: Add a "cooperation drift" - slowly adjust base cooperation rate based on outcomes
        self.cooperation_drift = 0.02
        # Mutations: Add a "risk tolerance" - dynamic based on recent variance
        self.risk_tolerance = 0.15
        # Mutations: Add a "trust ceiling" - maximum trust level
        self.trust_ceiling = 0.95
        # Mutations: Add a "trust floor" - minimum trust level
        self.trust_floor = 0.05
        # Mutations: Add a "recent_payoff" - track last payoff for adaptation
        self.recent_payoff = deque(maxlen=5)
        # Mutations: Add a "coop_history" - longer history for trend detection
        self.coop_history = {}
        for i in range(15):
            self.cooperation_scores[i] = deque([0.5], maxlen=30)
            self.reputation[i] = 0.5
            self.interactions[i] = deque(maxlen=30)
            self.last_coop_with[i] = None
            self.last_defect_against_me[i] = False
            self.coop_variances[i] = 0.0
            self.base_coop_rates[i] = 0.5
            self.last_action_against_me[i] = 'cooperate'
            self.reputation_trends[i] = deque(maxlen=10)
            self.defect_streak[i] = 0
            self.reputation_confidence[i] = 0
            self.coop_history[i] = deque(maxlen=30)

    def decide(self) -> bool:
        self.round_count += 1
        self.opponent_id = getattr(self, '_ctx_opponent_id', None)
        if self.opponent_id is None:
            return random.random() < 0.5

        opp_scores = self.cooperation_scores.get(self.opponent_id, deque([0.5], maxlen=30))
        if len(opp_scores) > 0:
            # Use exponential decay with memory_decay (same as parent)
            decay = 0.95
            est_coop = 0.0
            weight_sum = 0.0
            for i, score in enumerate(opp_scores):
                weight = decay ** (len(opp_scores) - i - 1)
                est_coop += score * weight
                weight_sum += weight
            est_coop /= weight_sum
            if len(opp_scores) > 1:
                mean = sum(opp_scores) / len(opp_scores)
                var = sum((s - mean) ** 2 for s in opp_scores) / len(opp_scores)
                self.coop_variances[self.opponent_id] = var
        else:
            est_coop = 0.5

        rep = self.reputation.get(self.opponent_id, 0.5)
        # Mutation: Reputation confidence - if few observations, reduce reputation influence
        confidence = self.reputation_confidence.get(self.opponent_id, 0)
        rep_weight = self.reputation_weight * min(1, confidence / self.confidence_threshold)
        trust_level = self.coop_weight * est_coop + rep_weight * rep

        variance = self.coop_variances.get(self.opponent_id, 0.0)
        trust_level -= self.risk_tolerance * variance

        # Mutation: Grudge mechanism - if opponent has a long defect streak, penalize more
        streak = self.defect_streak.get(self.opponent_id, 0)
        if streak > 2:
            trust_level -= self.grudge_factor * (streak - 2)

        # Mutation: Reciprocity bonus - if last interaction was mutual cooperation, boost
        last_interaction = self.interactions.get(self.opponent_id)
        if last_interaction:
            last_my, last_opp = last_interaction[-1]
            if last_my == 1 and last_opp == 1:
                trust_level += self.reciprocity_bonus

        # Mutation: Betrayal penalty - if I cooperated and they defected last time
        if last_interaction:
            last_my, last_opp = last_interaction[-1]
            if last_my == 1 and last_opp == 0:
                trust_level -= self.betrayal_penalty

        if self.last_defect_against_me.get(self.opponent_id, False):
            trust_level -= self.spite

        base_rate = self.base_coop_rates.get(self.opponent_id, 0.5)
        if base_rate < self.exploit_threshold:
            trust_level -= 0.1

        # Mutation: Generosity momentum - if my recent generosity has been increasing, be slightly more trusting
        if len(self.generosity_momentum) > 0:
            avg_gen = sum(self.generosity_momentum) / len(self.generosity_momentum)
            if avg_gen > 0.6:
                trust_level += 0.05

        # Mutation: Risk tolerance adaptation - if recent variance is low, increase risk tolerance
        if len(opp_scores) > 3:
            var = self.coop_variances.get(self.opponent_id, 0.0)
            if var < 0.05:
                self.risk_tolerance = min(0.3, self.risk_tolerance + 0.01)
            elif var > 0.2:
                self.risk_tolerance = max(0.05, self.risk_tolerance - 0.01)

        # Mutation: Trust ceiling and floor
        trust_level = max(self.trust_floor, min(self.trust_ceiling, trust_level))

        noise = random.gauss(0, 0.05)
        trust_level = max(0, min(1, trust_level + noise))

        if random.random() < self.exploration:
            return random.random() < 0.5

        # Mutation: Use a dynamic threshold - lower threshold if recent outcomes have been good
        threshold = 0.6
        if len(self.recent_payoff) > 0:
