        self.population_coop_rate = self.population_coop_rate * 0.98 + (coop_count / 2) * 0.02

        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.history:
                self.history[agent_id] = deque(maxlen=50)
            self.history[agent_id].append(action)
            delta = 0.08 if action == 'cooperate' else -0.12
            self.reputation[agent_id] = self.reputation.get(agent_id, 0.0) * (1 - self.alpha) + delta * self.alpha
            self.reputation[agent_id] = max(-1.0, min(1.0, self.reputation[agent_id]))
            if agent_id not in self.recent_coop_ratio:
                self.recent_coop_ratio[agent_id] = 0.5
            self.recent_coop_ratio[agent_id] = self.recent_coop_ratio[agent_id] * 0.7 + (1 if action == 'cooperate' else 0) * 0.3
            if action == 'cooperate':
                self.cooperation_streak[agent_id] = self.cooperation_streak.get(agent_id, 0) + 1
                self.defection_streak[agent_id] = 0
            else:
                self.defection_streak[agent_id] = self.defection_streak.get(agent_id, 0) + 1
                self.cooperation_streak[agent_id] = 0
            if agent_id in self.history and len(self.history[agent_id]) > 1:
                if self.history[agent_id][-1] != self.history[agent_id][-2]:
                    self.mixed_streak[agent_id] = self.mixed_streak.get(agent_id, 0) + 1
                else:
                    self.mixed_streak[agent_id] = self.mixed_streak.get(agent_id, 0) * 0.9

        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if action == 'defect':
                self.grudge[agent_id] = self.grudge.get(agent_id, 0.0) + 0.3
                self.grudge[agent_id] = min(1.0, self.grudge[agent_id])
                self.positive_bias[agent_id] = self.positive_bias.get(agent_id, 0.0) * 0.5
            else:
                self.positive_bias[agent_id] = self.positive_bias.get(agent_id, 0.0) + 0.1
                self.positive_bias[agent_id] = min(1.0, self.positive_bias[agent_id])
                self.grudge[agent_id] = self.grudge.get(agent_id, 0.0) * self.grudge_decay
            if agent_id not in self.grudge:
                self.grudge[agent_id] = 0.0
            if agent_id not in self.positive_bias:
                self.positive_bias[agent_id] = 0.0

        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if action == 'defect':
                self.defection_memory[agent_id] = self.defection_memory.get(agent_id, 0) + 1
            else:
                self.defection_memory[agent_id] = self.defection_memory.get(agent_id, 0) * 0.95

        if donor_id != self.agent_id:
            extra_penalty = min(0.2, self.defection_memory.get(donor_id, 0) * 0.02)
            trust_delta = self.cooperation_bonus if donor_action == 'cooperate' else -self.defection_penalty - extra_penalty
            self.trust[donor_id] = self.trust.get(donor_id, self.default_trust) + trust_delta
            self.trust[donor_id] = max(0.0, min(1.0, self.trust[donor_id]))
        if recipient_id != self.agent_id:
            extra_penalty = min(0.2, self.defection_memory.get(recipient_id, 0) * 0.02)
            trust_delta = self.cooperation_bonus if recipient_action == 'cooperate' else -self.defection_penalty - extra_penalty
            self.trust[recipient_id] = self.trust.get(recipient_id, self.default_trust) + trust_delta
            self.trust[recipient_id] = max(0.0, min(1.0, self.trust[recipient_id]))

        if donor_id == self.agent_id:
            self.my_recent_actions.append(donor_action)
            if recipient_id != self.agent_id:
                if donor_action == 'cooperate' and recipient_action == 'defect':
                    self.trust[recipient_id] = self.trust.get(recipient_id, self.default_trust) - 0.15
                elif donor_action == 'defect' and recipient_action == 'cooperate':
                    self.trust[recipient_id] = self.trust.get(recipient_id, self.default_trust) + 0.1
                self.trust[recipient_id] = max(0.0, min(1.0, self.trust[recipient_id]))
        if recipient_id == self.agent_id:
            self.my_recent_actions.append(recipient_action)
            if donor_id != self.agent_id:
                if recipient_action == 'cooperate' and donor_action == 'defect':
                    self.trust[donor_id] = self.trust.get(donor_id, self.default_trust) - 0.15
                elif recipient_action == 'defect' and donor_action == 'cooperate':
                    self.trust[donor_id] = self.trust.get(donor_id, self.default_trust) + 0.1
                self.trust[donor_id] = max(0.0, min(1.0, self.trust[donor_id]))

        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id != self.agent_id:
                if agent_id not in self.recent_opponent_coop:
                    self.recent_opponent_coop[agent_id] = deque(maxlen=20)
                self.recent_opponent_coop[agent_id].append(1 if action == 'cooperate' else 0)

        # NEW: Update outcome score based on the joint action
        # For the donor, if the recipient cooperated, that's positive outcome; if defected, negative
        # For the recipient, if the donor cooperated, positive; if defected, negative
        for agent_id, action, other_action in [(donor_id, donor_action, recipient_action), (recipient_id, recipient_action, donor_action)]:
            if agent_id == self.agent_id:
                continue  # Don't adjust self-outcome based on observer perspective
            # Compute outcome: +1 if both cooperate, -1 if both defect, else 0.5 for unilateral cooperation
            if action == 'cooperate' and other_action == 'cooperate':
                outcome = 1.0
            elif action == 'defect' and other_action == 'defect':
                outcome = -1.0
            elif action == 'cooperate' and other_action == 'defect':
                outcome = -0.5  # I cooperated but was exploited
            else:  # I defected and other cooperated
                outcome = 0.5  # I got away with defecting
            # Update outcome score with decay
            self.outcome_score[agent_id] = self.outcome_score.get(agent_id, 0.0) * self.outcome_decay + outcome * (1 - self.outcome_decay)
            # Clamp to [-1, 1]
            self.outcome_score[agent_id] = max(-1.0, min(1.0, self.outcome_score[agent_id]))

        if self.observation_count % 10 == 0:
            if self.population_coop_rate < 0.45:
                self.aggression = min(0.5, self.aggression + 0.05)
            elif self.population_coop_rate > 0.55:
                self.aggression = max(0.0, self.aggression - 0.05)

        if self.observation_count % 20 == 0:
            if self.population_coop_rate < 0.4:
                self.suspicion = min(0.2, self.suspicion + 0.02)
                self.leniency = max(0.0, self.leniency - 0.02)
            elif self.population_coop_rate > 0.6:
                self.suspicion = max(0.0, self.suspicion - 0.02)
                self.leniency = min(0.2, self.leniency + 0.02)

import math
