        self.recent_opponent_coop = {}
        self.alpha = 0.1  # Faster reputation updates
        self.default_trust = 0.5  # Lower baseline trust, more pessimistic
        self.aggression = 0.1  # Higher baseline aggression
        self.recent_coop_ratio = {}
        self.defection_memory = {}
        self.forgiveness = 0.05
        self.suspicion = 0.1
        self.leniency = 0.05
        self.cooperation_streak = {}
        self.defection_streak = {}
        self.mixed_streak = {}
        self.grudge = {}
        self.positive_bias = {}
        self.grudge_decay = 0.8  # Faster grudge decay
        self.positive_bias_decay = 0.9  # Faster positive bias decay
        self.defection_penalty = 0.4  # Higher penalty
        self.cooperation_bonus = 0.1  # Higher bonus
        # NEW: Track recent cooperation ratios with a smaller window
        self.recent_ratio_window = 10

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent not in self.trust:
            self.trust[opponent] = self.default_trust
        trust_score = self.trust[opponent]
        opp_rep = self.reputation.get(opponent, 0.0)
        recent_ratio = self.recent_coop_ratio.get(opponent, 0.5)
        # Different weighting: trust dominates more
        combined = 0.7 * trust_score + 0.1 * (opp_rep + 1) / 2 + 0.2 * recent_ratio
        forgiveness_bonus = self.forgiveness * self.recent_coop_ratio.get(opponent, 0.0)
        noise = random.uniform(-0.1, 0.1)  # More noise
        suspicion_penalty = self.suspicion * (self.defection_streak.get(opponent, 0) / 3.0)  # Stronger penalty
        leniency_bonus = self.leniency * (self.cooperation_streak.get(opponent, 0) / 3.0)
        mixed_penalty = 0.1 * self.mixed_streak.get(opponent, 0)  # Stronger mixed penalty
        grudge_penalty = self.grudge.get(opponent, 0.0) * 0.7  # Stronger grudge effect
        positive_bonus = self.positive_bias.get(opponent, 0.0) * 0.2
        prob_cooperate = combined + noise - self.aggression + forgiveness_bonus - suspicion_penalty + leniency_bonus - mixed_penalty - grudge_penalty + positive_bonus
        prob_cooperate = max(0.0, min(1.0, prob_cooperate))
        return random.random() < prob_cooperate

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.observation_count += 1
        actions = [donor_action, recipient_action]
        coop_count = sum(1 for a in actions if a == 'cooperate')
        self.population_coop_rate = self.population_coop_rate * 0.95 + (coop_count / 2) * 0.05  # Faster adaptation

        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.history:
                self.history[agent_id] = deque(maxlen=50)
            self.history[agent_id].append(action)
            # Stronger reputation update
            delta = 0.15 if action == 'cooperate' else -0.25
            self.reputation[agent_id] = self.reputation.get(agent_id, 0.0) * (1 - self.alpha) + delta * self.alpha
            self.reputation[agent_id] = max(-1.0, min(1.0, self.reputation[agent_id]))

            # Update recent cooperation ratio with a shorter window
            if agent_id not in self.recent_coop_ratio:
                self.recent_coop_ratio[agent_id] = 0.5
            self.recent_coop_ratio[agent_id] = self.recent_coop_ratio[agent_id] * 0.5 + (1 if action == 'cooperate' else 0) * 0.5

            # Update streaks
            if action == 'cooperate':
                self.cooperation_streak[agent_id] = self.cooperation_streak.get(agent_id, 0) + 1
                self.defection_streak[agent_id] = 0
            else:
                self.defection_streak[agent_id] = self.defection_streak.get(agent_id, 0) + 1
                self.cooperation_streak[agent_id] = 0
            if agent_id in self.history and len(self.history[agent_id]) > 1:
                if self.history[agent_id][-1] != self.history[agent_id][-2]:
                    self.mixed_streak[agent_id] = self.mixed_streak.get(agent_id, 0) + 1
                else:
                    self.mixed_streak[agent_id] = self.mixed_streak.get(agent_id, 0) * 0.8  # Faster decay

        # Update grudge and positive_bias
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if action == 'defect':
                self.grudge[agent_id] = self.grudge.get(agent_id, 0.0) + 0.4  # Higher grudge increase
                self.grudge[agent_id] = min(1.0, self.grudge[agent_id])
                self.positive_bias[agent_id] = self.positive_bias.get(agent_id, 0.0) * 0.3
            else:
                self.positive_bias[agent_id] = self.positive_bias.get(agent_id, 0.0) + 0.15
                self.positive_bias[agent_id] = min(1.0, self.positive_bias[agent_id])
                self.grudge[agent_id] = self.grudge.get(agent_id, 0.0) * self.grudge_decay
            if agent_id not in self.grudge:
                self.grudge[agent_id] = 0.0
            if agent_id not in self.positive_bias:
                self.positive_bias[agent_id] = 0.0

        # Update defection memory
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if action == 'defect':
                self.defection_memory[agent_id] = self.defection_memory.get(agent_id, 0) + 1
            else:
                self.defection_memory[agent_id] = self.defection_memory.get(agent_id, 0) * 0.9  # Faster decay

        # Update trust
        if donor_id != self.agent_id:
            extra_penalty = min(0.3, self.defection_memory.get(donor_id, 0) * 0.03)  # Higher extra penalty
            trust_delta = self.cooperation_bonus if donor_action == 'cooperate' else -self.defection_penalty - extra_penalty
            self.trust[donor_id] = self.trust.get(donor_id, self.default_trust) + trust_delta
            self.trust[donor_id] = max(0.0, min(1.0, self.trust[donor_id]))
        if recipient_id != self.agent_id:
            extra_penalty = min(0.3, self.defection_memory.get(recipient_id, 0) * 0.03)
            trust_delta = self.cooperation_bonus if recipient_action == 'cooperate' else -self.defection_penalty - extra_penalty
            self.trust[recipient_id] = self.trust.get(recipient_id, self.default_trust) + trust_delta
            self.trust[recipient_id] = max(0.0, min(1.0, self.trust[recipient_id]))

        # Track interactions with self (stronger reactions)
        if donor_id == self.agent_id:
            self.my_recent_actions.append(donor_action)
            if recipient_id != self.agent_id:
                if donor_action == 'cooperate' and recipient_action == 'defect':
                    self.trust[recipient_id] = self.trust.get(recipient_id, self.default_trust) - 0.25
                elif donor_action == 'defect' and recipient_action == 'cooperate':
                    self.trust[recipient_id] = self.trust.get(recipient_id, self.default_trust) + 0.15
                self.trust[recipient_id] = max(0.0, min(1.0, self.trust[recipient_id]))
        if recipient_id == self.agent_id:
            self.my_recent_actions.append(recipient_action)
            if donor_id != self.agent_id:
                if recipient_action == 'cooperate' and donor_action == 'defect':
                    self.trust[donor_id] = self.trust.get(donor_id, self.default_trust) - 0.25
                elif recipient_action == 'defect' and donor_action == 'cooperate':
                    self.trust[donor_id] = self.trust.get(donor_id, self.default_trust) + 0.15
                self.trust[donor_id] = max(0.0, min(1.0, self.trust[donor_id]))

        # Update recent opponent cooperation stats
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id != self.agent_id:
                if agent_id not in self.recent_opponent_coop:
                    self.recent_opponent_coop[agent_id] = deque(maxlen=20)
                self.recent_opponent_coop[agent_id].append(1 if action == 'cooperate' else 0)

        # Adapt aggression (faster adaptation)
        if self.observation_count % 5 == 0:
            if self.population_coop_rate < 0.5:
                self.aggression = min(0.6, self.aggression + 0.1)
            elif self.population_coop_rate > 0.6:
                self.aggression = max(0.0, self.aggression - 0.1)

        # Adapt suspicion and leniency (faster)
        if self.observation_count % 10 == 0:
            if self.population_coop_rate < 0.4:
                self.suspicion = min(0.3, self.suspicion + 0.05)
                self.leniency = max(0.0, self.leniency - 0.05)
            elif self.population_coop_rate > 0.6:
                self.suspicion = max(0.0, self.suspicion - 0.05)
                self.leniency = min(0.3, self.leniency + 0.05)

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.history = {}
        self.trust = {}
        self.interaction_count = {}
        self.population_coop_rate = 0.5
        self.observation_count = 0
        self.my_recent_actions = deque(maxlen=30)
        self.recent_opponent_coop = {}
        self.alpha = 0.05
        self.default_trust = 0.6
        self.aggression = 0.05
        self.recent_coop_ratio = {}
        self.defection_memory = {}
        self.forgiveness = 0.02
        self.suspicion = 0.0
        self.leniency = 0.0
        self.cooperation_streak = {}
        self.defection_streak = {}
        self.mixed_streak = {}
        self.grudge = {}
        self.positive_bias = {}
        self.grudge_decay = 0.9
        self.positive_bias_decay = 0.95
        self.defection_penalty = 0.3
        self.cooperation_bonus = 0.05
        # NEW: Track the last interaction outcome with each agent
        self.last_outcome = {}
        # NEW: Track a weighted recent outcome score in [-1, 1]
        self.outcome_score = {}
        # NEW: Decay factor for outcome score
        self.outcome_decay = 0.9

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent not in self.trust:
            self.trust[opponent] = self.default_trust
        trust_score = self.trust[opponent]
        opp_rep = self.reputation.get(opponent, 0.0)
        recent_ratio = self.recent_coop_ratio.get(opponent, 0.5)
        combined = 0.5 * trust_score + 0.2 * (opp_rep + 1) / 2 + 0.3 * recent_ratio
        forgiveness_bonus = self.forgiveness * self.recent_coop_ratio.get(opponent, 0.0)
        noise = random.uniform(-0.05, 0.05)
        suspicion_penalty = self.suspicion * (self.defection_streak.get(opponent, 0) / 5.0)
        leniency_bonus = self.leniency * (self.cooperation_streak.get(opponent, 0) / 5.0)
        mixed_penalty = 0.05 * self.mixed_streak.get(opponent, 0)
        grudge_penalty = self.grudge.get(opponent, 0.0) * 0.5
        positive_bonus = self.positive_bias.get(opponent, 0.0) * 0.3
        # NEW: Use outcome score as a more immediate signal
        outcome_effect = self.outcome_score.get(opponent, 0.0) * 0.2
        prob_cooperate = combined + noise - self.aggression + forgiveness_bonus - suspicion_penalty + leniency_bonus - mixed_penalty - grudge_penalty + positive_bonus + outcome_effect
        prob_cooperate = max(0.0, min(1.0, prob_cooperate))
        return random.random() < prob_cooperate

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.observation_count += 1
        actions = [donor_action, recipient_action]
        coop_count = sum(1 for a in actions if a == 'cooperate')
        self.population_coop_rate = self.population_coop_rate * 0.98 + (coop_count / 2) * 0.02

        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.history:
                self.history[agent_id] = deque(maxlen=50)
            self.history[agent_id].append(action)
            delta = 0.08 if action == 'cooperate' else -0.12
            self.reputation[agent_id] = self.reputation.get(agent_id, 0.0) * (1 - self.alpha) + delta * self.alpha
            self.reputation[agent_id] = max(-1.0, min(1.0, self.reputation[agent_id]))
            if agent_id not in self.recent_coop_ratio:
                self.recent_coop_ratio[agent_id] = 0.5
            self.recent_coop_ratio[agent_id] = self.recent_coop_ratio[agent_id] * 0.7 + (1 if action == 'cooperate' else 0) * 0.3
            if action == 'cooperate':
                self.cooperation_streak[agent_id] = self.cooperation_streak.get(agent_id, 0) + 1
                self.defection_streak[agent_id] = 0
            else:
                self.defection_streak[agent_id] = self.defection_streak.get(agent_id, 0) + 1
                self.cooperation_streak[agent_id] = 0
            if agent_id in self.history and len(self.history[agent_id]) > 1:
                if self.history[agent_id][-1] != self.history[agent_id][-2]:
                    self.mixed_streak[agent_id] = self.mixed_streak.get(agent_id, 0) + 1
                else:
                    self.mixed_streak[agent_id] = self.mixed_streak.get(agent_id, 0) * 0.9

        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if action == 'defect':
                self.grudge[agent_id] = self.grudge.get(agent_id, 0.0) + 0.3
                self.grudge[agent_id] = min(1.0, self.grudge[agent_id])
                self.positive_bias[agent_id] = self.positive_bias.get(agent_id, 0.0) * 0.5
            else:
                self.positive_bias[agent_id] = self.positive_bias.get(agent_id, 0.0) + 0.1
                self.positive_bias[agent_id] = min(1.0, self.positive_bias[agent_id])
                self.grudge[agent_id] = self.grudge.get(agent_id, 0.0) * self.grudge_decay
            if agent_id not in self.grudge:
                self.grudge[agent_id] = 0.0
            if agent_id not in self.positive_bias:
                self.positive_bias[agent_id] = 0.0

        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if action == 'defect':
                self.defection_memory[agent_id] = self.defection_memory.get(agent_id, 0) + 1
            else:
                self.defection_memory[agent_id] = self.defection_memory.get(agent_id, 0) * 0.95

        if donor_id != self.agent_id:
            extra_penalty = min(0.2, self.defection_memory.get(donor_id, 0) * 0.02)
            trust_delta = self.cooperation_bonus if donor_action == 'cooperate' else -self.defection_penalty - extra_penalty
            self.trust[donor_id] = self.trust.get(donor_id, self.default_trust) + trust_delta
            self.trust[donor_id] = max(0.0, min(1.0, self.trust[donor_id]))
        if recipient_id != self.agent_id:
            extra_penalty = min(0.2, self.defection_memory.get(recipient_id, 0) * 0.02)
            trust_delta = self.cooperation_bonus if recipient_action == 'cooperate' else -self.defection_penalty - extra_penalty
            self.trust[recipient_id] = self.trust.get(recipient_id, self.default_trust) + trust_delta
            self.trust[recipient_id] = max(0.0, min(1.0, self.trust[recipient_id]))

        if donor_id == self.agent_id:
            self.my_recent_actions.append(donor_action)
            if recipient_id != self.agent_id:
                if donor_action == 'cooperate' and recipient_action == 'defect':
                    self.trust[recipient_id] = self.trust.get(recipient_id, self.default_trust) - 0.15
                elif donor_action == 'defect' and recipient_action == 'cooperate':
                    self.trust[recipient_id] = self.trust.get(recipient_id, self.default_trust) + 0.1
                self.trust[recipient_id] = max(0.0, min(1.0, self.trust[recipient_id]))
        if recipient_id == self.agent_id:
            self.my_recent_actions.append(recipient_action)
            if donor_id != self.agent_id:
                if recipient_action == 'cooperate' and donor_action == 'defect':
                    self.trust[donor_id] = self.trust.get(donor_id, self.default_trust) - 0.15
                elif recipient_action == 'defect' and donor_action == 'cooperate':
                    self.trust[donor_id] = self.trust.get(donor_id, self.default_trust) + 0.1
                self.trust[donor_id] = max(0.0, min(1.0, self.trust[donor_id]))

        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id != self.agent_id:
                if agent_id not in self.recent_opponent_coop:
                    self.recent_opponent_coop[agent_id] = deque(maxlen=20)
                self.recent_opponent_coop[agent_id].append(1 if action == 'cooperate' else 0)

        # NEW: Update outcome score based on the joint action
        # For the donor, if the recipient cooperated, that's positive outcome; if defected, negative
        # For the recipient, if the donor cooperated, positive; if defected, negative
        for agent_id, action, other_action in [(donor_id, donor_action, recipient_action), (recipient_id, recipient_action, donor_action)]:
            if agent_id == self.agent_id:
                continue  # Don't adjust self-outcome based on observer perspective
            # Compute outcome: +1 if both cooperate, -1 if both defect, else 0.5 for unilateral cooperation
            if action == 'cooperate' and other_action == 'cooperate':
                outcome = 1.0
            elif action == 'defect' and other_action == 'defect':
                outcome = -1.0
            elif action == 'cooperate' and other_action == 'defect':
                outcome = -0.5  # I cooperated but was exploited
            else:  # I defected and other cooperated
                outcome = 0.5  # I got away with defecting
            # Update outcome score with decay
            self.outcome_score[agent_id] = self.outcome_score.get(agent_id, 0.0) * self.outcome_decay + outcome * (1 - self.outcome_decay)
            # Clamp to [-1, 1]
            self.outcome_score[agent_id] = max(-1.0, min(1.0, self.outcome_score[agent_id]))

        if self.observation_count % 10 == 0:
            if self.population_coop_rate < 0.45:
                self.aggression = min(0.5, self.aggression + 0.05)
            elif self.population_coop_rate > 0.55:
                self.aggression = max(0.0, self.aggression - 0.05)

        if self.observation_count % 20 == 0:
            if self.population_coop_rate < 0.4:
                self.suspicion = min(0.2, self.suspicion + 0.02)
                self.leniency = max(0.0, self.leniency - 0.02)
            elif self.population_coop_rate > 0.6:
                self.suspicion = max(0.0, self.suspicion - 0.02)
                self.leniency = min(0.2, self.leniency + 0.02)

import math
import random


class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Track reputation: dict mapping agent_id -> score (default 0)
        self.reputation = {}
        # Track number of times we've seen each agent's actions
        self.interaction_count = {}
        # Track whether we've ever defected against someone (for forgiveness)
        self.defections = set()
        # Track recent cooperation rate for each agent (last 10 observations)
        self.recent_coop = {}
        # Opponent id set before decide
        self._ctx_opponent_id = None
        # Generation counter (approx via rounds we've seen)
        self.round_seen = 0

    def _get_rep(self, agent_id: int) -> float:
        # Reputation score: starts at 0, updated with cooperation/defection
        return self.reputation.get(agent_id, 0.0)

    def _update_rep(self, agent_id: int, delta: float) -> None:
        self.reputation[agent_id] = self._get_rep(agent_id) + delta

    def _update_recent_coop(self, agent_id: int, action: str) -> None:
        # Maintain a deque of last 10 actions (cooperation=1, defection=0)
        if agent_id not in self.recent_coop:
            self.recent_coop[agent_id] = []
        q = self.recent_coop[agent_id]
        q.append(1.0 if action == "cooperate" else 0.0)
        if len(q) > 10:
            q.pop(0)

    def _coop_rate(self, agent_id: int) -> float:
        q = self.recent_coop.get(agent_id, [])
        if not q:
            return 0.5  # neutral
        return sum(q) / len(q)

    def decide(self) -> bool:
        # Get opponent rep and recent coop rate
        opp = self._ctx_opponent_id
        if opp is None:
            return True  # Should not happen, but safe

        # Base decision: cooperate if opponent's reputation is positive
        # or if we have limited info (first encounter)
        rep = self._get_rep(opp)
        coop_rate = self._coop_rate(opp)

        # Simple deterministic rule: cooperate if rep >= 0.0 and coop_rate >= 0.5
        # But also add a bit of forgiveness: if we've defected against them before,
        # be more forgiving after a while.
        if opp in self.defections:
            # Forgive if they've cooperated recently and rep >= -1
            if coop_rate >= 0.6 and rep >= -1.0:
                return True
            else:
                # Still defect if they're bad
                return not (rep >= 0.0)
        else:
            # Normal case: cooperate if rep >= 0.0 and coop_rate >= 0.5
            return (rep >= 0.0) and (coop_rate >= 0.5)

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Update reputation based on actions. Cooperation: +1, Defection: -1
        # Also track recent cooperation rates.
        self.round_seen += 1

        # Update donor's reputation
        delta_donor = 1.0 if donor_action == "cooperate" else -1.0
        self._update_rep(donor_id, delta_donor)
        self._update_recent_coop(donor_id, donor_action)

        # Update recipient's reputation (though recipient's action is also observed)
        delta_recip = 1.0 if recipient_action == "cooperate" else -1.0
        self._update_rep(recipient_id, delta_recip)
        self._update_recent_coop(recipient_id, recipient_action)

        # If we are involved, track if we defected against someone
        if donor_id == self.agent_id and donor_action == "defect":
            self.defections.add(recipient_id)
        if recipient_id == self.agent_id and recipient_action == "defect":
            self.defections.add(donor_id)

        # Also, if we are not involved, we might update our own behavior
        # based on third-party observations. No extra logic needed here.

        # Simple decay: to avoid runaway reputation, multiply by factor
        # every 100 rounds (approx). Not necessary, but keep small.
        # We'll just cap reputation between -10 and 10 to avoid extremes.
        if self.round_seen % 100 == 0:
            for aid in self.reputation:
                self.reputation[aid] = max(-10.0, min(10.0, self.reputation[aid] * 0.9))

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.rep = {}
        self.own_coop = 0
        self.own_total = 0
        self.defections_against = {}
        self.recent_coop = {}
        self.deque = deque
        self.own_recent_coop = deque(maxlen=10)
        self.recent_defections = {}
        self.rep_confidence = {}
        self.anger = {}  # NEW: tracks accumulated grievances per agent

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True

        # NEW: if we have strong anger towards opponent, always defect
        if self.anger.get(opponent, 0) >= 5:
            return False

        recent_defect_count = len(self.recent_defections.get(opponent, []))
        if recent_defect_count > 0:
            return False

        if opponent not in self.rep:
            return True

        coop_count, total = self.rep[opponent]
        if total == 0:
            return True

        coop_rate = coop_count / total
        confidence = self.rep_confidence[opponent][2] if opponent in self.rep_confidence else 0
        # NEW: threshold increases with anger to be more punitive
        threshold = 0.5 - 0.1 * confidence + 0.05 * self.anger.get(opponent, 0)
        own_recent_rate = sum(self.own_recent_coop) / max(1, len(self.own_recent_coop))
        threshold -= 0.1 * own_recent_rate
        return coop_rate > threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        for pid, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if pid == self.agent_id:
                continue
            if pid not in self.rep:
                self.rep[pid] = [0, 0]
                self.rep_confidence[pid] = [0, 0, 0]
            self.rep[pid][0] += 1 if action == 'cooperate' else 0
            self.rep[pid][1] += 1
            confidence = self.rep_confidence[pid][2]
            self.rep_confidence[pid][2] = min(1.0, confidence + 0.1)

            if pid not in self.recent_coop:
                self.recent_coop[pid] = self.deque(maxlen=10)
            self.recent_coop[pid].append(action == 'cooperate')

        # NEW: update anger based on observed defections against others
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            if donor_action == 'defect' and recipient_action == 'cooperate':
                # Donor defected against a cooperator - increase anger towards donor
                self.anger[donor_id] = self.anger.get(donor_id, 0) + 1
            elif donor_action == 'cooperate' and recipient_action == 'defect':
                # Recipient defected against a cooperator - increase anger towards recipient
                self.anger[recipient_id] = self.anger.get(recipient_id, 0) + 1
        elif donor_id == self.agent_id:
            self.own_total += 1
            if donor_action == 'cooperate':
                self.own_coop += 1
            self.own_recent_coop.append(donor_action == 'cooperate')
            if recipient_action == 'defect':
                self.defections_against[recipient_id] = self.defections_against.get(recipient_id, 0) + 1
                if recipient_id not in self.recent_defections:
                    self.recent_defections[recipient_id] = self.deque(maxlen=5)
                self.recent_defections[recipient_id].append(True)
                self.anger[recipient_id] = self.anger.get(recipient_id, 0) + 1  # NEW: anger on direct defection
            else:
                if recipient_id in self.recent_defections and len(self.recent_defections[recipient_id]) > 0:
                    self.recent_defections[recipient_id].popleft()
        elif recipient_id == self.agent_id:
            self.own_total += 1
            if recipient_action == 'cooperate':
                self.own_coop += 1
            self.own_recent_coop.append(recipient_action == 'cooperate')
            if donor_action == 'defect':
                self.defections_against[donor_id] = self.defections_against.get(donor_id, 0) + 1
                if donor_id not in self.recent_defections:
                    self.recent_defections[donor_id] = self.deque(maxlen=5)
                self.recent_defections[donor_id].append(True)
                self.anger[donor_id] = self.anger.get(donor_id, 0) + 1  # NEW: anger on direct defection
            else:
                if donor_id in self.recent_defections and len(self.recent_defections[donor_id]) > 0:
                    self.recent_defections[donor_id].popleft()

        # NEW: decay anger slowly to allow forgiveness over time
        for pid in list(self.anger.keys()):
            if pid != donor_id and pid != recipient_id:
                self.anger[pid] = max(0, self.anger[pid] - 0.01)
            else:
                self.anger[pid] = max(0, self.anger[pid] - 0.005)

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.rep = {}
        self.own_coop = 0
        self.own_total = 0
        self.defections_against = {}
        self.recent_coop = {}
        self.deque = deque
        self.own_recent_coop = deque(maxlen=10)
        self.recent_defections = {}
        self.rep_confidence = {}
        self.anger = {}
        self.trust = {}  # NEW: tracks trust level, decays over time

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True

        # NEW: if trust is very low, always defect
        if self.trust.get(opponent, 0.5) < 0.2:
            return False

        recent_defect_count = len(self.recent_defections.get(opponent, []))
        if recent_defect_count > 0:
            return False

        if opponent not in self.rep:
            return True

        coop_count, total = self.rep[opponent]
        if total == 0:
            return True

        coop_rate = coop_count / total
        confidence = self.rep_confidence[opponent][2] if opponent in self.rep_confidence else 0
        # NEW: use trust instead of anger, threshold decreases with trust
        threshold = 0.5 - 0.1 * confidence - 0.2 * self.trust.get(opponent, 0.5)
        own_recent_rate = sum(self.own_recent_coop) / max(1, len(self.own_recent_coop))
        threshold -= 0.1 * own_recent_rate
        return coop_rate > threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        for pid, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if pid == self.agent_id:
                continue
            if pid not in self.rep:
                self.rep[pid] = [0, 0]
                self.rep_confidence[pid] = [0, 0, 0]
                self.trust[pid] = 0.5
            self.rep[pid][0] += 1 if action == 'cooperate' else 0
            self.rep[pid][1] += 1
            confidence = self.rep_confidence[pid][2]
            self.rep_confidence[pid][2] = min(1.0, confidence + 0.1)

            if pid not in self.recent_coop:
                self.recent_coop[pid] = self.deque(maxlen=10)
            self.recent_coop[pid].append(action == 'cooperate')

        # NEW: update trust based on observed defections
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            if donor_action == 'defect' and recipient_action == 'cooperate':
                self.trust[donor_id] = max(0.0, self.trust.get(donor_id, 0.5) - 0.15)
            elif donor_action == 'cooperate' and recipient_action == 'defect':
                self.trust[recipient_id] = max(0.0, self.trust.get(recipient_id, 0.5) - 0.15)
            else:
                # Both cooperate or both defect - mild increase or decrease
                if donor_action == 'cooperate' and recipient_action == 'cooperate':
                    self.trust[donor_id] = min(1.0, self.trust.get(donor_id, 0.5) + 0.05)
                    self.trust[recipient_id] = min(1.0, self.trust.get(recipient_id, 0.5) + 0.05)
        elif donor_id == self.agent_id:
            self.own_total += 1
            if donor_action == 'cooperate':
                self.own_coop += 1
            self.own_recent_coop.append(donor_action == 'cooperate')
            if recipient_action == 'defect':
                self.defections_against[recipient_id] = self.defections_against.get(recipient_id, 0) + 1
                if recipient_id not in self.recent_defections:
                    self.recent_defections[recipient_id] = self.deque(maxlen=5)
                self.recent_defections[recipient_id].append(True)
                # Direct defect reduces trust more
                self.trust[recipient_id] = max(0.0, self.trust.get(recipient_id, 0.5) - 0.3)
            else:
                if recipient_id in self.recent_defections and len(self.recent_defections[recipient_id]) > 0:
                    self.recent_defections[recipient_id].popleft()
                # Direct cooperation increases trust
                self.trust[recipient_id] = min(1.0, self.trust.get(recipient_id, 0.5) + 0.1)
        elif recipient_id == self.agent_id:
            self.own_total += 1
            if recipient_action == 'cooperate':
                self.own_coop += 1
            self.own_recent_coop.append(recipient_action == 'cooperate')
            if donor_action == 'defect':
                self.defections_against[donor_id] = self.defections_against.get(donor_id, 0) + 1
                if donor_id not in self.recent_defections:
                    self.recent_defections[donor_id] = self.deque(maxlen=5)
                self.recent_defections[donor_id].append(True)
                self.trust[donor_id] = max(0.0, self.trust.get(donor_id, 0.5) - 0.3)
            else:
                if donor_id in self.recent_defections and len(self.recent_defections[donor_id]) > 0:
                    self.recent_defections[donor_id].popleft()
                self.trust[donor_id] = min(1.0, self.trust.get(donor_id, 0.5) + 0.1)

        # NEW: decay trust slowly toward 0.5 to allow recovery
        for pid in list(self.trust.keys()):
            if pid != donor_id and pid != recipient_id:
                self.trust[pid] += (0.5 - self.trust[pid]) * 0.01

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.history = {}
        self.my_actions = []
        self.observed_actions = {}
        self.interacted = set()
        self.recent_defections = {}
        self.population_cooperation = []
        self.my_coop_count = 0
        self.my_defect_count = 0
        self.overall_coop = {}
        self.overall_defect = {}
        self._ctx_opponent_id = None
        self.defections_against_me = {}
        self.trust_scores = {}
        # New: Memory of recent interactions for sliding window analysis
        self.recent_interactions = deque(maxlen=20)
        # New: Track a running "generosity" bias that evolves over time
        self.generosity_bias = 0.05
        # New: Track a "forgiveness" factor that increases after cooperation by others
        self.forgiveness = 0.0

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True

        # Use a sliding window of recent interactions for pattern detection
        opponent_interactions = [h for h in self.recent_interactions if opponent in (h[0], h[1])]
        if opponent_interactions:
            coop_count = sum(1 for (d, r, da, ra) in opponent_interactions if (d == opponent and da == 'cooperate') or (r == opponent and ra == 'cooperate'))
            defect_count = len(opponent_interactions) - coop_count
            if defect_count > coop_count * 1.5:
                return False

        # Check reputation and trust as before
        rep = self.reputation.get(opponent, 0.0)
        trust = self.trust_scores.get(opponent, 0.0)
        defections_against = self.defections_against_me.get(opponent, 0)
        # New: Add forgiveness to the threshold, making agent more tolerant after seeing cooperation
        adjusted_trust = trust + self.forgiveness * 0.1
        if adjusted_trust < -0.3 or defections_against > 2:
            return False
        elif adjusted_trust > 0.2:
            return True
        elif rep < -0.2:
            return False
        elif rep > 0.3:
            return random.random() > 0.2
        else:
            # New: Use a dynamic generosity bias that adapts based on population cooperation
            # If population is mostly cooperating, be more generous; if mostly defecting, be more cautious
            if self.population_cooperation:
                avg_coop = sum(self.population_cooperation) / len(self.population_cooperation)
                adjusted_bias = self.generosity_bias + (avg_coop - 0.5) * 0.2
            else:
                adjusted_bias = self.generosity_bias
            # If I've been cooperating a lot, sometimes defect to test
            if self.my_coop_count > self.my_defect_count + 5:
                return random.random() > 0.7
            return random.random() < adjusted_bias

