                if recipient_id not in self.recent_defections:
                    self.recent_defections[recipient_id] = self.deque(maxlen=5)
                self.recent_defections[recipient_id].append(True)
                self.anger[recipient_id] = self.anger.get(recipient_id, 0) + 1
            else:
                if recipient_id in self.recent_defections and len(self.recent_defections[recipient_id]) > 0:
                    self.recent_defections[recipient_id].popleft()
        elif recipient_id == self.agent_id:
            self.own_total += 1
            if recipient_action == 'cooperate':
                self.own_coop += 1
                # NEW: track cooperation from donor (we cooperated as recipient? Actually we are recipient, so we cooperated if recipient_action is cooperate)
                self.cooperation_with[donor_id] = self.cooperation_with.get(donor_id, 0) + 1
            else:
                self.defections_by_us[donor_id] = self.defections_by_us.get(donor_id, 0) + 1
            self.own_recent_coop.append(recipient_action == 'cooperate')
            if donor_action == 'defect':
