        if opponent_interactions:
            recent_opponent_interactions = opponent_interactions[-10:]
            coop_count = sum(1 for (d, r, da, ra) in recent_opponent_interactions if (d == opponent and da == 'cooperate') or (r == opponent and ra == 'cooperate'))
            defect_count = len(recent_opponent_interactions) - coop_count
            if defect_count > coop_count * 1.2:  # Lower threshold for defection detection
                return False

        # Check reputation and trust - with time decay on trust
        rep = self.reputation.get(opponent, 0.0)
        trust = self.trust_scores.get(opponent, 0.0)
        defections_against = self.defections_against_me.get(opponent, 0)
        last_time = self.last_interaction_time.get(opponent, -1)
        if last_time != -1:
            # Decay trust based on time since last interaction - more recent interactions weigh more
            time_diff = self.current_time - last_time
            trust *= (0.9 ** time_diff)
        if trust < -0.2 or defections_against > 1:  # Lower defection threshold
            return False
        elif trust > 0.15:
            return True
        elif rep < -0.15:
            return False
        elif rep > 0.35:
            return random.random() > 0.15  # Slightly more forgiving for high reputation
        else:
            # New: Use a dynamic generosity bias that adapts based on population cooperation
            # If population is mostly cooperating, be more generous; if mostly defecting, be more cautious
            if self.population_cooperation:
                avg_coop = sum(self.population_cooperation) / len(self.population_cooperation)
                adjusted_bias = self.generosity_bias + (avg_coop - 0.5) * 0.3  # Stronger adjustment
