                self.forgiveness_bias += 0.02
            self.forgiveness_bias = max(0.0, min(1.0, self.forgiveness_bias))

        # New: Track my own recent actions for pattern detection
        if donor_id == self.agent_id:
            self.my_recent_actions.append(donor_action)
