class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.cooperation_counts = {}
        self.defection_counts = {}
        self.interaction_history = {}
        self.trust = {}
        self.generation = 0

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True

        # Get reputation of opponent
        opp_rep = self.reputation.get(opponent, 0.5)

        # If we've interacted before, factor in history
        if opponent in self.interaction_history:
            history = self.interaction_history[opponent]
            coop_rate = sum(1 for h in history if h == 'C') / len(history)
            opp_rep = 0.7 * opp_rep + 0.3 * coop_rate

        # Tit-for-tat with forgiveness based on reputation
        if opponent in self.interaction_history and self.interaction_history[opponent][-1] == 'D':
            # If opponent defected last time, defect unless they have good reputation
            if opp_rep < 0.6:
                return False
            else:
                # Give benefit of the doubt with probability based on reputation
                return random.random() < opp_rep
        else:
            # Cooperate if reputation is decent
            return opp_rep >= 0.4

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        try:
            # Update reputation based on actions
            for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
                if agent_id == self.agent_id:
                    continue

                if action == 'cooperate':
                    self.cooperation_counts[agent_id] = self.cooperation_counts.get(agent_id, 0) + 1
                else:
                    self.defection_counts[agent_id] = self.defection_counts.get(agent_id, 0) + 1

                coop = self.cooperation_counts.get(agent_id, 0)
                defect = self.defection_counts.get(agent_id, 0)
                total = coop + defect

                if total > 0:
                    self.reputation[agent_id] = coop / total

            # Record interactions if we're involved
            if donor_id == self.agent_id:
                self._record_interaction(recipient_id, donor_action)
            elif recipient_id == self.agent_id:
                self._record_interaction(donor_id, recipient_action)

            # Update trust based on third-party observations
            if donor_id != self.agent_id and recipient_id != self.agent_id:
                if donor_action == 'cooperate' and recipient_action == 'cooperate':
                    self.trust[donor_id] = self.trust.get(donor_id, 0.5) * 1.05
                    self.trust[recipient_id] = self.trust.get(recipient_id, 0.5) * 1.05
                elif donor_action == 'defect' and recipient_action == 'defect':
                    self.trust[donor_id] = self.trust.get(donor_id, 0.5) * 0.95
                    self.trust[recipient_id] = self.trust.get(recipient_id, 0.5) * 0.95
                else:
                    defector = donor_id if donor_action == 'defect' else recipient_id
                    cooperator = recipient_id if donor_action == 'defect' else donor_id
                    self.trust[defector] = self.trust.get(defector, 0.5) * 0.8
                    self.trust[cooperator] = self.trust.get(cooperator, 0.5) * 1.1

                # Clamp trust values
                for key in self.trust:
                    self.trust[key] = max(0.0, min(1.0, self.trust[key]))
        except Exception:
            pass

    def _record_interaction(self, opponent_id: int, my_action: str) -> None:
        if opponent_id not in self.interaction_history:
            self.interaction_history[opponent_id] = []
        action = 'C' if my_action == 'cooperate' else 'D'
        self.interaction_history[opponent_id].append(action)
        # Keep only last 10 interactions to avoid memory growth
        if len(self.interaction_history[opponent_id]) > 10:
            self.interaction_history[opponent_id] = self.interaction_history[opponent_id][-10:]

