        # New: Track a "forgiveness" bias that evolves based on interactions where I was wronged
        self.forgiveness_bias = 0.1
        # New: Track a "retaliation" threshold that determines when to punish defection
        self.retaliation_threshold = 0.3
        # New: Track a "cooperation_history" for each agent to model reciprocity patterns
        self.cooperation_history = {}

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True

        # Use a sliding window of recent interactions for pattern detection
        opponent_interactions = [h for h in self.recent_interactions if opponent in (h[0], h[1])]
        if opponent_interactions:
            coop_count = sum(1 for (d, r, da, ra) in opponent_interactions if (d == opponent and da == 'cooperate') or (r == opponent and ra == 'cooperate'))
            defect_count = len(opponent_interactions) - coop_count
            if defect_count > coop_count * 1.5:
                return False

        # Check reputation and trust as before
        rep = self.reputation.get(opponent, 0.0)
        trust = self.trust_scores.get(opponent, 0.0)
        defections_against = self.defections_against_me.get(opponent, 0)

        # New: Use a dynamic retaliation threshold based on my own cooperation history
        # If I've been cooperating a lot, I'm more likely to retaliate against defection
        if self.my_coop_count > self.my_defect_count + 3:
            effective_threshold = self.retaliation_threshold * 0.8
        else:
            effective_threshold = self.retaliation_threshold

        if trust < -0.3 or defections_against > 2:
            return False
        elif trust > 0.2:
            return True
        elif rep < -0.2:
            return False
        elif rep > 0.3:
            return random.random() > 0.2
        else:
            # New: Use a dynamic generosity bias that adapts based on population cooperation
            # If population is mostly cooperating, be more generous; if mostly defecting, be more cautious
            if self.population_cooperation:
                avg_coop = sum(self.population_cooperation) / len(self.population_cooperation)
                adjusted_bias = self.generosity_bias + (avg_coop - 0.5) * 0.2
            else:
                adjusted_bias = self.generosity_bias
            # If I've been cooperating a lot, sometimes defect to test
            if self.my_coop_count > self.my_defect_count + 5:
                return random.random() > 0.7
            # New: If I've been wronged by this opponent recently, but my forgiveness bias is high, give another chance
            if defections_against > 0 and self.forgiveness_bias > 0.5:
                # Chance to forgive based on forgiveness bias
                return random.random() < self.forgiveness_bias
            # New: If the opponent has a history of cooperating with me, be more likely to cooperate
            coop_history = self.cooperation_history.get(opponent, [])
            if coop_history:
                last_action = coop_history[-1]
                if last_action == 'cooperate':
                    adjusted_bias += 0.1
                else:
                    adjusted_bias -= 0.1
            return random.random() < adjusted_bias

