            else:
                # I was not wronged or I cooperated - increase forgiveness slightly
                self.forgiveness_bias += 0.01
            self.forgiveness_bias = max(0.0, min(1.0, self.forgiveness_bias))

        # New: Adapt retaliation threshold based on the overall behavior of the population
        # If defection is common, lower the threshold to retaliate more quickly; if cooperation is common, raise it
        if self.population_cooperation:
