            for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
                if agent_id == self.agent_id:
                    continue

                if action == 'cooperate':
                    self.cooperation_counts[agent_id] = self.cooperation_counts.get(agent_id, 0) + 1
                else:
                    self.defection_counts[agent_id] = self.defection_counts.get(agent_id, 0) + 1

                coop = self.cooperation_counts.get(agent_id, 0)
                defect = self.defection_counts.get(agent_id, 0)
                total = coop + defect

                if total > 0:
                    self.reputation[agent_id] = coop / total

            # Record interactions if we're involved
            if donor_id == self.agent_id:
                self._record_interaction(recipient_id, donor_action)
            elif recipient_id == self.agent_id:
                self._record_interaction(donor_id, recipient_action)

            # NEW: Update momentum based on our own interactions
            if donor_id == self.agent_id or recipient_id == self.agent_id:
                partner_id = recipient_id if donor_id == self.agent_id else donor_id
                my_action = donor_action if donor_id == self.agent_id else recipient_action
                partner_action = recipient_action if donor_id == self.agent_id else donor_action

                if my_action == 'cooperate' and partner_action == 'cooperate':
                    self.momentum[partner_id] = self.momentum.get(partner_id, 0.0) + 0.2
                elif my_action == 'defect' and partner_action == 'defect':
                    self.momentum[partner_id] = self.momentum.get(partner_id, 0.0) - 0.2
                elif my_action == 'cooperate' and partner_action == 'defect':
                    self.momentum[partner_id] = self.momentum.get(partner_id, 0.0) - 0.1
                else:
                    self.momentum[partner_id] = self.momentum.get(partner_id, 0.0) + 0.1

                # Clamp momentum to [-1, 1] and add slight decay
                self.momentum[partner_id] = max(-1.0, min(1.0, self.momentum[partner_id] * 0.95))

            # Update trust based on third-party observations (modified for more nuanced behavior)
            if donor_id != self.agent_id and recipient_id != self.agent_id:
                if donor_action == 'cooperate' and recipient_action == 'cooperate':
                    self.trust[donor_id] = self.trust.get(donor_id, 0.5) * 1.05
                    self.trust[recipient_id] = self.trust.get(recipient_id, 0.5) * 1.05
                elif donor_action == 'defect' and recipient_action == 'defect':
                    self.trust[donor_id] = self.trust.get(donor_id, 0.5) * 0.95
                    self.trust[recipient_id] = self.trust.get(recipient_id, 0.5) * 0.95
                else:
                    defector = donor_id if donor_action == 'defect' else recipient_id
                    cooperator = recipient_id if donor_action == 'defect' else donor_id
                    self.trust[defector] = self.trust.get(defector, 0.5) * 0.8
                    self.trust[cooperator] = self.trust.get(cooperator, 0.5) * 1.1

                # Clamp trust values
                for key in self.trust:
                    self.trust[key] = max(0.0, min(1.0, self.trust[key]))

                # NEW: Update recent goodwill for cooperative observations
                if donor_action == 'cooperate':
                    self.recent_goodwill[donor_id] = self.recent_goodwill.get(donor_id, 0.0) + 0.1
                if recipient_action == 'cooperate':
                    self.recent_goodwill[recipient_id] = self.recent_goodwill.get(recipient_id, 0.0) + 0.1
                # Decay goodwill over time
                for key in list(self.recent_goodwill.keys()):
                    self.recent_goodwill[key] *= 0.95
                    if self.recent_goodwill[key] < 0.05:
                        del self.recent_goodwill[key]
        except Exception:
            pass

    def _record_interaction(self, opponent_id: int, my_action: str) -> None:
        if opponent_id not in self.interaction_history:
            self.interaction_history[opponent_id] = deque(maxlen=10)
        action = 'C' if my_action == 'cooperate' else 'D'
        self.interaction_history[opponent_id].append(action)

