        # This makes the agent more forgiving if it has been a while since last defection observed
        self.forgiveness *= 0.98
        if donor_action == 'defect' or recipient_action == 'defect':
            if donor_id != self.agent_id and recipient_id != self.agent_id:
                # Only increase if not directly involved to avoid self-bias
                self.forgiveness += 0.05
        # Cap forgiveness
        self.forgiveness = max(0.0, min(10.0, self.forgiveness))

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.rep = {}
        self.own_coop = 0
        self.own_total = 0
        self.defections_against = {}
        self.recent_coop = {}
        self.deque = deque
        self.own_recent_coop = deque(maxlen=10)
        self.recent_defections = {}
        self.rep_confidence = {}
        self.anger = {}
        self.cooperation_with = {}
        self.defections_by_us = {}
        # NEW: Track a personal "trust" score for each agent based on reciprocity
        self.reciprocity = {}

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True

        # NEW: if we have strong anger towards opponent, always defect
        if self.anger.get(opponent, 0) >= 5:
            return False

        recent_defect_count = len(self.recent_defections.get(opponent, []))
        if recent_defect_count > 0:
            return False

        if opponent not in self.rep:
            return True

        coop_count, total = self.rep[opponent]
        if total == 0:
            return True

        coop_rate = coop_count / total
        confidence = self.rep_confidence[opponent][2] if opponent in self.rep_confidence else 0
        # NEW: threshold increases with anger to be more punitive
        threshold = 0.5 - 0.1 * confidence + 0.05 * self.anger.get(opponent, 0)
        own_recent_rate = sum(self.own_recent_coop) / max(1, len(self.own_recent_coop))
        threshold -= 0.1 * own_recent_rate
        # NEW: reduce threshold if we have cooperated with this opponent many times before
        our_coop_with = self.cooperation_with.get(opponent, 0)
        our_def_with = self.defections_by_us.get(opponent, 0)
        if our_coop_with + our_def_with > 0:
            threshold -= 0.05 * (our_coop_with - our_def_with) / (our_coop_with + our_def_with)
        # NEW: adjust threshold based on reciprocity score
        recip = self.reciprocity.get(opponent, 0.0)
        threshold += 0.2 * recip  # higher reciprocity means more likely to defect (less trust)
        return coop_rate > threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        for pid, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if pid == self.agent_id:
                continue
            if pid not in self.rep:
                self.rep[pid] = [0, 0]
                self.rep_confidence[pid] = [0, 0, 0]
            self.rep[pid][0] += 1 if action == 'cooperate' else 0
            self.rep[pid][1] += 1
            confidence = self.rep_confidence[pid][2]
            self.rep_confidence[pid][2] = min(1.0, confidence + 0.1)

            if pid not in self.recent_coop:
                self.recent_coop[pid] = self.deque(maxlen=10)
            self.recent_coop[pid].append(action == 'cooperate')

        # NEW: update reciprocity based on observed interactions
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            # If donor cooperates and recipient cooperates, both are good -> decrease reciprocity for both
            if donor_action == 'cooperate' and recipient_action == 'cooperate':
                for pid in [donor_id, recipient_id]:
                    self.reciprocity[pid] = self.reciprocity.get(pid, 0.0) - 0.05
                    self.reciprocity[pid] = max(-1.0, self.reciprocity[pid])
            # If donor defects and recipient defects, both are bad -> increase reciprocity for both
            elif donor_action == 'defect' and recipient_action == 'defect':
                for pid in [donor_id, recipient_id]:
                    self.reciprocity[pid] = self.reciprocity.get(pid, 0.0) + 0.05
                    self.reciprocity[pid] = min(1.0, self.reciprocity[pid])
            # If one defects and one cooperates, the defector is worse -> increase reciprocity for defector
            elif donor_action == 'defect' and recipient_action == 'cooperate':
                self.reciprocity[donor_id] = self.reciprocity.get(donor_id, 0.0) + 0.1
                self.reciprocity[donor_id] = min(1.0, self.reciprocity[donor_id])
                self.reciprocity[recipient_id] = self.reciprocity.get(recipient_id, 0.0) - 0.05
                self.reciprocity[recipient_id] = max(-1.0, self.reciprocity[recipient_id])
            elif donor_action == 'cooperate' and recipient_action == 'defect':
                self.reciprocity[recipient_id] = self.reciprocity.get(recipient_id, 0.0) + 0.1
                self.reciprocity[recipient_id] = min(1.0, self.reciprocity[recipient_id])
                self.reciprocity[donor_id] = self.reciprocity.get(donor_id, 0.0) - 0.05
                self.reciprocity[donor_id] = max(-1.0, self.reciprocity[donor_id])

        # NEW: update anger based on observed defections against others
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            if donor_action == 'defect' and recipient_action == 'cooperate':
                self.anger[donor_id] = self.anger.get(donor_id, 0) + 1
            elif donor_action == 'cooperate' and recipient_action == 'defect':
                self.anger[recipient_id] = self.anger.get(recipient_id, 0) + 1
        elif donor_id == self.agent_id:
            self.own_total += 1
            if donor_action == 'cooperate':
                self.own_coop += 1
                self.cooperation_with[recipient_id] = self.cooperation_with.get(recipient_id, 0) + 1
            else:
                self.defections_by_us[recipient_id] = self.defections_by_us.get(recipient_id, 0) + 1
            self.own_recent_coop.append(donor_action == 'cooperate')
            if recipient_action == 'defect':
                self.defections_against[recipient_id] = self.defections_against.get(recipient_id, 0) + 1
                if recipient_id not in self.recent_defections:
                    self.recent_defections[recipient_id] = self.deque(maxlen=5)
                self.recent_defections[recipient_id].append(True)
                self.anger[recipient_id] = self.anger.get(recipient_id, 0) + 1
            else:
                if recipient_id in self.recent_defections and len(self.recent_defections[recipient_id]) > 0:
                    self.recent_defections[recipient_id].popleft()
        elif recipient_id == self.agent_id:
            self.own_total += 1
            if recipient_action == 'cooperate':
                self.own_coop += 1
                self.cooperation_with[donor_id] = self.cooperation_with.get(donor_id, 0) + 1
            else:
                self.defections_by_us[donor_id] = self.defections_by_us.get(donor_id, 0) + 1
            self.own_recent_coop.append(recipient_action == 'cooperate')
            if donor_action == 'defect':
                self.defections_against[donor_id] = self.defections_against.get(donor_id, 0) + 1
                if donor_id not in self.recent_defections:
                    self.recent_defections[donor_id] = self.deque(maxlen=5)
                self.recent_defections[donor_id].append(True)
                self.anger[donor_id] = self.anger.get(donor_id, 0) + 1
            else:
                if donor_id in self.recent_defections and len(self.recent_defections[donor_id]) > 0:
                    self.recent_defections[donor_id].popleft()

        # NEW: decay anger slowly to allow forgiveness over time
        for pid in list(self.anger.keys()):
            if pid != donor_id and pid != recipient_id:
                self.anger[pid] = max(0, self.anger[pid] - 0.01)
            else:
                self.anger[pid] = max(0, self.anger[pid] - 0.005)

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.history = {}
        self.my_actions = []
        self.observed_actions = {}
        self.interacted = set()
        self.recent_defections = {}
        self.population_cooperation = []
        self.my_coop_count = 0
        self.my_defect_count = 0
        self.overall_coop = {}
        self.overall_defect = {}
        self._ctx_opponent_id = None
        self.defections_against_me = {}
        self.trust_scores = {}
        # New: Use a deque with a much shorter window for recent interactions
        self.recent_interactions = deque(maxlen=5)
        # New: Instead of per-opponent generosity, use a random exploration probability
        self.explore_prob = 0.15
        # New: Track a "suspicion" counter that increases with observed defections and decays over time
        self.suspicion = 0.0
        # New: Track a "cooperation streak" for each opponent to detect patterns
        self.cooperation_streaks = {}
        # New: Track a "defection streak" for each opponent
        self.defection_streaks = {}
        # New: Track a "forgiveness" counter that resets defection penalties over time
        self.forgiveness = 0.0
        # New: Track a "reputation momentum" that accelerates reputation changes
        self.reputation_momentum = {}

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True

        # Use a sliding window of recent interactions for pattern detection (shorter window)
        opponent_interactions = [h for h in self.recent_interactions if opponent in (h[0], h[1])]
        if opponent_interactions:
            coop_count = sum(1 for (d, r, da, ra) in opponent_interactions if (d == opponent and da == 'cooperate') or (r == opponent and ra == 'cooperate'))
            defect_count = len(opponent_interactions) - coop_count
            # New: Use a more lenient threshold for defection detection
            if defect_count > coop_count:
                return False

        # Check reputation and trust as before
        rep = self.reputation.get(opponent, 0.0)
        trust = self.trust_scores.get(opponent, 0.0)
        defections_against = self.defections_against_me.get(opponent, 0)
        # New: Use suspicion to influence decision - if suspicion is high, be more cautious
        if trust < -0.3 or defections_against > 2 or self.suspicion > 2.0:
            return False
        elif trust > 0.4:
            return True
        elif rep < -0.2:
            return False
        elif rep > 0.3:
            return random.random() > 0.05
        else:
            # New: Use a random exploration mechanism instead of global generosity
            # If I've been cooperating a lot, sometimes defect to test
            if self.my_coop_count > self.my_defect_count + 4:
                return random.random() > 0.85
            # New: If there's a defection streak, be more cautious
            if self.defection_streaks.get(opponent, 0) > 3:
                return False
            # New: If there's a cooperation streak, be more trusting
            if self.cooperation_streaks.get(opponent, 0) > 4:
                return True
            # New: Add forgiveness mechanism - if I've forgiven recently, be more likely to cooperate
            if self.forgiveness > 3.0:
                return random.random() < 0.8
            # New: Exploration - randomly cooperate or defect to learn
            if random.random() < self.explore_prob:
                return random.random() < 0.5
            # Default to cooperation with some probability based on reputation
            return random.random() < (0.5 + rep)

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.overall_coop[donor_id] = self.overall_coop.get(donor_id, 0) + (1 if donor_action == 'cooperate' else 0)
        self.overall_defect[donor_id] = self.overall_defect.get(donor_id, 0) + (1 if donor_action == 'defect' else 0)
        self.overall_coop[recipient_id] = self.overall_coop.get(recipient_id, 0) + (1 if recipient_action == 'cooperate' else 0)
        self.overall_defect[recipient_id] = self.overall_defect.get(recipient_id, 0) + (1 if recipient_action == 'defect' else 0)

        # Asymmetric reputation update - defection punished more strongly (slightly modified)
        if donor_action == 'cooperate':
            self.reputation_momentum[donor_id] = self.reputation_momentum.get(donor_id, 0.0) + 0.02
            self.reputation[donor_id] = self.reputation.get(donor_id, 0.0) + 0.12
        else:
            self.reputation_momentum[donor_id] = self.reputation_momentum.get(donor_id, 0.0) - 0.05
            self.reputation[donor_id] = self.reputation.get(donor_id, 0.0) - 0.35
        if recipient_action == 'cooperate':
            self.reputation_momentum[recipient_id] = self.reputation_momentum.get(recipient_id, 0.0) + 0.02
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.0) + 0.12
        else:
            self.reputation_momentum[recipient_id] = self.reputation_momentum.get(recipient_id, 0.0) - 0.05
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.0) - 0.35

        for agent in [donor_id, recipient_id]:
            self.reputation[agent] = max(-1.0, min(1.0, self.reputation[agent]))
            # New: Apply momentum to reputation update
            self.reputation[agent] += self.reputation_momentum[agent]
            self.reputation[agent] = max(-1.0, min(1.0, self.reputation[agent]))

        # Trust scores with decay - more reactive (slightly modified)
        if donor_action == 'cooperate':
            self.trust_scores[donor_id] = self.trust_scores.get(donor_id, 0.0) + 0.18
        else:
            self.trust_scores[donor_id] = self.trust_scores.get(donor_id, 0.0) - 0.5
        if recipient_action == 'cooperate':
            self.trust_scores[recipient_id] = self.trust_scores.get(recipient_id, 0.0) + 0.18
        else:
            self.trust_scores[recipient_id] = self.trust_scores.get(recipient_id, 0.0) - 0.5

        for agent in [donor_id, recipient_id]:
            self.trust_scores[agent] = max(-1.0, min(1.0, self.trust_scores[agent]))
            self.trust_scores[agent] *= 0.99

        # New: Update recent interactions deque for all observed actions
        self.recent_interactions.append((donor_id, recipient_id, donor_action, recipient_action))

        # New: Update exploration probability based on observed cooperation/defection
        if donor_action == 'cooperate':
            self.explore_prob = max(0.05, self.explore_prob - 0.005)
        else:
            self.explore_prob = min(0.3, self.explore_prob + 0.01)
        if recipient_action == 'cooperate':
            self.explore_prob = max(0.05, self.explore_prob - 0.005)
        else:
            self.explore_prob = min(0.3, self.explore_prob + 0.01)

        # New: Update streaks
        for agent, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if action == 'cooperate':
                self.cooperation_streaks[agent] = self.cooperation_streaks.get(agent, 0) + 1
                self.defection_streaks[agent] = 0
            else:
                self.defection_streaks[agent] = self.defection_streaks.get(agent, 0) + 1
                self.cooperation_streaks[agent] = 0
            self.cooperation_streaks[agent] = min(10, self.cooperation_streaks.get(agent, 0))
            self.defection_streaks[agent] = min(10, self.defection_streaks.get(agent, 0))

        # If I am part of the pair, record interaction in history
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            opponent = recipient_id if donor_id == self.agent_id else donor_id
            self.interacted.add(opponent)
            if opponent not in self.history:
                self.history[opponent] = []
            self.history[opponent].append((donor_id, recipient_id, donor_action, recipient_action))
            if donor_id == self.agent_id:
                if donor_action == 'cooperate':
                    self.my_coop_count += 1
                else:
                    self.my_defect_count += 1
            elif recipient_id == self.agent_id:
                if recipient_action == 'cooperate':
                    self.my_coop_count += 1
                else:
                    self.my_defect_count += 1
            if donor_id == self.agent_id and recipient_action == 'defect':
                self.defections_against_me[recipient_id] = self.defections_against_me.get(recipient_id, 0) + 1
            elif recipient_id == self.agent_id and donor_action == 'defect':
                self.defections_against_me[donor_id] = self.defections_against_me.get(donor_id, 0) + 1

        # Track recent defections with decay
        if donor_action == 'defect':
            self.recent_defections[donor_id] = self.recent_defections.get(donor_id, 0) + 1
        if recipient_action == 'defect':
            self.recent_defections[recipient_id] = self.recent_defections.get(recipient_id, 0) + 1

        for agent in list(self.recent_defections.keys()):
            self.recent_defections[agent] = self.recent_defections[agent] * 0.9
            if self.recent_defections[agent] < 0.1:
                del self.recent_defections[agent]

        # New: Update suspicion based on observed defections, decaying over time
        # Only consider observations where I'm not directly involved to avoid bias
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            if donor_action == 'defect':
                self.suspicion += 0.1
            if recipient_action == 'defect':
                self.suspicion += 0.1
            # Decay suspicion slowly
            self.suspicion *= 0.99
            # Cap suspicion
            self.suspicion = max(0.0, min(5.0, self.suspicion))

        # New: Update population cooperation statistic (keep from parent but with shorter window)
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            coop_actions = (donor_action == 'cooperate') + (recipient_action == 'cooperate')
            self.population_cooperation.append(coop_actions / 2)
            if len(self.population_cooperation) > 20:
                self.population_cooperation.pop(0)
            # New: Use population cooperation to adjust suspicion (if population is cooperative, reduce suspicion)
            if len(self.population_cooperation) >= 5:
                avg_coop = sum(self.population_cooperation) / len(self.population_cooperation)
                if avg_coop > 0.7:
                    self.suspicion = max(0.0, self.suspicion - 0.05)
                elif avg_coop < 0.3:
                    self.suspicion = min(5.0, self.suspicion + 0.05)

        # New: Update forgiveness counter - decays over time but increases when I observe defections
        # This makes the agent more forgiving if it has been a while since last defection observed
        self.forgiveness *= 0.98
        if donor_action == 'defect' or recipient_action == 'defect':
            if donor_id != self.agent_id and recipient_id != self.agent_id:
                # Only increase if not directly involved to avoid self-bias
                self.forgiveness += 0.05
        # Cap forgiveness
        self.forgiveness = max(0.0, min(10.0, self.forgiveness))

import math
import random
from collections import deque


class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Track reputation: dict mapping agent_id -> score (default 0)
        self.reputation = {}
        # Track number of times we've seen each agent's actions
        self.interaction_count = {}
        # Track whether we've ever defected against someone (for forgiveness)
        self.defections = set()
        # Track recent cooperation rate for each agent (last 10 observations)
        self.recent_coop = {}
        # Opponent id set before decide
        self._ctx_opponent_id = None
        # Generation counter (approx via rounds we've seen)
        self.round_seen = 0
        # Introduce a trust threshold that shifts based on our own experience
        self.trust_threshold = 0.0  # Base threshold
        self.experience_count = 0  # Number of direct interactions we've had
        # NEW: Memory of past defections against us, with timestamps
        self.defection_memory = {}  # agent_id -> deque of (round_seen, defected)
        # NEW: Track our own reputation from the perspective of others (self-assessment)
        self.self_reputation = 0.0
        # NEW: Track how often we cooperate with each agent (for reciprocal strategy)
        self.cooperation_with = {}  # agent_id -> count of times we cooperated with them
        # NEW: Track how many times we've been defected against by each agent
        self.times_defected_against = {}  # agent_id -> count
        # NEW: Override forgiveness factor to be more forgiving when we've defected first
        self.defection_first = {}  # agent_id -> bool (True if we defected before they did)

    def _get_rep(self, agent_id: int) -> float:
        return self.reputation.get(agent_id, 0.0)

    def _update_rep(self, agent_id: int, delta: float) -> None:
        self.reputation[agent_id] = self._get_rep(agent_id) + delta

    def _update_recent_coop(self, agent_id: int, action: str) -> None:
        if agent_id not in self.recent_coop:
            self.recent_coop[agent_id] = deque(maxlen=10)
        self.recent_coop[agent_id].append(1.0 if action == "cooperate" else 0.0)

    def _coop_rate(self, agent_id: int) -> float:
        q = self.recent_coop.get(agent_id, deque())
        if not q:
            return 0.5
        return sum(q) / len(q)

    def _forgiveness_factor(self, agent_id: int) -> float:
        # Check if we have any recent defections from this agent
        if agent_id not in self.defection_memory:
            return 1.0
        # Get the most recent defection time
        times = [t for t, d in self.defection_memory[agent_id] if d]
        if not times:
            return 1.0
        # If the last defection was very recent (within last 5 rounds), less forgiving
        last_defect_time = max(times)
        if self.round_seen - last_defect_time < 5:
            return 0.5  # Less forgiving
        # If it's been a while, more forgiving
        return 1.5

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return True

        rep = self._get_rep(opp)
        coop_rate = self._coop_rate(opp)
        direct_interactions = self.interaction_count.get(opp, 0)

        # Dynamic threshold: use personal experience if we have direct interactions
        if direct_interactions > 0:
            effective_threshold = self.trust_threshold - 0.2
        else:
            effective_threshold = self.trust_threshold

        # Apply forgiveness factor based on our memory of their defections
        forgive = self._forgiveness_factor(opp)
        effective_threshold = effective_threshold * forgive

        # NEW: Reciprocal strategy - if we've cooperated with them a lot, be more willing
        # to cooperate even if their reputation is slightly below threshold
        coop_count = self.cooperation_with.get(opp, 0)
        if coop_count > 3:
            effective_threshold -= 0.3  # Reward for our own past cooperation

        # NEW: If we have defected against them first and they haven't retaliated yet,
        # be more forgiving (try to reconcile)
        if self.defection_first.get(opp, False):
            if coop_rate >= 0.5:
                effective_threshold -= 0.5  # Extra forgiveness if they still cooperate

        # Base decision: cooperate if rep >= threshold and coop_rate >= 0.5
        # But also add a bit of forgiveness: if we've defected against them before,
        # be more forgiving after a while.
        if opp in self.defections:
            if coop_rate >= 0.6 and rep >= -1.0:
                return True
            else:
                return not (rep >= effective_threshold)
        else:
            return (rep >= effective_threshold) and (coop_rate >= 0.5)

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        self.round_seen += 1

        # Update reputation
        delta_donor = 1.0 if donor_action == "cooperate" else -1.0
        self._update_rep(donor_id, delta_donor)
        self._update_recent_coop(donor_id, donor_action)

        delta_recip = 1.0 if recipient_action == "cooperate" else -1.0
        self._update_rep(recipient_id, delta_recip)
        self._update_recent_coop(recipient_id, recipient_action)

        # If we are involved, track direct interactions and update memory
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self.experience_count += 1
            other_id = recipient_id if donor_id == self.agent_id else donor_id
            other_action = recipient_action if donor_id == self.agent_id else donor_action
            self.interaction_count[other_id] = self.interaction_count.get(other_id, 0) + 1

            # Update trust threshold
            if other_action == "cooperate":
                self.trust_threshold -= 0.05
            else:
                self.trust_threshold += 0.1
            self.trust_threshold = max(-2.0, min(2.0, self.trust_threshold))

            # Record defection against us in memory
            if other_action == "defect":
                if other_id not in self.defection_memory:
                    self.defection_memory[other_id] = deque(maxlen=10)
                self.defection_memory[other_id].append((self.round_seen, True))
                # NEW: Increment count of times defected against
                self.times_defected_against[other_id] = self.times_defected_against.get(other_id, 0) + 1
            else:
                if other_id not in self.defection_memory:
                    self.defection_memory[other_id] = deque(maxlen=10)
                self.defection_memory[other_id].append((self.round_seen, False))

            # NEW: Track our own cooperation with that agent
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            if my_action == "cooperate":
                self.cooperation_with[other_id] = self.cooperation_with.get(other_id, 0) + 1

            # NEW: Update self-reputation based on our actions
            if my_action == "cooperate":
                self.self_reputation += 0.1
            else:
                self.self_reputation -= 0.2
            self.self_reputation = max(-2.0, min(2.0, self.self_reputation))

            # NEW: Track if we defected first (i.e., we defected and they didn't in the same interaction)
            if my_action == "defect" and other_action == "cooperate":
                self.defection_first[other_id] = True
            elif my_action == "cooperate" and other_action == "defect":
                self.defection_first[other_id] = False

        # Track if we defected against someone
        if donor_id == self.agent_id and donor_action == "defect":
            self.defections.add(recipient_id)
        if recipient_id == self.agent_id and recipient_action == "defect":
            self.defections.add(donor_id)

        # Decay reputation
        if self.round_seen % 100 == 0:
            for aid in self.reputation:
                self.reputation[aid] = max(-10.0, min(10.0, self.reputation[aid] * 0.9))

