        # If we've interacted before, factor in history
        if opponent in self.interaction_history:
            history = self.interaction_history[opponent]
            coop_rate = sum(1 for h in history if h == 'C') / len(history)
            opp_rep = 0.7 * opp_rep + 0.3 * coop_rate

        # NEW: Apply momentum - if recent interactions were cooperative, boost cooperation
        momentum_val = self.momentum.get(opponent, 0.0)
        if momentum_val > 0.5:
            opp_rep = min(1.0, opp_rep + 0.1)

        # Modified tit-for-tat with forgiveness based on reputation and momentum
        if opponent in self.interaction_history and len(self.interaction_history[opponent]) > 0:
            if self.interaction_history[opponent][-1] == 'D':
                # Defect if opponent defected and reputation is low or no positive momentum
                if opp_rep < 0.6 and momentum_val < 0.3:
                    return False
                else:
                    # Give benefit of the doubt with probability based on reputation and momentum
                    prob = opp_rep * (1.0 + momentum_val) / 2.0
                    return random.random() < prob
            else:
                # Opponent cooperated last time - cooperate unless reputation is very low
                if opp_rep < 0.2:
                    return False
                # NEW: Escalate cooperation if we have positive momentum
                if momentum_val > 0.7:
                    return random.random() < 0.9
                return True
        else:
            # No history - cooperate if reputation is decent
            return opp_rep >= 0.4

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
