            if donor_id == self.agent_id:
                self._record_interaction(recipient_id, donor_action)
            elif recipient_id == self.agent_id:
                self._record_interaction(donor_id, recipient_action)

            # NEW: Update momentum based on our own interactions
            if donor_id == self.agent_id or recipient_id == self.agent_id:
                partner_id = recipient_id if donor_id == self.agent_id else donor_id
                my_action = donor_action if donor_id == self.agent_id else recipient_action
                partner_action = recipient_action if donor_id == self.agent_id else donor_action

                if my_action == 'cooperate' and partner_action == 'cooperate':
