        self.agent_id = agent_id
        self.reputation = {}
        self.my_coop_count = 0
        self.my_defect_count = 0
        self.round_num = 0
        self.generation = 0
        self.opponent_id = None
        self.last_my_action = None
        self.last_opponent_action = None
        self._ctx_opponent_id = None
        # New: track recent actions per agent (deque of last 5 actions)
        self.action_history = defaultdict(lambda: deque(maxlen=5))
        self.confidence = {}
        self.trust_bias = 0.0  # Bias based on my own recent cooperation

    def decide(self) -> bool:
        self.round_num += 1
        self.opponent_id = self._ctx_opponent_id
        if self.opponent_id is None:
            return True

        # Initialize reputation for unknown opponents
        if self.opponent_id not in self.reputation:
            self.reputation[self.opponent_id] = 0.0
            self.confidence[self.opponent_id] = 0.0

        opp_rate = self.reputation[self.opponent_id]
        opp_confidence = self.confidence[self.opponent_id]

        # New mechanism: Incorporate confidence and my own cooperation bias
        # High confidence makes me more certain, low confidence makes me more cautious
        if opp_confidence < 0.3:
            # Uncertain - be more cautious, default to cooperate with moderate probability
            effective_rate = 0.5
        else:
            effective_rate = opp_rate

        # My own recent behavior influences decision (inherited)
        if self.last_my_action is not None and self.last_my_action == 'defect':
            # If I defected last round, maybe give opponent chance to retaliate
            return random.random() < 0.7

        # Add trust bias: if I've been cooperating a lot recently, I'm more trusting
        trust_bias = 0.1 if self.my_coop_count > self.my_defect_count else -0.1
        effective_rate = min(1.0, max(0.0, effective_rate + trust_bias))

        # Decision based on effective rate with confidence-based thresholds
        if effective_rate > 0.6:
            return True
        elif effective_rate > 0.3:
            # Moderate - use forgiveness from parent but adjusted by confidence
            forgiveness = max(0.2, 1.0 - self.round_num / 30)
            return random.random() < (0.5 + 0.3 * forgiveness * (0.5 + opp_confidence))
        else:
            # Low reputation - defect often
            return random.random() < 0.2

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        try:
            # Track own actions (inherited)
            if donor_id == self.agent_id:
                self.last_my_action = donor_action
                if donor_action == 'cooperate':
                    self.my_coop_count += 1
                else:
                    self.my_defect_count += 1
            if recipient_id == self.agent_id:
                self.last_my_action = recipient_action
                if recipient_action == 'cooperate':
                    self.my_coop_count += 1
                else:
                    self.my_defect_count += 1

            # Update reputation and confidence of observed agents
            for pid, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
                if pid == self.agent_id:
                    continue
                # Update action history
                self.action_history[pid].append(action)

                # Update moving average reputation (inherited)
                if pid not in self.reputation:
                    self.reputation[pid] = 0.0
                    self.confidence[pid] = 0.0
                if action == 'cooperate':
                    self.reputation[pid] = self.reputation[pid] * 0.9 + 0.1 * 1.0
                else:
                    self.reputation[pid] = self.reputation[pid] * 0.9 + 0.1 * 0.0

                # New: Update confidence based on consistency
                # Confidence increases when recent actions are consistent with reputation
                recent = list(self.action_history[pid])
                if len(recent) >= 3:
                    coop_count = sum(1 for a in recent if a == 'cooperate')
                    consistency = max(coop_count, len(recent) - coop_count) / len(recent)
                    # Confidence moves toward consistency
                    self.confidence[pid] = self.confidence[pid] * 0.8 + 0.2 * consistency

            # Track generation changes (inherited)
            if self.round_num > 0 and self.round_num % 30 == 0:
                self.generation += 1
                self.round_num = 0
                # Decay reputation and confidence slightly between generations
                for pid in self.reputation:
                    self.reputation[pid] *= 0.95
                    self.confidence[pid] *= 0.95

        except Exception:
            pass

