        coop_rate = self.cooperation_rate.get(opponent, 0.5)
        rep_score = self.reputation.get(opponent, 0.5)

        # Combine signals
        combined = 0.4 * trust_score + 0.3 * coop_rate + 0.3 * rep_score

        # Add some randomness for exploration
        if random.random() < self.epsilon:
            return random.random() < 0.5

        return combined > 0.5

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
