            elif donor_action == 'defect' and recipient_action == 'defect':
                self.win_streak = 0
                self.lose_streak += 1
            else:
                self.win_streak = 0
                self.lose_streak = 0

        # Adaptive epsilon based on performance
        total_actions = self.my_coop_count + self.my_defect_count
        if total_actions > 50:
            coop_ratio = self.my_coop_count / total_actions
            if coop_ratio > 0.8:
                self.epsilon = max(0.01, self.epsilon * 0.99)
            elif coop_ratio < 0.2:
                self.epsilon = min(0.2, self.epsilon * 1.01)

