                # NEW: Our cooperation helps reduce grudge
                if donor_id in self.grudge:
                    self.grudge[donor_id] = max(0, self.grudge[donor_id] - 0.5)

        # NEW: Decay anger and grudge slowly over time for non-involved agents
        for pid in list(self.anger.keys()):
            if pid != donor_id and pid != recipient_id:
                self.anger[pid] = max(0, self.anger[pid] - 0.01)
            else:
                self.anger[pid] = max(0, self.anger[pid] - 0.005)
        # NEW: Decay grudge for all agents slowly - but less than anger decay
        for pid in list(self.grudge.keys()):
            if pid != donor_id and pid != recipient_id:
                self.grudge[pid] = max(0, self.grudge[pid] - 0.005)
