import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.history = {}
        self.my_actions = []
        self.observed_actions = {}
        self.interacted = set()
        self.recent_defections = {}
        self.population_cooperation = []
        self.my_coop_count = 0
        self.my_defect_count = 0
        self.overall_coop = {}
        self.overall_defect = {}
        self._ctx_opponent_id = None
        self.defections_against_me = {}
        self.trust_scores = {}
        # Use a longer deque for recent interactions to capture more context
        self.recent_interactions = deque(maxlen=20)
        # Use per-opponent generosity scores
        self.opponent_generosity = {}
        # Track a "suspicion" counter that increases with observed defections and decays over time
        self.suspicion = 0.0
        # Track a "cooperation streak" for each opponent
        self.cooperation_streaks = {}
        # Track a "defection streak" for each opponent
        self.defection_streaks = {}
        # Track a "forgiveness" counter that resets defection penalties over time
        self.forgiveness = 0.0
        # NEW: Track a "retaliation" threshold - if an opponent defects against me, I will retaliate for a certain number of rounds
        self.retaliation_counter = {}
        # NEW: Track a "cautiousness" parameter that increases with observed defections and decreases with cooperation
        self.cautiousness = 0.0

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True

        # Check retaliation: if I'm currently retaliating against this opponent, defect
        if self.retaliation_counter.get(opponent, 0) > 0:
            return False

        # Use a sliding window of recent interactions for pattern detection (longer window)
        opponent_interactions = [h for h in self.recent_interactions if opponent in (h[0], h[1])]
        if opponent_interactions:
            coop_count = sum(1 for (d, r, da, ra) in opponent_interactions if (d == opponent and da == 'cooperate') or (r == opponent and ra == 'cooperate'))
            defect_count = len(opponent_interactions) - coop_count
            # Use a more lenient threshold for defection detection
            if defect_count > coop_count + 1:
                return False

        # Check reputation and trust
        rep = self.reputation.get(opponent, 0.0)
        trust = self.trust_scores.get(opponent, 0.0)
        defections_against = self.defections_against_me.get(opponent, 0)
        # Use cautiousness to influence decision - if cautiousness is high, be more cautious
        if trust < -0.2 or defections_against > 1 or self.cautiousness > 2.0:
            return False
        elif trust > 0.3:
            return True
        elif rep < -0.1:
            return False
        elif rep > 0.2:
            return random.random() > 0.1
        else:
            # Use per-opponent generosity scores
            gen = self.opponent_generosity.get(opponent, 0.05)
            # If I've been cooperating a lot, sometimes defect to test
            if self.my_coop_count > self.my_defect_count + 3:
                return random.random() > 0.8
            # If there's a defection streak, be more cautious
            if self.defection_streaks.get(opponent, 0) > 2:
                return False
            # If there's a cooperation streak, be more trusting
            if self.cooperation_streaks.get(opponent, 0) > 3:
                return True
            # Add forgiveness mechanism - if I've forgiven recently, be more likely to cooperate
            if self.forgiveness > 2.0:
                return random.random() < 0.7
            # NEW: Add a small chance to cooperate even if defection is likely, to test the opponent
            if defect_count > coop_count:
                return random.random() < 0.2
            return random.random() < gen

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.overall_coop[donor_id] = self.overall_coop.get(donor_id, 0) + (1 if donor_action == 'cooperate' else 0)
        self.overall_defect[donor_id] = self.overall_defect.get(donor_id, 0) + (1 if donor_action == 'defect' else 0)
        self.overall_coop[recipient_id] = self.overall_coop.get(recipient_id, 0) + (1 if recipient_action == 'cooperate' else 0)
        self.overall_defect[recipient_id] = self.overall_defect.get(recipient_id, 0) + (1 if recipient_action == 'defect' else 0)

        # Asymmetric reputation update - defection punished more strongly (slightly modified)
        if donor_action == 'cooperate':
            self.reputation[donor_id] = self.reputation.get(donor_id, 0.0) + 0.12
        else:
            self.reputation[donor_id] = self.reputation.get(donor_id, 0.0) - 0.35
        if recipient_action == 'cooperate':
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.0) + 0.12
        else:
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.0) - 0.35

        for agent in [donor_id, recipient_id]:
            self.reputation[agent] = max(-1.0, min(1.0, self.reputation[agent]))

        # Trust scores with decay - more reactive (slightly modified)
        if donor_action == 'cooperate':
            self.trust_scores[donor_id] = self.trust_scores.get(donor_id, 0.0) + 0.18
        else:
            self.trust_scores[donor_id] = self.trust_scores.get(donor_id, 0.0) - 0.5
        if recipient_action == 'cooperate':
            self.trust_scores[recipient_id] = self.trust_scores.get(recipient_id, 0.0) + 0.18
        else:
            self.trust_scores[recipient_id] = self.trust_scores.get(recipient_id, 0.0) - 0.5

        for agent in [donor_id, recipient_id]:
            self.trust_scores[agent] = max(-1.0, min(1.0, self.trust_scores[agent]))
            self.trust_scores[agent] *= 0.99

        # Update recent interactions deque for all observed actions
        self.recent_interactions.append((donor_id, recipient_id, donor_action, recipient_action))

        # Update per-opponent generosity scores and streaks
        for agent, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if action == 'cooperate':
                self.opponent_generosity[agent] = self.opponent_generosity.get(agent, 0.05) + 0.02
                self.cooperation_streaks[agent] = self.cooperation_streaks.get(agent, 0) + 1
                self.defection_streaks[agent] = 0
            else:
                self.opponent_generosity[agent] = self.opponent_generosity.get(agent, 0.05) - 0.04
                self.defection_streaks[agent] = self.defection_streaks.get(agent, 0) + 1
                self.cooperation_streaks[agent] = 0
            self.opponent_generosity[agent] = max(0.0, min(1.0, self.opponent_generosity[agent]))
            self.cooperation_streaks[agent] = min(10, self.cooperation_streaks.get(agent, 0))
            self.defection_streaks[agent] = min(10, self.defection_streaks.get(agent, 0))

        # If I am part of the pair, record interaction in history
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            opponent = recipient_id if donor_id == self.agent_id else donor_id
            self.interacted.add(opponent)
            if opponent not in self.history:
                self.history[opponent] = []
            self.history[opponent].append((donor_id, recipient_id, donor_action, recipient_action))
            if donor_id == self.agent_id:
                if donor_action == 'cooperate':
                    self.my_coop_count += 1
                else:
                    self.my_defect_count += 1
            elif recipient_id == self.agent_id:
                if recipient_action == 'cooperate':
                    self.my_coop_count += 1
                else:
                    self.my_defect_count += 1
            if donor_id == self.agent_id and recipient_action == 'defect':
                self.defections_against_me[recipient_id] = self.defections_against_me.get(recipient_id, 0) + 1
                # NEW: When an opponent defects against me, set retaliation counter
                self.retaliation_counter[recipient_id] = 2
            elif recipient_id == self.agent_id and donor_action == 'defect':
                self.defections_against_me[donor_id] = self.defections_against_me.get(donor_id, 0) + 1
                # NEW: When an opponent defects against me, set retaliation counter
                self.retaliation_counter[donor_id] = 2
            # NEW: Decay retaliation counter for all agents over time
            for agent in list(self.retaliation_counter.keys()):
                self.retaliation_counter[agent] -= 1
                if self.retaliation_counter[agent] <= 0:
                    del self.retaliation_counter[agent]

        # Track recent defections with decay
        if donor_action == 'defect':
            self.recent_defections[donor_id] = self.recent_defections.get(donor_id, 0) + 1
        if recipient_action == 'defect':
            self.recent_defections[recipient_id] = self.recent_defections.get(recipient_id, 0) + 1

        for agent in list(self.recent_defections.keys()):
            self.recent_defections[agent] = self.recent_defections[agent] * 0.9
            if self.recent_defections[agent] < 0.1:
                del self.recent_defections[agent]

        # Update suspicion based on observed defections, decaying over time
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            if donor_action == 'defect':
                self.suspicion += 0.1
            if recipient_action == 'defect':
                self.suspicion += 0.1
            self.suspicion *= 0.99
            self.suspicion = max(0.0, min(5.0, self.suspicion))

        # NEW: Update cautiousness - increases with observed defections, decreases with cooperation
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            if donor_action == 'defect' or recipient_action == 'defect':
                self.cautiousness += 0.05
            else:
                self.cautiousness -= 0.02
            self.cautiousness = max(0.0, min(5.0, self.cautiousness))

        # Update population cooperation statistic
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            coop_actions = (donor_action == 'cooperate') + (recipient_action == 'cooperate')
            self.population_cooperation.append(coop_actions / 2)
            if len(self.population_cooperation) > 30:
                self.population_cooperation.pop(0)
            if len(self.population_cooperation) >= 10:
                avg_coop = sum(self.population_cooperation) / len(self.population_cooperation)
                if avg_coop > 0.6:
                    self.suspicion = max(0.0, self.suspicion - 0.05)
                elif avg_coop < 0.4:
                    self.suspicion = min(5.0, self.suspicion + 0.05)

        # Update forgiveness counter
        self.forgiveness *= 0.98
        if donor_action == 'defect' or recipient_action == 'defect':
            if donor_id != self.agent_id and recipient_id != self.agent_id:
                self.forgiveness += 0.05
        self.forgiveness = max(0.0, min(10.0, self.forgiveness))

import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.round = 0
        self.generation = 0
        self.my_partner_history = {}
        self.third_party_reputation = {}
        self.my_actions = []
        self.my_partner_actions = []
        self.cooperation_score = 0.5
        self.trust_factor = 0.5
        self.defection_count = 0
        self.cooperation_count = 0
        self.generation_start = 0
        self.opponent_id = None
        self._ctx_opponent_id = None
        # New: memory of recent partner actions for sentiment analysis
        self.recent_partner_sentiment = {}

    def decide(self) -> bool:
        self.round += 1
        self.opponent_id = self._ctx_opponent_id
        if self.opponent_id is None:
            return True

        # Get partner's reputation and history
        reputation = self.third_party_reputation.get(self.opponent_id, 0.5)
        history = self.my_partner_history.get(self.opponent_id, [])

        # If we have history with this partner, use it
        if history:
            recent = history[-5:]  # last 5 interactions
            partner_coop_rate = sum(1 for a in recent if a == 'cooperate') / len(recent)
        else:
            partner_coop_rate = reputation

        # New: incorporate sentiment from recent partner actions
        sentiment = self.recent_partner_sentiment.get(self.opponent_id, 0.0)
        # Blend sentiment into coop rate
        blended_coop_rate = 0.7 * partner_coop_rate + 0.3 * sentiment

        # Adaptive threshold based on reputation and history
        threshold = 0.4 + 0.1 * (self.cooperation_score - 0.5)
        if blended_coop_rate >= threshold:
            return True
        else:
            # Sometimes test defection if partner is unreliable
            if random.random() < 0.1:
                return False
            return True

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        try:
            # Update third-party reputation
            if donor_id != self.agent_id:
                self._update_reputation(donor_id, donor_action)
            if recipient_id != self.agent_id:
                self._update_reputation(recipient_id, recipient_action)

            # Self-judgment: update own cooperation score
            if donor_id == self.agent_id or recipient_id == self.agent_id:
                if donor_id == self.agent_id:
                    self._update_own_score(donor_action)
                if recipient_id == self.agent_id:
                    self._update_own_score(recipient_action)

            # Track partner history and sentiment for self-involved interactions
            if donor_id == self.agent_id and recipient_id != self.agent_id:
                self._record_partner_action(recipient_id, recipient_action)
                self._update_sentiment(recipient_id, recipient_action)
            elif recipient_id == self.agent_id and donor_id != self.agent_id:
                self._record_partner_action(donor_id, donor_action)
                self._update_sentiment(donor_id, donor_action)

            # Generation tracking
            if self.round % 30 == 0:
                self.generation += 1
                # Decay old reputation and sentiment slightly
                for k in list(self.third_party_reputation.keys()):
                    self.third_party_reputation[k] *= 0.95
                for k in list(self.recent_partner_sentiment.keys()):
                    self.recent_partner_sentiment[k] *= 0.95
        except Exception:
            pass

    def _update_reputation(self, agent_id: int, action: str) -> None:
        current = self.third_party_reputation.get(agent_id, 0.5)
        if action == 'cooperate':
            new = current + 0.1
        else:
            new = current - 0.15
        self.third_party_reputation[agent_id] = max(0.0, min(1.0, new))

    def _update_own_score(self, action: str) -> None:
        if action == 'cooperate':
            self.cooperation_score = min(1.0, self.cooperation_score + 0.05)
            self.cooperation_count += 1
        else:
            self.cooperation_score = max(0.0, self.cooperation_score - 0.1)
            self.defection_count += 1

    def _record_partner_action(self, partner_id: int, action: str) -> None:
        if partner_id not in self.my_partner_history:
            self.my_partner_history[partner_id] = []
        self.my_partner_history[partner_id].append(action)
        # Keep history bounded
        if len(self.my_partner_history[partner_id]) > 50:
            self.my_partner_history[partner_id] = self.my_partner_history[partner_id][-50:]

    # New: update sentiment based on recent actions, more reactive to defections
    def _update_sentiment(self, partner_id: int, action: str) -> None:
        current = self.recent_partner_sentiment.get(partner_id, 0.0)
        if action == 'cooperate':
            new = current + 0.08
        else:
            new = current - 0.2
        self.recent_partner_sentiment[partner_id] = max(-1.0, min(1.0, new))

