            if pid not in self.opponent_recent_coop_avg:
                self.opponent_recent_coop_avg[pid] = 0.5
            self.opponent_recent_coop_avg[pid] = 0.9 * self.opponent_recent_coop_avg[pid] + 0.1 * (1 if action == 'cooperate' else 0)

            # NEW: increment betrayal count if observed defecting against a cooperator
            if donor_id == pid and donor_action == 'defect' and recipient_action == 'cooperate':
                self.betrayal_count[pid] += 1
            if recipient_id == pid and recipient_action == 'defect' and donor_action == 'cooperate':
