                    self.recent_outcomes.append(True)
                else:
                    # Neutral: keep as True if we cooperated with cooperation else False
                    if donor_action == 'cooperate':
                        self.recent_outcomes.append(True)
                    else:
                        self.recent_outcomes.append(False)

            # New: update forgiveness based on recent interactions
            if self.recent_outcomes:
                recent_defection_rate = sum(1 for o in self.recent_outcomes if not o) / len(self.recent_outcomes)
                if recent_defection_rate > 0.5:
                    # If many defections, reduce forgiveness (become more strict)
                    self.forgiveness = max(0.1, self.forgiveness - 0.02)
                else:
                    # If mostly cooperation, increase forgiveness (become more generous)
                    self.forgiveness = min(0.8, self.forgiveness + 0.01)

            # Generation tracking
            if self.round % 30 == 0:
                self.generation += 1
                # Decay old reputation and sentiment slightly
                for k in list(self.third_party_reputation.keys()):
                    self.third_party_reputation[k] *= 0.95
                for k in list(self.recent_partner_sentiment.keys()):
                    self.recent_partner_sentiment[k] *= 0.95
                # Clear recent outcomes each generation to avoid stale adaptation
                self.recent_outcomes.clear()
        except Exception:
            pass

    def _update_reputation(self, agent_id: int, action: str) -> None:
        current = self.third_party_reputation.get(agent_id, 0.5)
        if action == 'cooperate':
