                self.retaliation += 0.2
                # New mechanism: accumulate cooperation debt when defected against
                self.cooperation_debt[donor_id] = self.cooperation_debt.get(donor_id, 0.0) + 0.3
            # Decay cooperation debt over time
            for agent in list(self.cooperation_debt.keys()):
                self.cooperation_debt[agent] *= 0.98
                if self.cooperation_debt[agent] < 0.05:
                    del self.cooperation_debt[agent]

        # Track recent defections with decay
        if donor_action == 'defect':
