            # Update variance with a small learning rate
            self.behavior_variance[agent] = 0.9 * self.behavior_variance[agent] + 0.1 * diff

            # New: update first impression (long-term, less reactive)
            if agent not in self.first_impression:
                self.first_impression[agent] = 0.0
            # Blend current action into first impression with a small weight
            self.first_impression[agent] = (1 - self.first_impression_weight) * self.first_impression[agent] + self.first_impression_weight * (1 if action == 'cooperate' else -1)

        # If I am part of the pair, record interaction in history
        if donor_id == self.agent_id or recipient_id == self.agent_id:
