            # Decay suspicion slowly
            self.suspicion *= 0.99
            # Cap suspicion
            self.suspicion = max(0.0, min(5.0, self.suspicion))

        # New: Update population cooperation statistic (keep from parent but with shorter window)
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            coop_actions = (donor_action == 'cooperate') + (recipient_action == 'cooperate')
