                self.suspicion += 0.1
            if recipient_action == 'defect':
                self.suspicion += 0.1
            # Decay suspicion slowly
            self.suspicion *= 0.99
            # Cap suspicion
            self.suspicion = max(0.0, min(5.0, self.suspicion))

        # Update population cooperation statistic with shorter window
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            coop_actions = (donor_action == 'cooperate') + (recipient_action == 'cooperate')
            self.population_cooperation.append(coop_actions / 2)
            if len(self.population_cooperation) > 30:
                self.population_cooperation.pop(0)
            # Use population cooperation to adjust suspicion
            if len(self.population_cooperation) >= 10:
                avg_coop = sum(self.population_cooperation) / len(self.population_cooperation)
                if avg_coop > 0.6:
                    self.suspicion = max(0.0, self.suspicion - 0.05)
                elif avg_coop < 0.4:
                    self.suspicion = min(5.0, self.suspicion + 0.05)

        # Update forgiveness counter - decays over time but increases when I observe defections
        self.forgiveness *= 0.98
        if donor_action == 'defect' or recipient_action == 'defect':
            if donor_id != self.agent_id and recipient_id != self.agent_id:
                self.forgiveness += 0.05
        self.forgiveness = max(0.0, min(10.0, self.forgiveness))

        # New: Decay retaliation over time
        self.retaliation *= 0.95
        self.retaliation = max(0.0, min(10.0, self.retaliation))

        # New: Update patience - increases when observing cooperation, decreases when observing defection
        if donor_action == 'cooperate':
            self.patience += 0.03
        else:
            self.patience -= 0.05
        if recipient_action == 'cooperate':
            self.patience += 0.03
        else:
            self.patience -= 0.05
        # Decay patience slowly
        self.patience *= 0.995
        self.patience = max(0.0, min(10.0, self.patience))

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputations = {}
        self.interaction_history = {}
        self.rounds_played = 0
        self.epsilon = 0.05  # Increased exploration
        self._ctx_opponent_id = None
        self.recent_outcomes = {}
        self.reputation_velocity = {}
        # New: decaying trust multiplier
        self.trust_decay = 0.95
        self.trust_scores = {}  # agent_id -> float trust

    def _get_reputation(self, agent_id: int):
        coop, defect = self.reputations.get(agent_id, (0, 0))
        total = coop + defect
        if total == 0:
            return 0.5
        return coop / total

    def _get_interaction_stats(self, agent_id: int):
        hist = self.interaction_history.get(agent_id)
        if not hist:
            return None
        cc = hist.count('CC')
        cd = hist.count('CD')
        dc = hist.count('DC')
        dd = hist.count('DD')
        total = len(hist)
        opponent_coop = (cc + dc) / total
        my_coop = (cc + cd) / total
        return {
            'cc': cc, 'cd': cd, 'dc': dc, 'dd': dd,
            'total': total,
            'opponent_coop': opponent_coop,
            'my_coop': my_coop
        }

    def _get_reputation_velocity(self, agent_id: int):
        vel = self.reputation_velocity.get(agent_id)
        if not vel:
            return 0.0
        return sum(vel) / len(vel)

    def _get_trust(self, agent_id: int) -> float:
        # Trust starts at 1.0 and decays over time, but is updated by interactions
        return self.trust_scores.get(agent_id, 1.0)

    def decide(self) -> bool:
        if self._ctx_opponent_id is None:
            return True
        opponent = self._ctx_opponent_id
        rep = self._get_reputation(opponent)
        stats = self._get_interaction_stats(opponent)
        velocity = self._get_reputation_velocity(opponent)
        trust = self._get_trust(opponent)

        # Incorporate trust: adjust reputation by trust factor
        adjusted_rep = rep * trust + 0.2 * velocity
        if adjusted_rep > 0.7:
            decision = True
        elif adjusted_rep < 0.3:
            decision = False
        else:
            if stats and stats['total'] >= 3:
                last_outcome = self.interaction_history[opponent][-1]
                if last_outcome in ('CC', 'DC'):
                    decision = True
                else:
                    recent = self.recent_outcomes.get(opponent, deque(maxlen=5))
                    mutual_coop = recent.count('CC') / max(1, len(recent))
                    forgiveness = 0.1 + 0.5 * (rep - 0.3) / 0.4 + 0.3 * mutual_coop
                    forgiveness = min(1.0, forgiveness + 0.1 * max(0, velocity))
                    # Trust lowers forgiveness if low
                    forgiveness *= trust
                    decision = random.random() < forgiveness
            else:
                if velocity < -0.2:
                    decision = random.random() < 0.4 * trust
                else:
                    decision = random.random() < 0.6 * trust

        if random.random() < self.epsilon:
            return not decision
        return decision

    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        # Update reputation for both agents
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id != self.agent_id:
                coop, defect = self.reputations.get(agent_id, (0, 0))
                if action == 'cooperate':
                    coop += 1
                else:
                    defect += 1
                self.reputations[agent_id] = (coop, defect)
                if agent_id not in self.reputation_velocity:
                    self.reputation_velocity[agent_id] = deque(maxlen=5)
                total = coop + defect
                if total > 1:
                    prev_rep = (coop - 1) / (total - 1) if total > 1 else 0.5
                    new_rep = coop / total
                    delta = new_rep - prev_rep
                    self.reputation_velocity[agent_id].append(delta)

        # Update trust based on observed actions (both own and others)
        # Trust increases when cooperating, decreases when defecting
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id != self.agent_id:
                current_trust = self._get_trust(agent_id)
                # Decay trust slightly each observation
                current_trust *= self.trust_decay
                if action == 'cooperate':
                    current_trust += 0.1
                else:
                    current_trust -= 0.15
                # Clamp to [0.1, 2.0]
                current_trust = max(0.1, min(2.0, current_trust))
                self.trust_scores[agent_id] = current_trust

        # If I'm involved, record interaction history and adjust trust more strongly
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                opponent = recipient_id
                my_action = donor_action
                opp_action = recipient_action
            else:
                opponent = donor_id
                my_action = recipient_action
                opp_action = donor_action
            outcome = (my_action[0] + opp_action[0]).upper()
            if opponent not in self.interaction_history:
                self.interaction_history[opponent] = deque(maxlen=10)
            self.interaction_history[opponent].append(outcome)
            if opponent not in self.recent_outcomes:
                self.recent_outcomes[opponent] = deque(maxlen=5)
            self.recent_outcomes[opponent].append(outcome)
            self.rounds_played += 1

            # Additional trust update based on my own action and opponent's action
            # If I cooperated and opponent defected, trust drops more
            if my_action == 'cooperate' and opp_action == 'defect':
                self.trust_scores[opponent] = max(0.1, self._get_trust(opponent) - 0.2)
            elif my_action == 'defect' and opp_action == 'cooperate':
                self.trust_scores[opponent] = max(0.1, self._get_trust(opponent) - 0.1)
            elif my_action == 'cooperate' and opp_action == 'cooperate':
                self.trust_scores[opponent] = min(2.0, self._get_trust(opponent) + 0.1)

import math
import random
from collections import deque

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.history = {}
        self.my_actions = []
        self.observed_actions = {}
        self.interacted = set()
        self.recent_defections = {}
        self.population_cooperation = []
        self.my_coop_count = 0
        self.my_defect_count = 0
        self.overall_coop = {}
        self.overall_defect = {}
        self._ctx_opponent_id = None
        self.defections_against_me = {}
        self.trust_scores = {}
        # New: Use a deque for recent interactions with a shorter window
        self.recent_interactions = deque(maxlen=10)
        # New: Instead of a single generosity bias, use a per-opponent generosity score
        self.opponent_generosity = {}
        # New: Track a "suspicion" counter that increases with observed defections and decays over time
        self.suspicion = 0.0
        # New: Track a "cooperation streak" for each opponent to detect patterns
        self.cooperation_streaks = {}
        # New: Track a "defection streak" for each opponent
        self.defection_streaks = {}
        # New: Track a "forgiveness" counter that resets defection penalties over time
        self.forgiveness = 0.0
        # New: Track a "betrayal memory" - a dict mapping opponent to count of times they defected against me
        self.betrayal_memory = {}

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True

        # New: If opponent has betrayed me more than 3 times, always defect
        if self.betrayal_memory.get(opponent, 0) > 3:
            return False

        # Use a sliding window of recent interactions for pattern detection (shorter window)
        opponent_interactions = [h for h in self.recent_interactions if opponent in (h[0], h[1])]
        if opponent_interactions:
            coop_count = sum(1 for (d, r, da, ra) in opponent_interactions if (d == opponent and da == 'cooperate') or (r == opponent and ra == 'cooperate'))
            defect_count = len(opponent_interactions) - coop_count
            # New: Use a more aggressive threshold for defection detection
            if defect_count > coop_count:
                return False

        # Check reputation and trust as before
        rep = self.reputation.get(opponent, 0.0)
        trust = self.trust_scores.get(opponent, 0.0)
        defections_against = self.defections_against_me.get(opponent, 0)
        # New: Use suspicion to influence decision - if suspicion is high, be more cautious
        if trust < -0.2 or defections_against > 1 or self.suspicion > 1.5:
            return False
        elif trust > 0.3:
            return True
        elif rep < -0.1:
            return False
        elif rep > 0.2:
            return random.random() > 0.1
        else:
            # New: Use per-opponent generosity scores instead of a global bias
            gen = self.opponent_generosity.get(opponent, 0.05)
            # If I've been cooperating a lot, sometimes defect to test
            if self.my_coop_count > self.my_defect_count + 3:
                return random.random() > 0.8
            # New: If there's a defection streak, be more cautious
            if self.defection_streaks.get(opponent, 0) > 2:
                return False
            # New: If there's a cooperation streak, be more trusting
            if self.cooperation_streaks.get(opponent, 0) > 3:
                return True
            # New: Add forgiveness mechanism - if I've forgiven recently, be more likely to cooperate
            if self.forgiveness > 2.0:
                return random.random() < 0.7
            return random.random() < gen

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.overall_coop[donor_id] = self.overall_coop.get(donor_id, 0) + (1 if donor_action == 'cooperate' else 0)
        self.overall_defect[donor_id] = self.overall_defect.get(donor_id, 0) + (1 if donor_action == 'defect' else 0)
        self.overall_coop[recipient_id] = self.overall_coop.get(recipient_id, 0) + (1 if recipient_action == 'cooperate' else 0)
        self.overall_defect[recipient_id] = self.overall_defect.get(recipient_id, 0) + (1 if recipient_action == 'defect' else 0)

        # Asymmetric reputation update - defection punished more strongly (slightly modified)
        if donor_action == 'cooperate':
            self.reputation[donor_id] = self.reputation.get(donor_id, 0.0) + 0.12
        else:
            self.reputation[donor_id] = self.reputation.get(donor_id, 0.0) - 0.35
        if recipient_action == 'cooperate':
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.0) + 0.12
        else:
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.0) - 0.35

        for agent in [donor_id, recipient_id]:
            self.reputation[agent] = max(-1.0, min(1.0, self.reputation[agent]))

        # Trust scores with decay - more reactive (slightly modified)
        if donor_action == 'cooperate':
            self.trust_scores[donor_id] = self.trust_scores.get(donor_id, 0.0) + 0.18
        else:
            self.trust_scores[donor_id] = self.trust_scores.get(donor_id, 0.0) - 0.5
        if recipient_action == 'cooperate':
            self.trust_scores[recipient_id] = self.trust_scores.get(recipient_id, 0.0) + 0.18
        else:
            self.trust_scores[recipient_id] = self.trust_scores.get(recipient_id, 0.0) - 0.5

        for agent in [donor_id, recipient_id]:
            self.trust_scores[agent] = max(-1.0, min(1.0, self.trust_scores[agent]))
            self.trust_scores[agent] *= 0.99

        # New: Update recent interactions deque for all observed actions
        self.recent_interactions.append((donor_id, recipient_id, donor_action, recipient_action))

        # New: Update per-opponent generosity scores and streaks
        for agent, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if action == 'cooperate':
                self.opponent_generosity[agent] = self.opponent_generosity.get(agent, 0.05) + 0.02
                self.cooperation_streaks[agent] = self.cooperation_streaks.get(agent, 0) + 1
                self.defection_streaks[agent] = 0
            else:
                self.opponent_generosity[agent] = self.opponent_generosity.get(agent, 0.05) - 0.04
                self.defection_streaks[agent] = self.defection_streaks.get(agent, 0) + 1
                self.cooperation_streaks[agent] = 0
            self.opponent_generosity[agent] = max(0.0, min(1.0, self.opponent_generosity[agent]))
            self.cooperation_streaks[agent] = min(10, self.cooperation_streaks.get(agent, 0))
            self.defection_streaks[agent] = min(10, self.defection_streaks.get(agent, 0))

        # If I am part of the pair, record interaction in history
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            opponent = recipient_id if donor_id == self.agent_id else donor_id
            self.interacted.add(opponent)
            if opponent not in self.history:
                self.history[opponent] = []
            self.history[opponent].append((donor_id, recipient_id, donor_action, recipient_action))
            if donor_id == self.agent_id:
                if donor_action == 'cooperate':
                    self.my_coop_count += 1
                else:
                    self.my_defect_count += 1
            elif recipient_id == self.agent_id:
                if recipient_action == 'cooperate':
                    self.my_coop_count += 1
                else:
                    self.my_defect_count += 1
            if donor_id == self.agent_id and recipient_action == 'defect':
                self.defections_against_me[recipient_id] = self.defections_against_me.get(recipient_id, 0) + 1
                # New: Update betrayal memory when I'm defected against
                self.betrayal_memory[recipient_id] = self.betrayal_memory.get(recipient_id, 0) + 1
            elif recipient_id == self.agent_id and donor_action == 'defect':
                self.defections_against_me[donor_id] = self.defections_against_me.get(donor_id, 0) + 1
                # New: Update betrayal memory when I'm defected against
                self.betrayal_memory[donor_id] = self.betrayal_memory.get(donor_id, 0) + 1

        # Track recent defections with decay
        if donor_action == 'defect':
            self.recent_defections[donor_id] = self.recent_defections.get(donor_id, 0) + 1
        if recipient_action == 'defect':
            self.recent_defections[recipient_id] = self.recent_defections.get(recipient_id, 0) + 1

        for agent in list(self.recent_defections.keys()):
            self.recent_defections[agent] = self.recent_defections[agent] * 0.9
            if self.recent_defections[agent] < 0.1:
                del self.recent_defections[agent]

        # New: Update suspicion based on observed defections, decaying over time
        # Only consider observations where I'm not directly involved to avoid bias
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            if donor_action == 'defect':
                self.suspicion += 0.1
            if recipient_action == 'defect':
                self.suspicion += 0.1
            # Decay suspicion slowly
            self.suspicion *= 0.99
            # Cap suspicion
            self.suspicion = max(0.0, min(5.0, self.suspicion))

        # New: Update population cooperation statistic (keep from parent but with shorter window)
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            coop_actions = (donor_action == 'cooperate') + (recipient_action == 'cooperate')
            self.population_cooperation.append(coop_actions / 2)
            if len(self.population_cooperation) > 30:
                self.population_cooperation.pop(0)
            # New: Use population cooperation to adjust suspicion (if population is cooperative, reduce suspicion)
            if len(self.population_cooperation) >= 10:
                avg_coop = sum(self.population_cooperation) / len(self.population_cooperation)
                if avg_coop > 0.6:
                    self.suspicion = max(0.0, self.suspicion - 0.05)
                elif avg_coop < 0.4:
                    self.suspicion = min(5.0, self.suspicion + 0.05)

        # New: Update forgiveness counter - decays over time but increases when I observe defections
        # This makes the agent more forgiving if it has been a while since last defection observed
        self.forgiveness *= 0.98
        if donor_action == 'defect' or recipient_action == 'defect':
            if donor_id != self.agent_id and recipient_id != self.agent_id:
                # Only increase if not directly involved to avoid self-bias
                self.forgiveness += 0.05
        # Cap forgiveness
        self.forgiveness = max(0.0, min(10.0, self.forgiveness))

import math
import random
from collections import deque


class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.opponent_id = None
        self.round = 0
        self.generation = 0
        self.my_actions = []
        self.opponent_history = {}
        self.cooperation_scores = {}
        self.defection_scores = {}
        self.reputation = {}
        self.interactions = {}
        self.trust = {}
        self.personal_memory = deque(maxlen=50)
        self.partner_quality = {}
        self.retaliation_threshold = 0.5
        self.generosity = 0.2
        self.epsilon = 0.1
        self.best_response_memory = {}
        self.last_opponent = None
        self.my_last_action = None
        self.opp_last_action = None
        self.rounds_played = 0
        self.observed_pairs = {}
        self.recent_opponents = deque(maxlen=10)
        self.coop_consecutive = 0
        self.defect_consecutive = 0
        self.trust_decay = 0.05
        self.trust_recovery = 0.15
        self.signal_memory = {}
        self.reciprocity_weight = 0.3  # New: weight for indirect reciprocity in trust
        self.signal_decay = 0.1  # New: decay for signal memory influence

    def decide(self) -> bool:
        self.rounds_played += 1
        opp = self._ctx_opponent_id
        self.opponent_id = opp
        self.last_opponent = opp

        if opp not in self.trust:
            self.trust[opp] = 0.5
        if opp not in self.cooperation_scores:
            self.cooperation_scores[opp] = 0.5
        if opp not in self.reputation:
            self.reputation[opp] = [0, 0]

        self.recent_opponents.append(opp)

        # Compute composite trust with indirect reciprocity component
        direct_trust = self.trust.get(opp, 0.5)
        partner_qual = self.partner_quality.get(opp, 0.5)
        rep = self.get_global_reputation(opp)
        rep_score = rep if rep is not None else 0.5

        # Indirect reciprocity: use signal memory to adjust trust
        signal_score = 0.5
        if opp in self.signal_memory:
            sig = self.signal_memory[opp]
            if sig:
                coop_count = sum(1 for a in sig if a == 'cooperate')
                signal_score = coop_count / len(sig)
                # Apply decay: more recent signals matter more
                signal_score = signal_score * (1 - self.signal_decay * (len(sig) - 1) / max(1, len(sig)))

        composite = (0.5 * direct_trust + 0.3 * partner_qual + 0.2 * rep_score) * (1 - self.reciprocity_weight) + \
                    self.reciprocity_weight * signal_score

        # Explore more when uncertain
        if random.random() < self.epsilon:
            return random.random() < 0.6

        # Use a threshold on composite trust
        return composite >= 0.45

    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        # Update reputation for donor and recipient
        for agent_id, action in [(donor_id, donor_action),
                                 (recipient_id, recipient_action)]:
            if agent_id not in self.reputation:
                self.reputation[agent_id] = [0, 0]
            self.reputation[agent_id][0] += 1
            if action == 'cooperate':
                self.reputation[agent_id][1] += 1

        # Apply trust decay to all known agents
        for agent in self.trust:
            self.trust[agent] = max(0.0, self.trust[agent] - self.trust_decay)

        # If self is involved, update personal memory and trust
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                my_action = donor_action
                opp_action = recipient_action
                opp_id = recipient_id
            else:
                my_action = recipient_action
                opp_action = donor_action
                opp_id = donor_id

            self.personal_memory.append((opp_id, my_action, opp_action))
            if opp_id not in self.opponent_history:
                self.opponent_history[opp_id] = []
            self.opponent_history[opp_id].append(opp_action)

            # Asymmetric trust update: recover faster from cooperation, penalize defection more
            if opp_id not in self.trust:
                self.trust[opp_id] = 0.5
            if opp_action == 'cooperate':
                self.trust[opp_id] = min(1.0, self.trust[opp_id] + self.trust_recovery)
            else:
                self.trust[opp_id] = max(0.0, self.trust[opp_id] - 0.2)

            # Update cooperation score (weighted recent)
            if opp_id not in self.cooperation_scores:
                self.cooperation_scores[opp_id] = 0.5
            self.cooperation_scores[opp_id] = 0.9 * self.cooperation_scores[opp_id] + \
                0.1 * (1 if opp_action == 'cooperate' else 0)

            # Track interactions
            key = tuple(sorted((self.agent_id, opp_id)))
            if key not in self.interactions:
                self.interactions[key] = []
            self.interactions[key].append((my_action, opp_action))

            # Update consecutive streak counters
            if opp_action == 'cooperate':
                self.coop_consecutive += 1
                self.defect_consecutive = 0
            else:
                self.defect_consecutive += 1
                self.coop_consecutive = 0

            # Update signal memory for indirect reciprocity
            if opp_id not in self.signal_memory:
                self.signal_memory[opp_id] = deque(maxlen=10)
            self.signal_memory[opp_id].append(opp_action)

        else:
            # Third-party observation: update pair info
            key = (donor_id, recipient_id)
            if key not in self.observed_pairs:
                self.observed_pairs[key] = []
            self.observed_pairs[key].append((donor_action, recipient_action))

            # Indirect reciprocity: update trust based on observed cooperation
            for agent_id, action in [(donor_id, donor_action),
                                     (recipient_id, recipient_action)]:
                if agent_id not in self.trust:
                    self.trust[agent_id] = 0.5
                if action == 'cooperate':
                    self.trust[agent_id] = min(1.0, self.trust[agent_id] + 0.03)
                else:
                    self.trust[agent_id] = max(0.0, self.trust[agent_id] - 0.1)

        # Update partner quality based on observed cooperation
        for agent_id, action in [(donor_id, donor_action),
                                 (recipient_id, recipient_action)]:
            if agent_id not in self.partner_quality:
                self.partner_quality[agent_id] = 0.5
            if action == 'cooperate':
                self.partner_quality[agent_id] = min(1.0, self.partner_quality[agent_id] + 0.05)
            else:
                self.partner_quality[agent_id] = max(0.0, self.partner_quality[agent_id] - 0.05)

    def get_coop_rate(self, agent_id):
        """Get cooperation rate for an agent based on history"""
        if agent_id not in self.opponent_history:
            return 0.5
        hist = self.opponent_history[agent_id]
        if not hist:
            return 0.5
        return sum(1 for a in hist if a == 'cooperate') / len(hist)

    def get_global_reputation(self, agent_id):
        """Get global reputation for an agent"""
        if agent_id not in self.reputation:
            return None
        total, coop = self.reputation[agent_id]
        if total == 0:
