            opp = recipient_id
            action = donor_action
            if opp not in self.opponent_recent_actions:
                self.opponent_recent_actions[opp] = []
            self.opponent_recent_actions[opp].append(action)
            if len(self.opponent_recent_actions[opp]) > 10:
