import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.opponent_id = None
        # Reputation with asymmetric confidence: score in [-1, 1] and confidence in [0, 1]
        self.reputation = {}  # agent_id -> (score, confidence)
        self.total_rounds = 0
        self.my_recent_actions = []
        self.opponent_recent_actions = {}
        self.generosity = 0.1
        self.trust_threshold = 0.2
        # Memory window for reputation updates (shorter = more reactive)
        self.memory_window = 3

    def _get_rep(self, agent_id: int) -> float:
        """Get reputation score, default neutral 0.0"""
        return self.reputation.get(agent_id, (0.0, 0.0))[0]

    def _get_confidence(self, agent_id: int) -> float:
        """Get confidence in reputation estimate, default 0.0"""
        return self.reputation.get(agent_id, (0.0, 0.0))[1]

    def _update_rep(self, agent_id: int, delta: float) -> None:
        """Update reputation with confidence-based weighting: high confidence -> smaller updates"""
        score, conf = self.reputation.get(agent_id, (0.0, 0.0))
        # Weight delta by (1 - confidence) so early observations have bigger impact
        weighted_delta = delta * (1.0 - conf)
        new_score = max(-1.0, min(1.0, score + weighted_delta))
        # Increase confidence towards 1 but not fully (always some uncertainty)
        new_conf = min(1.0, conf + 0.2)
        self.reputation[agent_id] = (new_score, new_conf)

    def decide(self) -> bool:
        if self.opponent_id is None:
            return True
        opp_id = self.opponent_id
        rep = self._get_rep(opp_id)
        # Use confidence to adjust threshold: low confidence -> more cautious
        conf = self._get_confidence(opp_id)
        # Effective threshold decreases with confidence (more trusting when sure)
        effective_threshold = self.trust_threshold * (2.0 - conf)
        if conf > 0.5:
            # High confidence: decisive based on reputation
            if rep > effective_threshold:
                return True
            if rep < -effective_threshold:
                return False
        # Otherwise probabilistic with a gentler slope when uncertain
        prob = 1.0 / (1.0 + math.exp(-3.0 * (rep - self.generosity) / (1.0 + conf)))
        return random.random() < prob

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Update own recent actions if I am donor or recipient
        if donor_id == self.agent_id:
            self.total_rounds += 1
            self.my_recent_actions.append(donor_action)
            if len(self.my_recent_actions) > 10:
                self.my_recent_actions.pop(0)
        elif recipient_id == self.agent_id:
            self.total_rounds += 1
            self.my_recent_actions.append(recipient_action)
            if len(self.my_recent_actions) > 10:
                self.my_recent_actions.pop(0)

        # Update reputation of donor (if not self)
        if donor_id != self.agent_id:
            if donor_action == 'cooperate':
                self._update_rep(donor_id, 0.1)
            else:
                self._update_rep(donor_id, -0.15)

        # Update reputation of recipient (if not self)
        if recipient_id != self.agent_id:
            if recipient_action == 'cooperate':
                self._update_rep(recipient_id, 0.05)
            else:
                self._update_rep(recipient_id, -0.1)

        # Track recent actions for both participants if not self
        for opp in [donor_id, recipient_id]:
            if opp != self.agent_id:
                action = donor_action if opp == donor_id else recipient_action
                if opp not in self.opponent_recent_actions:
                    self.opponent_recent_actions[opp] = []
                self.opponent_recent_actions[opp].append(action)
                # Keep only last memory_window actions for reputation updates
                if len(self.opponent_recent_actions[opp]) > self.memory_window:
                    self.opponent_recent_actions[opp].pop(0)

        # If I am directly involved, also update reputation with stronger signal
        if donor_id == self.agent_id:
            opp = recipient_id
            if donor_action == 'cooperate':
                self._update_rep(opp, 0.05)  # extra positive for my cooperation
            else:
                self._update_rep(opp, -0.05)  # extra negative for my defection
        if recipient_id == self.agent_id:
            opp = donor_id
            if recipient_action == 'cooperate':
                # As recipient, if donor cooperated, I trust more; if I defected, less
                self._update_rep(opp, 0.1 if recipient_action == 'cooperate' else -0.1)

