        self.opponent_id = None
        self.reputation = {}  # agent_id -> reputation score
        self.interactions = {}  # agent_id -> list of (my_action, their_action)
        self.cooperation_rates = {}  # agent_id -> [cooperations, total_observations]
        self.round_num = 0
        self.generation = 0
        self.my_recent_actions = []
        self.opponent_recent_actions = []
        # Initialize with neutral reputation
        for i in range(15):
            self.reputation[i] = 0.5
            self.cooperation_rates[i] = [0, 0]

    def decide(self) -> bool:
        # Get opponent's reputation
        opp_rep = self.reputation.get(self.opponent_id, 0.5)
        # Get opponent's cooperation rate from observations
        coop_rate = 0.5
        if self.opponent_id in self.cooperation_rates:
            total = self.cooperation_rates[self.opponent_id][1]
            if total > 0:
                coop_rate = self.cooperation_rates[self.opponent_id][0] / total

        # Start with a baseline: cooperate if opponent seems cooperative
        # Combine reputation and observed cooperation rate
        trust_score = 0.6 * coop_rate + 0.4 * opp_rep

        # Add some forgiveness: if we have interacted before, consider history
        if self.opponent_id in self.interactions and len(self.interactions[self.opponent_id]) > 0:
            history = self.interactions[self.opponent_id]
            # Check recent interactions (last 5)
            recent = history[-5:]
            if len(recent) > 0:
                their_coop = sum(1 for _, their in recent if their)
                their_rate = their_coop / len(recent)
                trust_score = 0.7 * trust_score + 0.3 * their_rate

        # Add slight randomness to avoid being too predictable
        noise = random.uniform(-0.05, 0.05)
        trust_score += noise

        # Cooperate if trust score above threshold
        return trust_score >= 0.5

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update cooperation rates for both agents
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id != self.agent_id:  # Don't judge ourselves
                if agent_id in self.cooperation_rates:
                    self.cooperation_rates[agent_id][1] += 1
                    if action == 'cooperate':
                        self.cooperation_rates[agent_id][0] += 1
                else:
                    self.cooperation_rates[agent_id] = [1 if action == 'cooperate' else 0, 1]

